window.__Q=window.__Q||{};window.__Q["prev/7/A1"]=[{"q":"格列本脲降血糖作用的主要机制是","o":["增强胰岛素的作用","促进葡萄糖分解","刺激胰岛β细胞释放胰岛素","使细胞内cAMP减少","抑制胰高血糖素作用"],"a":2,"e":"格列本脲属磺酰脲类，阻断胰岛β细胞ATP敏感钾通道，使膜去极化、钙内流，从而刺激胰岛素释放而降糖。增强胰岛素作用、抑制胰高血糖素均非其主要机制；促进葡萄糖分解是双胍类的特点，该类药并不使细胞内cAMP减少"},{"q":"使用氢氯噻嗪时加用螺内酯的主要目的是","o":["增强利尿作用","对抗氢氯噻嗪所致的低血钾","延长氢氯噻嗪的作用时间","对抗氢氯噻嗪的升血糖作用","对抗氢氯噻嗪升高血尿酸的作用"],"a":1,"e":"氢氯噻嗪为排钾利尿药，长期应用易致低血钾；螺内酯竞争醛固酮受体而保钾，二者合用主要是对抗前者所致的低血钾，并协同增强利尿。增强利尿是次要目的而非主要目的；螺内酯并不延长其半衰期，对升血糖、升尿酸亦无针对性拮抗作用"},{"q":"大多数脂溶性药物跨膜转运的方式是","o":["被动转运","膜孔滤过","易化扩散","胞吞","主动转运"],"a":0,"e":"脂溶性药物可直接溶入脂质双分子层，顺浓度梯度扩散跨膜，不耗能、不需载体，属被动转运（简单扩散），是大多数药物的主要转运方式。膜孔滤过限于水溶性小分子；易化扩散虽不耗能但需载体；主动转运逆浓度梯度且耗能，均非脂溶性药物的主要方式"},{"q":"酚妥拉明对间羟胺升压作用的影响是","o":["升压作用增强","升压作用减弱","产生升压翻转效应","升压作用不变","先升压再降压"],"a":1,"e":"间羟胺主要激动α受体并促进去甲肾上腺素释放而升压，酚妥拉明阻断α受体后其升压作用被减弱。升压翻转效应是酚妥拉明对兼有β2激动作用的肾上腺素的特征，对间羟胺、去甲肾上腺素这类以α激动为主者只减弱而不翻转；单纯升压增强或不变均不符合"},{"q":"多黏菌素B的主要不良反应是","o":["肾损害","肝损害","耳毒性","消化道反应","过敏反应"],"a":0,"e":"多黏菌素B与细菌膜磷脂结合，破坏膜通透性，治疗剂量下最突出的是肾损害，表现为蛋白尿、管型尿等，是其首要不良反应。耳毒性是氨基糖苷类的典型毒性；肝损害、消化道反应并非其主要问题，过敏反应亦少见"},{"q":"苯二氮卓类的药理作用机制是","o":["阻断谷氨酸的兴奋作用","抑制GABA代谢增加其脑内含量","激动甘氨酸受体","易化GABA介导的氯离子内流","增加多巴胺刺激的cAMP活性"],"a":3,"e":"苯二氮䓬类与GABA_A受体复合物上的苯二氮䓬位点结合，促进GABA与受体结合，增加氯离子内流频率，从而易化GABA介导的突触抑制。该类药不直接阻断谷氨酸兴奋，也不抑制GABA代谢来增加其含量；激动甘氨酸受体、增加多巴胺刺激cAMP活性均与其中枢抑制机制无关"},{"q":"氨甲苯酸的作用是","o":["增加血小板聚集","促进肝脏合成凝血酶原","促使毛细血管收缩","激活纤溶酶原","对抗纤溶酶原激活因子"],"a":4,"e":"氨甲苯酸是抗纤溶药，竞争性抑制纤溶酶原激活因子，使纤溶酶原不能活化为纤溶酶，从而抑制纤维蛋白溶解而止血。促进肝脏合成凝血酶原是维生素K的作用；激活纤溶酶原恰是链激酶等溶栓药的机制，与其相反；增加血小板聚集、收缩毛细血管均非其机制"},{"q":"下列药物中，几乎无抗炎作用的是","o":["阿司匹林","对乙酰氨基酚","吲哚美辛","双氯芬酸","布洛芬"],"a":1,"e":"对乙酰氨基酚主要通过抑制中枢COX发挥解热镇痛作用，对外周COX抑制很弱，故几乎无抗炎抗风湿作用。阿司匹林、吲哚美辛、双氯芬酸、布洛芬均为非选择性COX抑制药，外周抗炎作用明显，可与本题形成对照"},{"q":"强心苷对下列哪些疾病诱发的心衰疗效较好","o":["瓣膜病、高血压、先天性心脏病","贫血、甲亢、维生素B6缺乏症","肺源性心脏病、心肌损伤、活动性心肌炎","严重二尖瓣狭窄和缩窄性心包炎","伴传导阻滞的心功能不全"],"a":0,"e":"强心苷增强心肌收缩力，对瓣膜病、高血压、先天性心脏病等所致心衰疗效较好，因其主要系心肌收缩功能障碍。肺源性心脏病、活动性心肌炎、心肌损伤疗效差且易中毒；严重二尖瓣狭窄、缩窄性心包炎属机械梗阻，强心苷无效；贫血、甲亢等代谢性病因者疗效亦差，应纠正病因为主"},{"q":"以下哪种细胞是环孢素的主要抑制靶点","o":["巨噬细胞","树突状细胞","自然杀伤细胞","T细胞","B细胞"],"a":3,"e":"环孢素与胞内亲环蛋白结合，抑制钙调磷酸酶，阻断T细胞（尤其辅助性T细胞）活化和白介素-2产生，主要抑制靶点为T细胞。它并不直接杀伤B细胞、巨噬细胞或自然杀伤细胞，对树突状细胞的抗原提呈亦非其主要作用环节"},{"q":"治疗呆小病的药物是","o":["甲巯咪唑","小剂量碘","甲状腺素","丙硫氧嘧啶","卡比马唑"],"a":2,"e":"呆小病因先天性甲状腺功能低下导致智力与体格发育障碍，须尽早补充甲状腺素替代治疗。甲巯咪唑、丙硫氧嘧啶、卡比马唑均抑制甲状腺激素合成，用于甲亢，会加重病情；小剂量碘主要用于单纯性甲状腺肿的防治，不能替代激素"},{"q":"应用奎尼丁治疗心房纤颤合用强心苷的目的是","o":["拮抗奎尼丁引起的血管扩张","对抗奎尼丁引起的心脏抑制","提高奎尼丁的血药浓度","增强奎尼丁的抗心律失常作用","抑制房室结传导，减慢心室率"],"a":4,"e":"奎尼丁转复心房纤颤时因其抗胆碱和扩血管作用可反射性加快心率，合用强心苷旨在抑制房室结传导、减慢心室率。强心苷并不拮抗奎尼丁的血管扩张或心脏抑制，也不提高其血药浓度，更不是增强其抗心律失常作用"},{"q":"去甲肾上腺素禁止肌肉或皮下注射给药，原因是","o":["易致心律失常","升压过强","无效","吸收慢，出现作用慢","强烈收缩局部血管，引起局部组织缺血坏死"],"a":4,"e":"去甲肾上腺素强烈激动α受体，肌肉或皮下注射会使局部血管剧烈收缩，造成局部组织缺血坏死，故禁用于此类给药，只宜静脉滴注。其升压作用强是可控的，并非禁用理由；吸收慢、易致心律失常均非局部给药禁忌的关键"},{"q":"下列哪种药物属于选择性环氧酶-2抑制药","o":["保泰松","阿司匹林","尼美舒利","舒林酸","双氯芬酸"],"a":2,"e":"尼美舒利对环氧酶-2有较高选择性，抑制前列腺素生成而抗炎镇痛，胃肠道不良反应较轻，属选择性环氧酶-2抑制药。保泰松、阿司匹林、舒林酸、双氯芬酸均主要抑制环氧酶-1或为非选择性抑制药，对胃黏膜刺激较大"},{"q":"药物肝肠循环影响了药物在体内的","o":["起效快慢","消除快慢","分布速度","给药途径","与血浆蛋白结合"],"a":1,"e":"肝肠循环指药物随胆汁排入肠道后被重吸收再入肝，使药物在体内停留时间延长、消除减慢，故影响的是消除快慢。它不改变药物起效快慢与分布速度，也不决定给药途径或与血浆蛋白结合的程度。该过程使血药浓度时间曲线出现第二峰，延长药效"},{"q":"用白酒送服2瓶地西泮（2.5mg×100片/瓶），以下可以作为解救药物的是","o":["伊马替尼","氟马西尼","索拉非尼","舒芬太尼","布美他尼"],"a":1,"e":"氟马西尼是苯二氮䓬受体竞争性拮抗剂，可迅速逆转地西泮的中枢抑制，是其中毒的特异解救药。伊马替尼、索拉非尼为抗肿瘤靶向药；舒芬太尼是阿片类镇痛药，可加重呼吸抑制；布美他尼为强效利尿药，均无解毒作用"},{"q":"抗菌谱是","o":["抗菌药物的治疗指数","抗菌药物的抗菌范围","抗菌药物的抗菌能力","抗菌药物的治疗效果","抗菌药物的适应证"],"a":1,"e":"抗菌谱指抗菌药物能够抑制或杀灭病原微生物的范围，是选择用药的基本依据。抗菌能力称为抗菌活性；治疗指数反映药物安全性；治疗效果是临床疗效；适应证是经批准的适用范围，均不等同于抗菌谱"},{"q":"以下哪种药物为α-葡萄糖苷酶抑制剂","o":["甲苯磺丁脲","甲巯咪唑","格列本脲","瑞格列奈","阿卡波糖"],"a":4,"e":"阿卡波糖竞争性抑制小肠刷状缘α-葡萄糖苷酶，延缓淀粉、蔗糖分解为葡萄糖，降低餐后血糖，属α-葡萄糖苷酶抑制剂。甲苯磺丁脲、格列本脲为磺酰脲类促胰岛素分泌药，瑞格列奈为格列奈类，甲巯咪唑则是抗甲状腺药"},{"q":"阿托品抑制腺体分泌作用最弱的是","o":["汗腺分泌","唾液腺分泌","胃酸分泌","呼吸道腺体分泌","泪腺分泌"],"a":2,"e":"阿托品阻断M受体抑制腺体分泌，对唾液腺、汗腺最敏感，呼吸道及泪腺次之；胃酸分泌受迷走、胃泌素与组胺多重调节，阻断M受体仅能轻度抑制，故抑制最弱的是胃酸分泌。其余四项的腺体分泌均易被阿托品明显抑制"},{"q":"治疗窦性心动过速首选的药物是","o":["奎尼丁","普萘洛尔","氟卡尼","苯妥英钠","利多卡因"],"a":1,"e":"窦性心动过速多因交感张力增高，普萘洛尔阻断β受体、减慢窦房结自律性，是首选。利多卡因、苯妥英钠主要针对室性心律失常；奎尼丁用于房性快速心律；氟卡尼为广谱抗心律失常药但非窦速首选。普萘洛尔对甲状腺功能亢进及焦虑所致窦速尤为适用"},{"q":"下列可削弱硝酸酯类的抗心绞痛作用的是","o":["室壁张力降低","心室容积缩小","心室压力降低","心脏体积缩小","心率加快"],"a":4,"e":"硝酸酯扩张静脉与动脉，降低前后负荷和室壁张力而减少心肌耗氧。心率加快会缩短舒张期冠脉灌注并增加耗氧，从而削弱其抗心绞痛作用。室壁张力降低、心室容积缩小、心室压力降低、心脏体积缩小均有利于降低耗氧，不会削弱疗效"},{"q":"用于治疗立克次体引起斑疹伤寒的首选药物是","o":["磺胺嘧啶","红霉素","四环素","氧氟沙星","青霉素G"],"a":2,"e":"四环素类能抑制立克次体蛋白质合成，是立克次体所致斑疹伤寒的首选。青霉素G、红霉素、氧氟沙星、磺胺嘧啶均非首选，其中磺胺类甚至可促进立克次体繁殖，不宜用于立克次体感染。多西环素同属四环素类，亦可作为替代药物"},{"q":"为使口服药物加速达到有效血浆浓度，缩短到达坪值时间，并维持体内药量在D～2D之间，应采取如下给药方案","o":["首剂给2D，维持量为2D/2t1/2","首剂给3D，维持量为D/t1/2","首剂给2D，维持量为2D/t1/2","首剂给3D，维持量为D/2t1/2","首剂给2D，维持量为D/t1/2"],"a":4,"e":"为使血药浓度迅速达标并维持体内药量在D至2D之间，首剂给负荷量2D，随后每个半衰期给维持量D（即D/t1/2），使消除量恰由每次给药补充。首剂3D或维持量用2D/t1/2、D/2t1/2均会使药量超出该范围或蓄积"},{"q":"下列药物中，不属于一氧化氮供体的是","o":["硝普钠","硝酸甘油","西地那非","硝苯地平","戊四硝酯"],"a":3,"e":"硝苯地平属二氢吡啶类钙通道阻滞药，通过阻断钙内流扩张血管，本身不释放一氧化氮，不属于一氧化氮供体。硝普钠、硝酸甘油、戊四硝酯均为硝酸酯类可释放一氧化氮；西地那非抑制磷酸二酯酶而增强一氧化氮效应"},{"q":"长期应用苯妥英钠可导致双香豆素","o":["作用增强","作用减弱","作用加快","作用时间延长","吸收增加"],"a":1,"e":"苯妥英钠是肝药酶诱导剂，可加速双香豆素在肝内的代谢灭活，使其抗凝作用减弱。它不影响双香豆素的吸收，也不改变其作用快慢，更不会使其作用增强或时间延长；合用时需监测凝血功能并调整剂量"},{"q":"长期大量应用易导致人体叶酸缺乏的药物是","o":["TMP","红霉素","四环素","链霉素","青霉素G"],"a":0,"e":"TMP（甲氧苄啶）抑制细菌二氢叶酸还原酶，长期大量应用也可抑制人体叶酸代谢，导致叶酸缺乏，故需监测。红霉素、四环素、链霉素通过抑制蛋白质合成抗菌，青霉素G抑制细胞壁合成，均无引起叶酸缺乏的作用"},{"q":"药效学主要研究","o":["药物的跨膜转运","药物的生物转化","药物的时量关系","药物对机体作用","血药浓度的昼夜节律"],"a":3,"e":"药效学研究药物对机体的作用及其作用机制，包括治疗作用与不良反应。药物的跨膜转运、生物转化、时量关系及血药浓度昼夜节律均属药动学范畴，描述机体对药物的处置规律，而非药物对机体的影响"},{"q":"应用地高辛治疗心房纤颤，减慢心室率主要作用是","o":["抑制房室结传导","加速房室结传导","抑制浦肯野纤维传导","加速浦肯野纤维传导","抑制窦房结传导"],"a":0,"e":"地高辛治疗心房纤颤时通过兴奋迷走神经抑制房室结传导，使过多房性冲动不能下传，从而减慢心室率。它并不加速房室结传导；浦肯野纤维传导受抑制主要与室性心律失常有关；窦房结传导抑制并非其减慢心室率的主要环节"},{"q":"下列属于药物基本作用的是","o":["治疗与不良反应","治疗与预防作用","对因治疗和对症治疗","兴奋和抑制作用","局部与吸收作用"],"a":3,"e":"药物对机体的基本作用表现为兴奋与抑制，分别是功能增强和功能减弱。治疗与不良反应、对因与对症治疗、局部与吸收作用是按不同标准对作用的分类，并非基本作用本身。这是药物作用最基本的两种表现形式"},{"q":"阿司匹林预防血栓形成的机制是","o":["抑制TXA2合成","促进PGI2合成","促进TXA2合成","抑制PGI2合成","抑制凝血酶原"],"a":0,"e":"阿司匹林不可逆乙酰化血小板环氧酶-1，减少血栓素A2（TXA2）合成，从而抑制血小板聚集、预防血栓形成。它不促进前列环素（PGI2）合成；低剂量对PGI2影响很小，并非通过抑制PGI2或抑制凝血酶原起作用"},{"q":"为预防长期大量服用阿司匹林引起出血，应选用下列哪个药物","o":["维生素C","维生素K","维生素B1","维生素A","维生素E"],"a":1,"e":"长期大量服用阿司匹林可抑制凝血酶原合成并抑制血小板聚集而致出血，维生素K能促进凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，故用于预防。维生素C、B1、A、E均不参与这些凝血因子的合成，无相应对抗出血作用"},{"q":"激动M受体不会引起","o":["支气管平滑肌收缩","骨骼肌收缩","胃肠道平滑肌收缩","膀胱逼尿肌收缩","睫状肌收缩"],"a":1,"e":"激动M受体可使支气管、胃肠道、膀胱逼尿肌及睫状肌等平滑肌收缩，并促进腺体分泌。骨骼肌收缩由运动神经终板的N_M受体介导，与M受体无关，故激动M受体不会引起骨骼肌收缩。睫状肌收缩致调节痉挛亦为M样效应"},{"q":"巴比妥类药物中毒时，静脉滴注碳酸氢钠是有效的解毒措施，其基本原因是","o":["减少巴比妥类药物从胃吸收","加速巴比妥类药物在体内破坏","对抗巴比妥类药物在中枢抑制","减少脑细胞中药物含量，加快从肾脏排泄","切断了巴比妥类药物的肠肝循环"],"a":3,"e":"巴比妥类为弱酸性药物，静脉滴注碳酸氢钠可碱化血液和尿液：一方面使脑细胞内药物向血浆转移，降低脑中药物含量；另一方面使肾小管中药物解离、减少重吸收，加快肾脏排泄。它不减少胃肠吸收，也不加速体内破坏或直接对抗中枢抑制"},{"q":"药物激动或阻断相应受体，取决于","o":["药物的化学结构","药物的剂量大小","药物内在活性的大小","药物与受体的亲和力强弱","药物的剂型"],"a":2,"e":"药物与受体结合后是激动还是阻断，取决于其内在活性：内在活性强者激动受体，无内在活性者虽能结合却阻断受体。亲和力只决定结合的牢固程度，与剂量、剂型、化学结构均不能直接判断是否激动或阻断"},{"q":"肼屈嗪降压作用方式是","o":["直接扩张小动脉","阻断外周α受体","耗竭肾上腺素能神经末梢的NA","抑制肾素释放","阻断中枢α受体"],"a":0,"e":"肼屈嗪直接松弛小动脉平滑肌，降低外周阻力而降压，主要用于中度高血压。阻断外周α受体是酚妥拉明的作用；耗竭去甲肾上腺素是利血平的机制；抑制肾素释放为β受体阻断药等，均非肼屈嗪的降压方式"},{"q":"普萘洛尔抗心绞痛的原理是","o":["延长射血时间","降低心肌耗氧量","增加前负荷","扩张动脉增加心肌供氧","降低外周阻力"],"a":1,"e":"普萘洛尔阻断心脏β受体，减慢心率、减弱心肌收缩力，从而显著降低心肌耗氧量而抗心绞痛。它延长射血时间、增加前负荷属不利因素；扩张动脉增加供氧是硝酸酯或钙拮抗剂的特点，普萘洛尔并无此作用"},{"q":"明朝时期编著，收载药物1890余种，被译成英、日、朝等七种文本的中国古典药物学巨著是","o":["《本草纲目》","《神农本草经》","《新修本草》","《黄帝内经》","《伤寒论》"],"a":0,"e":"《本草纲目》为明代李时珍编著，收载药物1890余种，被译成多国文字，是中国古典药物学巨著。《神农本草经》成书于汉代；《新修本草》为唐代官修药典；《黄帝内经》《伤寒论》皆为经典医著而非本草巨著"},{"q":"与口服给药相比，直肠给药的最主要优点是","o":["适用于昏迷、抽搐等不能口服","在一定程度上避免首过消除","吸收缓慢","适用于对胃刺激引起呕吐的药物","作用持久"],"a":1,"e":"直肠给药时栓剂经直肠下静脉回流，部分绕过肝脏，最主要优点是在一定程度上避免首过消除、提高生物利用度。适用于昏迷抽搐不能口服、避免胃刺激呕吐及作用持久虽是特点，但均非其区别于口服的主要药动学优势"},{"q":"下列疾病最适宜选用选择性M1受体阻断药治疗的是","o":["膀胱过度活动症","消化性溃疡","青光眼","支气管哮喘","妊娠呕吐"],"a":1,"e":"选择性M1受体阻断药哌仑西平抑制胃壁细胞M1受体，减少胃酸分泌，最适宜治疗消化性溃疡。膀胱过度活动症宜用M3受体阻断药；青光眼需用M受体激动药缩瞳降眼压；支气管哮喘、妊娠呕吐均非M1阻断药的适应证"},{"q":"脑内的胆碱受体以何种受体为主","o":["M1","M2","M3","M4","N"],"a":0,"e":"脑内胆碱受体以M1亚型为主，尤分布于大脑皮层与海马，参与学习记忆等中枢功能。M2多为心脏等外周突触前自身受体，M3主要在外分泌腺与平滑肌，M4、M5分布较少，N受体属烟碱型，均非脑内主要胆碱受体"},{"q":"维拉帕米不能用于治疗","o":["心绞痛","慢性心功能不全","高血压","室上性心动过速","心房纤颤"],"a":1,"e":"维拉帕米为非二氢吡啶类钙通道阻滞药，有明显负性肌力作用，可抑制心功能，故不能用于慢性心功能不全。它对心绞痛、高血压、室上性心动过速及心房纤颤伴快心室率均有较好疗效。其负性肌力作用在心功能不全者尤其危险"},{"q":"长期应用糖皮质激素可引起","o":["高血钙","高血钾","高血镁","高血磷","低血钾"],"a":4,"e":"长期大量应用糖皮质激素具有盐皮质激素样作用，促进肾排钾，引起低血钾，还可致水钠潴留、高血压。高血钙、高血钾、高血镁、高血磷均非其典型电解质紊乱，反而该类药可致钙丢失、低血钾。补钾并监测电解质是长期用药的必要措施"},{"q":"以下哪种类型的癫痫发作又称为癫痫小发作","o":["单纯性局限性发作","复合性局限性发作","失神性发作","肌阵挛性发作","强直-阵挛性发作"],"a":2,"e":"失神性发作突发短暂意识丧失、双眼凝视，脑电图呈3Hz棘慢波，又称癫痫小发作，多见于儿童。强直-阵挛性发作才是癫痫大发作；单纯或复合性局限性发作、肌阵挛性发作均为其他发作类型。乙琥胺与丙戊酸钠是小发作的常用药"},{"q":"属于抗雄激素类药物的是","o":["黄体酮","己烯雌酚","氯米芬","米非司酮","环丙孕酮"],"a":4,"e":"环丙孕酮为雄激素受体拮抗药，能竞争性阻断雄激素作用，属抗雄激素类药物，临床用于前列腺癌及多毛症等。黄体酮为孕激素，己烯雌酚为雌激素，氯米芬促排卵，米非司酮为抗孕激素药，均非抗雄激素药"},{"q":"青霉素G不宜口服的原因是","o":["脂溶性低","易被胃酸及消化酶破坏，吸收少且不规则","口服后达峰时间长","主要分布于细胞外液","几乎全部以原形经尿排泄"],"a":1,"e":"青霉素G不耐酸，口服易被胃酸及消化酶破坏，吸收少且不规则，血药浓度难以保证，故一般采用肌内注射或静脉给药。其脂溶性、达峰时间、体内分布及以原形经肾排泄的特点，均不是不宜口服的原因"},{"q":"普萘洛尔抗心律失常作用机制不包括","o":["阻断心脏β受体","降低窦房结、浦肯野纤维自律性","减少儿茶酚胺所致的迟后除极","减慢房室结传导，延长其有效不应期","开放乙酰胆碱敏感性钾通道"],"a":4,"e":"普萘洛尔抗心律失常通过阻断心脏β受体，降低窦房结与浦肯野纤维自律性，减慢房室结传导并延长有效不应期，减少儿茶酚胺所致迟后除极。开放乙酰胆碱敏感性钾通道是乙酰胆碱等拟胆碱作用，不属普萘洛尔机制"},{"q":"卵巢功能不全和闭经宜选用的药物是","o":["黄体酮","甲基睾丸酮","氯米芬","己烯雌酚","双醋炔诺醇"],"a":3,"e":"卵巢功能不全与闭经系雌激素缺乏所致，宜用雌激素己烯雌酚替代治疗，促进女性第二性征及子宫内膜发育。氯米芬用于促排卵，甲基睾丸酮为雄激素，双醋炔诺醇为孕激素，黄体酮用于黄体功能不足，均非该证首选"},{"q":"对抗局麻药中毒引起的惊厥，首选的药物是","o":["地西泮","苯妥英钠","硫喷妥钠","苯巴比妥","水合氯醛"],"a":0,"e":"地西泮增强中枢GABA能抑制，抗惊厥作用强、安全范围大，是对抗局麻药中毒所致惊厥的首选。苯妥英钠、苯巴比妥、水合氯醛虽也抗惊厥但起效慢或毒性较大；硫喷妥钠主要用于麻醉诱导，不作首选"},{"q":"卡托普利发挥降压作用主要是通过","o":["直接舒张血管平滑肌","兴奋中枢α受体","阻滞钙通道","抑制血管紧张素转化酶","利尿作用"],"a":3,"e":"卡托普利含巯基，抑制血管紧张素转化酶，使血管紧张素Ⅱ生成减少、醛固酮分泌下降并扩张血管，从而降压。它不直接舒张平滑肌，不阻滞钙通道，不兴奋中枢α受体，其降压亦非利尿作用所致。其缓激肽蓄积还可引起干咳，为该药特征性不良反应"},{"q":"TMP与SMZ联合用药的机制是","o":["增加SMZ吸收","增加TMP吸收","减慢SMZ的消除","发挥协同抗菌作用","减慢TMP的消除"],"a":3,"e":"TMP抑制二氢叶酸还原酶，SMZ抑制二氢蝶酸合酶，两者序贯阻断细菌叶酸合成，形成双重阻断而发挥协同抗菌作用，可使抑菌转为杀菌。它们并不互相增加吸收，也不减慢彼此消除，联用意义在于抗菌协同而非药动学影响"},{"q":"巴比妥类药物中毒用碳酸氢钠的目的是","o":["酸碱中和解毒","促进其经肾排泄","防止酸中毒","对抗中枢抑制","促进其经生物膜扩散"],"a":1,"e":"巴比妥类为弱酸性药物，中毒时给予碳酸氢钠碱化尿液，使肾小管中药物解离增多、重吸收减少，从而促进其经肾排泄。该措施并非酸碱中和解毒，也不对抗中枢抑制，更不是防止酸中毒或促进经生物膜扩散"},{"q":"心率受阿托品影响最明显的人群是","o":["老年人","青壮年人","婴幼儿","正在运动的人","迷走神经张力低的人"],"a":1,"e":"阿托品阻断M受体，解除迷走神经对心脏的抑制，使心率加快。青壮年迷走神经张力较高，故心率受阿托品影响最明显；老年人及婴幼儿迷走张力偏低，正在运动者交感兴奋占优，迷走张力低者本身抑制弱，影响均较小"},{"q":"以下哪项免疫调节药物由真菌代谢产物中提取的环状多肽","o":["环孢素","他克莫司","环磷酰胺","干扰素","泼尼松"],"a":0,"e":"环孢素是从真菌代谢产物中提取的环状多肽，选择性抑制T细胞活化，是常用免疫抑制剂。他克莫司为真菌来源的大环内酯类，环磷酰胺是烷化剂，干扰素为细胞因子，泼尼松为糖皮质激素，化学本质均不符"},{"q":"下列哪项不是中枢乙酰胆碱的功能","o":["觉醒","学习","记忆","运动调节","中枢抑制"],"a":4,"e":"中枢乙酰胆碱参与觉醒、学习、记忆及运动调节等兴奋性功能，是重要的兴奋性递质。中枢抑制主要由γ-氨基丁酸、甘氨酸等抑制性递质介导，不属于中枢乙酰胆碱的功能。胆碱能神经元功能亢进与帕金森病、阿尔茨海默病相关"},{"q":"药物在肝脏生物转化，不属于第一步反应的是","o":["氧化","还原","水解","结合","去硫"],"a":3,"e":"肝脏生物转化第一步为Ⅰ相反应，包括氧化、还原、水解，去硫即脱硫属氧化反应。结合反应（葡萄糖醛酸化、硫酸化等）属第二步Ⅱ相反应，故不属于第一步；其余各项均为Ⅰ相反应。Ⅰ相反应引入或暴露极性基团，为Ⅱ相结合创造条件"},{"q":"某患者诊断为钩端螺旋体病，治疗药物首选","o":["四环素","红霉素","庆大霉素","氨苄西林","青霉素G"],"a":4,"e":"钩端螺旋体对青霉素G高度敏感，青霉素G杀菌力强，是钩端螺旋体病的首选，早期足量应用疗效佳。四环素、红霉素、氨苄西林可作替代或用于预防，庆大霉素对螺旋体作用差，均非首选。青霉素过敏者可改用四环素或多西环素"},{"q":"以下药物对胃的刺激性较大的是","o":["地西泮","水合氯醛","苯巴比妥","甲丙氨酯","硫喷妥钠"],"a":1,"e":"水合氯醛口服对胃黏膜有强烈刺激，可引起恶心、呕吐，故胃溃疡患者慎用，常稀释后保留灌肠给药。地西泮、苯巴比妥、甲丙氨酯、硫喷妥钠对胃的刺激性均明显小于水合氯醛。其代谢产物三氯乙醇仍有镇静作用，维持时间较长"},{"q":"青霉素类最严重的不良反应为","o":["肝毒性","肾毒性","耳毒性","过敏性休克","二重感染"],"a":3,"e":"青霉素类最严重的不良反应是过敏性休克，属Ⅰ型变态反应，可在用药后数分钟内发生，须立即皮下注射肾上腺素抢救。肝毒性、肾毒性、耳毒性、二重感染虽可发生，但均不如过敏性休克凶险和危急。用药前应常规做皮试并备好抢救药品"},{"q":"通过改变细菌细胞膜功能而产生抗菌作用的药物是","o":["四环素","多黏菌素B","红霉素","链霉素","氯霉素"],"a":1,"e":"多黏菌素B与革兰阴性菌细胞膜磷脂结合，破坏膜的通透性，使胞内成分外漏而杀菌，是通过改变细胞膜功能抗菌的药物。四环素、红霉素、链霉素、氯霉素均通过抑制细菌蛋白质合成发挥作用。因其毒性较大，现多局部应用或作最后选择"},{"q":"下列疾病中宜采用阿托品进行治疗的是","o":["室性心动过速","窦房阻滞","室上性心动过速","缺血性心脏病","窦性心动过速"],"a":1,"e":"阿托品解除迷走神经对心脏的抑制，加快心率、改善传导，可用于窦房阻滞、房室阻滞等缓慢性心律失常。室性心动过速、室上性心动过速及缺血性心脏病用阿托品加快心率会加重病情，窦性心动过速本已心率增快，更不宜使用"},{"q":"可抑制骨髓造血功能的药物是","o":["四环素","米诺环素","氯霉素","红霉素","氨苄西林"],"a":2,"e":"氯霉素最突出的严重不良反应是抑制骨髓造血功能，可引起再生障碍性贫血，与剂量无关且死亡率高，故应用受限。四环素、米诺环素、红霉素、氨苄西林均无明显的骨髓造血抑制作用。故用药期间应定期检查血象"},{"q":"他汀类药物是","o":["胆碱酯酶抑制药","碳酸酐酶抑制药","HMG-CoA还原酶抑制药","Na＋、K＋-ATP酶抑制药","磷酸二酯酶抑制药"],"a":2,"e":"他汀类竞争性抑制HMG-CoA还原酶，阻断胆固醇合成的关键步骤，降低血胆固醇，是调血脂药。胆碱酯酶抑制药如新斯的明，碳酸酐酶抑制药如乙酰唑胺，Na⁺-K⁺-ATP酶抑制药如地高辛，磷酸二酯酶抑制药如西地那非，机制各异"},{"q":"与药物的过敏反应无关的是","o":["药物的代谢产物","制剂中的杂质","患者的体质","遗传因素","药物的剂量"],"a":4,"e":"过敏反应是抗原抗体介导的变态反应，与药物剂量无关，微量即可触发，与药物代谢产物、制剂杂质、患者体质及遗传因素有关。故药物的剂量与过敏反应无关，其余四项均为影响因素。过敏反应属于变态反应，与药理作用及剂量均无关"},{"q":"下列哪种类型的癫痫首选苯妥英钠","o":["局限性发作","癫痫小发作","肌阵挛性发作","婴儿痉挛","精神运动性发作"],"a":0,"e":"苯妥英钠对癫痫大发作和局限性发作疗效好，是首选之一，通过阻滞钠通道稳定神经元膜。癫痫小发作（失神发作）首选乙琥胺，苯妥英钠无效甚至加重；肌阵挛性发作、婴儿痉挛、精神运动性发作均非其首选"},{"q":"糖皮质激素隔日清晨一次给药法，可避免","o":["对胃酸胃蛋白酶分泌的刺激作用","类肾上腺皮质功能亢进综合征","反跳现象","诱发和加重感染","反馈性抑制垂体-肾上腺皮质轴机能"],"a":4,"e":"糖皮质激素分泌有昼夜节律，清晨分泌达峰。隔日清晨一次给药可顺应生理节律，显著减轻对垂体-肾上腺皮质轴的反馈性抑制，避免肾上腺皮质萎缩。反跳现象、类库欣综合征、诱发感染、刺激胃酸分泌并不能靠该方案避免"},{"q":"青霉素对以下哪种病原体引起的感染多数抗药","o":["钩端螺旋体","白喉杆菌","肺炎球菌","肠球菌","放线菌"],"a":3,"e":"青霉素对肠球菌多数耐药，抗菌活性差，肠球菌感染常需氨苄西林联合氨基糖苷类。对钩端螺旋体、白喉杆菌、肺炎球菌、放线菌等，青霉素G仍为敏感或首选药物，抗菌效果良好。肠球菌感染多需联合用药或选用万古霉素"},{"q":"硫酸镁中毒导致血压下降时，最佳选择的治疗药物是","o":["肾上腺素","异丙肾上腺素","去甲肾上腺素","氯化钙","50%葡萄糖"],"a":3,"e":"硫酸镁中毒时血镁过高抑制神经肌肉及心血管，氯化钙提供的钙离子与镁离子竞争结合位点，可迅速对抗镁的毒性，是最佳解救药。肾上腺素、异丙肾上腺素、去甲肾上腺素均为升压药，50%葡萄糖也无拮抗镁离子的作用"},{"q":"骨质疏松症的主要特征不包括","o":["骨量降低","骨脆性降低","骨组织微细结构破坏","骨的力学功能减弱","是一种全身代谢性疾病"],"a":1,"e":"骨质疏松症以骨量降低、骨组织微细结构破坏、骨脆性增加和力学功能减弱为特征，是全身代谢性骨病，易发生骨折。骨脆性降低与事实相反，骨脆性升高才是其特征，故该项不属于主要特征。诊断以骨密度降低和脆性骨折为重要依据"},{"q":"用于治疗阿尔茨海默病的胆碱酯酶抑制药是","o":["左旋多巴","占诺美林","多奈哌齐","美金刚","苯海索"],"a":2,"e":"多奈哌齐是中枢胆碱酯酶抑制药，增加脑内乙酰胆碱含量，改善阿尔茨海默病患者的认知功能。左旋多巴用于帕金森病，占诺美林为M1受体激动药，美金刚为NMDA受体拮抗药，苯海索为中枢抗胆碱药，机制均不同"},{"q":"激动后，可促进肾素分泌的是","o":["α1受体","α2受体","β1受体","β2受体","β3受体"],"a":2,"e":"肾小球旁器细胞上的β1受体激动后，激活腺苷酸环化酶、升高cAMP，促进肾素分泌，进而启动肾素-血管紧张素-醛固酮系统。α1、α2受体及β2、β3受体激动均不以促进肾素分泌为主要效应"},{"q":"去甲肾上腺素生物合成过程中的限速酶是","o":["多巴脱羧酶","多巴胺β-羟化酶","酪氨酸羟化酶","儿茶酚胺氧位甲基转移酶","单胺氧化酶"],"a":2,"e":"去甲肾上腺素合成以酪氨酸为原料，酪氨酸羟化酶催化生成多巴，是整个合成过程的限速酶，受终产物反馈抑制。多巴脱羧酶、多巴胺β-羟化酶催化后续步骤，儿茶酚胺氧位甲基转移酶与单胺氧化酶则负责降解"},{"q":"吗啡引起瞳孔缩小的机制是","o":["激动虹膜括约肌M受体","阻滞虹膜辐射肌α受体","直接兴奋虹膜括约肌","兴奋支配瞳孔的副交感神经，瞳孔括约肌收缩","激动睫状肌β受体"],"a":3,"e":"吗啡激动中枢阿片受体，兴奋支配瞳孔的副交感神经（动眼神经），使瞳孔括约肌收缩，出现针尖样瞳孔，这是其中毒特征之一。虹膜括约肌上主要为M受体，吗啡并非直接激动该受体或直接兴奋括约肌，激动睫状肌β受体更无关"},{"q":"能与林可霉素竞争同一结合部位，呈拮抗作用的药物是","o":["链霉素","万古霉素","青霉素","红霉素","替考拉宁"],"a":3,"e":"红霉素与林可霉素均作用于细菌核糖体50S亚基，结合部位相同或相近，合用可相互竞争而呈拮抗，故不宜联用。链霉素作用于30S亚基，万古霉素、替考拉宁作用于细胞壁，青霉素抑制细胞壁合成，均无此竞争关系"},{"q":"下列四环素类药物中，抗菌作用最强的是","o":["米诺环素","多西环素","四环素","土霉素","金霉素"],"a":0,"e":"米诺环素（二甲胺四环素）口服吸收好、组织穿透力强，是四环素类中抗菌作用最强者。多西环素抗菌活性次之，四环素、土霉素、金霉素抗菌作用相对较弱，且金霉素因毒性大现多外用。其脂溶性高，易透过血脑屏障及组织屏障"},{"q":"氯丙嗪引起锥体外系反应的机制是","o":["阻断肾上腺素α受体","阻断结节-漏斗系统D2受体","阻断中脑-边缘系统D2样受体","阻断中脑-皮层系统的D2样受体","阻断黑质-纹状体系统D2受体"],"a":4,"e":"氯丙嗪阻断黑质-纹状体通路D2受体，使纹状体多巴胺功能减弱、乙酰胆碱相对亢进，引起锥体外系反应。阻断中脑-边缘与中脑-皮层D2样受体产生抗精神病疗效；阻断结节-漏斗D2受体致内分泌紊乱；阻断α受体致体位性低血压"},{"q":"乙酰胆碱的主要消除方式是","o":["被单胺氧化酶所破坏","被氧位甲基转移酶破坏","被磷酸二酯酶破坏","被乙酰胆碱酯酶破坏","被神经末梢再摄取"],"a":3,"e":"乙酰胆碱释放入突触间隙后，主要被乙酰胆碱酯酶迅速水解为胆碱和乙酸而消除，作用短暂。单胺氧化酶、儿茶酚胺氧位甲基转移酶主要降解单胺类递质，磷酸二酯酶水解cAMP，神经末梢再摄取亦非其主要消除方式"},{"q":"可首选治疗流行性脑脊髓膜炎的药物是","o":["甲氧苄啶","司帕沙星","氧氟沙星","磺胺嘧啶银","磺胺嘧啶"],"a":4,"e":"磺胺嘧啶血浆蛋白结合率适中，易透过血脑屏障，在脑脊液中浓度较高，是治疗流行性脑脊髓膜炎的首选。甲氧苄啶单用易耐药；氧氟沙星、司帕沙星为喹诺酮类，非首选；磺胺嘧啶银主要用于烧伤创面"},{"q":"选择性M1受体阻断药是","o":["阿托品","东莨菪碱","贝那替秦","溴丙胺太林","哌仑西平"],"a":4,"e":"哌仑西平选择性阻断M1受体，抑制胃酸与胃蛋白酶分泌，是选择性M1受体阻断药。阿托品、东莨菪碱、溴丙胺太林均阻断多种M受体亚型，选择性差；贝那替秦为解痉药，亦非选择性M1阻断药。该药对胃酸分泌的抑制优于一般解痉药"},{"q":"阿托品对眼的作用表现为","o":["降低眼内压","调节痉挛","缩瞳","收缩瞳孔括约肌","调节晶状体扁平"],"a":4,"e":"阿托品阻断睫状肌M受体，使睫状肌松弛、悬韧带拉紧，晶状体变扁平，屈光度降低而致调节麻痹，便于验光。它同时散瞳并升高眼内压，故不降低眼内压；调节痉挛、缩瞳、收缩瞳孔括约肌均为拟胆碱药的作用"},{"q":"新斯的明不宜用于治疗","o":["青光眼","手术后尿潴留","阵发性室上性心动过速","筒箭毒碱过量中毒","重症肌无力"],"a":0,"e":"新斯的明抑制胆碱酯酶、增强胆碱能作用，可收缩瞳孔括约肌、使房角变窄、升高眼内压，故不宜用于青光眼。它对重症肌无力、手术后尿潴留、阵发性室上性心动过速及筒箭毒碱过量中毒均有治疗作用"},{"q":"下列药物中具有内在拟交感活性的是","o":["普萘洛尔","纳多洛尔","噻吗洛尔","吲哚洛尔","阿替洛尔"],"a":3,"e":"吲哚洛尔除阻断β受体外尚具有内在拟交感活性，可部分激动受体，故心率抑制较轻。普萘洛尔、纳多洛尔、噻吗洛尔、阿替洛尔均为无内在拟交感活性的β受体阻断药。这一特性使其在降压时较少引起心动过缓"},{"q":"对急性痛风有效的药物是","o":["秋水仙碱","别嘌醇","丙磺舒","阿司匹林","保泰松"],"a":0,"e":"秋水仙碱抑制微管聚合与白细胞趋化，迅速控制急性痛风性关节炎的炎症与疼痛，对急性痛风有效。别嘌醇抑制尿酸生成、丙磺舒促进尿酸排泄，均用于慢性痛风缓解期，急性期单用可加重或延长发作；阿司匹林、保泰松非首选"},{"q":"骨折剧痛，宜选用的止痛药是","o":["可待因","氯丙嗪","罗通定","吲哚美辛","哌替啶"],"a":4,"e":"骨折剧痛属剧烈锐痛，哌替啶为阿片类镇痛药，激动中枢阿片受体，镇痛作用强、起效快，宜选用。可待因、罗通定镇痛较弱，适用于轻中度疼痛；吲哚美辛抗炎镇痛，对剧痛乏力；氯丙嗪无镇痛作用。但其代谢产物去甲哌替啶蓄积可致惊厥，不宜长期大量用"},{"q":"对毒性反应的描述错误的是","o":["在药物剂量过大时可能会发生","一般可以预知","导致畸胎不属于毒性反应","药物在体内蓄积过多时可能会发生","包括急性毒性反应和慢性毒性反应"],"a":2,"e":"毒性反应指剂量过大或蓄积过多引起的机体损害，一般可以预知，分急性毒性与慢性毒性。致畸属于特殊毒性（三致），是毒性反应的一种，故“导致畸胎不属于毒性反应”的说法错误。三致反应属于慢性毒性的特殊类型"},{"q":"药物或其代谢物排泄的主要途径是","o":["肾","胆道","肠道","汗腺","肺"],"a":0,"e":"肾是药物及其代谢物排泄的主要途径，多数药物以原形或代谢物经肾小球滤过、肾小管分泌随尿排出。胆道、肠道、汗腺、肺也可排泄部分药物，但均非主要途径。肾功能不全时药物排泄受阻，易致蓄积中毒，需调整剂量"},{"q":"关于糖皮质激素抗炎作用的基本机制，错误的是","o":["与靶细胞质内的糖皮质激素受体结合，而影响了参与炎症的一些基因转录","可抑制炎性介质白三烯等的生成","直接杀灭细菌","抑制一氧化氮合酶的表达","对细胞能量代谢有直接影响"],"a":2,"e":"糖皮质激素抗炎通过与胞内受体结合，影响炎症相关基因转录，抑制磷脂酶A2及白三烯等炎性介质生成，抑制一氧化氮合酶表达，并影响细胞能量代谢。它并无直接杀灭细菌的作用，反而降低机体防御，故该项错误"},{"q":"可用于治疗高钙血症的药物是","o":["阿米洛利","氨苯喋啶","呋塞米","氢氯噻嗪","螺内酯"],"a":2,"e":"呋塞米抑制髓袢升支粗段Na⁺-K⁺-2Cl⁻共转运，促进钙排泄，可用于高钙血症。氢氯噻嗪促进远曲小管对钙的重吸收，可降低尿钙，用于含钙肾结石；阿米洛利、氨苯蝶啶、螺内酯为保钾利尿药，不用于高钙血症"},{"q":"首过消除主要发生在","o":["口服给药","肌内注射","静脉推注","腹腔注射","静脉滴注"],"a":0,"e":"口服药物经胃肠道吸收后由门静脉进入肝脏，部分被代谢灭活，使进入体循环的药量减少，即首过消除，故主要发生于口服给药。肌内注射、静脉推注、腹腔注射、静脉滴注均可不同程度避开肝脏首过效应"},{"q":"可用于各种局部麻醉方法的局麻药是","o":["丁卡因","利多卡因","普鲁卡因","丁哌卡因","罗哌卡因"],"a":1,"e":"利多卡因穿透力强、弥散广、作用快而维持时间适中、毒性较小，可用于表面、浸润、传导、蛛网膜下腔及硬膜外麻醉等各种局部麻醉。丁卡因毒性大不作浸润麻醉，普鲁卡因穿透力差不宜表面麻醉，丁哌卡因、罗哌卡因应用范围相对受限"},{"q":"肾绞痛时宜选用的治疗药物组合是","o":["阿托品和新斯的明合用","东莨菪碱和毒扁豆碱合用","哌替啶和吗啡合用","阿托品和哌替啶合用","东莨菪碱和哌替啶合用"],"a":3,"e":"肾绞痛系输尿管平滑肌剧烈痉挛所致，阿托品阻断M受体解痉，哌替啶激动阿片受体镇痛，二者合用标本兼治。吗啡可收缩平滑肌、加重痉挛，故不首选；单用解痉或阿托品与新斯的明、东莨菪碱与毒扁豆碱合用均不合理"},{"q":"下列有关于抗贫血药铁剂的描述，不正确的是","o":["Fe2＋易于吸收","铁剂和维生素C同服不利于吸收","鞣质不利于铁剂的吸收","铁剂和牛奶同服不利于吸收","四环素会影响铁剂的吸收"],"a":1,"e":"维生素C为还原剂，可将难以吸收的三价铁还原为易吸收的二价铁，促进铁吸收，故“铁剂和维生素C同服不利于吸收”的说法错误。鞣质、牛奶中的钙和磷酸盐、四环素均可与铁形成难溶物或络合物，妨碍铁吸收；Fe²⁺易被吸收"},{"q":"治疗重症肌无力应选用","o":["新斯的明","毛果芸香碱","毒扁豆碱","筒箭毒碱","碘解磷定"],"a":0,"e":"重症肌无力因神经肌肉接头处乙酰胆碱受体减少，新斯的明抑制胆碱酯酶、减少乙酰胆碱水解，并直接激动N_M受体，显著增强肌力，是首选。毒扁豆碱主要用于青光眼；筒箭毒碱阻断N_M受体，会加重肌无力；碘解磷定用于有机磷中毒；毛果芸香碱为M受体激动药"},{"q":"药动学中房室模型中的房室划分是基于","o":["药物的代谢率","药物的转运速率","药物的吸收率","药物的排泄速率","药物的分布容积"],"a":1,"e":"房室模型依据药物在体内各组织间转运（分布）速率的快慢划分，转运速率相近的组织归为同一房室，故基于药物的转运速率。代谢率、吸收率、排泄速率反映的是消除与摄入过程，分布容积是空间参数，均非划分依据"},{"q":"属于β-肾上腺素受体激动药的平喘药是","o":["沙丁胺醇","胆茶碱","酮替芬","布地奈德","扎鲁司特"],"a":0,"e":"沙丁胺醇选择性激动支气管β2受体，激活腺苷酸环化酶使cAMP升高，舒张支气管平滑肌而平喘，属β肾上腺素受体激动药。胆茶碱为黄嘌呤类，酮替芬为抗过敏药，布地奈德为糖皮质激素，扎鲁司特为白三烯受体拮抗药"},{"q":"对临床MRSA作用强，被誉为“抗生素的最后一道防线”的药物是","o":["多黏菌素B","阿奇霉素","多西霉素","万古霉素","林可霉素"],"a":3,"e":"万古霉素对耐甲氧西林金黄色葡萄球菌（MRSA）作用强，是治疗严重MRSA感染的特效药，被誉为“抗生素的最后一道防线”。多黏菌素B主要针对革兰阴性菌，阿奇霉素、多西霉素、林可霉素对MRSA疗效差或易耐药"},{"q":"某患者诊断为梅毒感染，治疗药物首选青霉素G，其抗菌作用机制为","o":["抑制细菌细胞壁的合成","改变胞浆膜的通透性","抑制细菌蛋白质的合成","抑制细菌叶酸的合成","抑制细菌DNA的复制"],"a":0,"e":"青霉素G与细菌细胞壁肽聚糖合成中的转肽酶结合，抑制肽链交联，阻碍细胞壁合成，使细菌膨胀破裂死亡，故梅毒螺旋体感染首选青霉素G。改变胞浆膜通透性是多黏菌素类机制，抑制蛋白质合成、叶酸合成、DNA复制分属其他抗菌药"},{"q":"通过保护胃黏膜治疗消化性溃疡的药物是","o":["硫酸镁","乳酶生","硫糖铝","碳酸氢钠","碳酸钙"],"a":2,"e":"硫糖铝在酸性环境中解离为硫酸蔗糖复合物，紧贴于溃疡面形成保护膜，隔绝胃酸和胃蛋白酶，保护胃黏膜促进愈合。硫酸镁为泻药，碳酸氢钠、碳酸钙为抗酸药仅中和胃酸，乳酶生为益生菌制剂，均非胃黏膜保护剂"},{"q":"硝酸甘油最常用的给药途径是","o":["贴皮","静脉注射","口服","舌下给药","吸入"],"a":3,"e":"硝酸甘油首过消除极强，口服几乎全部被肝脏灭活，故最常用的给药途径是舌下含服，经口腔黏膜吸收迅速起效、避开首过效应。贴皮起效慢用于预防，静脉注射用于急性心衰或手术中控制性降压，口服、吸入均非常规"},{"q":"与细菌耐药性产生无关的是","o":["细菌产生β内酰胺酶水解青霉素G","细菌产生钝化酶灭活氨基糖苷类抗生素","细菌体内与抗菌药结合的靶位结构改变","细菌改变对抗菌药的通透性降低抗菌药在菌体内的浓度","细菌体内产生的内毒素增加"],"a":4,"e":"细菌耐药的常见机制包括产生β-内酰胺酶水解青霉素G、产生钝化酶灭活氨基糖苷类、改变药物作用靶位结构、降低膜通透性减少药物摄入等。细菌产生内毒素是增强侵袭力与毒力的表现，与耐药性产生无关"},{"q":"在体内的代谢产物仍有抗凝作用的药物是","o":["肝素","水蛭素","华法林","阿司匹林","醋硝香豆素"],"a":4,"e":"醋硝香豆素口服吸收后在体内经代谢转化，其代谢产物仍具有抗凝活性，作用维持时间较长。肝素、水蛭素以原形直接发挥抗凝作用；阿司匹林为抗血小板药；华法林的代谢产物基本无抗凝活性，与醋硝香豆素不同"},{"q":"无中枢抑制作用的药物是","o":["苯海拉明","异丙嗪","特非那定","曲吡那敏","氯苯那敏"],"a":2,"e":"特非那定为第二代H1受体阻断药，不易透过血脑屏障，几无中枢镇静作用。苯海拉明、异丙嗪、曲吡那敏、氯苯那敏均为第一代H1受体阻断药，易进入中枢，有明显嗜睡、乏力等中枢抑制。但该类药有个别致心律失常的报告，联用大环内酯类需谨慎"},{"q":"下列情况慎用碘制剂的是","o":["孕妇","甲亢患者术前准备","单纯性甲状腺肿","甲状腺危象","白细胞减少"],"a":0,"e":"碘可透过胎盘屏障进入乳汁，孕妇应用可能抑制胎儿或新生儿甲状腺功能，故需慎用。甲亢术前准备用碘剂使腺体缩小变硬，单纯性甲状腺肿补充小剂量碘，甲状腺危象用大剂量碘剂，白细胞减少并非碘制剂的慎用指征"},{"q":"强心苷中毒所致室性心动过速伴有二度房室传导阻滞应选用的治疗药物是","o":["维拉帕米","氯化钾","普鲁卡因胺","氟桂利嗪","苯妥英钠"],"a":4,"e":"强心苷中毒出现室性心动过速时，苯妥英钠为首选，能对抗强心苷所致心律失常且不抑制房室传导。氯化钾适用于伴低钾者，但本例已有二度房室传导阻滞，补钾可加重传导阻滞；维拉帕米、普鲁卡因胺、氟桂利嗪均非首选"},{"q":"舌下给药的主要优点是","o":["经济方便","吸收面积大","吸收规则","避免首过消除","副作用少"],"a":3,"e":"舌下给药时药物经舌下丰富的毛细血管直接吸收入血，绕过肝脏，主要优点是避免首过消除、起效迅速。经济方便、吸收面积大、吸收规则、副作用少均非其主要药动学优势，且舌下给药面积实际有限。但剂量不宜过大，且仅适用于脂溶性、可黏膜吸收的药物"},{"q":"治疗黏液性水肿的药物是","o":["甲巯咪唑","丙硫氧嘧啶","小剂量碘剂","甲状腺激素","卡比马唑"],"a":3,"e":"黏液性水肿是成人甲状腺功能减退的表现，因甲状腺激素缺乏致黏液性物质沉积，治疗须补充甲状腺激素。甲巯咪唑、丙硫氧嘧啶、卡比马唑抑制激素合成，用于甲亢；小剂量碘仅用于单纯性甲状腺肿，均不适用"},{"q":"有关哌替啶的描述错误的是","o":["可以用于心源性哮喘","镇痛效价强度比吗啡弱","有止泻作用","有呼吸抑制作用","有成瘾性"],"a":2,"e":"哌替啶无止泻作用，相反因兴奋胃肠道平滑肌使其张力增加，但不似吗啡明显减少肠蠕动而致便秘。它可用于心源性哮喘，镇痛效价强度约为吗啡的十分之一，具有呼吸抑制和成瘾性，故“有止泻作用”描述错误"},{"q":"可迅速进入中枢神经系统的M受体阻断药是","o":["山莨菪碱","东莨菪碱","溴甲东莨菪碱","哌仑西平","地西泮"],"a":1,"e":"东莨菪碱脂溶性高，易透过血脑屏障进入中枢，中枢抗胆碱作用强，可迅速入脑。山莨菪碱中枢作用弱；溴甲东莨菪碱为季铵盐，难以透过血脑屏障；哌仑西平选择性阻断M1且不易入脑；地西泮虽入脑但非M受体阻断药"},{"q":"可用于治疗癌症呕吐的药物是","o":["氯噻嗪","氯氮平","氯胺酮","甲氯芬酯","氯丙嗪"],"a":4,"e":"氯丙嗪阻断延髓催吐化学感受区的D2受体，具有强大镇吐作用，可用于癌症、放射病及药物引起的呕吐。氯噻嗪为利尿药，氯氮平为抗精神病药，氯胺酮为麻醉药，甲氯芬酯为中枢兴奋药，均无镇吐用途"},{"q":"临床上可以口服治疗消化性溃疡的前列腺素类似物是","o":["双嘧达莫","前列环素","米索前列醇","前列腺素E2","奥美拉唑"],"a":2,"e":"米索前列醇是前列腺素E1类似物，口服可抑制胃酸分泌并增加胃黏膜血流、保护黏膜，是临床口服治疗消化性溃疡的前列腺素类似物。双嘧达莫为抗血小板药，前列环素、前列腺素E2不稳定不宜口服，奥美拉唑为质子泵抑制剂而非前列腺素类"},{"q":"可增强加拉碘铵肌松作用的药物是","o":["青霉素","庆大霉素","氯霉素","头孢拉定","多黏菌素E"],"a":1,"e":"庆大霉素属氨基糖苷类，具有神经肌肉接头阻滞作用，可减少乙酰胆碱释放并降低终板敏感性，与肌松药加拉碘铵合用可增强其肌松效应。青霉素、头孢拉定无明显神经肌肉阻滞作用，氯霉素亦不增强肌松，多黏菌素E虽有阻滞但非本题所指"},{"q":"以下哪项不是自身免疫性疾病的共同特点","o":["病因大多不明，女性多于男性","血液中常存在高滴度自身抗体","多因严重感染、恶性肿瘤、免疫抑制剂等原因引起","常反复发作或慢性迁延","有明显的家族倾向性"],"a":2,"e":"自身免疫病多病因不明、女性多见，血中常有高滴度自身抗体，病情反复发作或慢性迁延，并有明显家族倾向。“多因严重感染、恶性肿瘤、免疫抑制剂等引起”是继发性免疫缺陷病的特点，不属于自身免疫病的共同特点"},{"q":"药物效应动力学研究的是","o":["人体对药物的反应性","如何提高药物疗效","实验动物对药物的反应性","药物在机体的影响下发生的变化及规律","药物对机体的作用及作用机制"],"a":4,"e":"药物效应动力学（药效学）研究药物对机体的作用及作用机制。人体或实验动物对药物的反应性表述片面；药物在机体影响下发生的变化及规律属药动学研究内容；如何提高疗效是临床用药目标而非学科定义"},{"q":"浸润麻醉时局麻药中加入肾上腺素的目的是","o":["预防过敏性休克","防止麻醉过程产生血压下降","对抗局麻药的扩张血管作用","延长局麻作用持续时间","促进局麻药的吸收"],"a":3,"e":"浸润麻醉时局麻药中加入少量肾上腺素，可收缩局部血管、减慢药物吸收，既延长局麻作用持续时间，又降低全身毒性。它不能预防过敏性休克，亦非为防止血压下降；对抗局麻药扩血管是手段，根本目的在于延长麻醉时间，加入肾上腺素反使吸收减少"},{"q":"无明显中枢副作用的H1受体阻断药是","o":["苯海拉明","异丙嗪","美克洛嗪","氯苯那敏","阿司咪唑"],"a":4,"e":"阿司咪唑为第二代H1受体阻断药，不易透过血脑屏障，无明显中枢镇静副作用。苯海拉明、异丙嗪、氯苯那敏为第一代，中枢抑制明显；美克洛嗪亦属第一代哌嗪类，有一定中枢作用，均不符合。其半衰期长，每日一次给药即可"},{"q":"患儿，男，4岁，因患体癣需要局部应用制霉菌素，该药特点为","o":["极易产生耐药性","对念珠菌属抗菌活性较高","可注射给药","局部给药时不良反应明显","口服给药主要不良反应为粒细胞减少"],"a":1,"e":"制霉菌素为多烯类抗真菌药，与真菌膜麦角固醇结合，对念珠菌属抗菌活性较高，因毒性大不作注射，主要局部应用或口服治疗肠道念珠菌感染。其耐药性并不易产生；局部给药不良反应轻微；口服主要为胃肠反应，粒细胞减少并非其特点"},{"q":"磺胺类药物目前临床应用大大受限的主要原因是","o":["抗菌谱窄","血药浓度低","细菌易耐药","容易引起过敏反应","易透过血脑屏障"],"a":3,"e":"磺胺类为广谱抗菌药，但不良反应多见，尤其容易引起过敏反应，如皮疹、药热乃至剥脱性皮炎，使其临床应用大大受限。其抗菌谱并不窄，血药浓度不低，易透过血脑屏障反是优点；细菌易耐药虽也是问题，但过敏反应更为突出"},{"q":"使用胰岛素治疗过程中若出现饥饿、心悸、昏迷、震颤、惊厥等应立即给予","o":["肾上腺素皮下注射","胰岛素皮下注射","异丙嗪肌内注射","50%葡萄糖静脉注射","氢化可的松肌内注射"],"a":3,"e":"胰岛素过量会引起严重低血糖，出现饥饿、心悸、震颤、惊厥乃至昏迷，须立即静脉注射50%葡萄糖升高血糖。肾上腺素、氢化可的松仅作辅助；再给胰岛素会加重低血糖；异丙嗪为抗组胺药，均与抢救低血糖无关"},{"q":"下列属于新药的是","o":["已上市的药品改变剂型","已上市的药品改变给药途径","已上市的药品增加新的适应证","已上市的药品制成新的复方制剂","未曾在中国境内外上市销售的药品"],"a":4,"e":"新药是指未曾在中国境内外上市销售的药品。已上市药品改变剂型、改变给药途径、增加新适应证或制成新的复方制剂，属于改良型新药或按新药管理，但并非严格意义上的全新新药。改良型新药虽按新药程序审批，但其活性成分已上市"},{"q":"呋塞米的临床应用不包括","o":["治疗水肿","加速毒物排出","预防急慢性肾衰竭","治疗尿崩症","治疗高钙血症"],"a":3,"e":"呋塞米为强效袢利尿药，临床用于各种水肿、加速毒物排出、预防急性肾衰竭及治疗高钙血症。尿崩症的治疗宜用氢氯噻嗪或去氨加压素，呋塞米利尿强却不用于尿崩症，故该项不属于其临床应用。急性肾衰竭早期用呋塞米可维持尿量、冲洗肾小管"},{"q":"吗啡的下述药理作用，哪项是错误的","o":["镇痛作用","呼吸抑制作用","镇咳作用","食欲抑制作用","止泻作用"],"a":3,"e":"吗啡具有镇痛、镇静、镇咳、抑制呼吸、止泻及缩瞳等作用，并能扩张血管。食欲抑制并非吗啡的药理作用，该项描述错误；其余各项均为吗啡的典型作用。其中镇咳因成瘾性已少用，止泻用于严重腹泻，缩瞳呈针尖样为中毒标志"},{"q":"外周肾上腺素能神经合成与释放的主要递质是","o":["多巴胺","肾上腺素","去甲肾上腺素","异丙肾上腺素","间羟胺"],"a":2,"e":"外周肾上腺素能神经（交感神经节后纤维）合成与释放的主要递质是去甲肾上腺素。肾上腺素主要由肾上腺髓质分泌入血；多巴胺为中枢及部分外周递质；异丙肾上腺素、间羟胺为人工合成的拟肾上腺素药，非体内主要递质"},{"q":"NN受体激动剂产生的药理作用是","o":["胃肠道平滑肌舒张","呼吸道分泌物减少","血管扩张，血压下降","心率加快，心肌收缩力增强","骨骼肌收缩"],"a":3,"e":"NN（N1）受体分布于自主神经节和肾上腺髓质，激动后兴奋节后神经元并促使儿茶酚胺释放，表现为心率加快、心肌收缩力增强、血压升高。骨骼肌收缩由N_M受体介导；胃肠道平滑肌舒张、呼吸道分泌物减少、血管扩张均为M样或其他效应"},{"q":"可用糖皮质激素治疗的是","o":["严重哮喘伴有高血压","病毒感染","精神病患者服用苯巴比妥引起的过敏性皮炎","急性淋巴细胞白血病","带状疱疹"],"a":3,"e":"糖皮质激素可抑制淋巴细胞增殖、溶解淋巴细胞，对急性淋巴细胞白血病有较好疗效。严重哮喘伴高血压者用激素可升高血压，不宜；病毒感染、带状疱疹使用激素会降低免疫、加重感染；苯巴比妥致过敏性皮炎应停药并抗过敏，均非激素适应证"},{"q":"治疗铜绿假单胞菌感染有效的药物是","o":["头孢氨苄","克林霉素","青霉素","羧苄西林","阿莫西林"],"a":3,"e":"羧苄西林为抗铜绿假单胞菌青霉素，对铜绿假单胞菌有效，常用于其感染。头孢氨苄为一代头孢、青霉素、阿莫西林对铜绿假单胞菌无效；克林霉素主要针对革兰阳性菌与厌氧菌，亦无效。铜绿假单胞菌感染还可选用哌拉西林、头孢他啶或氨基糖苷类"},{"q":"利福平抗结核菌的作用原理是","o":["干扰菌体RNA的合成","干扰菌体DNA的合成","抑制分枝菌酸","抑制蛋白质合成","竞争PABA"],"a":0,"e":"利福平特异性抑制细菌依赖DNA的RNA聚合酶，阻碍mRNA合成，从而干扰菌体RNA合成而抗菌。抑制分枝菌酸是异烟肼的机制；竞争PABA是磺胺类；抑制蛋白质合成、干扰DNA复制分属氨基糖苷类、喹诺酮类等药物"},{"q":"卡比多巴治疗帕金森病的机制是","o":["激动中枢多巴胺受体","抑制外周多巴脱羧酶活性","阻断中枢胆碱受体","抑制多巴胺的再摄取","使多巴胺受体增敏"],"a":1,"e":"卡比多巴为外周多巴脱羧酶抑制剂，不能透过血脑屏障，与左旋多巴合用时减少外周多巴胺生成，使更多左旋多巴进入脑内转化为多巴胺而改善帕金森病。它不直接激动中枢多巴胺受体，不阻断胆碱受体，也不抑制多巴胺再摄取或使受体增敏"},{"q":"下列哪个镇静催眠药物适合治疗单纯入睡困难","o":["地西泮","异戊巴比妥","唑吡坦","水合氯醛","丁螺环酮"],"a":2,"e":"唑吡坦选择性作用于GABA_A受体ω1亚型，起效快、维持时间短、宿醉效应小，适合单纯入睡困难。地西泮、异戊巴比妥、水合氯醛作用时间较长，易致次日困倦；丁螺环酮为抗焦虑药，无明显催眠作用"},{"q":"吗啡禁用于分娩止痛，是由于","o":["可抑制新生儿呼吸","易产生成瘾性","易在新生儿体内蓄积","镇痛效果差","可致新生儿便秘"],"a":0,"e":"吗啡极易透过胎盘屏障，而新生儿血脑屏障发育不全、对阿片类敏感，吗啡可抑制新生儿呼吸中枢致呼吸抑制，故禁用于分娩止痛。成瘾性、便秘、蓄积虽是问题，但抑制新生儿呼吸是最危险的禁忌理由；其镇痛效果并不差"},{"q":"有关噻氯匹定的说法，正确的是","o":["与血小板膜糖蛋白GP Ⅱb/Ⅲa受体结合，阻断受体与纤维蛋白原的结合","骨髓抑制常发生在用药3个月之后","干扰血小板膜糖蛋白GP Ⅱb/Ⅲa受体与纤维蛋白原结合，抑制血小板激活","口服后2小时即可发挥作用","主要不良反应为诱发消化性溃疡"],"a":2,"e":"噻氯匹定通过抑制ADP介导的血小板活化，干扰血小板膜糖蛋白GPⅡb/Ⅲa受体与纤维蛋白原结合，从而抑制血小板聚集。直接结合GPⅡb/Ⅲa受体的是阿昔单抗等单抗；其骨髓抑制多发生在用药早期而非3个月后；口服起效需数日；主要不良反应为出血与骨髓抑制而非消化性溃疡"},{"q":"糖皮质激素治疗哪种休克效果最佳","o":["感染中毒性休克","低血容量性休克","过敏性休克","心源性休克","疼痛性休克"],"a":0,"e":"糖皮质激素具有抗炎、抗毒、抗免疫和抗休克作用，对感染中毒性休克疗效最佳，但须在足量有效抗生素配合下使用。过敏性休克首选肾上腺素；低血容量性休克以补液为主；心源性休克、疼痛性休克并非其最佳适应证"},{"q":"毒扁豆碱可用于治疗","o":["青光眼","重症肌无力","腹胀气","尿潴留","阵发性室上性心动过速"],"a":0,"e":"毒扁豆碱为胆碱酯酶抑制剂，使乙酰胆碱蓄积，缩瞳并降低眼内压，可用于治疗青光眼。重症肌无力、腹胀气、尿潴留多用新斯的明；阵发性室上性心动过速亦可首选新斯的明，毒扁豆碱因毒性较大不作首选"},{"q":"耳、肾毒性最大的氨基糖苷类抗生素是","o":["西索米星","奈替米星","卡那霉素","庆大霉素","新霉素"],"a":4,"e":"新霉素耳毒性与肾毒性在氨基糖苷类中最大，故不作全身给药，仅供局部或口服肠道消毒。卡那霉素、庆大霉素耳肾毒性也较明显但低于新霉素；西索米星、奈替米星毒性相对较小。口服极少吸收，可用于肠道术前准备"},{"q":"属于抗精神分裂症药的是","o":["氨氯地平","氯氮平","丙咪嗪","氟西汀","碳酸锂"],"a":1,"e":"氯氮平为二苯二氮䓬类抗精神病药，对精神分裂症疗效好、锥体外系反应少，属抗精神分裂症药。氨氯地平为钙通道阻滞药；丙咪嗪为三环类抗抑郁药；氟西汀为选择性5-羟色胺再摄取抑制药；碳酸锂为抗躁狂药"},{"q":"硝普钠治疗心功能不全的药理学基础是","o":["改善冠脉血流","降低心输出量","降低血压","扩张动、静脉而降低心脏前、后负荷","扩张动脉降低后负荷"],"a":3,"e":"硝普钠可同时扩张动脉和静脉，降低心脏后负荷与前负荷，减轻心脏负担、改善心功能，是治疗急性心功能不全的药理学基础。它并非单纯降低血压或降低心输出量，扩张冠脉改善血流亦非主要机制；只扩动脉降后负荷的描述不全面"},{"q":"下列关于阿司匹林的不良反应，错误的是","o":["胃肠道反应最为常见","维生素K可预防阿司匹林导致的出血","阿司匹林哮喘是以抗原-抗体反应为基础的过敏反应","病毒感染患儿不宜用阿司匹林","静脉滴注碳酸氢钠可缓解严重的水杨酸反应"],"a":2,"e":"阿司匹林哮喘并非抗原-抗体介导的过敏反应，而是抑制环氧酶后前列腺素合成减少、白三烯生成相对增多所致，故该项错误。胃肠道反应最常见；维生素K可预防出血；病毒感染患儿用阿司匹林易致Reye综合征；静脉滴注碳酸氢钠碱化尿液可缓解水杨酸反应"},{"q":"因行胃镜操作给予筒箭毒碱导致中毒，建议给予的抢救药物是","o":["肾上腺素","去甲肾上腺素","新斯的明","多巴胺","麻黄碱"],"a":2,"e":"筒箭毒碱为非去极化型肌松药，竞争性阻断神经肌肉接头N_M受体。新斯的明抑制胆碱酯酶、增加乙酰胆碱，可竞争性拮抗其肌松作用，是抢救首选。肾上腺素、去甲肾上腺素、多巴胺、麻黄碱均为拟肾上腺素药，不能解除神经肌肉阻滞"},{"q":"酚妥拉明不用于治疗","o":["顽固性充血性心力衰竭","休克","胃十二指肠溃疡","肾上腺嗜铬细胞瘤","外周血管痉挛性疾病"],"a":2,"e":"酚妥拉明阻断α受体，扩张血管，可用于外周血管痉挛性疾病、休克、肾上腺嗜铬细胞瘤及顽固性充血性心力衰竭。它可促进胃酸分泌、加重溃疡，故不用于胃十二指肠溃疡，属禁忌。其扩血管作用还可改善微循环，用于休克治疗"},{"q":"伴有心绞痛的高血压患者宜选用的降压药物是","o":["硝酸甘油","普萘洛尔","维拉帕米","氢氯噻嗪","卡托普利"],"a":1,"e":"普萘洛尔降压同时减慢心率、降低心肌耗氧量，对伴有心绞痛的高血压患者尤为适宜。硝酸甘油主治心绞痛但不作常规降压；维拉帕米亦可用但非首选；氢氯噻嗪、卡托普利虽能降压，但无直接缓解心绞痛的优势"},{"q":"绝大多数的药物受体是属于","o":["分子量小于1000的小分子物质","双分子层的脂质物质","位于膜上或胞内的蛋白质","DNA","RNA"],"a":2,"e":"绝大多数药物受体是位于细胞膜上或胞内的蛋白质（多为糖蛋白），通过构象变化传递信号。分子量小于1000的小分子、双分子层脂质、DNA和RNA均非药物受体的普遍化学本质。受体的特异性取决于其立体构象与结合位点"},{"q":"糖皮质激素大剂量突击疗法适用于","o":["肾病综合征","结缔组织病","恶性淋巴瘤","感染中毒性休克","顽固性支气管哮喘"],"a":3,"e":"糖皮质激素大剂量突击疗法用于急性、危及生命的严重感染中毒性休克，短期内大剂量给药以迅速抗炎抗休克。肾病综合征、结缔组织病多采用一般剂量长期疗法；恶性淋巴瘤需综合化疗；顽固性哮喘多用吸入或中等剂量"},{"q":"治疗癫痫大发作和单纯局限性发作首选","o":["苯二氮䓬类","乙琥胺","苯巴比妥钠","卡马西平","丙戊酸钠"],"a":3,"e":"卡马西平阻滞钠通道、稳定神经元膜，是治疗癫痫大发作和单纯局限性发作的首选之一。乙琥胺仅对小发作有效；苯二氮䓬类多用于癫痫持续状态；苯巴比妥、丙戊酸钠虽有效但非本题首选。对丙戊酸钠不耐受者可换用卡马西平，但需监测血象与肝功能"},{"q":"阿托品作用于","o":["烟碱受体","α受体","β受体","突触前M受体","各类型M受体"],"a":4,"e":"阿托品为M胆碱受体阻断药，对M1、M2、M3、M4、M5各亚型均无选择性，可阻断各类型M受体。它对烟碱受体、α受体、β受体无明显阻断作用；突触前M受体亦属M受体亚型之一，可被阻断，但概括以各类型M受体最准确"},{"q":"氨基糖苷类抗生素的耐药机制不包括","o":["产生乙酰化酶","产生β-内酰胺酶","产生腺苷化酶","外膜膜孔蛋白的结构改变","30S核糖体改变"],"a":1,"e":"氨基糖苷类耐药机制包括产生乙酰化酶、腺苷化酶、磷酸化酶等钝化酶，外膜膜孔蛋白改变使药物进入减少，以及30S核糖体靶位改变。产生β-内酰胺酶是青霉素类、头孢菌素类的耐药机制，不属于氨基糖苷类"},{"q":"氯沙坦的作用靶点是","o":["α1受体","AT1受体","AT2受体","β受体","血管紧张素转化酶"],"a":1,"e":"氯沙坦选择性阻断血管紧张素Ⅱ的AT1受体，抑制血管收缩与醛固酮释放而降压。它不作用于α1、β受体，不激动AT2受体，也不抑制血管紧张素转化酶（后者为卡托普利等ACE抑制药的作用靶点）"},{"q":"某药剂量相等的两种制剂口服后曲线下面积相等，但达峰时间不同，是因为","o":["肝脏代谢速度不同","肾脏排泄速度不同","血浆蛋白结合率不同","分布部位不同","吸收速度不同"],"a":4,"e":"两种制剂剂量相等、曲线下面积相等，说明吸收程度与生物利用度相同；达峰时间不同反映的是药物吸收快慢的差异，故原因是吸收速度不同。肝脏代谢、肾脏排泄、血浆蛋白结合率及分布部位不同主要影响消除或分布，不改变达峰时间的这种关系"},{"q":"体内药物主动转运的特点是","o":["由载体进行，消耗能量","由载体进行，不消耗能量","不消耗能量，无竞争性抑制","消耗能量，无竞争性抑制","不消耗能量，有竞争性抑制"],"a":0,"e":"主动转运需载体蛋白参与，可逆浓度梯度转运，因而消耗能量，并具有饱和性与竞争性抑制。不耗能者为被动转运或易化扩散；无竞争性抑制不符合载体转运的特点，故“由载体进行、消耗能量”正确。如神经末梢对去甲肾上腺素的再摄取即属此方式"},{"q":"中枢镇静作用最强的药物是","o":["阿司咪唑","苯海拉明","西替利嗪","苯茚胺","氯雷他定"],"a":1,"e":"苯海拉明为第一代H1受体阻断药，脂溶性高、易透过血脑屏障，中枢镇静作用最强，服后明显嗜睡。阿司咪唑、氯雷他定、西替利嗪为第二代，几无中枢抑制；苯茚胺虽有中枢作用但亦具一定兴奋性，均不及苯海拉明"},{"q":"当肝功能严重障碍时，药物从机体的消除有何变化","o":["消除速率加快，应适当增加给药剂量","消除速率减慢，应适当减少给药剂量","消除速率加快，半衰期延长，应适当减少给药剂量","消除速率减慢，半衰期缩短，应适当增加给药剂量","消除速率不变，半衰期延长，应适当减少给药剂量"],"a":1,"e":"肝脏是药物代谢的主要器官，肝功能严重障碍时药物生物转化减慢，消除速率下降、半衰期延长，易致蓄积中毒，故应适当减少给药剂量。消除加快或剂量增加均错误；消除速率不变亦不符合肝功能受损的实际情况"},{"q":"属于中效能利尿药的药物是","o":["呋塞米","依他尼酸","氢氯噻嗪","布美他尼","阿米洛利"],"a":2,"e":"氢氯噻嗪抑制远曲小管前段Na⁺-Cl⁻共转运，利尿作用中等，属中效能利尿药。呋塞米、依他尼酸、布美他尼作用于髓袢升支粗段，为高效能利尿药；阿米洛利为低效能保钾利尿药。该类药还可用于尿崩症及含钙肾结石的防治"},{"q":"华法林引起的出血宜选用","o":["去甲肾上腺素","维生素K","氨甲苯酸","对氯苯甲酸","维生素C"],"a":1,"e":"华法林为维生素K拮抗剂，抑制维生素K依赖凝血因子的合成，过量引起出血时宜用维生素K对抗。去甲肾上腺素仅局部收缩血管止血；氨甲苯酸为抗纤溶药，对华法林无效；对氯苯甲酸、维生素C均无拮抗华法林的作用"},{"q":"麻黄碱的用途中，描述错误的是","o":["可用于房室传导阻滞的治疗","可用于轻症哮喘的治疗","缓解荨麻疹的皮肤黏膜症状","治疗鼻黏膜充血引起的鼻塞","防治硬膜外麻醉和蛛网膜下腔麻醉引起的低血压"],"a":0,"e":"麻黄碱激动α、β受体并促进去甲肾上腺素释放，用于防治硬膜外与蛛网膜下腔麻醉所致低血压、轻症哮喘、鼻黏膜充血性鼻塞及缓解荨麻疹皮肤黏膜症状。房室传导阻滞需用异丙肾上腺素或阿托品加速传导，麻黄碱无此用途，A项描述错误。鼻塞、哮喘、低血压防治均是其明确适应证，勿与传导阻滞混淆"},{"q":"苯海索的作用是","o":["促进DA神经元释放DA，抑制DA摄取","在脑内转变为DA，补充纹状体中DA之不足","激活DA受体","拮抗中枢胆碱受体","兴奋中枢胆碱受体"],"a":3,"e":"苯海索为中枢性抗胆碱药，通过拮抗纹状体中枢胆碱受体、减弱胆碱能功能而改善帕金森病震颤与僵直。促进DA释放并抑制摄取是金刚烷胺的作用，在脑内转变为DA是左旋多巴的机制，激活DA受体为溴隐亭等激动剂效应，均非苯海索所有"},{"q":"促进铁的吸收因素有","o":["磷酸盐","碳酸盐","四环素","维生素C","抗酸药"],"a":3,"e":"维生素C可将三价铁还原为易吸收的二价铁，并与铁形成可溶性络合物，因而促进铁剂吸收。磷酸盐、碳酸盐及抗酸药在肠道与铁形成难溶沉淀而妨碍吸收，四环素亦与铁络合降低吸收，均属抑制因素而非促进因素"},{"q":"以下关于血/气分配系数小的全麻药，描述正确的是","o":["诱导快，苏醒快","诱导慢，苏醒快","诱导快，苏醒慢","诱导慢，苏醒慢","不影响诱导，苏醒快"],"a":0,"e":"血/气分配系数小表示药物在血中溶解度低，肺泡与血液间很快达到平衡，故诱导迅速、停药后苏醒亦快。血/气分配系数大者则诱导慢、苏醒慢，常易被倒置设错；该系数只影响起效与恢复速度，并不改变麻醉强度本身"},{"q":"丙硫氧嘧啶的作用机制是","o":["抑制甲状腺激素的合成","抑制甲状腺激素的释放","抑制甲状腺激素的利用","抑制甲状腺激素的摄取","增加外周组织中T3水平"],"a":0,"e":"丙硫氧嘧啶属硫脲类，通过抑制甲状腺过氧化物酶，阻止碘的氧化、酪氨酸碘化及偶联，从而抑制甲状腺激素合成。它并不抑制已合成激素的释放，那是碘剂的作用，也不影响摄取，反而抑制外周T4向T3转化，故增加外周T3水平一说不成立"},{"q":"下列何药可用于治疗立克次体引起的斑疹伤寒","o":["青霉素","红霉素","四环素","阿奇霉素","乙酰螺旋霉素"],"a":2,"e":"四环素类为治疗立克次体感染如斑疹伤寒的首选药物，能抑制立克次体蛋白质合成。青霉素对立克次体无效，红霉素、阿奇霉素、乙酰螺旋霉素属大环内酯类，主要覆盖革兰阳性菌与非典型病原体，并非斑疹伤寒首选"},{"q":"下列疾病，禁用糖皮质激素类药物的是","o":["中毒性菌痢","感染性休克","活动性消化性溃疡病","重症伤寒","过敏性休克"],"a":2,"e":"糖皮质激素可抑制胃黏膜前列腺素合成、减少黏液分泌并促进胃酸分泌，故活动性消化性溃疡病禁用，以免诱发出血穿孔。感染性休克、中毒性菌痢、重症伤寒在有效抗感染基础上可短期合用激素，过敏性休克亦可用其抗过敏抗休克，均非绝对禁忌"},{"q":"磺胺类药物常见的不良反应不包括","o":["结晶尿、血尿和尿闭等症状","药物热、皮疹、偶见多形性红斑及剥脱性皮炎","白细胞减少症","再生障碍性贫血","过敏性休克"],"a":4,"e":"磺胺类常见不良反应包括尿中结晶析出引起结晶尿、血尿甚至尿闭，过敏反应如药物热、皮疹及多形性红斑、剥脱性皮炎，以及白细胞减少、再生障碍性贫血等造血抑制。过敏性休克并非其常见不良反应，多见于青霉素类，故不属于磺胺类常见不良反应之列"},{"q":"心房纤颤伴甲亢应选用","o":["维拉帕米","奎尼丁","胺碘酮","普萘洛尔","地高辛"],"a":3,"e":"普萘洛尔阻断β受体可减慢房室传导、控制房颤心室率，同时抑制外周T4向T3转化，兼顾甲亢症状，故为房颤伴甲亢首选。维拉帕米、地高辛虽可减慢心室率但无抗甲状腺作用；胺碘酮含碘可加重甲亢；奎尼丁可能加快心室率，均非适宜选择"},{"q":"强心苷中肠肝循环量最多的药物是","o":["洋地黄毒苷","地高辛","毛花苷丙","毒毛花苷K","铃兰毒苷"],"a":0,"e":"洋地黄毒苷脂溶性高、口服吸收完全，主要在肝内代谢并随胆汁排入肠道后重吸收，肠肝循环量在强心苷中最大，故作用维持最久。地高辛主要以原形经肾排泄，肠肝循环少；毛花苷丙、毒毛花苷K为速效静脉制剂，排泄快，几无肠肝循环"},{"q":"不能减少触发活动的机制是","o":["促进或加速复极，可减少早后除极","抑制早后除极上升支的内向离子流，可减少早后除极","降低最大舒张电位，可减少早后除极","抑制细胞内钙超载，可减少迟后除极的发生","动作电位时程过度延长，可减少早后除极的发生"],"a":2,"e":"早后除极发生于复极二、三相，与复极延迟、内向离子流增强有关；促进或加速复极、抑制早后除极上升支的内向电流均能有效减少早后除极，抑制细胞内钙超载则针对迟后除极。最大舒张电位是舒张期最负电位，降低它只影响自律性，与早后除极无关，故不能减少触发活动"},{"q":"布洛芬主要用于","o":["冠心病","心源性哮喘","风湿性关节炎","人工冬眠","镇静催眠"],"a":2,"e":"布洛芬为芳基丙酸类非甾体抗炎药，抑制环氧合酶减少前列腺素合成，具有较强的抗炎镇痛作用，临床主要用于风湿性、类风湿性关节炎及骨关节炎。冠心病、心源性哮喘不属其适应证；人工冬眠为氯丙嗪配伍用药；镇静催眠是巴比妥类或苯二氮䓬类的作用，与布洛芬无关"},{"q":"地塞米松适用于下列哪种疾病的治疗","o":["水痘","糖尿病","带状疱疹","霉菌感染","再生障碍性贫血"],"a":4,"e":"糖皮质激素可刺激骨髓造血功能，使红细胞、血红蛋白及血小板升高，故可用于再生障碍性贫血的治疗。水痘、带状疱疹等病毒感染使用激素可致病毒扩散，糖尿病者升高血糖，霉菌感染会助长真菌繁殖，均属禁忌或不宜，不是地塞米松的适用病症"},{"q":"哌唑嗪可选择性阻断","o":["β1受体","β2受体","α1受体","α2受体","M受体"],"a":2,"e":"哌唑嗪为选择性α1肾上腺素受体阻断药，通过阻断血管平滑肌突触后膜α1受体、扩张小动脉和小静脉而降低血压。它不阻断β1、β2受体，对突触前膜α2受体无明显作用，故较少引起反射性心率加快；M受体属胆碱受体，与哌唑嗪无关"},{"q":"氨基糖苷类抗生素的抗菌作用机制是","o":["抑制细胞壁的合成","影响细菌胞浆膜通透性","抗叶酸代谢","抑制细菌蛋白质的合成","抑制核酸代谢"],"a":3,"e":"氨基糖苷类抗生素与细菌核糖体30S亚基结合，抑制蛋白质合成起始阶段并造成读码错误，最终抑制细菌蛋白质合成而杀菌。抑制细胞壁合成是青霉素类、头孢菌素类作用；影响胞浆膜通透性为多黏菌素类；抗叶酸代谢是磺胺类与甲氧苄啶；抑制核酸代谢则为喹诺酮类等"},{"q":"以下免疫抑制剂及其作用机制配对错误的是","o":["环孢素——抑制T细胞活化、抑制多种细胞因子的生成","泼尼松——抑制多种细胞因子的基因转录","他克莫司——抑制嘌呤及嘧啶的合成","巴利昔单克隆抗体——阻断T help细胞IL-2受体","环磷酰胺——杀伤增殖期淋巴细胞及NK细胞活性"],"a":2,"e":"他克莫司属钙调磷酸酶抑制剂，通过阻断T细胞活化及IL-2等细胞因子转录发挥作用，抑制嘌呤、嘧啶合成是硫唑嘌呤、霉酚酸酯的机制，故该项配对错误。环孢素同为钙调磷酸酶抑制剂，泼尼松抑制细胞因子基因转录，环磷酰胺杀伤增殖期淋巴细胞，巴利昔单抗阻断IL-2受体，配对均正确"},{"q":"下列哪种药物可用于治疗焦虑症","o":["异戊巴比妥","唑吡坦","水合氯醛","甲丙氨酯","丁螺环酮"],"a":4,"e":"丁螺环酮为5-HT1A受体部分激动剂，是常用的非苯二氮䓬类抗焦虑药，无镇静催眠及成瘾性。异戊巴比妥、水合氯醛主要为镇静催眠药，唑吡坦是短效催眠药；甲丙氨酯虽属弱安定类但现已少用且非首选，治疗焦虑症以丁螺环酮为代表"},{"q":"促进胰岛素分泌的口服降糖药是","o":["甲苯磺丁脲","二甲双胍","吡格列酮","阿卡波糖","罗格列酮"],"a":0,"e":"甲苯磺丁脲属磺酰脲类，通过阻断胰岛β细胞ATP敏感钾通道、使细胞膜去极化而促进胰岛素释放，用于2型糖尿病。二甲双胍主要减少肝糖输出、改善胰岛素抵抗；吡格列酮、罗格列酮为噻唑烷二酮类胰岛素增敏剂；阿卡波糖抑制α-糖苷酶延缓糖吸收，均不促进胰岛素分泌"},{"q":"抑制远曲小管近端Na+-Cl-同向转运子的药物是","o":["呋塞米","螺内酯","氢氯噻嗪","乙酰唑胺","甘露醇"],"a":2,"e":"氢氯噻嗪作用于远曲小管近端，抑制Na+-Cl-同向转运子，减少钠氯重吸收而发挥中效利尿作用。呋塞米抑制髓袢升支粗段Na+-K+-2Cl-共转运子；螺内酯拮抗醛固酮受体；乙酰唑胺抑制碳酸酐酶；甘露醇为渗透性利尿药，作用部位与机制均不同"},{"q":"治疗梅毒与钩端螺旋体病应首选","o":["四环素","庆大霉素","红霉素","氯霉素","青霉素"],"a":4,"e":"青霉素G对梅毒螺旋体、钩端螺旋体高度敏感，是治疗梅毒与钩端螺旋体病的首选药物。四环素、红霉素仅作青霉素过敏者的替代；庆大霉素对螺旋体无效；氯霉素主要用于伤寒等，均非首选"},{"q":"青霉素类药共同具有","o":["耐酸、口服有效","耐β-内酰胺酶","抗菌谱广","主要应用于革兰氏阳性菌感染","可能发生过敏性休克，并有交叉过敏反应"],"a":4,"e":"各类青霉素均含β-内酰胺环，可引起过敏反应，严重者过敏性休克，且彼此间存在交叉过敏，这是其共同特点。青霉素类并非都耐酸，如青霉素G不耐酸，多数也不耐β-内酰胺酶，抗菌谱有窄有广，也不能笼统说主要用于革兰阳性菌感染，故其余概括不成立"},{"q":"氯丙嗪阻断黑质-纹状体通路D2受体引起","o":["抗精神病作用","体温调节失灵","催乳素分泌","锥体外系反应","镇吐作用"],"a":3,"e":"氯丙嗪阻断黑质-纹状体通路D2受体，使纹状体多巴胺功能减弱、胆碱能相对亢进，引起锥体外系反应，表现为帕金森综合征、静坐不能等。抗精神病作用源于中脑边缘及皮质通路D2阻断；镇吐作用于延脑催吐化学感受区；催乳素分泌源于结节-漏斗通路阻断，各通路对应效应不同"},{"q":"需要饭前服用的药物是","o":["哌仑西平","溴丙胺太林","山莨菪碱","阿托品","地泊溴铵"],"a":1,"e":"溴丙胺太林为季铵类M受体阻断药，抑制胃肠平滑肌痉挛与胃酸分泌，需在饭前服用以提前发挥解痉制酸作用。阿托品、山莨菪碱虽同为M阻断药但多用于止痛、抗休克，服用时间不强调饭前；哌仑西平、地泊溴铵虽亦制酸解痉，但经典需饭前服者以溴丙胺太林为代表"},{"q":"下列哪种药物为治疗心绞痛的钙拮抗药","o":["硝苯地平","普萘洛尔","硝酸甘油","硝酸异山梨酯","特拉唑嗪"],"a":0,"e":"硝苯地平为二氢吡啶类钙通道阻滞药，扩张冠脉与外周血管、解除冠脉痉挛，适用于心绞痛尤其变异型。普萘洛尔是β受体阻断药；硝酸甘油、硝酸异山梨酯属硝酸酯类；特拉唑嗪为α1受体阻断药，均不属钙拮抗药"},{"q":"胰岛素的常用给药途径是","o":["口服","皮下注射","静脉注射","肌内注射","吸入"],"a":1,"e":"胰岛素为多肽类，口服易被消化酶破坏，常规给药途径为皮下注射，吸收平稳方便。静脉注射仅用于急症如酮症酸中毒需快速起效时；肌内注射吸收快且不规律，少用；吸入途径尚未成为常规。故皮下注射是胰岛素最常用的给药方式"},{"q":"阿司匹林用于防止脑血栓形成时，不用大剂量的原因是","o":["避免胃肠道反应","避免激活血管壁中PG合成酶","避免激活血小板中PG合成酶","避免抑制血管壁中PG合成酶","避免抑制血小板中PG合成酶"],"a":3,"e":"小剂量阿司匹林选择性抑制血小板环氧合酶，减少血栓素TXA2生成而抗血小板聚集，用于预防脑血栓。大剂量则同时抑制血管壁环氧合酶，使前列环素PGI2合成减少，PGI2本可抑制血小板聚集、扩张血管，其减少会削弱抗栓效应，故不宜大剂量。血小板中PG合成酶正是小剂量抑制的靶点，并非要避免"},{"q":"属于男性避孕药的是","o":["乙酸棉酚","米非司酮","炔诺酮","甲地孕酮","己烯雌酚"],"a":0,"e":"棉酚（乙酸棉酚）可抑制精子生成、降低精子活力，是经典的男性避孕药。米非司酮为抗孕激素药，用于抗早孕；炔诺酮、甲地孕酮为孕激素类，多用于女性避孕；己烯雌酚为雌激素类，均非男性避孕药"},{"q":"产生副反应的剂量是","o":["半数致死量","治疗量","极量","中毒量","无效量"],"a":1,"e":"副作用（副反应）是药物在治疗剂量下出现的与治疗目的无关的作用，源于药物作用选择性低，故发生在治疗量。极量是允许使用的最大剂量，超过极量易中毒；中毒量引起毒性反应；半数致死量为致死剂量；无效量低于阈剂量不产生效应，均非副反应所用剂量"},{"q":"多奈哌齐口服的生物利用度为100%，这意味着多奈哌齐口服","o":["消除速度缓慢","吸收完全","后血药浓度变化和静脉滴注一致","吸收迅速","代谢缓慢"],"a":1,"e":"生物利用度指药物经血管外给药后吸收进入体循环的相对量与速度，100%表示药物被完全吸收进入循环。它反映的是吸收程度而非速度，故不能说明吸收迅速或消除、代谢快慢；血药浓度变化与静脉滴注一致需同时满足吸收速度与程度条件，仅生物利用度100%不足以推出"},{"q":"新生儿使用磺胺类药物易出现胆红素脑病，是因为磺胺类药物","o":["减少胆红素排泄","竞争血浆白蛋白而置换出胆红素","降低血-脑脊液屏障的功能","溶解红细胞","抑制肝药酶"],"a":1,"e":"磺胺类与胆红素竞争血浆白蛋白结合位点，可将已结合的胆红素置换出来，使游离胆红素升高；新生儿血脑屏障未成熟，游离胆红素易入脑致核黄疸。磺胺并不减少胆红素排泄、不溶解红细胞，也不主要抑制肝药酶或破坏血脑屏障，故其余解释不成立"},{"q":"肿瘤化疗引起的呕吐选用","o":["阿托品","枸橼酸铋钾","昂丹司琼","乳果糖","甘露醇"],"a":2,"e":"昂丹司琼为5-HT3受体拮抗剂，阻断化疗药物刺激肠嗜铬细胞释放的5-HT作用于呕吐中枢，是防治肿瘤化疗所致恶心呕吐的首选。阿托品为M阻断药，对化疗呕吐效差；枸橼酸铋钾、乳果糖、甘露醇分别为胃黏膜保护剂、泻药和脱水药，与止吐无关"},{"q":"下列最常用于表面麻醉的药物是","o":["普鲁卡因","丁卡因","布比卡因","罗哌卡因","甲哌卡因"],"a":1,"e":"丁卡因穿透黏膜能力强、作用迅速，是表面麻醉最常用药物，多用于眼科、耳鼻喉科黏膜麻醉。普鲁卡因穿透力弱、不适用于表面麻醉；布比卡因、罗哌卡因、甲哌卡因主要用于浸润麻醉、传导麻醉和硬膜外麻醉，表面麻醉并非其首选用途"},{"q":"急性严重中毒性感染采用糖皮质激素类药物治疗的用法和疗程是","o":["大剂量突击静注或静滴","一般剂量多次给药","大剂量肌肉注射","大剂量口服","隔日疗法"],"a":0,"e":"急性严重中毒性感染在足量有效抗菌药基础上，采用大剂量糖皮质激素突击静脉注射或静滴，可迅速抗炎抗毒抗休克，疗程一般较短。一般剂量多次给药用于普通炎症；肌肉注射、口服起效慢不适于急救；隔日疗法用于长期维持治疗以减少不良反应，均非急性抢救用法"},{"q":"下列何药用于治疗鳞状上皮癌疗效最好","o":["6-MP","5-FU","VCR","BLM","CTX"],"a":3,"e":"博来霉素（BLM）对鳞状上皮癌如头颈部、皮肤、肺鳞癌疗效较好，且骨髓抑制轻。6-MP为嘌呤类似物主要用于白血病；5-FU为嘧啶类似物多用于消化道癌；VCR为长春碱类；CTX为环磷酰胺，均非鳞癌首选"},{"q":"下列药物中，能阻断甲硫氨酸脑啡肽生理学活性的是","o":["亮氨酸脑啡肽","吗啡","哌替啶","纳洛酮","喷他佐辛"],"a":3,"e":"纳洛酮为阿片受体竞争性拮抗药，可拮抗脑啡肽、内啡肽及吗啡类激动μ、κ等受体的活性，故能阻断甲硫氨酸脑啡肽的生理效应。吗啡、哌替啶为阿片受体激动剂，喷他佐辛为部分激动剂，均模拟而非阻断脑啡肽作用；亮氨酸脑啡肽本身为激动性肽类"},{"q":"地西泮抗焦虑作用的部位是","o":["脑干网状结构","丘脑","第三脑室周围灰质","大脑边缘系统","大脑导水管周围灰质"],"a":3,"e":"地西泮通过增强GABA能神经抑制功能发挥抗焦虑作用，其作用部位主要在大脑边缘系统，特别是杏仁核等结构。脑干网状结构与其镇静、催眠及肌松有关；导水管周围灰质参与镇痛；丘脑为感觉中继；第三脑室周围灰质非抗焦虑主要部位，故其余选项对应效应不同"},{"q":"可增强心肌收缩力及明显舒张肾血管的药物是","o":["肾上腺素","麻黄碱","甲氧明","多巴胺","去甲肾上腺素"],"a":3,"e":"多巴胺激动β1受体增强心肌收缩力，并激动肾血管多巴胺受体使肾血管舒张、增加肾血流，适用于心源性休克伴肾功能不全。肾上腺素、去甲肾上腺素主要收缩血管升高血压；麻黄碱作用温和且升压为主；甲氧明为α受体激动药，收缩血管，无舒张肾血管作用"},{"q":"药-时曲线下面积代表","o":["药物血浆半衰期","药物剂量","药物吸收速度","药物排泄量","药物进入循环的相对量"],"a":4,"e":"药-时曲线下面积（AUC）反映一定时间内药物进入体循环的相对总量，是评价生物利用度和吸收程度的重要指标。血浆半衰期反映消除快慢；吸收速度由达峰时间等体现；排泄量需由尿药数据测得；剂量是给药量而非进入循环的量，均与AUC含义不同"},{"q":"性激素受体位于","o":["细胞膜","细胞质","细胞核","线粒体","粗面内质网"],"a":2,"e":"性激素属类固醇激素，其受体为细胞内受体，主要位于细胞核，激素-受体复合物结合DNA调控基因转录而发挥作用。细胞膜受体多为肽类、儿茶酚胺类激素受体；线粒体、粗面内质网并非性激素受体定位，胞质型受体最终也转位入核"},{"q":"以下哪种药物可以对各型血吸虫病、肠吸虫以及肺吸虫产生有效的治疗效果","o":["甲硝唑","青蒿素","吡喹酮","二氯尼特","乙胺嗪"],"a":2,"e":"吡喹酮为广谱抗吸虫药，对各型血吸虫、华支睾吸虫、肺吸虫及姜片虫等均有高效，是血吸虫病首选。甲硝唑主治厌氧菌和阿米巴；青蒿素抗疟；二氯尼特抗阿米巴；乙胺嗪抗丝虫，均不覆盖血吸虫与吸虫"},{"q":"解热镇痛药的共同作用机制是","o":["抑制脑内γ-氨基丁酸（GABA）合成","抑制多巴胺合成","直接抑制中枢神经系统","减少炎症部位刺激因子合成","抑制前列腺素（PG）的合成"],"a":4,"e":"解热镇痛抗炎药通过抑制环氧合酶、减少前列腺素合成而发挥解热、镇痛、抗炎作用，这是其共同机制。此类药物不影响GABA或多巴胺合成，也不直接普遍抑制中枢神经系统；减少炎症部位刺激因子合成表述笼统且非公认机制，抑制PG合成才是本质"},{"q":"吩噻嗪类抗精神病药引起的帕金森综合征宜选用","o":["左旋多巴","金刚烷胺","司来吉兰","溴隐亭","苯海索"],"a":4,"e":"吩噻嗪类阻断黑质-纹状体D2受体引起药源性帕金森综合征，宜用中枢抗胆碱药苯海索治疗，通过恢复胆碱与多巴胺平衡缓解症状。左旋多巴、金刚烷胺、司来吉兰、溴隐亭均通过增加多巴胺能发挥疗效，但受体已被阻断，难以奏效，且左旋多巴还可加重精神症状"},{"q":"ACEI使用中被迫停药的主因是","o":["低血糖","阳痿","体位性高血压","刺激性干咳","头痛、潮红"],"a":3,"e":"ACEI抑制血管紧张素转换酶，使缓激肽等降解减少而在体内蓄积，刺激呼吸道引起刺激性干咳，是患者被迫停药的最常见原因。低血糖、阳痿并非ACEI典型不良反应；ACEI降压而非升高血压，故无体位性高血压；头痛、潮红多见于钙通道阻滞剂"},{"q":"关于苯二氮䓬类的中枢作用机制，以下说法正确的是","o":["作用于GABAB受体","抑制GABA与其受体结合","增加Cl-通道开放频率","延长Cl-通道开放时间","引起神经元细胞膜去极化"],"a":2,"e":"苯二氮䓬类与GABAA受体复合物上的苯二氮䓬位点结合，促进GABA与受体结合，增加氯离子通道开放频率，使氯离子内流增加、细胞膜超极化而发挥中枢抑制。它不作用于GABAB受体，也不抑制GABA结合；延长氯离子通道开放时间是巴比妥类机制；超极化而非去极化为其电生理改变"},{"q":"介导吗啡镇痛效应的主要阿片受体是","o":["α受体","β受体","δ受体","κ受体","μ受体"],"a":4,"e":"吗啡镇痛主要由激动μ阿片受体介导，μ受体激活产生强效镇痛、镇静及呼吸抑制等效应。δ、κ受体激动也有一定镇痛，κ受体激动可致镇痛镇静但伴烦躁，但吗啡镇痛以μ受体为主；α、β受体属肾上腺素受体，与阿片镇痛无关"},{"q":"治疗链激酶过量所致的出血宜选用","o":["右旋糖酐","垂体后叶素","维生素K","氨甲苯酸","鱼精蛋白"],"a":3,"e":"链激酶激活纤溶酶原、促进纤维蛋白溶解，过量可致纤溶亢进性出血，宜用抗纤溶药氨甲苯酸抑制纤溶酶原激活而止血。维生素K用于华法林等抗凝药过量；鱼精蛋白拮抗肝素；右旋糖酐为血浆代用品；垂体后叶素用于咯血等，均非链激酶过量出血的解救药"},{"q":"哌唑嗪的降压作用主要是","o":["激动中枢与外周α2受体","妨碍递质贮存而使递质耗竭","减少血管紧张素Ⅱ的作用","选择性的阻断α1受体的作用","直接扩张血管"],"a":3,"e":"哌唑嗪选择性阻断突触后膜α1受体，扩张小动脉和小静脉、降低外周阻力而降压，对α2受体作用弱，较少引起反射性心率加快。激动α2受体是可乐定机制；利血平妨碍递质贮存；减少血管紧张素Ⅱ作用是ACEI或ARB机制；直接扩张血管为硝普钠等，均与哌唑嗪不同"},{"q":"下列药物中脑血管扩张性偏头痛宜选用的是","o":["硝苯地平","尼群地平","非洛地平","尼索地平","尼莫地平"],"a":4,"e":"尼莫地平为二氢吡啶类钙通道阻滞剂，对脑血管有较高选择性，能扩张脑血管、改善脑供血，用于脑血管痉挛及偏头痛预防。硝苯地平、尼群地平、非洛地平、尼索地平主要扩张外周血管降压，对脑血管选择性不及尼莫地平"},{"q":"下列关于我国古代药物学著作对应正确的是","o":["孙思邈——《神农本草经》","华佗——《新修本草》","张仲景——《千金要方》","李时珍——《本草纲目》","扁鹊——《千金翼方》"],"a":3,"e":"李时珍为明代医药学家，编著《本草纲目》，是本草学的集大成之作，该项对应正确。《神农本草经》成书于汉代、非孙思邈所著；孙思邈著《千金要方》《千金翼方》；《新修本草》为唐代官修本草；张仲景著《伤寒杂病论》，其余对应均错"},{"q":"青霉素的抗菌作用机制是","o":["与细菌胞浆膜结合，破坏胞浆膜结构","破坏细胞壁使水分内渗","抑制DNA多聚酶，影响DNA的合成","与PBP结合，抑制细菌细胞壁合成","抑制菌体蛋白的合成"],"a":3,"e":"青霉素β-内酰胺环与细菌青霉素结合蛋白（PBP）结合，抑制转肽酶、阻碍肽聚糖交联，使细胞壁缺损，菌体因渗透压作用肿胀破裂。它并不直接破坏胞浆膜；抑制DNA多聚酶是喹诺酮类机制；抑制菌体蛋白合成是氨基糖苷类、四环素类作用，故其余陈述不符"},{"q":"下列关于拉贝洛尔作用的叙述，正确的是","o":["对β受体的阻断作用强于普萘洛尔","对β1受体有选择性阻断作用","对α受体的阻断作用强于酚妥拉明","多用于治疗中度和重度高血压","常用于心功能不全者"],"a":3,"e":"拉贝洛尔兼有α1和β受体阻断作用，降压温和持久，临床多用于中度和重度高血压，尤其适用于妊娠高血压。其对β受体阻断作用弱于普萘洛尔，对α受体阻断亦弱于酚妥拉明；无β1选择性；因抑制心肌收缩力，心功能不全者慎用，故其余说法有误"},{"q":"磺酰脲类药物引起较严重的不良反应是","o":["胃肠道反应","过敏反应","嗜睡","持久性的低血糖反应","粒细胞减少"],"a":3,"e":"磺酰脲类促胰岛素分泌，最严重不良反应为持久性低血糖，尤其老年、肝肾功能不全者易发生，严重可致昏迷。胃肠道反应、过敏反应、粒细胞减少虽可出现但相对较轻或少见；嗜睡并非其典型不良反应，故持久性低血糖为其较严重的不良反应"},{"q":"氨基糖苷类抗生素抑制细菌蛋白质合成的作用点是","o":["只作用于起始阶段","只作用于肽链延伸阶段","只作用于终止阶段","蛋白质合成的全过程","抑制蛋白质的转运"],"a":3,"e":"氨基糖苷类与核糖体30S亚基结合，既抑制起始复合物形成，又引起读码错误使肽链延伸异常，并阻碍终止释放，作用于蛋白质合成全过程。因此不能说只作用于起始、延伸或终止某一阶段；抑制蛋白质的转运亦非其抗菌机制"},{"q":"选择性作用于β2受体的药物是","o":["多巴胺","沙丁胺醇","麻黄碱","多巴酚丁胺","氨茶碱"],"a":1,"e":"沙丁胺醇为选择性β2肾上腺素受体激动药，激动支气管平滑肌β2受体而舒张支气管，用于哮喘。多巴胺、麻黄碱作用于多种受体、选择性低；多巴酚丁胺主要激动β1受体；氨茶碱通过抑制磷酸二酯酶、拮抗腺苷受体平喘，不直接激动β2受体"},{"q":"下列关于奎尼丁抗心律失常作用的叙述，错误的是","o":["降低浦肯野纤维自律性","减慢心房、心室和浦肯野纤维传导性","延长心房、心室和浦肯野纤维的动作电位时程和有效不应期","阻滞钠通道，不影响钾通道","对钠通道、钙通道都有抑制作用"],"a":3,"e":"奎尼丁为Ia类抗心律失常药，主要阻滞钠通道，同时亦阻滞钾通道，延长动作电位时程和有效不应期，故不影响钾通道的说法错误。它能降低浦肯野纤维自律性、减慢心房心室及浦肯野纤维传导、延长不应期，对钠、钙通道均有抑制，其余叙述符合其电生理作用"},{"q":"下列疾病中可以使用阿托品治疗的是","o":["青光眼","前列腺增生","心肌缺血","室性心律失常","窦性心动过缓"],"a":4,"e":"阿托品阻断M受体、解除迷走神经对心脏的抑制，加快心率，可用于治疗窦性心动过缓及房室传导阻滞。青光眼、前列腺增生为阿托品禁忌，可升高眼压、加重排尿困难；心肌缺血、室性心律失常亦非其适应证，甚至可加重病情"},{"q":"关于肾素-血管紧张素系统（RAS）描述正确的是","o":["RAS仅存在于体液系统中","RAS仅存在于循环系统中","RAS激活可诱导高血压、心肌肥厚等病理过程","肾素由心肌细胞分泌，使血管紧张素原转化成血管紧张素Ⅰ","血管紧张素Ⅱ作用于血管紧张素受体亚型2（AT2），产生血管收缩作用"],"a":2,"e":"肾素-血管紧张素系统激活后生成血管紧张素Ⅱ，引起血管收缩、醛固酮分泌及心肌重构，参与高血压、心肌肥厚等病理过程，该项描述正确。该系统既存在于循环系统也存在于局部组织，并非仅限其一；肾素由肾小球旁器分泌而非心肌细胞；血管紧张素Ⅱ主要经AT1受体产生缩血管效应，AT2受体作用相反"},{"q":"可引起乳酸性酸中毒的药物是","o":["胰岛素","格列吡嗪","格列喹酮","氯磺丙脲","二甲双胍"],"a":4,"e":"二甲双胍抑制肝糖异生、促进无氧糖酵解，可增加乳酸生成并减少其清除，在肝肾功能不全等情况下易致乳酸性酸中毒。胰岛素、格列吡嗪、格列喹酮、氯磺丙脲常见不良反应为低血糖，一般不引起乳酸酸中毒，故与双胍类机制不同"},{"q":"治疗敏感菌引起的急慢性骨及关节感染，宜选用","o":["红霉素","乙酰螺旋霉素","麦白霉素","林可霉素","万古霉素"],"a":3,"e":"林可霉素在骨组织和关节滑液中浓度高，对革兰阳性菌及厌氧菌有效，适用于敏感菌所致急慢性骨与关节感染。红霉素、乙酰螺旋霉素、麦白霉素属大环内酯类，骨组织浓度低；万古霉素主要用于耐甲氧西林金葡菌重症感染，均非骨关节感染首选"},{"q":"合理应用双膦酸盐类治疗骨质疏松的注意事项中不包括","o":["应用3～5年后应该考虑药物假期","停用后疗效平稳下降","停用后其抗骨折的作用可以保存数年","使用超过5年，罕见不良反应发生率依然较低","停用双膦酸盐类治疗后，如果骨折风险仍高，可以换用特立帕肽"],"a":3,"e":"双膦酸盐使用三至五年后应考虑药物假期，停药后抗骨折作用可维持数年、疗效平稳下降；若停药后骨折风险仍高可换用特立帕肽。但使用超过五年后，颌骨坏死、非典型股骨骨折等罕见不良反应发生率上升，并非依然较低，故该项不属于合理注意事项"},{"q":"阿片受体拮抗药为","o":["苯佐那酯","吗啡","喷他佐辛","喷托维林","纳洛酮"],"a":4,"e":"纳洛酮为纯阿片受体拮抗药，对μ、κ、δ受体均有拮抗作用，用于吗啡类药物过量中毒的解救。吗啡为阿片受体激动剂；喷他佐辛为部分激动剂；苯佐那酯、喷托维林为镇咳药，无阿片受体拮抗作用，故只有纳洛酮符合"},{"q":"下列降血糖的药物中，可造成乳酸血症的是","o":["氯磺丙脲","胰岛素","甲苯磺丁脲","二甲双胍","格列齐特"],"a":3,"e":"二甲双胍促进外周组织无氧酵解、抑制肝糖异生，使乳酸产生增加而清除减少，可致乳酸血症甚至乳酸性酸中毒。氯磺丙脲、甲苯磺丁脲、格列齐特属磺酰脲类，主要致低血糖；胰岛素亦以低血糖为主要不良反应，均不引起乳酸血症"},{"q":"用于心脏骤停复苏的最佳药物是","o":["去甲肾上腺素","麻黄碱","肾上腺素","多巴胺","间羟胺"],"a":2,"e":"肾上腺素激动α、β受体，收缩外周血管升高主动脉舒张压、增加冠脉灌注，并兴奋心脏，是心脏骤停复苏的首选药物。去甲肾上腺素、间羟胺以升压为主；麻黄碱作用温和；多巴胺用于休克，均非心脏骤停复苏最佳选择"},{"q":"乙胺丁醇可致","o":["球后视神经炎","外周神经炎","耳神经损害","中毒性脑病","粒细胞减少症"],"a":0,"e":"乙胺丁醇主要不良反应为球后视神经炎，表现为视力下降、红绿色盲、视野缩小，与剂量和疗程相关。外周神经炎多见于异烟肼因维生素B6缺乏；耳神经损害为氨基糖苷类；中毒性脑病、粒细胞减少并非乙胺丁醇的典型毒性"},{"q":"用于诱导麻醉的药物是","o":["硫喷妥钠","司可巴比妥","苯巴比妥","水合氯醛","氯丙嗪"],"a":0,"e":"硫喷妥钠为超短效巴比妥类，静脉注射后迅速透过血脑屏障、起效快而维持短，常用于诱导麻醉及短时手术麻醉。司可巴比妥、苯巴比妥属中长效巴比妥类，主要镇静催眠抗惊厥；水合氯醛为催眠药；氯丙嗪为抗精神病药，均不用于诱导麻醉"},{"q":"小剂量氯丙嗪镇吐作用部位是","o":["延脑呕吐中枢","内耳前庭","胃黏膜感受器","延脑催吐化学感受区","胃肠道"],"a":3,"e":"小剂量氯丙嗪阻断延脑催吐化学感受区的D2受体而发挥镇吐作用，对直接刺激呕吐中枢的呕吐无效。延脑呕吐中枢为其大剂量作用部位之一；内耳前庭为晕动病呕吐部位，氯丙嗪对此无效；胃黏膜感受器、胃肠道并非其镇吐主要作用部位"},{"q":"抗菌谱是指","o":["抗菌药物杀灭细菌的强度","抗菌药物抑制细菌的能力","抗菌药物的抗菌程度","抗菌药物一定的抗菌范围","抗菌药物对耐药菌的疗效"],"a":3,"e":"抗菌谱指抗菌药物抑制或杀灭病原微生物的范围，如窄谱、广谱之分。杀灭细菌的强度、抑制细菌的能力属于抗菌活性，常用最低抑菌浓度、最低杀菌浓度表示；对耐药菌的疗效属于抗菌效果评价，均不等同于抗菌谱这一范围概念"},{"q":"下列哪项不属于糖皮质激素的禁忌证","o":["曾患严重精神病","新近胃肠吻合术","水痘","非特异性角膜炎","严重糖尿病"],"a":3,"e":"糖皮质激素禁忌证包括曾患严重精神病、新近胃肠吻合术、水痘等病毒感染、严重糖尿病、角膜溃疡及消化性溃疡等。非特异性角膜炎并非糖皮质激素的禁忌证，在控制感染前提下局部运用激素可减轻炎症，故该项不属于禁忌范围"},{"q":"下列哪种药是β-内酰胺酶抑制药","o":["阿莫西林","头孢哌酮","舒巴坦","头孢他啶","氨曲南"],"a":2,"e":"舒巴坦为β-内酰胺酶抑制药，本身抗菌作用弱，通过抑制β-内酰胺酶保护青霉素类、头孢菌素类不被水解，常与氨苄西林等制成复方制剂。阿莫西林、头孢哌酮、头孢他啶为β-内酰胺类抗生素，氨曲南为单环β-内酰胺类，均非酶抑制剂"},{"q":"普萘洛尔治疗心绞痛时，可产生下列哪种作用","o":["增加心收缩力，减慢心率","心室容积增大，射血时间延长","扩张冠脉","扩张动脉","抑制心肌收缩力，增快心率"],"a":1,"e":"普萘洛尔阻断心肌β1受体，减慢心率、降低收缩力，虽降低耗氧，但也可使心室容积增大、射血时间延长而增加耗氧，这是其不利的一面，临床与硝酸酯类合用可相互抵消。它抑制而非增加心收缩力，心率减慢而非增快；无直接扩张冠脉或动脉作用"},{"q":"治疗肺炎球菌性肺炎的首选药是","o":["链霉素","四环素","氯霉素","红霉素","青霉素"],"a":4,"e":"肺炎链球菌对青霉素G高度敏感，青霉素是治疗肺炎球菌性肺炎的首选药物。链霉素主要用于结核及革兰阴性菌；四环素、氯霉素、红霉素多作替代或用于青霉素过敏者，疗效不及青霉素，故均非首选"},{"q":"8岁以下儿童禁止使用的药物是","o":["氨苄西林","四环素","庆大霉素","头孢克肟","诺氟沙星"],"a":1,"e":"四环素类能与钙结合沉积于牙齿和骨骼，引起牙釉质发育不全、牙齿黄染及骨生长抑制，故八岁以下儿童、孕妇禁用。氨苄西林、头孢克肟属β-内酰胺类，儿童可用；庆大霉素虽具耳肾毒性但非八岁以下绝对禁用；诺氟沙星因影响软骨发育亦不宜儿童使用，但经典八岁以下禁用者为四环素"},{"q":"对肠道革兰氏阴性杆菌和铜绿假单胞菌，所产生的多种氨基糖苷类灭活酶稳定的氨基糖苷类抗生素是","o":["卡那霉素","阿米卡星","链霉素","青霉素","妥布霉素"],"a":1,"e":"阿米卡星为半合成氨基糖苷类，其结构对肠道革兰阴性杆菌产生的多种氨基糖苷钝化酶稳定，故对耐庆大霉素、卡那霉素的菌株仍有效。卡那霉素、链霉素、妥布霉素易被钝化酶灭活；青霉素不属氨基糖苷类，故均不选"},{"q":"后遗效应是","o":["血药浓度已降至阈浓度以下时残存的药理效应","血药浓度过高引起的不良反应","血浆蛋白结合率过高引起的不良反应","短期内残存的药理效应","机体产生依赖性引起"],"a":0,"e":"后遗效应指停药后血药浓度已降至阈浓度以下时仍残存的药理效应，如服用巴比妥类催眠药后次晨的困倦。血药浓度过高引起的是毒性反应；短期内残存的效应表述不准确；血浆蛋白结合率高影响分布而非后遗效应；药物依赖性属特殊毒性，均与后遗效应定义不同"},{"q":"治疗流行性脑脊髓膜炎的首选药是","o":["链霉素","四环素","磺胺嘧啶","红霉素","环丙沙星"],"a":2,"e":"磺胺嘧啶血浆蛋白结合率适中、易透过血脑屏障，在脑脊液中浓度较高，是治疗流行性脑脊髓膜炎的首选磺胺药。链霉素、四环素、红霉素、环丙沙星虽对脑膜炎奈瑟菌有一定作用，但透过血脑屏障或疗效不及磺胺嘧啶，均非首选"},{"q":"直接作用于支气管腺体，促进黏液分泌细胞的溶酶体释出，裂解黏痰中的黏多糖纤维的药物是","o":["N-乙酰半胱氨酸","氯化铵","溴己新","喷托维林","美司坦"],"a":2,"e":"溴己新直接作用于支气管腺体，促进黏液分泌细胞溶酶体释放，使黏痰中的黏多糖纤维裂解、痰液变稀易于咳出，用于痰黏难咳者。N-乙酰半胱氨酸通过断裂二硫键化痰；氯化铵为刺激性祛痰药；喷托维林、美司坦主要为止咳药，机制不同"},{"q":"可用于急性风湿热鉴别诊断的药物是","o":["保泰松","对乙酰氨基酚","阿司匹林","布洛芬","吲哚美辛"],"a":2,"e":"阿司匹林小剂量抗血小板、大剂量抗炎抗风湿，可用于急性风湿热的鉴别诊断与治疗，用药后发热、关节痛等迅速缓解支持风湿热诊断。保泰松因毒性大少用；对乙酰氨基酚抗炎作用弱，不用于风湿热；布洛芬、吲哚美辛虽抗炎但非风湿热鉴别诊断的经典用药"},{"q":"下列药物中降低血浆胆固醇作用最明显的是","o":["烟酸","他汀类","贝特类","抗氧化剂","多烯脂肪酸类"],"a":1,"e":"他汀类通过抑制HMG-CoA还原酶减少胆固醇合成，并上调低密度脂蛋白受体，显著降低血浆低密度脂蛋白胆固醇，是降低胆固醇作用最强的一类。贝特类、多烯脂肪酸类主要降甘油三酯；烟酸降脂谱较广但降胆固醇强度不及他汀；抗氧化剂如普罗布考主要抗氧化、降胆固醇作用有限"},{"q":"下列药物中半衰期最长的二氢吡啶类药物是","o":["硝苯地平","尼莫地平","氨氯地平","尼群地平","尼索地平"],"a":2,"e":"氨氯地平口服吸收缓慢、半衰期长达三十五至五十小时，是二氢吡啶类中作用最持久者，每日一次给药即可。硝苯地平、尼莫地平、尼群地平、尼索地平半衰期均较短，需多次给药或缓释制剂维持，故氨氯地平半衰期最长"},{"q":"治疗高胆固醇血症的首选药物是","o":["低分子肝素","氯贝丁酯","烟酸","洛伐他汀","苯扎贝特"],"a":3,"e":"洛伐他汀为他汀类，抑制HMG-CoA还原酶、降低低密度脂蛋白胆固醇，是治疗高胆固醇血症的首选药物。氯贝丁酯、苯扎贝特属贝特类，主要降甘油三酯；烟酸降脂谱广但非高胆固醇首选；低分子肝素为抗凝药，与降脂无关"},{"q":"下列哪项不符合氨基糖苷类抗生素的特点","o":["对革兰氏阴性杆菌具强大抗菌作用","具有抗菌后效应","干扰细菌核酸合成","抗菌作用为浓度依赖性","口服不吸收"],"a":2,"e":"氨基糖苷类通过抑制细菌蛋白质合成发挥抗菌作用，并不干扰核酸合成，故该项不符合其特点。此类药物对革兰阴性杆菌作用强大，属浓度依赖性抗菌药，具有抗菌后效应，且口服难吸收、需注射给药，其余各项均为其真实特点"},{"q":"吗啡镇咳的主要作用部位是","o":["脑室及导水管周围灰质","脑干网状结构","延髓孤束核","中脑盖前核","大脑皮层"],"a":2,"e":"吗啡镇咳作用主要通过抑制延髓孤束核等咳嗽中枢相关部位，降低咳嗽反射敏感性。脑室及导水管周围灰质主要介导镇痛；脑干网状结构参与觉醒与镇痛调节；中脑盖前核与瞳孔反射有关；大脑皮层为高级中枢，均非吗啡镇咳的主要作用部位"},{"q":"耐药金黄色葡萄球菌感染不宜采用青霉素G治疗，此细菌对青霉素G产生耐药的可能机制是","o":["细胞膜通透性改变","产生乙酰转移酶","菌体内靶位结构改变","产生β-内酰胺酶","产生二氢蝶酸合酶"],"a":3,"e":"耐药金黄色葡萄球菌对青霉素G耐药的主要机制是产生β-内酰胺酶，即青霉素酶，水解药物β-内酰胺环使其失活。细胞膜通透性改变、靶位结构改变可见于其他耐药机制但不是金葡菌对青霉素G的主要方式；乙酰转移酶涉及氨基糖苷类；二氢蝶酸合酶与磺胺类耐药相关"},{"q":"高血压药物治疗的新概念不包括","o":["终身治疗","平稳降压","有效治疗","间断用药","联合用药"],"a":3,"e":"高血压药物治疗强调终身治疗、有效治疗、平稳降压与联合用药，以提高依从性、保护靶器官，间断用药会导致血压波动、增加心脑血管事件，不属于新概念。其余各项均为现代高血压治疗的基本原则，故间断用药为不包括的内容"},{"q":"组织中的组胺主要存在于","o":["粒细胞","红细胞","肥大细胞","嗜酸细胞","巨噬细胞"],"a":2,"e":"组织中组胺主要储存于肥大细胞和嗜碱性粒细胞的颗粒中，受到刺激时脱颗粒释放，参与过敏反应与炎症。粒细胞、红细胞、巨噬细胞并非组胺主要储存细胞；嗜酸细胞主要参与抗寄生虫与过敏调节，含主要碱性蛋白等而非大量组胺"},{"q":"毛果芸香碱不能用于治疗","o":["青光眼","虹膜炎","唾液腺功能减退","阵发性心动过速","阿托品中毒"],"a":3,"e":"毛果芸香碱为M胆碱受体激动药，可缩瞳降眼压治疗青光眼，与扩瞳药交替用于虹膜炎，促进唾液分泌治唾液腺功能减退，并可解救阿托品中毒。阵发性心动过速非其适应证，M受体激动虽可减慢心率，但临床不用毛果芸香碱治疗该心律失常"},{"q":"阻碍细胞有丝分裂的抗癌药是","o":["丝裂霉素","氟尿嘧啶","紫杉醇","甲氨蝶呤","氨苯蝶啶"],"a":2,"e":"紫杉醇促进微管蛋白聚合、抑制微管解聚，使细胞周期阻滞于G2/M期，阻碍有丝分裂而发挥抗癌作用。丝裂霉素为烷化剂类、交叉联结DNA；氟尿嘧啶、甲氨蝶呤为抗代谢药干扰核酸合成；氨苯蝶啶为利尿药，均非通过阻碍有丝分裂起作用"},{"q":"治疗脑水肿宜选用的药物是","o":["呋塞米","氢氯噻嗪","氨苯蝶啶","螺内酯","阿米洛利"],"a":0,"e":"呋塞米为强效袢利尿药，快速强效利尿、降低血容量，并可降低脑脊液生成，可用于脑水肿，常与甘露醇交替使用。氢氯噻嗪利尿作用温和；氨苯蝶啶、螺内酯为保钾利尿药，作用弱；阿米洛利亦为保钾利尿药，均不适用于脑水肿的紧急处理"},{"q":"硫酸镁不能用于治疗","o":["肠内毒物排出","阻塞性黄疸","高血压危象","子痫","消化性溃疡"],"a":4,"e":"硫酸镁口服可导泻排出肠内毒物、利胆用于阻塞性黄疸，注射可抗惊厥治疗子痫、舒张血管用于高血压危象。消化性溃疡并非其适应证，口服镁盐对溃疡无治疗作用且可刺激肠道，故硫酸镁不能用于治疗消化性溃疡"},{"q":"一旦糖皮质激素与其受体结合，从其受体复合物中解离的是","o":["启动子","热休克蛋白","抑制性蛋白","兴奋性蛋白","大分子蛋白复合物"],"a":1,"e":"胞浆中糖皮质激素受体与热休克蛋白等分子伴侣结合成无活性复合物，激素与受体结合后热休克蛋白解离，受体活化转位入核调控基因转录。启动子为DNA序列；抑制性蛋白、兴奋性蛋白、大分子蛋白复合物均非该解离成分，故只有热休克蛋白符合"},{"q":"下列不属于影响细菌细胞壁合成的抗生素是","o":["青霉素类","头孢菌素类","万古霉素","林可霉素","杆菌肽"],"a":3,"e":"林可霉素通过与细菌核糖体50S亚基结合抑制蛋白质合成，不属于影响细胞壁合成的抗生素。青霉素类、头孢菌素类抑制肽聚糖交联；万古霉素阻碍肽聚糖合成；杆菌肽抑制细胞壁合成，均通过干扰细胞壁发挥作用"},{"q":"药物的血浆半衰期（t1/2）是指","o":["稳态血浆药物浓度下降一半的时间","有效血浆药物浓度下降一半的时间","血浆药物浓度下降一半的时间","药物被肝脏转化一半的时间","药物从肾脏排泄一半的时间"],"a":2,"e":"血浆半衰期指血浆药物浓度下降一半所需的时间，是反映药物消除快慢、确定给药间隔的重要依据。稳态血药浓度下降一半是停药后的消除情况；有效浓度下降一半、肝脏转化一半、肾脏排泄一半均非半衰期的规范定义，故以血浆药物浓度下降一半为准"},{"q":"有关水蛭素的叙述，正确的是","o":["主要经肝脏代谢失活","过量可用维生素K对抗","口服易吸收","灭活凝血因子Ⅱa、Ⅶa、Ⅸa、Ⅹa","抑制凝血酶活性"],"a":4,"e":"水蛭素是强效、特异的直接凝血酶抑制剂，与凝血酶活性中心结合而抑制其活性，抗凝作用不依赖抗凝血酶Ⅲ。它主要经肾排泄、口服不吸收；过量无特异性拮抗剂，维生素K不能对抗；灭活Ⅱa、Ⅶa、Ⅸa、Ⅹa是肝素等的作用，故只有抑制凝血酶活性正确"},{"q":"应用硫脲类抗甲药最需要注意的严重不良反应是","o":["粒细胞缺乏","药物热","甲状腺肿大","突眼加重","甲状腺素缺乏"],"a":0,"e":"硫脲类抗甲状腺药最严重的不良反应是粒细胞缺乏症，可致严重感染，用药中应定期复查血常规，一旦发生须立即停药。药物热、皮疹较常见但较轻；甲状腺肿大、突眼加重与激素水平波动有关；甲状腺素缺乏是过量表现，均非最需警惕的严重反应"},{"q":"既可用于活动性结核病的治疗，又可用作预防的药物","o":["乙胺丁醇","环丝氨酸","链霉素","异烟肼","对氨水杨酸"],"a":3,"e":"异烟肼对结核分枝杆菌疗效高、毒性低、穿透力强，既可用于各型活动性结核病的治疗，也可用于结核病密切接触者的预防。乙胺丁醇、环丝氨酸、对氨水杨酸主要用于治疗且疗效较弱；链霉素针剂且毒性较大，均不常规用于预防"},{"q":"吗啡的适应证是","o":["心源性哮喘","支气管哮喘","诊断未明的急腹症","颅内压增高","分娩止痛"],"a":0,"e":"吗啡可扩张外周血管、降低心脏前后负荷，并减轻焦虑、抑制呼吸中枢对二氧化碳的敏感性，缓解心源性哮喘的呼吸困难，是其适应证。支气管哮喘禁用吗啡，可加重支气管痉挛并抑制呼吸；诊断未明急腹症、颅内压增高、分娩止痛均属禁忌，以免掩盖病情或致呼吸抑制"},{"q":"属于抗孕激素类药物的是","o":["米非司酮","黄体酮","己烯雌酚","氯米芬","环丙孕酮"],"a":0,"e":"米非司酮为孕激素受体拮抗剂，属抗孕激素药，可对抗孕激素作用、终止早期妊娠，常与米索前列醇合用抗早孕。黄体酮为孕激素；己烯雌酚为雌激素；氯米芬为促排卵药，属抗雌激素；环丙孕酮为孕激素类抗雄激素药，均非抗孕激素"},{"q":"一个效价强度高、效能强的激动剂应是","o":["高脂溶性，短t1/2","高亲和力，高内在活性","低亲和力，低内在活性","低亲和力，高内在活性","高亲和力，低内在活性"],"a":1,"e":"效价强度取决于药物与受体的亲和力，亲和力高则所需剂量小、效价强度高；效能取决于内在活性，内在活性高则最大效应强，故效价强度高且效能强的激动剂应具备高亲和力与高内在活性。低亲和力、低内在活性者效价与效能均低；仅高亲和力或仅高内在活性只满足其一，均不全面"},{"q":"下列关于离子通道生理功能，错误的是","o":["维持细胞正常形态和功能完整性","对血管平滑肌的舒缩活动无影响","介导兴奋-收缩偶联和兴奋-分泌偶联","决定细胞的兴奋性、不应性和传导性","参与细胞跨膜信号转导过程"],"a":1,"e":"离子通道通过调控离子跨膜流动参与细胞跨膜信号转导，决定细胞兴奋性、不应性与传导性，介导兴奋-收缩偶联和兴奋-分泌偶联，并维持细胞正常形态与功能完整性。血管平滑肌的舒缩依赖钙、钾等离子通道，故对血管平滑肌舒缩活动无影响的说法错误"},{"q":"肝药酶的特点是","o":["专一性高，活性高","专一性高，活性低","专一性低，个体差异大","专一性低，个体差异小","专一性高，个体差异大"],"a":2,"e":"肝药酶即细胞色素P450系统，专一性低，可代谢多种化学结构不同的药物，且活性受遗传、年龄、疾病及诱导或抑制因素影响，个体差异大。其专一性并非高，活性也不是普遍高，个体差异小的说法与事实相悖，故正确特点为专一性低、个体差异大"},{"q":"阿卡波糖的药理作用是","o":["减慢碳水化合物水解及产生葡萄糖的速度并延缓葡萄糖的吸收","结合胰岛β细胞膜上的特异性受体，促进胰岛素分泌","改善胰岛素抵抗","促进脂肪组织摄取葡萄糖","促进胰岛素的作用"],"a":0,"e":"阿卡波糖竞争性抑制肠道α-糖苷酶，延缓淀粉、蔗糖等碳水化合物水解为葡萄糖，从而减慢葡萄糖生成与吸收、降低餐后血糖。结合胰岛β细胞受体促胰岛素分泌是磺酰脲类机制；改善胰岛素抵抗是噻唑烷二酮类作用；促进脂肪摄取葡萄糖、促进胰岛素作用亦非阿卡波糖机制"},{"q":"能促进去甲肾上腺素能神经末梢释放NA的拟肾上腺素药物是","o":["去甲肾上腺素","异丙肾上腺素","新斯的明","麻黄碱","多巴酚丁胺"],"a":3,"e":"麻黄碱为混合型拟肾上腺素药，既直接激动α、β受体，又能促进去甲肾上腺素能神经末梢释放NA，作用温和持久。去甲肾上腺素直接激动受体、不促释放；异丙肾上腺素为β受体激动剂；新斯的明为胆碱酯酶抑制剂；多巴酚丁胺主要激动β1受体，均不通过促进NA释放起效"},{"q":"改善恶性贫血患者的神经症状宜用","o":["叶酸","铁剂","维生素B1","维生素B12","亚叶酸钙"],"a":3,"e":"恶性贫血因内因子缺乏致维生素B12吸收障碍，维生素B12参与神经髓鞘合成，补充后可改善患者的神经症状并纠正贫血。叶酸仅纠正贫血、不能改善神经损害；铁剂用于缺铁性贫血；维生素B1用于脚气病；亚叶酸钙为叶酸衍生物，均不能改善恶性贫血的神经症状"},{"q":"小儿发热常选用的药物是","o":["阿司匹林","对乙酰氨基酚","吲哚美辛","吡罗昔康","尼美舒利"],"a":1,"e":"对乙酰氨基酚对胃肠道刺激小、不良反应较少，是儿童发热常用的退热药。阿司匹林在儿童病毒感染时有诱发Reye综合征的风险，不宜常规用于小儿发热；吲哚美辛、吡罗昔康、尼美舒利不良反应相对较多，均非小儿发热首选"},{"q":"阿托品抗休克主要是由于","o":["收缩血管，升高血压","兴奋心脏，输出量增加","扩张血管，改善微循环","扩张支气管，缓解呼吸困难","减少休克因子的释放"],"a":2,"e":"大剂量阿托品可解除血管痉挛、扩张外周血管、改善微循环，因而用于感染性休克等的治疗。它并不收缩血管升压，也不以兴奋心脏增加输出量为主；扩张支气管、缓解呼吸困难是β2激动药作用；减少休克因子释放亦非其主要机制"},{"q":"易渗入骨组织中治疗骨髓炎的有效药物是","o":["红霉素","吉他霉素","克林霉素","阿奇霉素","罗红霉素"],"a":2,"e":"克林霉素在骨组织中浓度高、穿透力强，对引起骨髓炎的常见病原菌如金葡菌、厌氧菌有效，是治疗骨髓炎的适宜药物。红霉素、吉他霉素、阿奇霉素、罗红霉素属大环内酯类，骨组织浓度低，不适合骨髓炎治疗"},{"q":"甲苯磺丁脲降血糖作用的主要机制是","o":["增强胰岛素作用","提高靶细胞的敏感性","刺激胰岛β细胞释放胰岛素","使细胞内cAMP含量减少","抑制胰高血糖素的作用"],"a":2,"e":"甲苯磺丁脲属磺酰脲类，主要阻断胰岛β细胞ATP敏感钾通道、使细胞膜去极化并开放钙通道，促使胰岛素释放而降血糖，故需胰岛β细胞尚有功能。增强胰岛素作用、提高靶细胞敏感性是增敏剂机制；减少环磷酸腺苷、抑制胰高血糖素均非其主要作用方式"},{"q":"药物零级动力学消除是指","o":["药物完全消除到零","单位时间内按恒量消除药物","药物消除速度与吸收速度相等","单位时间内按恒比消除药物","血浆浓度达到稳定水平"],"a":1,"e":"零级动力学消除指单位时间内消除恒定数量的药物，其消除速度与血药浓度无关，多见于药物浓度过高、消除能力饱和时。按恒比消除是一级动力学特点；完全消除到零、消除速度与吸收速度相等、血浆浓度稳定均不是零级动力学的定义"},{"q":"最易引起暂时或永久性耳聋的利尿药是","o":["依他尼酸","布美他尼","呋塞米","氢氧噻嗪","氯酞酮"],"a":0,"e":"依他尼酸属强效袢利尿药，耳毒性在利尿药中最为明显，易引起暂时或永久性耳聋，与氨基糖苷类合用毒性相加。呋塞米、布美他尼亦有耳毒性但相对较轻；氢氯噻嗪、氯酞酮属噻嗪类，基本无耳毒性，故依他尼酸最易致耳聋"},{"q":"HMG-CoA还原酶抑制剂是","o":["普罗布考","考来烯胺","苯扎贝特","洛伐他汀","氯贝丁酯"],"a":3,"e":"洛伐他汀为他汀类药物，竞争性抑制HMG-CoA还原酶、减少胆固醇合成，是经典的降脂药。普罗布考为抗氧化降脂药；考来烯胺为胆汁酸螯合剂；苯扎贝特、氯贝丁酯属贝特类，主要降甘油三酯，均非HMG-CoA还原酶抑制剂"},{"q":"促进药物被动转运的因素里，最普遍的是","o":["药物的跨膜浓度差小","药物油水分布系数小","药物的分子量小","药物的解离度小","药物的脂溶性小"],"a":3,"e":"多数药物以简单扩散方式跨膜转运，只有非解离型、脂溶性高的药物易通过，故解离度小即非解离型比例高，是促进被动转运最普遍的因素。跨膜浓度差大才利于扩散而非小；油水分布系数大、脂溶性大才促进转运；分子量小虽有利，但解离度是决定能否转运的普遍关键因素"},{"q":"以下关于曲马多的药理作用，错误的是","o":["较弱的μ受体激动作用","呼吸抑制作用弱","对胃肠道无影响","纳洛酮可完全拮抗其镇痛效应","镇痛效力与喷他佐辛相当"],"a":3,"e":"曲马多镇痛机制包括较弱的μ受体激动及抑制去甲肾上腺素、5-羟色胺重摄取，纳洛酮仅能部分拮抗其镇痛效应，故完全拮抗的说法错误。曲马多呼吸抑制弱、对胃肠道影响小，镇痛效力约与喷他佐辛相当，这些叙述均符合其药理特点"},{"q":"能嵌入到肿瘤细胞DNA双链中影响其功能的药物是","o":["甲氨蝶呤","氟尿嘧啶","阿糖胞苷","放线菌素D","L-门冬酰胺酶"],"a":3,"e":"放线菌素D可嵌入DNA双链碱基对之间，阻碍RNA聚合酶结合、抑制转录而发挥抗肿瘤作用。甲氨蝶呤抑制二氢叶酸还原酶；氟尿嘧啶、阿糖胞苷为抗代谢药抑制DNA合成；L-门冬酰胺酶水解门冬酰胺，均非嵌入DNA双链的药物"},{"q":"奥美拉唑治疗消化性溃疡的作用是","o":["阻断M1胆碱受体，抑制胃酸分泌","阻断H2受体，抑制胃酸分泌","阻断胃泌素受体，抑制胃酸分泌","抑制胃壁细胞H＋泵，抑制胃酸分泌","保护胃黏膜"],"a":3,"e":"奥美拉唑为质子泵抑制剂，特异抑制胃壁细胞氢钾ATP酶，阻断胃酸分泌的最后环节，抑酸强而持久。阻断M1受体是哌仑西平机制；阻断H2受体是西咪替丁等H2受体拮抗剂；阻断胃泌素受体为丙谷胺；单纯保护胃黏膜为铋剂、硫糖铝，均非奥美拉唑作用"},{"q":"引起血压双相反应的药物是","o":["去甲肾上腺素","麻黄碱","肾上腺素","间羟胺","异丙肾上腺素"],"a":2,"e":"肾上腺素激动α受体使血管收缩、血压升高，随后β2受体效应显现使血管舒张、血压略降，形成先升后降的双相反应。去甲肾上腺素、间羟胺以α效应为主，主要升压；麻黄碱作用温和；异丙肾上腺素激动β受体主要降压，均无典型双相反应"},{"q":"目前临床上，戊巴比妥主要用于下列哪种情况","o":["抗焦虑","镇静催眠","抗惊厥抗癫痫","中枢性肌肉松弛","内镜检查前"],"a":2,"e":"戊巴比妥为中效巴比妥类，具有镇静、催眠、抗惊厥作用，临床主要用于抗惊厥、抗癫痫。其抗焦虑、中枢性肌松作用不突出；镇静催眠多用短效类；内镜检查前常用短效镇静药；苯巴比妥更常用于抗癫痫，但戊巴比妥亦用于抗惊厥，均非其余选项所述的首要用途"},{"q":"碘化物的急性不良反应是","o":["心绞痛","血管神经性水肿","粒细胞缺乏","甲状腺功能减退","耳毒性"],"a":1,"e":"碘化物急性不良反应主要为过敏反应，表现为血管神经性水肿、喉头水肿、皮疹甚至过敏性休克，需警惕。心绞痛非碘剂典型急性反应；粒细胞缺乏是硫脲类严重不良反应；甲状腺功能减退是碘剂长期过量抑制激素合成的慢性后果；耳毒性为氨基糖苷类等，均非碘化物急性反应"},{"q":"梗阻性黄疸引起的出血宜选用哪种药物进行治疗","o":["氨甲苯酸","去甲肾上腺素","维生素K","链激酶","纤维蛋白原"],"a":2,"e":"梗阻性黄疸时胆汁排出受阻，脂溶性维生素K吸收减少，依赖维生素K的凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成障碍而致出血，应补充维生素K。氨甲苯酸用于纤溶亢进出血；去甲肾上腺素局部止血；链激酶为溶栓药，可加重出血；纤维蛋白原用于低纤维蛋白原血症，均非梗阻性黄疸出血的根本治疗"},{"q":"普萘洛尔禁用于支气管哮喘的机理是","o":["阻断支气管平滑肌β2受体","阻断支气管平滑肌β1受体","阻断支气管平滑肌α受体","阻断支气管平滑肌M受体","激动支气管平滑肌M受体"],"a":0,"e":"普萘洛尔为非选择性β受体阻断药，阻断支气管平滑肌β2受体，使支气管收缩、痉挛，诱发或加重哮喘，故禁用于支气管哮喘。β1受体主要位于心脏；α受体、M受体与支气管舒张无直接对应，阻断M受体反而舒张支气管，均非普萘洛尔诱发哮喘的机制"},{"q":"氯丙嗪抗精神病作用机制是阻断","o":["中枢α肾上腺素受体","中枢β肾上腺素受体","中脑边缘叶及中脑皮质通路中DA受体","黑质纹状体通路中的5-HT1受体","中枢M1受体"],"a":2,"e":"氯丙嗪抗精神病作用主要阻断中脑-边缘系统和中脑-皮层通路的D2样受体，改善精神分裂症阳性症状。阻断黑质-纹状体D2受体引起锥体外系反应；阻断结节-漏斗D2受体致催乳素升高；阻断α受体致体位性低血压；阻断M受体致口干、便秘，均非抗精神病主要机制"},{"q":"通过干扰细菌蛋白质合成而产生抗菌作用的抗菌药物是","o":["万古霉素","青霉素","多黏菌素","庆大霉素","头孢菌素"],"a":3,"e":"庆大霉素属氨基糖苷类，与细菌核糖体30S亚基结合、抑制蛋白质合成而产生抗菌作用。万古霉素、青霉素、头孢菌素均通过干扰细胞壁合成起效；多黏菌素影响细胞膜通透性，均不通过抑制蛋白质合成抗菌"},{"q":"长期应用有成瘾性的镇咳药是","o":["喷托维林","可待因","氯化铵","苯佐那酯","右美沙芬"],"a":1,"e":"可待因为阿片类中枢性镇咳药，镇咳作用强，长期应用可产生依赖性和成瘾性，故需控制使用。喷托维林、右美沙芬为非成瘾性中枢镇咳药；苯佐那酯为外周性镇咳药；氯化铵为祛痰药，均无成瘾性，故只有可待因符合"},{"q":"与丙磺舒竞争肾小管分泌的抗生素是","o":["链霉素","青霉素","多黏菌素B","异烟肼","氯霉素"],"a":1,"e":"青霉素主要经肾小管主动分泌排泄，丙磺舒与其竞争同一有机阴离子转运载体，减少青霉素分泌、提高其血药浓度并延长作用时间。链霉素、多黏菌素B、异烟肼、氯霉素的排泄不主要依赖该分泌途径，故不与丙磺舒发生此类竞争"},{"q":"关于硝酸甘油的作用，哪项是错误的","o":["扩张脑血管","扩张冠状血管","心率减慢","扩张静脉","降低外周阻力"],"a":2,"e":"硝酸甘油扩张静脉和动脉、降低前后负荷并扩张冠脉，可因血压下降反射性引起心率加快，故心率减慢错误。它能扩张冠状血管、脑血管，扩张静脉降低前负荷，降低外周阻力，这些均为其真实作用"},{"q":"药动学是研究","o":["药物作用随剂量变化的规律","药物作用随时间变化的规律","药物的体内过程及体内药物浓度随时间变化的规律","药物作用随药物化学结构变化的规律","药物的体内过程及体内药物浓度随剂量变化的规律"],"a":2,"e":"药动学研究药物在体内的吸收、分布、代谢、排泄等体内过程，以及体内药物浓度随时间变化的规律，常用半衰期、清除率等参数描述。药物作用随剂量、时间或化学结构变化的规律属于药效学或构效关系范畴；随剂量变化的浓度规律表述片面，故以体内过程及浓度随时间变化为准"},{"q":"兼有抗利尿素分泌作用的降血糖药是","o":["甲苯磺丁脲","二甲双胍","格列本脲","氯磺丙脲","苯乙双胍"],"a":3,"e":"氯磺丙脲属磺酰脲类，除降血糖外还能促进抗利尿激素分泌、增强肾小管对水的重吸收，可用于轻度尿崩症，是兼有抗利尿作用的降糖药。甲苯磺丁脲、格列本脲无此作用；二甲双胍、苯乙双胍为双胍类，主要通过减少肝糖输出降糖，均无抗利尿效应"},{"q":"氯霉素的抗菌谱中，不包括","o":["金葡菌","伤寒杆菌","肺炎链球菌","结核分枝杆菌","立克次体"],"a":3,"e":"氯霉素抗菌谱广，对金葡菌、伤寒杆菌、肺炎链球菌及立克次体等均有效，曾用于伤寒、立克次体病。但对结核分枝杆菌无效，结核病需用异烟肼、利福平等抗结核药，故结核分枝杆菌不在氯霉素抗菌谱内"},{"q":"对普鲁卡因胺的叙述错误的是","o":["作用与奎尼丁相似但较弱","能降低浦肯野纤维的自律性","减慢传导速度","延长有效不应期","较强的抗α受体和抗胆碱作用"],"a":4,"e":"普鲁卡因胺为Ia类抗心律失常药，作用与奎尼丁相似但较弱，能降低浦肯野纤维自律性、减慢传导、延长有效不应期。其抗α受体和抗胆碱作用远较奎尼丁弱，几乎无明显抗胆碱作用，故较强的抗α受体和抗胆碱作用不符合普鲁卡因胺，该项叙述错误"},{"q":"以下属于麻醉前给药的药物是","o":["氯丙嗪","阿托品","琥珀胆碱","氯胺酮","丙泊酚"],"a":1,"e":"阿托品为M受体阻断药，麻醉前给药可抑制唾液腺、支气管腺体分泌，防止误吸并保持呼吸道通畅，还可防止麻醉中迷走反射引起的心动过缓。氯丙嗪为抗精神病药；琥珀胆碱为肌松药；氯胺酮、丙泊酚为麻醉药，均非麻醉前给药"},{"q":"某药按零级动力学消除，其消除半衰期等于","o":["0.693/Ke","Ke/0.5C0","0.5C0/Ke","Ke/0.5","0.5/Ke"],"a":2,"e":"零级动力学消除时血药浓度按恒定速率下降，即浓度等于初始浓度减去消除速率常数与时间之积，当浓度降为初始值一半时，半衰期等于零点五倍初始浓度除以消除速率常数，与初始浓度有关。零点六九三除以消除速率常数是一级动力学半衰期公式，其余表达式不符合零级消除的速度方程"},{"q":"下列属于西咪替丁临床适应证的是","o":["严重急性感染","异体器官移植","消化性溃疡","再生障碍性贫血","感染中毒性休克"],"a":2,"e":"西咪替丁为H2受体拮抗药，抑制胃酸分泌，临床用于胃、十二指肠溃疡及胃酸分泌过多症，促进溃疡愈合。严重急性感染、感染中毒性休克需抗感染抗休克；异体器官移植用免疫抑制剂；再生障碍性贫血用糖皮质激素或免疫抑制治疗，均非西咪替丁适应证"},{"q":"氯丙嗪抗精神病作用的主要机制是","o":["阻断黑质-纹状体系统D2受体","阻断中脑-边缘系统和中脑-皮层系统的D2样受体","阻断结节-漏斗系统D2受体","阻断肾上腺素α受体","阻断M胆碱受体"],"a":1,"e":"氯丙嗪抗精神病作用主要通过阻断中脑-边缘系统与中脑-皮层系统的D2样受体，缓解精神分裂症幻觉、妄想等阳性症状。阻断黑质-纹状体D2受体引起锥体外系反应；阻断结节-漏斗D2受体致内分泌紊乱；阻断α受体、M受体分别引起低血压和抗胆碱效应，均非抗精神病主要机制"},{"q":"可刺激卵巢滤泡发育和成熟，使其分泌雌激素的物质是","o":["FSH","LH","GnRH","TSH","ACTH"],"a":0,"e":"FSH即促卵泡激素，作用于卵巢颗粒细胞，促进卵泡发育与成熟，并刺激雌激素分泌。LH主要促进排卵和黄体形成、孕激素分泌；GnRH为下丘脑释放激素，促进垂体释放FSH、LH；TSH调节甲状腺；ACTH调节肾上腺皮质，均非直接促卵泡发育成熟的主要激素"},{"q":"新药Ⅱ期临床试验观察病例不少于","o":["50例","100例","200例","300例","400例"],"a":1,"e":"我国新药临床试验规定，Ⅱ期临床试验为治疗作用初步评价阶段，观察病例数不少于一百例，以评价疗效与安全性。Ⅰ期一般为二十至三十例；Ⅲ期不少于三百例；四百例并非Ⅱ期的最低病例数要求，故一百例为Ⅱ期临床试验的规定例数"},{"q":"可强烈促进血小板聚集的是","o":["PGE1","PGI2","TXA2","5-HT","PGF2α"],"a":2,"e":"TXA2即血栓素A2，由血小板产生，强烈促进血小板聚集并收缩血管，是血栓形成的重要介质。PGI2即前列环素，由血管内皮产生，抑制血小板聚集、舒张血管，作用与TXA2相反；PGE1亦抑制聚集；5-HT、PGF2α促聚集作用远弱于TXA2，故TXA2作用最强"},{"q":"下列药物中对于变异型心绞痛治疗效果最好，并对伴有高血压患者尤为适用的是","o":["硝苯地平","硝酸甘油","普萘洛尔","维拉帕米","硝酸异山梨酯"],"a":0,"e":"硝苯地平为二氢吡啶类钙通道阻滞剂，强力扩张冠状动脉、解除冠脉痉挛，对变异型心绞痛疗效最好，同时扩张外周血管降压，特别适合伴高血压者。硝酸甘油、硝酸异山梨酯主要扩张静脉；普萘洛尔阻断β受体可致冠脉痉挛加重，不宜用于变异型；维拉帕米对冠脉痉挛作用不及硝苯地平"},{"q":"高效利尿药的作用机制是","o":["抑制髓袢升支Na＋-K＋交换","减少近曲小管NaCl的再吸收","抑制髓袢升支髓质部与皮质部Na＋-K＋-2Cl－共转运","作用于髓袢升支皮质部，阻断NaCl再吸收","抑制远曲小管Na＋-K＋交换"],"a":2,"e":"高效即袢利尿药如呋塞米抑制髓袢升支粗段髓质部与皮质部的钠钾氯同向转运子，减少氯化钠重吸收、破坏髓质高渗梯度，产生强大利尿作用。抑制钠钾交换是保钾利尿药机制；减少近曲小管重吸收是碳酸酐酶抑制剂等作用；阻断髓袢升支皮质部氯化钠重吸收是噻嗪类，作用部位不同"},{"q":"下列可影响递质释放的药物是","o":["毛果芸香碱","地西泮","烟碱","去甲肾上腺素","麻黄碱"],"a":4,"e":"麻黄碱除直接激动受体外，还能促进去甲肾上腺素能神经末梢释放NA，属于影响递质释放的药物。毛果芸香碱直接激动M受体；地西泮增强GABA能抑制；烟碱激动N受体；去甲肾上腺素直接激动肾上腺素受体，均不以促进递质释放为主要机制"},{"q":"下列哪种情况不必首选胰岛素治疗","o":["1型糖尿病","2型糖尿病患者经饮食治疗无效","2型糖尿病患者口服降糖药治疗无效","酮症酸中毒","糖尿病并发严重感染"],"a":1,"e":"胰岛素适用于1型糖尿病、酮症酸中毒、糖尿病并发严重感染及2型口服降糖药无效者。2型糖尿病患者经饮食治疗无效时，可先选用口服降糖药，并非必须首选胰岛素，故该情况不必首选胰岛素治疗"},{"q":"出现紧张、忧虑、失眠并伴有心悸、出汗、震颤等症状，下列可以显著改善该症状的药物是","o":["地西泮","苯妥英钠","唑吡坦","水合氯醛","氟马西尼"],"a":0,"e":"紧张、忧虑、失眠伴心悸、出汗、震颤为焦虑症表现，地西泮通过增强GABA能抑制、作用于大脑边缘系统，抗焦虑作用显著，可改善上述症状。苯妥英钠为抗癫痫药；唑吡坦、水合氯醛主要催眠；氟马西尼为苯二氮䓬受体拮抗剂，用于解救苯二氮䓬类过量，均不适用"},{"q":"常用舌下给药的药物是","o":["阿司匹林","硝酸甘油","维拉帕米","链霉素","苯妥英钠"],"a":1,"e":"硝酸甘油舌下含服可直接经口腔黏膜吸收入血、避开首过消除，起效快，是心绞痛急性发作常用给药方式。阿司匹林、维拉帕米、链霉素、苯妥英钠一般口服或注射给药，不采用舌下途径，故舌下给药以硝酸甘油最常用"},{"q":"作用快而短暂，不用于治疗，可用于诊断重症肌无力的药物是","o":["新斯的明","毒扁豆碱","毛果芸香碱","依酚氯铵","安贝氯铵"],"a":3,"e":"依酚氯铵为短效胆碱酯酶抑制剂，静脉注射后作用快而短暂，可使重症肌无力患者肌力一过性改善，用于该病的诊断，而不用于常规治疗。新斯的明、安贝氯铵为治疗用药；毒扁豆碱、毛果芸香碱主要用于眼科，均非重症肌无力的诊断用药"},{"q":"有关肝素的药理作用机制，叙述正确的是","o":["拮抗维生素K","直接灭活凝血因子Ⅱa、Ⅶa、Ⅸa、Ⅹa","增强抗凝血酶Ⅲ的活性","直接与凝血酶结合，抑制其活性","抑制凝血因子的生物合成"],"a":2,"e":"肝素主要通过与抗凝血酶Ⅲ结合、增强其活性，加速对凝血因子Ⅱa、Ⅸa、Ⅹa、Ⅺa、Ⅻa等的灭活而抗凝。拮抗维生素K是华法林机制；肝素不直接灭活凝血因子，也不直接结合凝血酶，更不抑制凝血因子合成，故增强抗凝血酶Ⅲ活性为其正确机制"},{"q":"只激动M受体的药物是","o":["乙酰胆碱","阿托品","毒扁豆碱","氯贝胆碱","卡巴胆碱"],"a":3,"e":"氯贝胆碱为选择性M胆碱受体激动药，对M受体作用较强、对N受体几无作用，临床用于术后尿潴留等。乙酰胆碱、卡巴胆碱对M、N受体均有激动作用；阿托品为M受体阻断药；毒扁豆碱为胆碱酯酶抑制剂，间接增加乙酰胆碱，均非只激动M受体的药物"},{"q":"与血浆蛋白结合力较强的两种药物同时应用时，应注意","o":["结合型药物增加，药理作用下降","游离型药物增加，药理活性增加","结合型药物减少，药理活性下降","游离型药物减少，药理活性下降","结合型药物增加，药理活性下降"],"a":1,"e":"两药竞争血浆蛋白结合位点时，结合力强者置换结合力弱者，使后者游离型药物增多、药理活性与毒性增加，需注意调整剂量。结合型药物本身无药理活性，其增加或减少对活性的影响方向与游离型相反，故结合型增加、游离型减少导致活性下降等说法均不符合置换规律"},{"q":"第三代头孢菌素的特点不包括","o":["对革兰氏阳性菌作用比第一、二代强","对革兰氏阴性菌包括肠杆菌属和铜绿假单胞菌及厌氧菌有较强的作用","t1/2较长，体内分布广","对肾脏基本无毒性","对β-内酰胺酶有较高稳定性"],"a":0,"e":"第三代头孢菌素对革兰阴性菌包括肠杆菌、铜绿假单胞菌及厌氧菌作用强，对β-内酰胺酶稳定性高，半衰期较长、体内分布广、基本无肾毒性；但对革兰阳性菌的作用较第一、二代弱，而非更强，故该项不属于第三代头孢的特点"},{"q":"下列药物可用于治疗高钙血症的药物是","o":["呋塞米","氨苯喋啶","乙酰唑胺","噻嗪类","甘露醇"],"a":0,"e":"呋塞米抑制髓袢升支粗段钠钾氯共转运，增加尿钙排泄，可用于高钙血症的治疗，常与生理盐水合用。噻嗪类减少尿钙排泄，可致血钙升高，不宜用于高钙血症；氨苯蝶啶、乙酰唑胺、甘露醇对钙排泄影响小或机制不同，均非高钙血症的适宜药物"},{"q":"能降低地高辛血药浓度的药物是","o":["奎尼丁","苯妥英钠","胺碘酮","维拉帕米","普罗帕酮"],"a":1,"e":"苯妥英钠为肝药酶诱导剂，可加速地高辛代谢、降低其血药浓度。奎尼丁、胺碘酮、维拉帕米、普罗帕酮与地高辛合用多通过竞争排泄或分布，使地高辛血药浓度升高，易致中毒，需减量，故只有苯妥英钠降低地高辛浓度"},{"q":"以下关于丁丙诺啡的描述，正确的是","o":["镇痛效力弱于吗啡","呼吸抑制作用强","可用于吗啡成瘾的脱毒治疗","拮抗μ受体","激动κ受体"],"a":2,"e":"丁丙诺啡为阿片受体部分激动剂，对μ受体部分激动、对κ受体拮抗，镇痛效力强于吗啡，呼吸抑制较轻且有封顶效应，可用于吗啡等阿片类成瘾的脱毒替代治疗。它激动而非拮抗μ受体，故拮抗μ受体错误；其余关于镇痛效力弱、呼吸抑制强的描述亦不符"},{"q":"治疗继发性醛固酮增多症的首选药物是","o":["呋塞米","氢氯噻嗪","氨苯喋啶","螺内酯","甘露醇"],"a":3,"e":"螺内酯为醛固酮受体拮抗药，竞争性拮抗醛固酮的保钠排钾作用，故是治疗继发性醛固酮增多症所致水肿的首选。呋塞米、氢氯噻嗪为排钾利尿药；氨苯蝶啶虽保钾但直接阻滞钠通道、不拮抗醛固酮；甘露醇为脱水药，均非针对醛固酮增多的首选"},{"q":"脑内最重要的抑制性神经递质是","o":["5-HT","GABA","ACh","DA","NA"],"a":1,"e":"γ-氨基丁酸是脑内最主要的抑制性递质，通过激活GABA受体开放氯通道使突触后膜超极化，产生广泛抑制效应。5-HT与DA、NA同属单胺类递质，多以调制兴奋或抑制的双向作用为主，并非首要抑制递质。ACh在脑内多为兴奋性递质，其毒蕈碱样作用可致心率减慢、腺体分泌增加，与抑制性递质的定义不同"},{"q":"与核蛋白30S亚基结合，阻止氨基酰tRNA进入A位的抗菌药是","o":["氯霉素","林可霉素","庆大霉素","四环素","链霉素"],"a":3,"e":"四环素类与细菌核糖体30S亚基的A位结合，阻止氨基酰tRNA进入，从而抑制肽链延长，属快速抑菌药。链霉素、庆大霉素虽也作用于30S亚基，但通过引起mRNA错读合成异常蛋白，并非占据A位。氯霉素结合50S亚基抑制肽酰转移酶，林可霉素同样作用于50S亚基，二者位点与四环素不同"},{"q":"某驾驶员患有过敏性鼻炎，工作期间最宜使用","o":["苯海拉明","异丙嗪","曲吡那敏","阿司咪唑","氯苯那敏"],"a":3,"e":"阿司咪唑为第二代H1受体阻断药，不易透过血脑屏障，无明显镇静和嗜睡作用，适合需保持警觉的驾驶员。苯海拉明、异丙嗪、曲吡那敏均为第一代药物，中枢抑制作用明显，可致嗜睡、注意力下降。氯苯那敏虽有中枢抑制较弱之说，但仍可产生困倦，驾驶或高空作业者不宜使用"},{"q":"多巴胺使肾和肠系膜的血管舒张，是由于","o":["兴奋β受体","直接作用于血管平滑肌","选择性兴奋DA受体","选择性阻断α受体","促组胺释放"],"a":2,"e":"多巴胺在低至中等剂量时选择性激动肾、肠系膜血管的D1受体，激活腺苷酸环化酶使血管平滑肌舒张，增加肾血流量。兴奋β受体主要见于较高剂量，且以心脏β1兴奋为主，并非肾血管舒张的机制。直接扩血管见于其他药物，阻断α受体为酚妥拉明的作用，促组胺释放则与过敏反应相关"},{"q":"苯巴比妥在临床上不用于","o":["镇静、催眠","麻醉","抗惊厥","抗癫痫","中枢性肌松作用"],"a":4,"e":"苯巴比妥为巴比妥类中效药，通过增强GABA能抑制发挥镇静、催眠、抗惊厥和抗癫痫作用，大剂量可用于麻醉。其不具有中枢性骨骼肌松弛作用，肌松作用主要见于地西泮等苯二氮䓬类或中枢性肌松药。镇静催眠和抗惊厥是巴比妥类的经典适应证，与肌松作用机制不同"},{"q":"绝对口服生物利用度等于","o":["（静脉注射定量药物后AUC/口服等量药物后AUC）×100%","（口服等量药物后AUC/静脉注射定量药物后AUC）×100%","（口服定量药物后AUC/静脉注射定量药物后AUC）×100%","（口服一定药物后AUC/静脉注射定量药物后AUC）×100%","（静脉注射等量药物后AUC/口服定量药物后AUC）×100%"],"a":1,"e":"绝对口服生物利用度以静脉注射为参比，等于口服等量药物后曲线下面积与静脉注射等量药物后曲线下面积之比再乘百分之百，静脉给药生物利用度视为百分之百。将比值倒置即成为静脉与口服之比，意义相反。口服与静脉剂量必须相等才有可比性，否则比值失去剂量校正的基础"},{"q":"下列关于新斯的明的作用描述正确的是","o":["脂溶性高，易透过血脑屏障进入中枢神经系统","对骨骼肌作用最强，对心血管、腺体作用较弱","对胃肠道和膀胱平滑肌作用较强，可用于前列腺肥大所致尿潴留","滴眼可降低眼内压","可用于解救除极化型肌松药中毒"],"a":1,"e":"新斯的明为可逆性胆碱酯酶抑制药，对骨骼肌的兴奋作用最强，因其还能直接激动运动终板N2受体并促进乙酰胆碱释放，对心血管和腺体作用较弱。该药为季铵类，脂溶性低，不易透过血脑屏障，中枢作用不明显。它可用于术后尿潴留，但前列腺肥大所致机械性梗阻并非其适应证；解救除极化型肌松药中毒反而加重肌松"},{"q":"影响半衰期长短的主要因素是","o":["剂量","吸收速度","原血浆浓度","消除速度","给药时间"],"a":3,"e":"半衰期是血药浓度下降一半所需时间，按一级动力学消除时t1/2等于0.693除以消除速率常数，故主要取决于药物的消除速度。剂量和给药时间只改变初始或稳态浓度水平，不改变消除速率常数。吸收速度影响达峰时间，原血浆浓度随消除自然下降，均非决定半衰期长短的因素"},{"q":"以下哪种药物组合对疟原虫有协同治疗作用","o":["青蒿素+乙胺嘧啶","青蒿素+氯喹","青蒿素+甲氟喹","青蒿素+奎宁","氯喹+奎宁"],"a":2,"e":"青蒿素类与甲氟喹合用可产生协同抗疟作用，两者作用于不同环节，甲氟喹半衰期长，还能延缓耐药性的产生，是常用的联合方案。青蒿素与氯喹或奎宁合用疗效并不优于单用，且可能交叉耐药。乙胺嘧啶主要抑制二氢叶酸还原酶，多用于预防，与青蒿素的协同关系不如甲氟喹明确"},{"q":"抗精神病作用强，且锥体外系副作用轻的药物是","o":["氯丙嗪","氯氮平","氟哌啶醇","氯普噻吨","五氟利多"],"a":1,"e":"氯氮平为二苯并氮䓬类非典型抗精神病药，对精神分裂症阳性及阴性症状均有较好疗效，锥体外系反应明显少于经典药物。氯丙嗪、氟哌啶醇、氯普噻吨、五氟利多均属典型抗精神病药，主要通过阻断D2受体发挥作用，疗效确切但易出现震颤、僵直等锥体外系症状"},{"q":"目前临床医师推荐常用的抗高血压药不包括","o":["利尿药","钾通道阻滞药","β受体阻断药","ACEI","ARB"],"a":1,"e":"常用一线降压药包括利尿药、β受体阻断药、ACEI、ARB和钙通道阻滞药，钾通道阻滞药虽可降压，但因不良反应较多，不列入临床常规推荐。利尿药通过排钠减少血容量，β受体阻断药降低心输出量和肾素释放，ACEI与ARB分别抑制血管紧张素Ⅱ生成和阻断其受体，均为推荐类别"},{"q":"化疗药物是指","o":["治疗各种疾病的化学药物","抗菌药物","专门治疗结核病的化学药物","防治病原微生物、寄生虫及恶性肿瘤的化学药物","人工合成的化学药物"],"a":3,"e":"化学治疗药物指用于防治病原微生物、寄生虫感染及恶性肿瘤的化学药物，按对象可分为抗感染药、抗寄生虫药和抗肿瘤药。治疗各种疾病的化学药物范围过宽，包含了非化疗药。抗菌药物和抗结核药仅是其中一个分支，人工合成也只是来源分类，均不足以概括化疗药的完整内涵"},{"q":"下列药物属于肾素抑制药的是","o":["阿利吉仑","普萘洛尔","卡托普利","氯沙坦","氢氯噻嗪"],"a":0,"e":"阿利吉仑是直接肾素抑制药，与肾素活性部位结合，阻断血管紧张素原转化为血管紧张素Ⅰ，从源头抑制RAAS。卡托普利抑制血管紧张素转化酶，属于ACEI而非肾素抑制药。氯沙坦阻断AT1受体，普萘洛尔通过抑制肾素释放间接起效，氢氯噻嗪为利尿药，作用环节各不相同"},{"q":"金黄色葡萄球菌感染首选的治疗药物是","o":["青霉素G","氨苄西林","苯唑西林","万古霉素","头孢氨苄"],"a":3,"e":"万古霉素通过抑制细菌细胞壁肽聚糖合成发挥强大杀菌作用，对耐药革兰阳性菌尤其耐甲氧西林金黄色葡萄球菌感染为首选，故可用于金黄色葡萄球菌重症感染。青霉素G易被青霉素酶水解，苯唑西林虽耐酶但对耐甲氧西林菌株无效。氨苄西林和头孢氨苄对产酶金葡菌的可靠性不及万古霉素"},{"q":"某哮喘患者，遵医嘱使用沙丁胺醇治疗哮喘的作用机制是","o":["激动β1受体","激动β2受体","阻断β1受体","阻断β2受体","阻断M受体"],"a":1,"e":"沙丁胺醇为选择性β2受体激动药，激动支气管平滑肌β2受体后激活腺苷酸环化酶，使cAMP升高，支气管平滑肌松弛，用于缓解哮喘急性发作。激动β1受体主要兴奋心脏，非平喘所需。阻断β受体反而收缩支气管，阻断M受体为异丙托溴铵的作用机制，均与本药相反"},{"q":"促进胰岛释放胰岛素的药物是","o":["格列苯脲","二甲双胍","阿卡波糖","罗格列酮","苯乙双胍"],"a":0,"e":"格列苯脲属磺酰脲类口服降糖药，阻断胰岛β细胞ATP敏感钾通道，使膜去极化、钙内流，从而促进胰岛素释放，故适用于有一定胰岛功能的患者。二甲双胍和苯乙双胍主要通过抑制肝糖异生、改善外周胰岛素抵抗起效，不刺激分泌。阿卡波糖抑制α葡萄糖苷酶延缓糖吸收，罗格列酮为胰岛素增敏剂"},{"q":"支原体肺炎首选药物是","o":["青霉素","红霉素","氯霉素","多黏菌素","利福平"],"a":1,"e":"肺炎支原体无细胞壁，青霉素和头孢类对其无效，红霉素等大环内酯类通过与细菌50S亚基结合抑制蛋白质合成，是支原体肺炎首选。氯霉素虽也抑制蛋白合成，但因骨髓抑制等毒性不作首选。多黏菌素作用于革兰阴性菌胞膜，利福平主要用于结核和部分革兰阳性菌，均非支原体肺炎常规用药"},{"q":"抗血小板药物不包括","o":["阿司匹林","噻氯匹啶","双嘧达莫","尿激酶","水蛭素"],"a":3,"e":"尿激酶为溶栓药，直接激活纤溶酶原转变为纤溶酶，溶解已形成的纤维蛋白血栓，用于急性血栓栓塞性疾病，不属于抗血小板药。阿司匹林抑制环氧酶减少TXA2生成，噻氯匹啶阻断P2Y12受体，双嘧达莫抑制磷酸二酯酶，三者均通过不同环节抑制血小板聚集，是典型的抗血小板药"},{"q":"具有抗病毒作用的抗帕金森病药物是","o":["左旋多巴","卡比多巴","金刚烷胺","溴隐亭","司来吉兰"],"a":2,"e":"金刚烷胺原为抗流感病毒药，后发现其可促进纹状体多巴胺释放并抑制再摄取，还能轻度阻断谷氨酸NMDA受体，用于帕金森病。左旋多巴需补充多巴胺前体，卡比多巴为外周脱羧酶抑制药，单用无效。溴隐亭直接激动D2受体，司来吉兰抑制单胺氧化酶B，各自机制与金刚烷胺不同"},{"q":"关于吗啡描述错误的是","o":["强而持久的镇痛作用","镇静作用","呼吸抑制","降低胃肠平滑肌张力","引起体位性低血压"],"a":3,"e":"吗啡兴奋胃肠道平滑肌，提高张力并抑制蠕动，使肠内容物通过延缓，同时抑制消化液分泌、提高括约肌张力，故常见便秘，降低胃肠平滑肌张力的说法与事实相反。其强效镇痛、镇静及呼吸抑制均为典型作用。吗啡扩张外周血管可引起体位性低血压，亦符合其药理特点"},{"q":"普鲁卡因不可用于哪种局麻方式","o":["蛛网膜下腔麻醉","浸润麻醉","表面麻醉","传导麻醉","硬膜外麻醉"],"a":2,"e":"普鲁卡因对黏膜穿透力弱，难以透过黏膜发挥表面麻醉作用，故不用于表面麻醉，常用表面麻醉药为丁卡因。其亲脂性低、毒性较小，适合浸润麻醉，也可用于传导麻醉、蛛网膜下腔麻醉和硬膜外麻醉。作用时间短、穿透力差是限制其表面应用的关键"},{"q":"连续服用巴比妥类药物，突然停药，易发生","o":["成瘾性","反跳现象","睡眠改善","呼吸抑制","习惯性"],"a":1,"e":"长期连续服用巴比妥类药物后突然停药，可出现反跳现象，表现为原症状加重、失眠和焦虑，与药物依赖及中枢抑制适应有关。成瘾性和习惯性属于精神与躯体依赖的不同表现，并非停药后症状加重的专有名称。呼吸抑制为过量中毒反应，睡眠改善更与停药后的反跳相反"},{"q":"去甲肾上腺素用于上消化道出血时采用的给药方式是","o":["稀释后口服","皮下注射","静脉注射","肌肉注射","静脉滴注"],"a":0,"e":"去甲肾上腺素用于上消化道出血时采用稀释后口服，使药物直接作用于食管和胃黏膜血管α受体，局部收缩止血，因口服吸收少且经首过消除，全身不良反应较轻。静脉滴注主要用于休克时升压，皮下或肌内注射可致局部组织坏死，静脉注射血压骤升风险大，均非消化道止血的给药途径"},{"q":"对非甾体类抗炎药引起的消化性溃疡，有特效的药物是","o":["米索前列醇","昂丹司琼","硫糖铝","多潘立酮","三硅酸镁"],"a":0,"e":"米索前列醇为前列腺素E1衍生物，能抑制胃酸分泌并增加胃黏膜黏液和碳酸氢盐分泌、改善黏膜血流，对非甾体抗炎药抑制前列腺素所致的消化性溃疡有特效。硫糖铝为黏膜保护剂，三硅酸镁为抗酸药，均无针对病因的替代作用。昂丹司琼为止吐药，多潘立酮为促胃肠动力药，与溃疡愈合无关"},{"q":"阿司匹林用于防治血栓形成的机理是","o":["直接抑制磷脂酶","减少花生四烯酸的堆积","抑制PG合成酶，使TXA2合成减少","直接抑制PGI2生成","直接对抗PG"],"a":2,"e":"阿司匹林不可逆乙酰化环氧酶即PG合成酶，使血小板中TXA2生成减少，抑制血小板聚集，从而防治血栓形成。其并不直接抑制磷脂酶，也不减少花生四烯酸堆积。PGI2由血管内皮合成，小剂量阿司匹林对其影响较小，并非直接对抗前列腺素，故低剂量即可选择性抗血小板"},{"q":"氨基糖苷类对下列那类细菌不敏感","o":["大肠埃希菌","铜绿假单胞菌","克雷伯菌","耐甲氧西林金黄色葡萄球菌","厌氧菌"],"a":4,"e":"氨基糖苷类对需氧革兰阴性杆菌如大肠埃希菌、克雷伯菌、铜绿假单胞菌以及耐甲氧西林金黄色葡萄球菌均有较好抗菌活性。其进入细菌依赖氧依赖性主动转运，厌氧菌缺乏该转运系统，故天然耐药、不敏感。这一机制也解释了氨基糖苷类对厌氧菌感染无效的临床特点"},{"q":"以下哪种小分子化合物不是多靶点的抗肿瘤药物","o":["索拉非尼","舒尼替尼","厄洛替尼","克唑替尼","拉帕替尼"],"a":2,"e":"厄洛替尼为选择性表皮生长因子受体酪氨酸激酶抑制剂，靶点单一，不属于多靶点抗肿瘤药。索拉非尼抑制RAF、VEGFR等多个激酶，舒尼替尼靶点包括VEGFR和PDGFR，克唑替尼抑制ALK、ROS1和MET，拉帕替尼同时抑制EGFR和HER2，均属多靶点药物"},{"q":"可用于肾上腺嗜铬细胞瘤鉴别诊断的药物是","o":["育亨宾","酚妥拉明","硝普钠","可乐定","普萘洛尔"],"a":1,"e":"酚妥拉明为非选择性α受体阻断药，可拮抗嗜铬细胞瘤释放大量儿茶酚胺引起的升压效应，注射后血压显著下降有助于该病的鉴别诊断。育亨宾选择性阻断α2受体，主要用于实验研究。硝普钠直接扩血管降压，可乐定为中枢α2激动药，普萘洛尔阻断β受体，均不用于此项鉴别"},{"q":"普萘洛尔的禁忌证不包括","o":["严重左室心功能不全","窦性心动过缓","支气管哮喘","重度房室传导阻滞","稳定型心绞痛"],"a":4,"e":"稳定型心绞痛是普萘洛尔的适应证，其通过阻断β受体减慢心率、降低心肌收缩力，减少心肌耗氧量而缓解心绞痛，并非禁忌。严重左室功能不全和窦性心动过缓者用药可加重心衰和心率过慢，重度房室传导阻滞者阻滞加重，支气管哮喘患者可诱发支气管痉挛，均为禁忌"},{"q":"应用华法林时为掌握好剂量，应测定","o":["凝血酶原时间","凝血时间","止血时间","部分凝血质时间","出血时间"],"a":0,"e":"华法林通过抑制维生素K依赖凝血因子的合成发挥抗凝作用，主要延长外源性凝血途径的凝血酶原时间，临床以PT或INR为监测指标调整剂量。凝血时间反映内源性途径，对华法林不敏感。出血时间反映血小板功能，部分凝血活酶时间用于监测肝素，均非华法林剂量调整的依据"},{"q":"局麻药的作用机制是","o":["局麻药阻碍Ca2＋内流，阻碍复极化","局麻药促进Na＋内流，产生持久去极化","局麻药促进K＋内流，促进复极化","局麻药阻碍Na＋内流，阻碍去极化","局麻药阻碍K＋外流，阻碍去极化"],"a":3,"e":"局麻药以非解离型穿透神经膜，在膜内侧解离后带正电荷，与电压门控钠通道结合并阻断钠内流，使动作电位去极化受阻，神经冲动传导中断。阻碍钙内流或钾外流并非其主要机制，促进钠内流会加强去极化而与麻醉作用相反，促进钾内流同样不能阻断动作电位的产生"},{"q":"可用于治疗肝性脑病的药物是","o":["丙环定","溴隐亭","苯海索","卡比多巴","左旋多巴"],"a":4,"e":"左旋多巴进入脑内转化为多巴胺，可补充肝性脑病中不足的兴奋性神经递质，改善意识状态，故可用于治疗肝性脑病。卡比多巴为外周脱羧酶抑制药，单用不能进入中枢，无此疗效。苯海索、丙环定均为中枢抗胆碱药，溴隐亭为多巴胺受体激动药，作用环节与补充递质不同"},{"q":"用药前必须做皮肤过敏试验的局麻药是","o":["罗哌卡因","普鲁卡因","丁卡因","利多卡因","丁哌卡因"],"a":1,"e":"普鲁卡因为酯类局麻药，其代谢产物对氨基苯甲酸易引起过敏反应，用药前必须做皮肤过敏试验。利多卡因为酰胺类，过敏罕见，一般无需常规皮试。丁卡因、罗哌卡因和丁哌卡因虽也可致敏，但临床要求常规皮试的仍以普鲁卡因为典型代表，这是酯类与酰胺类的重要区别"},{"q":"糖皮质激素类药物隔日疗法宜选用","o":["泼尼松","氟轻松","地塞米松","氢化可的松","曲安西龙"],"a":0,"e":"隔日疗法宜选用中效糖皮质激素泼尼松，其半衰期适中，隔日清晨一次给药可减轻对下丘脑垂体肾上腺轴的抑制，同时保留抗炎疗效。地塞米松为长效制剂，作用时间长，对轴的抑制明显，不宜隔日使用。氢化可的松为短效，需多次给药。氟轻松和曲安西龙多用于外用或局部注射，非隔日疗法首选"},{"q":"属于骨吸收抑制药的是","o":["降钙素","甲状旁腺激素","氟化物","钙剂","维生素D"],"a":0,"e":"降钙素通过抑制破骨细胞活性、减少骨吸收而降低骨转换，属于骨吸收抑制药，临床用于骨质疏松伴骨痛。甲状旁腺激素间歇给药可促进骨形成，属骨形成促进药。氟化物促进骨形成，钙剂和维生素D为骨矿化相关补充药，均不归入骨吸收抑制药"},{"q":"肿瘤化疗后引起的粒细胞缺乏症宜选用","o":["硫酸亚铁","叶酸","非格司亭","红细胞生成素","维生素B12"],"a":2,"e":"非格司亭为重组人粒细胞集落刺激因子，可促进骨髓粒系造血干细胞的增殖分化，升高外周血中性粒细胞，用于肿瘤化疗后粒细胞缺乏症。硫酸亚铁补铁用于缺铁性贫血，叶酸和维生素B12用于巨幼红细胞性贫血，红细胞生成素刺激红细胞生成，均不针对粒细胞缺乏"},{"q":"出现青霉素所致的过敏性休克时，应立即选用","o":["肾上腺素","糖皮质激素","青霉素","苯海拉明","苯巴比妥"],"a":0,"e":"青霉素过敏性休克时首选肾上腺素，其激动α受体收缩血管升高血压，激动β1受体增强心输出量，并激动β2受体松弛支气管平滑肌、抑制介质释放，能迅速逆转休克。糖皮质激素起效慢，仅作辅助。苯海拉明为H1阻断药，作用有限。青霉素本身为致敏原，苯巴比妥无抗休克作用"},{"q":"毒扁豆碱滴眼后缩瞳的机制是","o":["直接兴奋瞳孔括约肌M受体","直接兴奋睫状肌M受体","直接阻断瞳孔开大肌α受体","促进ACh释放激动M受体","抑制AChE，减少ACh水解"],"a":4,"e":"毒扁豆碱为可逆性胆碱酯酶抑制药，滴眼后抑制乙酰胆碱酯酶，减少乙酰胆碱水解，使突触间隙乙酰胆碱蓄积并激动瞳孔括约肌M受体，产生缩瞳。它不直接激动M受体，也不促进乙酰胆碱释放，更不阻断瞳孔开大肌α受体，这些说法均与其间接拟胆碱的作用机制不符"},{"q":"可用于治疗尿崩症的利尿药是","o":["呋塞米","氢氯噻嗪","螺内酯","氨苯蝶啶","乙酰唑胺"],"a":1,"e":"氢氯噻嗪通过排钠使血浆渗透压降低，减少尿崩症患者尿量，是治疗尿崩症的利尿药，对肾性尿崩症也有效。呋塞米利尿作用强，会加重多尿。螺内酯和氨苯蝶啶为保钾利尿药，无此用途。乙酰唑胺抑制碳酸酐酶，主要用于青光眼，亦非尿崩症用药"},{"q":"盐皮质激素临床多用于","o":["慢性肾上腺皮质功能减退","糖尿病","甲状腺功能亢进","严重感染/炎症","休克"],"a":0,"e":"盐皮质激素以醛固酮为代表，促进肾远曲小管和集合管保钠排钾，临床主要用于慢性肾上腺皮质功能减退症的替代治疗。糖尿病和甲状腺功能亢进与盐皮质激素无关。严重感染和炎症主要用糖皮质激素抗炎抗毒，休克治疗亦以糖皮质激素或血管活性药为主，均非盐皮质激素的适应证"},{"q":"丁螺环酮抗焦虑的主要作用位点是","o":["GABAA受体","NMDA受体","D2受体","N受体","5-HT1A受体"],"a":4,"e":"丁螺环酮为选择性5-HT1A受体部分激动药，通过调节5-HT能神经传递发挥抗焦虑作用，无镇静催眠和成瘾性，也不引起明显锥体外系反应。苯二氮䓬类作用于GABAA受体，NMDA受体与谷氨酸兴奋传递相关，D2受体为抗精神病药靶点，N受体为烟碱型胆碱受体，均非其主要作用位点"},{"q":"下列降压药物中直接抑制血管紧张素转化酶的是","o":["依那普利","缬沙坦","阿利吉仑","利血平","可乐定"],"a":0,"e":"依那普利为血管紧张素转化酶抑制药，通过抑制ACE减少血管紧张素Ⅱ生成，同时减少缓激肽降解，用于降压。缬沙坦阻断AT1受体，不抑制转化酶。阿利吉仑直接抑制肾素，作用于更上游。利血平耗竭交感神经末梢递质，可乐定激动中枢α2受体，均不直接抑制转化酶"},{"q":"胸痛剧烈伴刺激性干咳的患者宜选用","o":["喷托维林","可待因","右美沙芬","苯佐那酯","溴己新"],"a":1,"e":"可待因为中枢性镇咳药，兼有中等强度镇痛作用，适合胸痛剧烈伴刺激性干咳者，既止咳又缓解疼痛。右美沙芬镇咳强度与可待因相当但无镇痛作用。喷托维林镇咳较弱并有解痉作用，苯佐那酯为外周性镇咳药，溴己新为祛痰药，均不能兼顾剧烈胸痛的镇痛需求"},{"q":"X药对某受体有亲和力，无内在活性；Y药对该受体既有亲和力，又有内在活性，则X、Y分别是","o":["激动药，拮抗药","拮抗药，激动药","部分激动药，激动药","拮抗药，拮抗药","激动药，激动药"],"a":1,"e":"药物与受体结合需具备亲和力和内在活性，X有亲和力而无内在活性，能占据受体但不能产生效应，属拮抗药。Y兼具亲和力与内在活性，能激动受体产生效应，属激动药。部分激动药虽有内在活性但不足，与完全激动药合用可减弱其效应，题干所给条件并不符合这一情形"},{"q":"不属于碳青霉烯类抗生素的是","o":["硫霉素","亚胺培南","美罗培南","帕尼培南","氨曲南"],"a":4,"e":"氨曲南为单环β内酰胺类抗生素，不属于碳青霉烯类。硫霉素为碳青霉烯类母核，亚胺培南、美罗培南、帕尼培南均属碳青霉烯类，抗菌谱广、对β内酰胺酶稳定。氨曲南仅对革兰阴性需氧菌有效，对革兰阳性菌和厌氧菌无效，抗菌谱与碳青霉烯类明显不同"},{"q":"治疗青霉素引起的过敏性休克的首选药是","o":["多巴酚丁胺","异丙肾上腺素","去甲肾上腺素","多巴胺","肾上腺素"],"a":4,"e":"青霉素引起的过敏性休克首选肾上腺素，其α样作用收缩血管、提升血压并减轻黏膜水肿，β1样作用增强心肌收缩，β2样作用解除支气管痉挛并抑制过敏介质释放。多巴酚丁胺和多巴胺主要用于心衰或休克升压，异丙肾上腺素无α效应不能提升血压，去甲肾上腺素缺乏明显支气管舒张作用"},{"q":"以下属于骨形成促进药的是","o":["阿仑膦酸钠","甲状旁腺激素","降钙素","替勃龙","雷洛昔芬"],"a":1,"e":"甲状旁腺激素间歇给药可促进成骨细胞活性、增加骨形成，属于骨形成促进药，用于骨质疏松症。阿仑膦酸钠为双膦酸盐，抑制破骨细胞属骨吸收抑制药。降钙素抑制破骨细胞，替勃龙和雷洛昔芬为选择性雌激素受体调节剂，主要通过抑制骨吸收发挥作用"},{"q":"新斯的明最显著的药理作用是","o":["减慢心率","促进腺体分泌","兴奋骨骼肌","兴奋中枢","降低眼内压"],"a":2,"e":"新斯的明最显著的作用是兴奋骨骼肌，机制包括抑制胆碱酯酶减少乙酰胆碱破坏、直接激动运动终板N2受体以及促进乙酰胆碱释放，故用于重症肌无力。减慢心率和促进腺体分泌为其胆碱能效应但较弱，不易进入中枢，滴眼降眼内压并非其突出作用"},{"q":"下列不属于麦角生物碱类药物的适应证的是","o":["产后止血","子宫复原","偏头痛","催产引产","人工冬眠"],"a":3,"e":"麦角生物碱对子宫平滑肌有强大而持久的兴奋作用，但易引起强直性收缩，不宜用于催产引产，临床用于产后止血和子宫复原，麦角胺类还可用于偏头痛。人工冬眠采用氯丙嗪等中枢抑制药配伍，与麦角类作用无关。催产引产宜用缩宫素小剂量静脉滴注"},{"q":"激动H2受体产生的效应是","o":["胃肠平滑肌收缩","支气管平滑肌收缩","胃壁细胞胃酸分泌增多","心房收缩增强，房室结传导减慢","瞳孔缩小"],"a":2,"e":"H2受体激动可激活胃壁细胞腺苷酸环化酶，升高cAMP并激活质子泵，使胃酸分泌增多，故H2受体阻断药可抑制胃酸。胃肠和支气管平滑肌收缩主要由M受体介导，心房收缩增强由β1受体介导，瞳孔缩小为M受体激动的结果，均非H2受体兴奋的效应"},{"q":"急性吗啡中毒的特效解毒药是","o":["洛贝林","尼克刹米","纳洛酮","美沙酮","二甲弗林"],"a":2,"e":"纳洛酮为阿片受体纯拮抗药，与μ、κ等受体亲和力高而本身无内在活性，能迅速逆转吗啡等阿片类引起的呼吸抑制和意识障碍，是急性吗啡中毒的特效解毒药。洛贝林、尼可刹米、二甲弗林为中枢兴奋药，仅对症且易致惊厥。美沙酮为阿片受体激动药，用于替代脱毒，不能解毒"},{"q":"育亨宾可选择性阻断","o":["M受体","β1受体","β2受体","α1受体","α2受体"],"a":4,"e":"育亨宾为选择性α2受体阻断药，可阻断突触前膜α2受体，促进去甲肾上腺素释放，主要用于实验研究。酚妥拉明为非选择性α受体阻断药，对α1和α2均有作用。普萘洛尔阻断β受体，M受体阻断药如阿托品作用于胆碱能系统，均不同于育亨宾的选择性"},{"q":"治疗立克次体感染所致斑疹伤寒首选","o":["四环素","庆大霉素","青霉素","链霉素","多黏菌素"],"a":0,"e":"立克次体为专性细胞内寄生菌，四环素类能进入细胞内抑制其蛋白质合成，是斑疹伤寒等立克次体感染的首选。青霉素作用于细胞壁，对细胞内立克次体效果差。庆大霉素和链霉素为氨基糖苷类，主要针对革兰阴性杆菌。多黏菌素作用于革兰阴性菌细胞膜，对立克次体无效"},{"q":"硫酸镁没有下述哪项作用","o":["强心作用","下泻作用","降压作用","利胆作用","中枢抑制作用"],"a":0,"e":"硫酸镁口服可导泻和利胆，注射给药可抑制中枢、松弛平滑肌并扩张血管降压，镁离子还可拮抗钙离子用于抗惊厥，但不具有强心作用，过量反而抑制心肌。下泻、降压、利胆和中枢抑制均与其不同给药途径和镁离子的药理特点相符，强心并非其作用"},{"q":"下列二氢吡啶类钙拮抗药中半衰期最长的是","o":["硝苯地平","尼莫地平","氨氯地平","尼群地平","尼索地平"],"a":2,"e":"氨氯地平在二氢吡啶类中半衰期最长，可达数十小时，起效缓慢、作用持久，每日一次给药即可。硝苯地平、尼群地平、尼索地平半衰期较短，需多次给药或缓释制剂。尼莫地平半衰期也较短，主要用于脑血管痉挛。半衰期差异与药物分子结构和清除率不同有关"},{"q":"下列药物的作用靶点和药理作用组合正确的是","o":["舒马普坦-5-HT1A受体——抗焦虑","丁螺环酮-5-HT1A受体——抑制食欲","赛庚啶-5-HT2受体——偏头痛","西沙必利-5-HT3受体——胃肠动力","昂丹司琼-5-HT3受体——镇吐"],"a":2,"e":"赛庚啶可阻断5-HT2受体，兼有较强H1受体阻断作用，临床可用于偏头痛的预防和过敏性疾病，故该项配对正确。舒马普坦为5-HT1B/1D受体激动药，用于偏头痛急性发作而非5-HT1A抗焦虑。丁螺环酮激动5-HT1A受体发挥抗焦虑作用，并不抑制食欲。西沙必利为5-HT4受体激动药，促进胃肠动力，与5-HT3无关"},{"q":"有关利多卡因的叙述，错误的是","o":["缩短或不影响浦肯野纤维的动作电位时程","减小动作电位4相去极斜率，降低自律性","使缺血心肌的传导速度加快","主要作用于心室肌和浦氏纤维","仅对室性心律失常有效"],"a":2,"e":"利多卡因主要作用于心室肌和浦肯野纤维，阻滞钠内流，缩短或不影响浦肯野纤维动作电位时程，减小4相去极斜率而降低自律性，仅对室性心律失常有效。缺血心肌对利多卡因敏感，传导被抑制而非加快，使缺血区传导加快的说法与治疗作用相反，属于错误叙述"},{"q":"几乎无抗炎抗风湿作用的药物是","o":["阿司匹林","对乙酰氨基酚","保泰松","吲哚美辛","布洛芬"],"a":1,"e":"对乙酰氨基酚主要抑制中枢环氧酶减少前列腺素合成，解热镇痛作用明显，但外周抗炎抗风湿作用极弱，因对外周环氧酶抑制弱且被过氧化物灭活，故几乎无抗炎抗风湿效应。阿司匹林、保泰松、吲哚美辛、布洛芬均通过抑制外周前列腺素合成发挥抗炎抗风湿作用"},{"q":"竞争性抑制磺胺类药物抗菌作用的是","o":["PABA","6-APA","TMP","7-ACA","GABA"],"a":0,"e":"磺胺类与对氨基苯甲酸结构相似，竞争二氢蝶酸合酶，阻断二氢叶酸合成，从而抑制细菌核酸合成，PABA可竞争性拮抗其抗菌作用。6-APA为青霉素母核，7-ACA为头孢菌素母核，均无此作用。TMP抑制二氢叶酸还原酶，GABA为抑制性递质，与磺胺抗菌机制无关"},{"q":"下列属于抗癫痫药物的作用机制的是","o":["增强乙酰胆碱的作用","增强γ-氨基丁酸的作用","阻断儿茶酚胺的作用","阻断天冬氨酸的作用","阻断多巴胺的作用"],"a":1,"e":"多数抗癫痫药通过增强γ氨基丁酸能抑制发挥作用，如苯二氮䓬类促进GABA与受体结合，丙戊酸钠抑制GABA降解，从而提高脑内抑制性递质水平、抑制神经元异常放电。乙酰胆碱和儿茶酚胺为兴奋性递质，增强其作用不利于控制发作。天冬氨酸为兴奋性氨基酸，多巴胺与癫痫机制无直接对应"},{"q":"阿糖胞苷抗代谢作用机制是","o":["阻止嘧啶核苷酸合成","抑制DNA多聚酶","抑制二氢叶酸还原酶","抑制核苷酸还原酶","抑制拓扑异构酶"],"a":1,"e":"阿糖胞苷在体内转化为阿糖胞苷三磷酸，竞争性抑制DNA多聚酶并掺入DNA链，阻断DNA复制，属抗代谢类抗肿瘤药。阻止嘧啶核苷酸合成是氟尿嘧啶等的作用，抑制二氢叶酸还原酶为甲氨蝶呤，抑制核苷酸还原酶为羟基脲，抑制拓扑异构酶为喜树碱类，机制各异"},{"q":"氨基糖苷类抗生素用于治疗泌尿系统感染，是因为","o":["对尿道感染常见致病菌敏感","大量原形药物由肾排出","使肾皮质激素分泌增加","对肾毒性低","尿碱化可提高疗效"],"a":1,"e":"氨基糖苷类主要以原形经肾小球滤过排出，尿中浓度高，超过多数致病菌的最小抑菌浓度，故适用于泌尿系统感染。其对尿路常见革兰阴性杆菌确实敏感，但药物在尿中高浓度才是关键。该类有一定肾毒性而非毒性低，尿碱化可增强活性但非用于泌尿感染的主要原因"},{"q":"血浆蛋白低下的老年人，应用两种能与血浆白蛋白高度结合的药物时，应注意","o":["降低一种药物剂量","增加一种药物剂量","两种药物剂量都要适当减少","两种药物剂量都要增加","两种药物剂量不变"],"a":2,"e":"血浆白蛋白低下时，两药与白蛋白结合位点竞争，游离药物浓度升高，若不调整剂量易致毒性，故两种药物剂量都应适当减少。仅降低一种剂量不能消除另一种的置换风险。增加剂量或维持原量会进一步升高游离浓度，加重不良反应，均不可取"},{"q":"下列属于非选择性钙通道阻滞药的一组药物是","o":["奎尼丁、普萘洛尔、氟桂利嗪","尼莫地平、哌克昔林、氟桂利嗪","地尔硫䓬、哌克昔林、普尼拉明","维拉帕米、地尔硫䓬、硝苯地平","普尼拉明、哌克昔林、氟桂利嗪"],"a":4,"e":"普尼拉明、哌克昔林和氟桂利嗪对多种离子通道或钙通道亚型选择性低，属非选择性钙通道阻滞药。维拉帕米、地尔硫䓬和硝苯地平主要阻滞L型钙通道，属选择性钙拮抗药。奎尼丁为钠通道阻滞药，普萘洛尔为β受体阻断药，尼莫地平为二氢吡啶类选择性钙拮抗药，归类不同"},{"q":"下列药物长期使用可引起高钾血症的是","o":["氢氯噻嗪","呋塞米","甘露醇","氨苯蝶啶","乙酰唑胺"],"a":3,"e":"氨苯蝶啶直接阻断远曲小管和集合管钠通道，减少钠重吸收并抑制钾分泌，属保钾利尿药，长期使用可引起高钾血症。氢氯噻嗪、呋塞米及乙酰唑胺均增加钾排泄，长期应用易致低钾。甘露醇为渗透性利尿药，主要通过脱水起作用，不引起明显血钾升高"},{"q":"下列不能通过口服途径给药的药物是","o":["青霉素G","青霉素V","氨苄西林","头孢氨苄","头孢拉定"],"a":0,"e":"青霉素G在胃酸中不稳定，易被酸水解失活，且对青霉素酶敏感，故不能口服，临床采用肌内注射或静脉给药。青霉素V耐酸可口服。氨苄西林、头孢氨苄和头孢拉定对酸较稳定，均可口服给药，这与青霉素G的酸不稳定性形成对比"},{"q":"新斯的明用于重症肌无力，是由于","o":["对中枢的兴奋作用","增加乙酰胆碱的合成","兴奋骨骼肌中的M受体","抑制胆碱酯酶和兴奋骨骼肌","促进Ca2+内流"],"a":3,"e":"新斯的明抑制胆碱酯酶，减少乙酰胆碱水解，同时直接激动骨骼肌运动终板N2受体并促进乙酰胆碱释放，增强肌收缩力，故用于重症肌无力。它并不增加乙酰胆碱合成，也不主要兴奋中枢，更非通过促进钙内流起效；兴奋骨骼肌中的M受体之说与运动终板受体类型不符"},{"q":"治疗强心苷中毒引起的窦性心动过缓宜选用","o":["阿托品","奎尼丁","普萘洛尔","维拉帕米","氯化钾"],"a":0,"e":"强心苷中毒引起的窦性心动过缓源于迷走神经张力过高，阿托品阻断M受体解除迷走抑制，使心率加快，是首选处理。维拉帕米和普萘洛尔均减慢心率，会加重心动过缓。奎尼丁可加快心率但不适用于中毒处理。氯化钾用于纠正快速性心律失常伴低钾，对窦缓不适用"},{"q":"异烟肼抗结核杆菌的机制是","o":["破坏细菌细胞壁","影响细菌胞质膜的通透性","抑制细胞核酸代谢","抑制细菌分枝菌酸合成","抑制DNA螺旋酶"],"a":3,"e":"异烟肼通过抑制分枝菌酸合成，破坏结核分枝杆菌细胞壁的完整性，对结核杆菌有强大选择性杀菌作用。破坏细菌细胞壁为青霉素类机制，影响胞质膜通透性为多黏菌素类，抑制核酸代谢为利福平，抑制DNA螺旋酶为喹诺酮类，均非异烟肼的作用靶点"},{"q":"对华法林不正确的论述是","o":["在体内有抗凝作用","可口服","抗凝作用由ATⅢ介导","能防止血栓的形成和扩大","在体外无抗凝作用"],"a":2,"e":"华法林通过抑制维生素K依赖凝血因子的合成发挥抗凝作用，其效应并非由抗凝血酶Ⅲ介导，抗凝血酶Ⅲ介导是肝素的作用机制，故该项论述不正确。华法林口服有效，仅在体内发挥抗凝作用，能防止血栓形成和扩大，体外无抗凝效应，这些表述均符合其特点"},{"q":"硝苯地平的主要作用机制是","o":["阻滞钠通道","阻滞钾通道","阻滞钙通道","促进NO生成","减少血管紧张素生成"],"a":2,"e":"硝苯地平为二氢吡啶类钙通道阻滞药，阻滞血管平滑肌L型钙通道，减少钙内流，使血管舒张、血压下降，同时解除冠脉痉挛。阻滞钠通道为奎尼丁等抗心律失常药，阻滞钾通道可延长动作电位，促进NO生成是硝酸酯类或NO供体的作用，减少血管紧张素生成是ACEI的机制，均非硝苯地平的作用"},{"q":"静脉注射某药，引起心率加快，平均血压无变化，瞳孔散大，皮肤干燥，该药物可能是","o":["α受体激动药","β受体激动药","M受体阻断药","N受体阻断药","M受体激动药"],"a":2,"e":"M受体阻断药如阿托品可阻断节后胆碱能神经支配的效应器，使心率加快、瞳孔散大、腺体分泌减少而皮肤干燥；因不激动α受体，血压可无明显变化。α受体激动药显著升压并反射性减慢心率，β受体激动药多伴血压变化，N受体阻断药主要影响神经节和神经肌肉接头，M受体激动药则引起心率减慢和腺体分泌增加"},{"q":"琥珀胆碱用于气管镜操作时，其给药途径是","o":["口服","静脉注射","肌内注射","皮下注射","吸入"],"a":1,"e":"琥珀胆碱为除极化型肌松药，口服吸收差且在胃肠道易被破坏，气管镜操作时需静脉注射给药，起效快、维持时间短，便于短期肌松。肌内注射吸收不规则，皮下注射和吸入途径均不适用，口服无法达到有效血药浓度，故静脉注射是唯一合理的给药方式"},{"q":"具有降血脂及抗氧化作用的药物是","o":["美伐他汀","烟酸","非诺贝特","普罗布考","吉非贝齐"],"a":3,"e":"普罗布考能降低血浆总胆固醇和低密度脂蛋白，并具有强抗氧化作用，可抑制低密度脂蛋白氧化修饰，用于高胆固醇血症。他汀类如美伐他汀主要抑制胆固醇合成，烟酸和贝特类如非诺贝特、吉非贝齐主要降低甘油三酯，抗氧化作用均不如普罗布考突出"},{"q":"万古霉素不具有下列哪种特点","o":["口服易吸收","抗菌机制为阻碍细菌细胞壁合成","对革兰氏阳性细菌有强大杀菌作用","口服给药用于治疗假膜性肠炎","较大剂量，可引起听力损害"],"a":0,"e":"万古霉素口服不易吸收，仅用于肠道假膜性肠炎的局部治疗，全身感染需静脉给药，故口服易吸收的说法错误。其抗菌机制为阻碍细菌细胞壁合成，对革兰阳性菌有强大杀菌作用，大剂量或肾功能不全时可出现耳毒性和肾毒性，引起听力损害，这些均为其特点"},{"q":"具有中枢性降压作用的药物","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":0,"e":"可乐定为中枢性降压药，激动延髓孤束核α2受体和咪唑啉受体，降低交感神经张力而降压，还可抑制胃肠分泌和运动。美卡拉明为神经节阻断药，利舍平耗竭交感递质，卡托普利抑制血管紧张素转化酶，氢氯噻嗪为利尿药，降压作用部位均不在中枢"},{"q":"下列关于异丙肾上腺素作用的叙述，不正确的是","o":["激动β1受体","激动β2受体","收缩冠状动脉","舒张冠状动脉","松弛支气管平滑肌"],"a":2,"e":"异丙肾上腺素为β受体激动药，激动β2受体可舒张冠状动脉和支气管平滑肌，并促进糖原分解使cAMP增多，同时抑制组胺等过敏介质释放，因而不会收缩冠状动脉，该项叙述错误。其激动β1和β2受体是基本药理特性，松弛支气管平滑肌亦正确"},{"q":"阿托品解除平滑肌痉挛，疗效最好的是","o":["胆绞痛","肾绞痛","胃肠绞痛","膀胱刺激征","支气管哮喘"],"a":2,"e":"阿托品阻断M受体解除平滑肌痉挛，对胃肠平滑肌痉挛所致绞痛疗效最好，可迅速缓解疼痛。胆绞痛和肾绞痛因痉挛剧烈，单用阿托品疗效较差，常需配伍哌替啶。膀胱刺激征疗效有限，支气管哮喘更因阿托品抑制分泌使痰液黏稠而不宜使用"},{"q":"甲氨蝶呤的抗癌作用机制是","o":["抑制二氢叶酸还原酶，干扰核酸合成","抑制二氢蝶酸合成酶，干扰核酸合成","抑制DNA多聚酶，干扰核酸合成","抑制转录酶，干扰核酸合成","抑制胸苷酸合成酶，干扰核酸合成"],"a":0,"e":"甲氨蝶呤抑制二氢叶酸还原酶，阻断二氢叶酸还原为四氢叶酸，干扰一碳单位代谢和核酸合成，主要杀伤增殖期肿瘤细胞。抑制二氢蝶酸合成酶为磺胺类，抑制DNA多聚酶为阿糖胞苷，抑制转录酶为放线菌素类，抑制胸苷酸合成酶为氟尿嘧啶，靶点各不相同"},{"q":"苯妥英钠的应用是","o":["抗高血压","抗癫痫，抗心律失常","镇静","治疗窦性心动过速","催眠"],"a":1,"e":"苯妥英钠为乙内酰脲类抗癫痫药，通过阻滞钠通道、抑制异常放电扩散，用于癫痫大发作和局限性发作，同时可抑制室性心律失常，尤其对洋地黄中毒所致者有效。其无明显镇静催眠作用，不用于抗高血压，对窦性心动过速也非首选适应证"},{"q":"因短时外科手术使用某肌松药，使用后导致肌肉酸痛的药物是","o":["阿托品","筒箭毒碱","硫喷妥钠","琥珀胆碱","酚妥拉明"],"a":3,"e":"琥珀胆碱为除极化型肌松药，给药初期引起肌纤维成束收缩即肌束颤动，术后可出现肌肉酸痛，常用于短时外科操作的气管插管。筒箭毒碱为非除极化型肌松药，不引起肌束颤动。阿托品为M受体阻断药，硫喷妥钠为静脉麻醉药，酚妥拉明为α受体阻断药，均无此反应"},{"q":"下列关于钙通道阻滞剂药动学特性，说法正确的是","o":["钙通道阻滞药口服均能吸收，首过效应不明显，因此生物利用度较高","钙通道阻滞药与血浆蛋白结合率较低","维拉帕米、硝苯地平、地尔硫䓬的半衰期较短","氨氯地平的生物利用度较低，一般不超过60%","钙通道阻滞药通常在体内不代谢，通过肾脏排出"],"a":2,"e":"维拉帕米、硝苯地平和地尔硫䓬半衰期较短，需多次给药或使用缓释制剂，该项说法正确。钙通道阻滞药口服吸收良好但首过效应明显，生物利用度多不高，且与血浆蛋白结合率高，主要在肝代谢，多数以代谢产物排出的说法并不成立。氨氯地平生物利用度高、半衰期长，并非低于百分之六十"},{"q":"某药按一级动力学消除，给药间隔为一个半衰期。为了迅速达到稳态的血药浓度，首次给药剂量应该是常规每次药量的","o":["0.5倍","1倍","2倍","3倍","4倍"],"a":2,"e":"按一级动力学消除且给药间隔等于一个半衰期时，首次给予常规剂量的二倍即负荷剂量，可使血药浓度迅速达到稳态水平，之后按常规剂量维持。半倍或一倍剂量需经多个半衰期才接近稳态，三倍、四倍剂量则超过有效浓度范围，可能增加毒性，均非标准的负荷剂量"},{"q":"以下关于非甾体类抗炎药对体温影响的描述，正确的是","o":["使升高的体温恢复到正常水平","使正常体温进一步降低","导致体温调定点下移","使体温调节中枢失灵","增加下丘脑的PGE2合成"],"a":0,"e":"解热镇痛药通过抑制下丘脑环氧酶减少PGE2合成，使发热者升高的体温调定点回落至正常，仅对发热有效，不降低正常体温，也不使体温调定点低于正常或使中枢失灵。该类药物并不增加下丘脑PGE2合成，恰恰相反是抑制其生成"},{"q":"关于考来烯胺对血脂的影响正确的是","o":["主要降低血浆TG","明显降低血浆HDL","明显降低VLDL，轻度升高HDL","降低血浆TC、LDL-C ，明显升高HDL","降低TC、LDL-C，对HDL影响小"],"a":4,"e":"考来烯胺为胆汁酸螯合剂，在肠道结合胆汁酸阻断其重吸收，促进胆固醇转化为胆汁酸排出，从而降低血浆总胆固醇和低密度脂蛋白胆固醇，对高密度脂蛋白影响较小。其主要降低LDL而非甘油三酯，不明显降低HDL，也不显著升高HDL，这些都是其作用特点"},{"q":"关于氨茶碱，下列描述哪一项是错误的","o":["可兴奋心脏","为迅速控制哮喘，应快速静脉注射","可兴奋中枢","具有一定的利尿作用","可松弛支气管和其他平滑肌"],"a":1,"e":"氨茶碱静脉给药须缓慢注射或稀释后滴注，快速推注可致心悸、心律失常甚至惊厥和心脏骤停，故为迅速控制哮喘而快速静脉注射的说法错误。其能松弛支气管平滑肌，兼具兴奋心脏、兴奋中枢和一定利尿作用，这些描述均正确"},{"q":"用于哮喘预防性治疗及过敏性鼻炎的药物是","o":["沙丁胺醇","氨茶碱","色甘酸钠","肾上腺素","异丙托溴铵"],"a":2,"e":"色甘酸钠可稳定肥大细胞膜，阻止组胺等过敏介质释放，用于支气管哮喘的预防性治疗和过敏性鼻炎，对已发作的急性哮喘无效。沙丁胺醇为β2激动药用于急性缓解，氨茶碱为支气管舒张药，肾上腺素用于急性发作，异丙托溴铵为M受体阻断药，均非以预防过敏介质释放为主要机制"},{"q":"关于强心苷的论述，下述哪项是错误的","o":["口服吸收率与极性成反比","安全范围小，易中毒","治疗量可有心电图改变","具有负性频率作用","对肺源性心脏病的心力衰竭疗效最好"],"a":4,"e":"强心苷对不同病因的心衰疗效有差异，对高血压心脏病、瓣膜病和先天性心脏病所致心衰疗效较好，对肺源性心脏病和心肌炎所致心衰疗效差且易中毒，故疗效最好的说法错误。其口服吸收率与极性成反比，安全范围小易中毒，治疗量可致心电图改变，并具有负性频率作用"},{"q":"局麻药中加用肾上腺素能达到的目的是","o":["加快局麻药的吸收速率","提高血内局麻药浓度","延长局麻药维持时间","减少腺体分泌以防误吸","增加腺体分泌"],"a":2,"e":"局麻药中加入少量肾上腺素可收缩局部血管，减缓局麻药吸收，延长作用时间并降低血药浓度、减少中毒风险，还能减少出血。其目的不是加快吸收或提高血药浓度。减少腺体分泌以防误吸是麻醉前用阿托品的目的，增加腺体分泌与肾上腺素作用相反"},{"q":"不具有肾毒性的药物是","o":["头孢唑林","磺胺嘧啶","庆大霉素","多黏菌素","青霉素"],"a":4,"e":"青霉素本身无明显肾毒性，主要经肾排泄但一般不损伤肾小管，肾功能不全时亦相对安全。头孢唑林、磺胺嘧啶可致肾损害，庆大霉素和多黏菌素均有明显肾毒性，其中氨基糖苷类和多黏菌素尤其突出，使用时需监测肾功能，这与青霉素形成对比"},{"q":"金黄色葡萄球菌引起的急慢性骨髓炎最好选用","o":["阿莫西林","红霉素","头孢曲松","克林霉素","克拉霉素"],"a":3,"e":"克林霉素对革兰阳性菌包括金黄色葡萄球菌抗菌活性强，且在骨组织中浓度高，是金黄色葡萄球菌所致急慢性骨髓炎的首选。阿莫西林和头孢曲松在骨中浓度较低，红霉素和克拉霉素对金葡菌作用较弱且易耐药，均不如克林霉素适合骨感染"},{"q":"中枢抗胆碱药物中毒解救宜用","o":["新斯的明","毒扁豆碱","吡斯的明","依酚氯铵","安贝氯铵"],"a":1,"e":"毒扁豆碱为可逆性胆碱酯酶抑制药，脂溶性较高，易透过血脑屏障进入中枢，增加脑内乙酰胆碱含量，故可用于中枢抗胆碱药物如阿托品中毒的解救。新斯的明、吡斯的明、依酚氯铵和安贝氯铵均为季铵类，难以进入中枢，仅能对抗外周抗胆碱作用"},{"q":"关于普萘洛尔的抗心律失常作用机制，下列描述错误的是","o":["延长房室结有效不应期","治疗剂量延长浦肯野纤维的动作电位时程和有效不应期","阻断心脏β受体","降低窦房结、浦肯野纤维的自律性","降低儿茶酚胺所致的迟后除极幅度，防止触发活动"],"a":1,"e":"普萘洛尔治疗剂量阻断心脏β受体，降低窦房结和浦肯野纤维自律性，延长房室结有效不应期，并降低儿茶酚胺所致迟后除极幅度，防止触发活动。其在治疗剂量下并不延长浦肯野纤维的动作电位时程和有效不应期，故该项属于错误描述，与延长房室结不应期并不矛盾"},{"q":"下列平喘药中属于M胆碱受体阻断药是","o":["特布他林","丙酸倍氯米松","酮替芬","异丙托溴铵","克伦特罗"],"a":3,"e":"异丙托溴铵为M胆碱受体阻断药，吸入后阻断支气管平滑肌M受体，抑制迷走神经张力，使支气管舒张，用于平喘尤其适合慢性阻塞性肺病。特布他林和克伦特罗为β2受体激动药，丙酸倍氯米松为糖皮质激素，酮替芬为过敏介质释放抑制药，均非抗胆碱药"},{"q":"治疗闭角型青光眼应选用","o":["筒箭毒碱","乙酰胆碱","琥珀胆碱","毛果芸香碱","新斯的明"],"a":3,"e":"毛果芸香碱为M受体激动药，滴眼后激动瞳孔括约肌M受体使瞳孔缩小，拉开房角、开放小梁网，促进房水回流而降低眼内压，是闭角型青光眼首选。琥珀胆碱和筒箭毒碱为肌松药，乙酰胆碱作用广泛且不稳定，新斯的明对闭角型青光眼并非首选且可能加重充血"},{"q":"阵发性室上性心动过速并发变异型心绞痛，宜采用的治疗药物是","o":["维拉帕米","利多卡因","普鲁卡因胺","奎尼丁","普萘洛尔"],"a":0,"e":"维拉帕米为钙通道阻滞药，可延长房室结有效不应期、减慢传导，是阵发性室上性心动过速首选，同时扩张冠脉、解除冠脉痉挛，适用于变异型心绞痛，故为最合适的选择。利多卡因和普鲁卡因胺主要用于室性心律失常，奎尼丁对室上速非首选，普萘洛尔对变异型心绞痛可能加重痉挛"},{"q":"用药剂量过大时，对机体产生的危害性反应称为","o":["后遗效应","变态反应","毒性反应","质反应","特异质反应"],"a":2,"e":"毒性反应是用药剂量过大或用药时间过长，药物在体内蓄积过多时对机体产生的危害性反应，可累及多个系统且较为严重。后遗效应指停药后残留的药理效应，变态反应为免疫介导的异常反应，质反应描述效应性质的分布，特异质反应与遗传因素相关，均非剂量过大所致"},{"q":"适于治疗铜绿假单胞菌感染的药物是","o":["链霉素","四环素","氯霉素","妥布霉素","卡那霉素"],"a":3,"e":"妥布霉素为氨基糖苷类抗生素，对铜绿假单胞菌的抗菌活性较强，是治疗其感染的适宜药物。链霉素主要用于结核，四环素和氯霉素为广谱抑菌药但对铜绿假单胞菌作用弱，卡那霉素对绿脓杆菌效果差且毒性较大，均非首选"},{"q":"阿托品对眼的作用为","o":["缩瞳，眼内压升高，调节痉挛","扩瞳，眼内压降低，调节痉挛","缩瞳，眼内压降低，调节痉挛","扩瞳，眼内压升高，调节麻痹","缩瞳，眼内压升高，调节麻痹"],"a":3,"e":"阿托品阻断瞳孔括约肌M受体，使瞳孔散大；因虹膜根部堆积房角变窄、房水回流受阻，眼内压升高；同时阻断睫状肌M受体，使悬韧带拉紧、晶状体变扁，调节麻痹而视近物模糊。缩瞳和调节痉挛为毛果芸香碱等M受体激动药的作用，与阿托品相反"},{"q":"磺胺类药物抗菌作用机理是","o":["阻碍核酸的功能","阻碍细胞壁的合成","干扰胞浆膜的功能","阻碍蛋白质的合成","竞争二氢蝶酸合酶"],"a":4,"e":"磺胺类与对氨基苯甲酸竞争二氢蝶酸合酶，阻断二氢叶酸合成，使细菌缺乏四氢叶酸而核酸合成受阻，发挥抑菌作用。阻碍细胞壁合成是青霉素类机制，干扰胞浆膜为多黏菌素类，阻碍蛋白质合成如氨基糖苷类和四环素类，阻碍核酸功能如喹诺酮类，均非磺胺的作用环节"},{"q":"氨基糖苷类抗生素消除的主要途径是","o":["经肝微粒体酶灭活","经肾小管分泌排出","以原形经肾小球滤过排出","与葡糖醛酸结合后经肾排出","经乙酰化灭活"],"a":2,"e":"氨基糖苷类主要以原形经肾小球滤过排出，尿中浓度高，肾功能减退时易蓄积中毒，需据肾功能调整剂量。其不被肝微粒体酶灭活，也不主要经肾小管分泌或与葡糖醛酸结合，乙酰化灭活并非主要消除途径，原形经肾滤过才是其消除特点"},{"q":"青霉素的抗菌谱不包括","o":["肺炎球菌","脑膜炎双球菌","破伤风杆菌","伤寒杆菌","钩端螺旋体"],"a":3,"e":"青霉素G主要对革兰阳性球菌如肺炎球菌、破伤风杆菌等革兰阳性杆菌以及脑膜炎双球菌和钩端螺旋体有效，对革兰阴性杆菌作用弱。伤寒杆菌为革兰阴性杆菌，不在青霉素抗菌谱内，治疗需用氯霉素或氟喹诺酮类等，故青霉素的抗菌谱不包括伤寒杆菌"},{"q":"下列药物中，预防或治疗脑血管痉挛效果好的是","o":["普萘洛尔","硝苯地平","氟桂利嗪","维拉帕米","地高辛"],"a":2,"e":"氟桂利嗪为钙通道阻滞药，可抑制钙离子进入血管平滑肌细胞，缓解血管痉挛，对脑血管痉挛及前庭功能紊乱效果好，也可用于偏头痛预防。普萘洛尔、硝苯地平和维拉帕米主要用于心血管疾病的降压和抗心绞痛，地高辛为强心苷，均无明确的缓解脑血管痉挛优势"},{"q":"可激动N受体的是","o":["醋甲胆碱","毛果芸香碱","毒蕈碱","氯贝胆碱","占诺美林"],"a":0,"e":"醋甲胆碱为胆碱酯类，可激动M受体，对N受体也有一定激动作用，属于胆碱受体激动药中毒蕈碱样与烟碱样作用兼具的代表。毛果芸香碱、毒蕈碱、氯贝胆碱和占诺美林主要选择性激动M受体，对N受体几乎无作用，这是它们与醋甲胆碱的关键区别"},{"q":"不属于钙通道阻滞药的是","o":["维拉帕米","地尔硫䓬","米诺地尔","硝苯地平","氟桂利嗪"],"a":2,"e":"米诺地尔为钾通道开放药，通过开放血管平滑肌钾通道使膜超极化、血管舒张而降压，不属于钙通道阻滞药。维拉帕米和地尔硫䓬为非二氢吡啶类钙拮抗药，硝苯地平为二氢吡啶类，氟桂利嗪为选择性较低的钙通道阻滞药，均以阻滞钙内流为机制"},{"q":"氟喹诺酮类药物临床应用广泛，但是要警惕滥用现象，以下不属于它的不良反应是","o":["骨髓抑制","中枢神经系统毒性","心脏毒性","软骨损伤","光敏反应"],"a":0,"e":"氟喹诺酮类常见不良反应包括中枢神经系统毒性、心脏毒性如QT延长、软骨及肌腱损伤和光敏反应，儿童及孕妇慎用。骨髓抑制并非其典型不良反应，多见于氯霉素和抗肿瘤药，故该项不属于氟喹诺酮类的不良反应"},{"q":"临床上酚妥拉明常采用的给药方式是","o":["直肠给药","雾化吸入","皮下注射","口服","静脉注射"],"a":4,"e":"酚妥拉明口服生物利用度低、首过效应明显，临床上常采用静脉注射给药，用于嗜铬细胞瘤诊断、高血压危象及抗休克等。直肠给药和雾化吸入均非其常规途径，皮下注射吸收不可靠且局部刺激大，口服疗效差，均不适合作为常用给药方式"},{"q":"下列关于离子通道特征说法正确的是","o":["离子通道有三大特征，离子选择性，门控特性，离子电流特性","某一种离子可以通过大多数通道进行跨膜转运","通道激活，允许某些离子顺浓度差和电位差通过膜","通道失活时通道关闭，外来刺激强可以进入开放状态","通道关闭，遇到刺激后，转为失活状态"],"a":2,"e":"离子通道激活开放后，允许特定离子顺浓度梯度和电位梯度跨膜移动，形成离子电流，该项描述正确。离子通道具有离子选择性，一种离子一般只通过相应通道，而非通过大多数通道。失活状态的通道在刺激下不能直接转为开放，须先复活；关闭状态受刺激后转为开放而非失活"},{"q":"解热镇痛药适用于治疗","o":["慢性钝痛","内脏绞痛","分娩止痛","外伤剧痛","术后剧痛"],"a":0,"e":"解热镇痛药通过抑制外周前列腺素合成，对慢性钝痛如头痛、牙痛、关节痛和痛经效果良好，且无成瘾性。内脏绞痛需解痉药如阿托品，分娩止痛、外伤剧痛和术后剧痛属于锐痛或严重疼痛，需吗啡等阿片类镇痛药，解热镇痛药对这类疼痛疗效差"},{"q":"硝酸酯类药物与普萘洛尔合用治疗心绞痛，下列说法不正确的是","o":["协同降低心肌耗氧量","避免心室容积增加","避免心肌收缩力增强","避免心率加快","避免普萘洛尔抑制心脏"],"a":4,"e":"硝酸酯与普萘洛尔合用可协同降低心肌耗氧量，硝酸酯扩张静脉降低前负荷并可避免普萘洛尔所致心室容积增大，普萘洛尔则可对抗硝酸酯引起的反射性心率加快和心肌收缩力增强，这些配伍优势均成立。合用并不能避免普萘洛尔本身对心脏的抑制，故该项说法不正确"},{"q":"苯海拉明不具备的药理作用是","o":["镇静作用","抗胆碱作用","减少胃酸分泌作用","局麻作用","止吐作用"],"a":2,"e":"苯海拉明为第一代H1受体阻断药，具有镇静、抗胆碱、局麻和止吐作用，可用于晕动病和过敏性疾病。其并不减少胃酸分泌，减少胃酸分泌是H2受体阻断药如西咪替丁的作用，二者受体亚型不同，这也是苯海拉明不具备的药理作用"},{"q":"氟西汀主要的药理作用是","o":["抗抑郁作用","抗躁狂作用","抗精神分裂症作用","催眠作用","抗癫痫作用"],"a":0,"e":"氟西汀为选择性5-HT再摄取抑制药，通过抑制突触前膜对5-HT的再摄取，增强中枢5-HT能神经传递，主要用于抑郁症，也可用于强迫症和贪食症。抗躁狂常用锂盐，抗精神分裂症需多巴胺受体阻断药，催眠用镇静催眠药，抗癫痫另有专用药物，均非氟西汀的主要用途"},{"q":"心律失常的治疗方式不包括","o":["药物治疗","安装起搏器","电复律","导管消融","支架手术"],"a":4,"e":"心律失常的治疗包括药物治疗、安装起搏器、电复律和导管消融等，起搏器用于缓慢性心律失常，电复律用于快速性心律失常，导管消融可根治部分折返性心动过速。支架手术用于冠状动脉狭窄的血运重建，属于冠心病治疗手段，并不直接治疗心律失常"},{"q":"利福平的抗菌作用机制是","o":["抗叶酸代谢","抑制细菌细胞壁合成","影响胞质膜通透性","抑制蛋白质合成","抑制核酸代谢"],"a":4,"e":"利福平通过抑制细菌DNA依赖的RNA聚合酶，阻碍转录和核酸代谢，对结核杆菌及多种细菌有杀菌作用。抗叶酸代谢为磺胺类和甲氧苄啶，抑制细胞壁合成为青霉素类，影响胞质膜通透性为多黏菌素类，抑制蛋白质合成为氨基糖苷类和大环内酯类，均与利福平机制不同"},{"q":"丙咪嗪抗抑郁作用机制正确的是","o":["耗竭体内儿茶酚胺","抑制突触前膜对NA和5-HT的再摄取","抑制突出前膜NA的释放","阻断M胆碱受体","中枢兴奋作用"],"a":1,"e":"丙咪嗪为三环类抗抑郁药，主要抑制突触前膜对去甲肾上腺素和5-HT的再摄取，增加突触间隙递质浓度而发挥抗抑郁作用。耗竭儿茶酚胺为利血平的作用，抑制递质释放会加重抑郁，阻断M胆碱受体为其不良反应机制而非治疗机制，中枢兴奋亦非其抗抑郁原理"},{"q":"金刚烷胺治疗帕金森的原理是","o":["促多巴胺释放","激动D2受体","抑制胆碱酯酶","阻断中枢M胆碱受体","抑制氨基酸脱羧酶"],"a":0,"e":"金刚烷胺治疗帕金森病主要通过促进纹状体多巴胺释放并抑制其再摄取，增加突触间隙多巴胺含量，还可轻度拮抗谷氨酸NMDA受体。其不直接激动D2受体，也不抑制胆碱酯酶，阻断中枢M胆碱受体是苯海索的作用，抑制氨基酸脱羧酶与卡比多巴的机制不符"},{"q":"利多卡因降低心肌自律性的机制是","o":["抑制Na＋内流","促进Na＋内流","抑制K＋外流","抑制Ca2＋内流","促进Ca2＋内流"],"a":0,"e":"利多卡因阻滞心肌细胞钠通道，抑制快反应细胞4相钠内流，减小舒张期自动去极化斜率，从而降低浦肯野纤维自律性。促进钠内流会加快去极化，抑制钾外流延长复极，作用于钙通道主要影响慢反应细胞，均非利多卡因降低自律性的主要机制"},{"q":"有关抗血小板药的叙述，正确的是","o":["阿昔单抗是P2Y12受体拮抗药","利多格雷通过促进TXA2合酶活性发挥作用","阿司匹林的剂量超过300mg，抗血小板作用强","双嘧达莫可诱发心绞痛发作","噻氯匹定主要与纤维蛋白原竞争血小板膜糖蛋白受体"],"a":3,"e":"双嘧达莫扩张冠状动脉但主要扩张小阻力血管，可产生冠脉窃血，诱发心绞痛发作，故该叙述正确。阿昔单抗为GPⅡb/Ⅲa受体拮抗药而非P2Y12拮抗药，利多格雷抑制TXA2合酶而非促进其活性，阿司匹林小剂量即可抗血小板，超过三百毫克并非作用更强，噻氯匹定阻断P2Y12受体而非与纤维蛋白原竞争"},{"q":"解热镇痛药的解热特点是","o":["可降低正常体温","可降低直接注入PG引起的发热","仅降低致热原引起的发热","解热作用受环境温度影响","外界温度高可升高体温"],"a":2,"e":"解热镇痛药仅能降低致热原引起的发热，通过抑制中枢PGE2合成使调定点回降，对正常体温无明显影响，也不降低直接注入PG引起的发热。其解热作用受环境温度影响小，外界温度高时不会因此升高体温，这些说法均与实际特点不符"},{"q":"无内在拟交感活性的选择性β1受体阻断药是","o":["普萘洛尔","美托洛尔","醋丁洛尔","吲哚洛尔","普拉洛尔"],"a":1,"e":"美托洛尔为选择性β1受体阻断药，且无内在拟交感活性，主要通过减慢心率、降低心肌收缩力发挥降压和抗心绞痛作用。普萘洛尔为非选择性β受体阻断药，醋丁洛尔和普拉洛尔虽有β1选择性但具内在拟交感活性，吲哚洛尔内在拟交感活性明显，均不符合条件"},{"q":"对肾脏毒性最小的头孢菌素是","o":["头孢氨苄","头孢唑林","头孢噻吩","头孢匹罗","头孢呋辛"],"a":3,"e":"头孢匹罗为第四代头孢菌素，对β内酰胺酶稳定性高，肾毒性在头孢类中最小。头孢噻吩、头孢唑林和头孢氨苄属第一代，有一定肾毒性，头孢呋辛为第二代，肾毒性较第一代低但仍高于第四代，故肾毒性最小者为头孢匹罗"},{"q":"治疗梅毒首选","o":["氨苄西林","青霉素","四环素","庆大霉素","红霉素"],"a":1,"e":"梅毒螺旋体对青霉素高度敏感，青霉素各剂型包括苄星青霉素为治疗各期梅毒的首选，疗效确切。氨苄西林、四环素、庆大霉素和红霉素仅用于青霉素过敏者的替代治疗，疗效不及青霉素，故梅毒治疗首选青霉素"},{"q":"长期应用广谱抗生素，为预防出血，应补充","o":["铁剂","叶酸","维生素B12","维生素K","维生素C"],"a":3,"e":"长期应用广谱抗生素可抑制肠道正常菌群，使维生素K合成减少，导致维生素K依赖凝血因子合成不足而出血，故应补充维生素K预防。铁剂用于缺铁性贫血，叶酸和维生素B12用于巨幼红细胞性贫血，维生素C参与胶原合成，均不能纠正抗生素相关的凝血障碍"},{"q":"阿司匹林哪组作用与相应机制不符","o":["解热作用是抑制中枢PG合成","抗炎作用是抑制炎症部位PG合成","镇痛作用主要是抑制中枢PG合成","水杨酸反应是过量中毒表现","预防血栓形成是抑制TXA2大于PGI2"],"a":2,"e":"阿司匹林的镇痛作用主要抑制外周炎症部位前列腺素合成，降低痛觉敏感性，而非主要抑制中枢PG合成，故该项作用与机制不符。其解热确与抑制中枢PG合成有关，抗炎抑制炎症部位PG合成，水杨酸反应为过量中毒表现，预防血栓与抑制TXA2强于PGI2相关，配对均正确"},{"q":"某感染中毒性休克患者，伴尿少，宜选用的措施是","o":["地塞米松＋多巴胺＋头孢他啶","地塞米松＋肾上腺素＋螺旋霉素","地塞米松＋硝苯地平＋四环素","地塞米松＋普萘洛尔＋SMZ","地塞米松＋去甲肾上腺素"],"a":0,"e":"感染中毒性休克伴尿少需在抗感染基础上抗休克，地塞米松抗炎抗毒抗休克，多巴胺兴奋心脏并改善肾血流增加尿量，头孢他啶覆盖革兰阴性菌尤其铜绿假单胞菌，组合合理。肾上腺素、硝苯地平、普萘洛尔及去甲肾上腺素或升压过度或降压、减慢心率，搭配抗菌药物亦不合理，均非适宜措施"},{"q":"在胃肠道，脂溶性药物主要的吸收方式是","o":["易化扩散","简单扩散","主动转运","膜孔滤过","胞吞"],"a":1,"e":"脂溶性药物在胃肠道主要经简单扩散跨膜吸收，顺着浓度梯度进行，不耗能也无需载体，吸收速度与脂溶性和膜面积相关。易化扩散需载体，主动转运耗能且可逆浓度梯度，膜孔滤过适用于水溶性小分子，胞吞为大分子颗粒的转运方式，均非脂溶性药物的主要吸收方式"},{"q":"氢氯噻嗪可引起的不良反应是","o":["低血糖","水和电解质紊乱","高钾血症","低血脂","耳聋"],"a":1,"e":"氢氯噻嗪为噻嗪类利尿药，长期应用可引起水和电解质紊乱，如低钾、低钠、低氯性碱中毒及高尿酸血症，还可升高血糖和血脂。其不引起低血糖，反而升高血糖；导致低钾而非高钾；耳聋主要见于高效能袢利尿药，均非氢氯噻嗪的典型不良反应"},{"q":"A B C三药的LD50分别为20 20 30mg/kg，ED50分别为10 20 20mg/kg，则三药的安全性大小顺序为","o":["A＝B＞C","A＞B＝C","A＞B＞C","A＞C＞B","A＜B＜C"],"a":3,"e":"药物安全性可用治疗指数即半数致死量与半数有效量之比评价，A药为二十比十等于二，B药为二十比二十等于一，C药为三十比二十等于一点五，故安全性顺序为A大于C大于B。比值越小安全性越低，据此A最优、B最差，其他排序均不符合计算结果"},{"q":"作浸润麻醉时，对普鲁卡因过敏者可选用","o":["丁卡因","利多卡因","溴丙胺太林","普鲁卡因胺","对氨基苯甲酸"],"a":1,"e":"普鲁卡因为酯类局麻药，过敏者禁用，浸润麻醉可改用酰胺类的利多卡因，后者致敏罕见且穿透力较强。丁卡因同属酯类且毒性大，不宜交叉使用。溴丙胺太林为M受体阻断药，普鲁卡因胺为抗心律失常药，对氨基苯甲酸为普鲁卡因代谢产物，均不能替代局麻"},{"q":"普萘洛尔治疗心绞痛的主要药理作用是","o":["抑制心肌收缩力，减慢心率","扩张冠脉","降低心脏前负荷","降低左室壁张力","以上都不是"],"a":0,"e":"普萘洛尔治疗心绞痛主要通过阻断β受体抑制心肌收缩力、减慢心率，从而降低心肌耗氧量。其并不扩张冠脉，也不以降低心脏前负荷或左室壁张力为主要机制，故后几项均不符合其核心作用"},{"q":"糖皮质激素和抗生素合用治疗严重感染的目的是","o":["增强机体的对疾病的防御能力","增强抗生素的抗菌活性","增强机体应激性","抗毒素、抗休克、缓解毒血症状","拮抗抗生素的副作用"],"a":3,"e":"严重感染时糖皮质激素与抗生素合用，利用其抗炎、抗毒素、抗休克作用缓解毒血症状，帮助患者度过危险期，同时抗生素针对病原菌治疗。激素并不增强机体防御能力，反而可能抑制免疫；也不增强抗生素抗菌活性或拮抗其副作用，增强应激性亦非合用目的"},{"q":"抗心律失常药物的作用机制不包括","o":["降低自律性","减少后除极","延长ERP","消除折返","提高自律性"],"a":4,"e":"抗心律失常药通过降低自律性、减少后除极、延长有效不应期和消除折返等机制发挥作用，提高自律性会加重心律失常，不属于治疗机制。降低窦房结等起搏点自律性可减少异位节律，延长有效不应期可终止折返，抑制早后除极可防止触发活动，均为常用机制"},{"q":"以下哪种药物能够对蛔虫、钩虫、蛲虫、鞭虫以及绦虫等多种肠道蠕虫产生良好的治疗效果","o":["哌嗪","甲硝唑","甲苯达唑","恩波吡维胺","吡喹酮"],"a":2,"e":"甲苯达唑为广谱抗肠蠕虫药，可抑制虫体微管聚合和葡萄糖摄取，对蛔虫、钩虫、蛲虫、鞭虫及绦虫等多种肠道蠕虫均有良好疗效。哌嗪主要对蛔虫和蛲虫有效，甲硝唑针对厌氧菌和原虫，恩波吡维胺仅对蛲虫有效，吡喹酮主要通过其对绦虫和血吸虫有效，抗菌谱均不及甲苯达唑"},{"q":"糖皮质激素类药物对中枢神经具有","o":["镇静作用","抑制作用","兴奋作用","抗抑郁作用","催眠作用"],"a":2,"e":"糖皮质激素对中枢神经系统有兴奋作用，可提高情绪、使注意力集中，大剂量可致欣快、失眠甚至精神失常，故属于兴奋而非抑制或镇静。镇静、催眠和抗抑郁均不是其药理表现，抑制中枢的说法与激素引起的中枢兴奋特点相反"},{"q":"哌替啶不引起","o":["恶心，呕吐","便秘","镇静","体位性低血压","呼吸抑制"],"a":1,"e":"哌替啶为阿片类镇痛药，可产生镇静、呼吸抑制、恶心呕吐和体位性低血压，但因对胃肠平滑肌兴奋作用较弱、成瘾性较低，一般不引起便秘或仅轻微，这是它与吗啡的重要区别。其余各项均为哌替啶与吗啡共有的典型作用"},{"q":"与局麻药合用，可延长局麻药作用时间的药物是","o":["肾上腺素","酚妥拉明","麻黄碱","多巴胺","异丙肾上腺素"],"a":0,"e":"肾上腺素激动α受体收缩局部血管，减缓局麻药吸收，从而延长局麻作用时间并减少全身毒性反应。酚妥拉明阻断α受体反而加速吸收，麻黄碱、多巴胺和异丙肾上腺素的α缩血管作用弱或以β效应为主，均不能像肾上腺素那样有效延长局麻时间"},{"q":"用左旋多巴治疗震颤麻痹时，应与下列何药合用","o":["维生素B6","多巴胺","苯乙肼","卡比多巴","多巴脱羧酶"],"a":3,"e":"左旋多巴单用时大部分在外周被多巴脱羧酶转化为多巴胺，进入脑内量少且外周副作用多，合用卡比多巴这一外周脱羧酶抑制药可减少外周转化，使更多左旋多巴入脑，增强疗效并减轻不良反应。维生素B6加速外周脱羧，多巴胺不能透过血脑屏障，苯乙肼风险大，均不宜合用"},{"q":"抑制肿瘤细胞脱氧胸苷酸合成酶的药物是","o":["甲氨蝶呤","氟尿嘧啶","阿糖胞苷","放线菌素D","L-门冬酰胺酶"],"a":1,"e":"氟尿嘧啶在体内转化为氟脱氧尿苷酸，抑制胸苷酸合成酶，阻断脱氧尿苷酸甲基化为脱氧胸苷酸，从而抑制DNA合成。甲氨蝶呤抑制二氢叶酸还原酶，阿糖胞苷抑制DNA多聚酶，放线菌素D嵌入DNA抑制转录，门冬酰胺酶水解门冬酰胺，靶点均不同"},{"q":"治疗罕见真菌感染的首选药物是","o":["伊曲康唑","氟康唑","咪康唑","酮康唑","氟胞嘧啶"],"a":0,"e":"伊曲康唑为广谱三唑类抗真菌药，对深部真菌和部分罕见真菌感染有效，抗菌谱较氟康唑更广，可用于氟康唑无效的病例。氟康唑主要用于念珠菌和隐球菌，咪康唑和酮康唑多用于浅表或局部感染且毒性较大，氟胞嘧啶抗菌谱窄且易耐药，均非罕见真菌感染首选"},{"q":"治疗白喉杆菌感染的首选药是","o":["青霉素","红霉素","四环素","氯霉素","庆大霉素"],"a":0,"e":"白喉杆菌为革兰阳性杆菌，对青霉素敏感，青霉素可抑制其细胞壁合成、杀灭细菌并减少外毒素产生，是白喉感染首选，白喉仍需配合白喉抗毒素中和毒素。红霉素用于青霉素过敏者，四环素、氯霉素和庆大霉素疗效均不及青霉素，不作首选"},{"q":"关于阿司匹林的不良反应，错误的叙述是","o":["胃肠道反应最为常见","凝血障碍，术前1周应停用","过敏反应，哮喘、慢性荨麻疹患者不宜用","水钠潴留，引起局部水肿","水杨酸反应是中毒表现"],"a":3,"e":"阿司匹林常见不良反应包括胃肠道反应、凝血障碍、过敏反应和水杨酸反应，术前一周应停药，哮喘和慢性荨麻疹患者慎用。水钠潴留引起局部水肿并非其典型不良反应，某些其他解热镇痛药或糖皮质激素才易引起，故该项叙述错误"},{"q":"属于抗雌激素类药物的是","o":["氯米芬","己烯雌酚","黄体酮","米非司酮","环丙孕酮"],"a":0,"e":"氯米芬为选择性雌激素受体调节剂，竞争阻断下丘脑雌激素受体，解除雌激素负反馈，促进促性腺激素释放，用于促排卵，属于抗雌激素药。己烯雌酚为雌激素类，黄体酮为孕激素，米非司酮为抗孕激素，环丙孕酮为雄激素受体拮抗药，均非抗雌激素药"},{"q":"甲状腺素的主要适应证是","o":["甲状腺危象","轻、中度甲状腺功能亢进","甲亢的手术前准备","交感神经活性增强引起的病变","黏液性水肿"],"a":4,"e":"甲状腺素主要用于甲状腺功能减退的替代治疗，黏液性水肿为成人严重甲减的典型表现，是其重要适应证。甲状腺危象和甲亢手术前准备需用抗甲状腺药，轻中度甲亢不宜补充甲状腺素，交感神经活性增强所致病变应用β受体阻断药，均非甲状腺素适应证"},{"q":"红霉素是下列哪种细菌感染的首选药","o":["溶血链球菌","金黄色葡萄球菌","军团菌","沙眼衣原体","大肠杆菌"],"a":2,"e":"军团菌为细胞内寄生菌，红霉素等大环内酯类能进入细胞内抑制其蛋白质合成，是军团菌肺炎的首选药。溶血性链球菌感染首选青霉素，金黄色葡萄球菌感染多用耐酶青霉素或万古霉素，沙眼衣原体感染常用四环素类或阿奇霉素，大肠杆菌感染多用第三代头孢或氟喹诺酮类"},{"q":"药物的pKa是指","o":["药物完全解离时的pH","药物解离30%时的pH","药物解离50%时的pH","药物解离80%时的pH","药物未解离时的pH"],"a":1,"e":"官方答案为药物解离30%时的pH，但依据教材，正确答案为药物解离50%时的pH。pKa指药物解离度为一半时的溶液pH，此时解离型与未解离型浓度相等，是反映酸碱性与解离程度的特征常数。解离百分之三十并无特殊意义，不能作为定义；完全解离、未解离及解离八十百分比时的pH同样不是pKa的含义，原答案把解离度数值写错，故不成立"},{"q":"卡托普利的降压作用与下列哪种机制无关","o":["抑制整体RAAS的AngⅡ形成","减少AngⅡ的对AT1受体的激动","加速缓激肽的水解","减少P物质的水解","促进前列腺素的合成"],"a":2,"e":"卡托普利抑制血管紧张素转化酶，既减少血管紧张素Ⅱ生成，也使缓激肽降解减少而蓄积，促进前列腺素和P物质发挥作用，从而降压并产生咳嗽等不良反应。加速缓激肽水解与抑制作用相反，不属于其机制；其余各项分别对应RAAS抑制和缓激肽、P物质及前列腺素效应，均成立"},{"q":"异丙肾上腺素没有下述哪种作用","o":["松弛支气管平滑肌","激动β受体","收缩支气管黏膜血管","促使ATP转变为cAMP","抑制组胺等过敏性介质释放"],"a":2,"e":"异丙肾上腺素为β受体激动药，可激动β2受体松弛支气管平滑肌，并促使ATP转变为cAMP、抑制组胺等过敏介质释放，对支气管黏膜血管亦以β2介导的舒张为主，故收缩支气管黏膜血管的说法错误。激动β受体是其基本作用，松弛支气管平滑肌亦正确"},{"q":"硝苯地平常见的不良反应是","o":["心率减慢","降低心肌耗氧量","面红、头痛","皮疹","失眠"],"a":2,"e":"硝苯地平扩张外周血管可引起反射性心率加快，并因血管扩张出现面红、头痛、踝部水肿等不良反应。降低心肌耗氧量属于其治疗作用而非不良反应，皮疹和失眠并非其常见反应，心率减慢更与反射性心动过速相反，故面红、头痛是最常见者"},{"q":"下列抗高血压药物不良反应错误的是","o":["哌唑嗪——首次用药发生了体位性低血压","可乐定——突然停药而发生的反跳性高血压危象","利舍平——抑郁性精神病","氢氯噻嗪——低血钾","氯沙坦——低血钾"],"a":4,"e":"氯沙坦阻断AT1受体，减少醛固酮分泌，可使血钾升高而非降低，故低血钾的配对错误。哌唑嗪首次用药可致体位性低血压，可乐定突然停药可发生反跳性高血压危象，利舍平可致抑郁性精神病，氢氯噻嗪因排钾引起低血钾，这些配对均正确"},{"q":"氯丙嗪引起的口干、便秘和视力模糊是由于","o":["阻断M胆碱受体","阻断α肾上腺素受体","阻断组胺受体","阻断β肾上腺素受体","阻断DA受体"],"a":0,"e":"氯丙嗪阻断M胆碱受体，抑制腺体分泌并减弱胃肠蠕动，引起口干、便秘，阻断睫状肌M受体可致视力模糊，这些均为其抗胆碱不良反应。阻断α受体主要引起体位性低血压，阻断组胺受体与镇静相关，阻断β受体并非其作用，阻断DA受体则与锥体外系反应及疗效相关"},{"q":"容易导致灰婴综合征，新生儿、早产儿、孕妇、哺乳期妇女禁用的抗菌药物是","o":["阿司匹林","磺胺嘧啶","氯霉素","左氧氟沙星","庆大霉素"],"a":2,"e":"氯霉素可抑制骨髓造血，新生儿、早产儿肝内葡萄糖醛酸转移酶发育不全，不能有效结合药物，致其在体内蓄积引起灰婴综合征，故新生儿、早产儿及孕妇哺乳期妇女禁用。磺胺嘧啶可与胆红素竞争血浆蛋白，新生儿用可致核黄疸，同样需避用。庆大霉素主要表现耳肾毒性，左氧氟沙星影响软骨发育，阿司匹林与瑞氏综合征相关，均与灰婴综合征无关"},{"q":"Vaughan Williams分类法中的Ⅲ类抗心律失常药是","o":["钠通道阻滞药","β受体阻滞药","钙通道阻滞药","延长动作电位时程药","腺苷"],"a":3,"e":"Vaughan WilliamsⅢ类为延长动作电位时程药，代表药胺碘酮，主要阻滞钾通道，延长复极与有效不应期。Ⅰ类为钠通道阻滞药，Ⅰa适度阻滞如奎尼丁，Ⅰb轻度阻滞如利多卡因，Ⅰc明显阻滞如普罗帕酮；Ⅱ类为β受体阻滞药如普萘洛尔；Ⅳ类为钙通道阻滞药如维拉帕米。腺苷通过激动腺苷受体抑制房室结传导，属其他类，均不属Ⅲ类"},{"q":"机体连续多次用药后对药物的反应性降低，该现象称为","o":["依赖性","耐药性","耐受性","后遗效应","继发反应"],"a":2,"e":"耐受性指机体连续多次用药后对药物反应性降低，需增加剂量才能维持原效应，停药后多可恢复。耐药性指病原体或肿瘤细胞对反复应用的化疗药敏感性降低，主体是病原体而非机体，二者最易混淆。依赖性强调反复用药产生的强迫性觅药状态，后遗效应为停药后血药浓度降至阈下仍残留的效应，继发反应则是药物治疗作用带来的不良后果，均非反应性降低"},{"q":"瘤型麻风杆菌感染治疗的首选药是","o":["异烟肼","氨苯砜","利福平","链霉素","氯法齐明"],"a":4,"e":"氯法齐明为吩嗪类抗麻风药，可嵌入分枝杆菌DNA抑制其增殖，兼具抗炎和免疫调节作用，对瘤型麻风疗效好，常用于氨苯砜耐药或联合化疗。氨苯砜为砜类基础抗麻风药，单用于瘤型麻风易耐药。利福平抑制DNA依赖的RNA多聚酶，常与氨苯砜、氯法齐明联合。异烟肼、链霉素主要针对结核分枝杆菌，不用于麻风，均非本题所指首选"},{"q":"强心苷中毒引起的心律失常，不宜用氯化钾的是","o":["房室结性心动过速","室性心动过速","室性期前收缩","房室传导阻滞","房性心动过速"],"a":3,"e":"强心苷中毒出现房室传导阻滞时不宜补钾，高血钾可进一步抑制房室传导、加重阻滞。室性心动过速、室性期前收缩等快速性心律失常多与细胞内缺钾、最大舒张电位上移有关，补钾可与强心苷竞争Na⁺-K⁺-ATP酶而减轻毒性。房室结性、房性心动过速亦属快速性心律失常，可用钾盐或苯妥英钠处理，只有传导阻滞属抑制性表现，补钾会恶化"},{"q":"预防严重创伤后可能出现的应激性溃疡应选用","o":["奥美拉唑","哌仑西平","NaHCO3","阿托品","阿司咪唑"],"a":0,"e":"奥美拉唑为质子泵抑制剂，不可逆抑制胃壁细胞H⁺-K⁺-ATP酶，抑酸作用强而持久，能有效预防严重创伤后的应激性溃疡。哌仑西平选择性阻断M1受体抑酸，作用较弱；阿托品阻断M受体同时抑制胃肠动力，不良反应多。NaHCO₃为可吸收抗酸药，中和胃酸短暂且产气，仅缓解症状。阿司咪唑阻断H1受体抗过敏，与胃酸分泌无关"},{"q":"中枢抗胆碱药不能缓解长期应用氯丙嗪出现的","o":["帕金森综合征","迟发性运动障碍","静坐不能","面容呆板","急性肌张力障碍"],"a":1,"e":"迟发性运动障碍为长期阻断黑质-纹状体D2受体后多巴胺受体向上调节所致，中枢抗胆碱药不仅无效反而可加重，需停药或改用氯氮平。氯丙嗪引起的帕金森综合征、面容呆板、静坐不能及急性肌张力障碍均属锥体外系反应，由纹状体胆碱能相对亢进引起，可用苯海索、东莨菪碱等中枢抗胆碱药缓解，唯迟发性运动障碍例外"},{"q":"治疗阿尔茨海默病的NMDA受体拮抗药是","o":["石杉碱甲","利斯的明","多奈哌齐","氯胺酮","美金刚"],"a":4,"e":"美金刚为非竞争性NMDA受体拮抗药，可阻断谷氨酸能神经过度兴奋造成的神经毒性，用于中重度阿尔茨海默病。石杉碱甲、利斯的明、多奈哌齐均为胆碱酯酶抑制剂，通过增加脑内乙酰胆碱改善认知，机制不同。氯胺酮虽也拮抗NMDA受体，但分离麻醉与致幻作用强，不用于痴呆治疗，是常见易混项，答题须抓住治疗AD这一限定"},{"q":"治疗手术后腹胀及尿潴留可用","o":["乙酰胆碱","毛果芸香碱","毒扁豆碱","新斯的明","加兰他敏"],"a":3,"e":"新斯的明为可逆性胆碱酯酶抑制药，抑制胆碱酯酶使乙酰胆碱蓄积，对骨骼肌及胃肠、膀胱平滑肌兴奋作用强，用于术后腹胀和尿潴留。乙酰胆碱作用广泛且被迅速水解，不作全身应用。毛果芸香碱主要激动M受体用于青光眼，毒扁豆碱易透过血脑屏障、中枢毒性大，加兰他敏多用于阿尔茨海默病，均非术后腹胀尿潴留常用药"},{"q":"左旋多巴治疗帕金森病的机制是","o":["补充纹状体内多巴胺","抑制外周多巴脱羧酶","直接激动多巴胺受体","阻断中枢胆碱受体","兴奋中枢NA受体"],"a":0,"e":"左旋多巴为多巴胺前体，可透过血脑屏障，在脑内经多巴脱羧酶转化为多巴胺，补充纹状体多巴胺不足而改善帕金森病症状。抑制外周多巴脱羧酶是卡比多巴、苄丝肼的作用，二者本身无抗帕金森效应，仅合用减少外周脱羧。直接激动多巴胺受体的是溴隐亭、普拉克索，阻断中枢胆碱受体的是苯海索，兴奋中枢NA受体与本病治疗无关"},{"q":"治疗单纯疱疹脑炎有效的药物是","o":["金刚烷胺","阿昔洛韦","利巴韦林","碘苷","盐酸吗啉胍"],"a":1,"e":"阿昔洛韦为鸟苷类似物，经疱疹病毒胸苷激酶活化后抑制病毒DNA多聚酶，对单纯疱疹病毒选择性强，是单纯疱疹脑炎的有效药物。金刚烷胺仅对甲型流感有效，通过阻断M2蛋白起作用。碘苷毒性大，仅限局部用于疱疹性角膜炎。利巴韦林、盐酸吗啉胍为广谱抗病毒药，对疱疹脑炎疗效不确切，不作首选"},{"q":"含有巯基的血管紧张素转化酶抑制药是","o":["依那普利","福辛普利","赖诺普利","卡托普利","雷米普利"],"a":3,"e":"卡托普利分子中含巯基，可与血管紧张素转化酶活性中心的锌离子结合而抑制该酶，是首个临床应用的ACE抑制药，巯基也与其味觉障碍、皮疹等不良反应相关。依那普利、赖诺普利、雷米普利为含羧基的ACE抑制药，其中依那普利仍需肝内水解为依那普利拉生效。福辛普利含膦酸基，经肝肠双通道消除，均不含巯基"},{"q":"可促进肾上腺素能神经递质释放的是","o":["毛果芸香碱","肾上腺素","麻黄碱","胍乙啶","利舍平"],"a":2,"e":"麻黄碱为混合型拟肾上腺素药，除直接激动α、β受体外，主要促进交感神经末梢释放去甲肾上腺素，作用温和持久，有中枢兴奋与快速耐受性。肾上腺素直接激动受体，不依赖递质释放。胍乙啶阻止去甲肾上腺素释放并耗竭递质，利舍平耗竭囊泡内去甲肾上腺素，二者均抑制而非促进释放。毛果芸香碱为M受体激动药，与肾上腺素能递质无关"},{"q":"可抑制前庭神经内耳功能的药物是","o":["阿托品","东莨菪碱","山莨菪碱","毒扁豆碱","筒箭毒碱"],"a":1,"e":"东莨菪碱为中枢抗胆碱药，可抑制前庭神经内耳功能及大脑皮层，抗晕动、镇吐作用强，常制成透皮贴剂预防晕车晕船。阿托品中枢兴奋明显，不用于防晕，主要用于解痉、散瞳及抑制腺体分泌。山莨菪碱选择性解除血管痉挛、改善微循环。毒扁豆碱为胆碱酯酶抑制药，筒箭毒碱为N2受体阻断的肌松药，均无抗晕动作用"},{"q":"糖皮质激素可治疗","o":["角膜溃疡","真菌感染","接触性皮炎","水痘","肾上腺皮质功能亢进"],"a":2,"e":"糖皮质激素具有强大抗炎、抗过敏作用，可减轻接触性皮炎的红肿瘙痒，局部或短期系统用药有效。角膜溃疡、真菌感染、水痘均属感染性或病毒性病变，激素抑制局部防御、促进病原体繁殖而加重病情，属禁忌。肾上腺皮质功能亢进本身即皮质醇过多所致，使用激素会进一步加重，亦禁用，只有接触性皮炎为变态反应性炎症，是其适应证"},{"q":"慢性钝痛时，不宜用吗啡的主要原因是","o":["对钝痛效果差","治疗量即抑制呼吸","可致便秘","易成瘾","易引起体位性低血压"],"a":3,"e":"吗啡反复用于慢性钝痛易产生耐受和身体依赖，停药出现戒断症状，成瘾性强，故慢性钝痛首选解热镇痛药而不是吗啡。吗啡对钝痛同样有效，说其效果差并不正确。治疗量确可抑制呼吸，但这是急性中毒的主要危险，非慢性钝痛限用的原因。便秘、体位性低血压为常见不良反应，可对症处理，不构成不宜长期用于慢性钝痛的主要理由"},{"q":"五氟利多的适应证是","o":["躁狂症","精神分裂症","抑郁症","焦虑症","帕金森病"],"a":1,"e":"五氟利多为二苯丁哌啶类长效抗精神病药，每周口服一次，通过阻断中脑边缘系统D2受体发挥抗精神病作用，适用于精神分裂症的维持治疗。躁狂症首选碳酸锂，抑郁症用三环类或SSRI，焦虑症常用苯二氮䓬类，帕金森病为多巴胺不足、需用左旋多巴或受体激动药治疗，五氟利多阻断多巴胺受体反可诱发帕金森样症状，均非其适应证"},{"q":"以下哪项不是形成肿瘤多药耐药的机制","o":["化疗药物转运及摄取障碍","肿瘤细胞分解酶水平增加","抑制p-糖蛋白外排泵","化疗药物活化障碍","肿瘤细胞修复机制增加"],"a":2,"e":"肿瘤多药耐药机制包括药物转运摄取障碍、P-糖蛋白等外排泵表达增加、药物活化障碍、谷胱甘肽S转移酶等分解酶水平升高以及DNA修复能力增强。抑制P-糖蛋白外排泵可提高细胞内药物浓度，是逆转多药耐药的治疗策略，而非耐药形成机制，故选此。其余各项分别对应摄入减少、灭活增强、活化不足和损伤修复增强，均属耐药产生环节"},{"q":"药物达到一定效应时所需要的相对剂量，称为","o":["效价强度","效能","阈剂量","治疗量","极量"],"a":0,"e":"效价强度指药物达到一定效应时所需的相对剂量或浓度，所需剂量越小则效价强度越高，主要反映药物与受体的亲和力。效能指药物所能达到的最大效应，与效价强度是不同的概念，两者无必然平行关系，是最常见的易混点。阈剂量为刚能引起效应的最小剂量，治疗量为安全有效剂量范围，极量为最大有效剂量，均非达到某一效应所需相对剂量的定义"},{"q":"误服有机磷酸酯类农药后，导致体内某物质蓄积，进而激动骨骼肌中NM受体，出现骨骼肌震颤。该物质是","o":["琥珀胆碱","筒箭毒碱","乙酰胆碱","卡巴胆碱","贝胆碱"],"a":2,"e":"有机磷酸酯类持久抑制胆碱酯酶，使乙酰胆碱在突触间隙大量蓄积，过度激动骨骼肌终板N_M受体，出现肌束颤动、肌无力甚至呼吸肌麻痹。琥珀胆碱虽也激动N_M受体，但为外源性除极化肌松药，非体内蓄积物质。筒箭毒碱阻断N_M受体致肌松，作用相反。卡巴胆碱、贝胆碱为人工合成胆碱酯，均非中毒时体内蓄积的递质"},{"q":"钙拮抗药对心脏的作用是","o":["加快心率","加快传导","减弱心肌收缩力","扩张血管","抑制血小板聚集"],"a":2,"e":"钙拮抗药阻滞心肌细胞L型钙通道，减少Ca²⁺内流，抑制兴奋-收缩耦联，表现为负性肌力，使心肌收缩力减弱，并减慢心率与房室传导。加快心率、加快传导与其心脏抑制作用相反。扩张血管是对血管平滑肌的作用，不属对心脏的直接效应。抑制血小板聚集仅为部分钙拮抗药的外周效应，也不是对心脏的作用，故均非本题所指"},{"q":"中和胃酸作用强、吸收后引起碱血症的抗酸药是","o":["氢氧化铝","氢氧化镁","三硅酸镁","碳酸氢钠","碳酸钙"],"a":3,"e":"碳酸氢钠为可吸收性抗酸药，中和胃酸作用强而快，口服后吸收入血可使血浆碳酸氢盐升高，引起代谢性碱血症，故不宜长期大量使用。氢氧化铝、三硅酸镁、碳酸钙为难吸收抗酸药，在胃内局部中和胃酸而不引起全身碱化，其中氢氧化铝易致便秘、三硅酸镁作用缓慢。氢氧化镁因镁离子不易吸收而致泻明显，均无碱血症之弊"},{"q":"主要作用于髓袢升支粗段髓质部和皮质部的利尿药是","o":["呋塞米","氢氯噻嗪","螺内脂","乙酰唑胺","甘露醇"],"a":0,"e":"呋塞米为高效能袢利尿药，抑制髓袢升支粗段髓质部与皮质部的Na⁺-K⁺-2Cl⁻共转运体，破坏肾髓质高渗梯度，利尿作用强。氢氯噻嗪作用于远曲小管近端，抑制Na⁺-Cl⁻共转运体，为中效药。螺内酯竞争性拮抗醛固酮，作用于远曲小管和集合管。乙酰唑胺抑制近曲小管碳酸酐酶，甘露醇为渗透性利尿药，作用部位与机制均不同"},{"q":"某感染患者，青霉素过敏，不宜选用的药物是","o":["四环素","红霉素","磺胺类","氯霉素","阿莫西林"],"a":4,"e":"阿莫西林为青霉素类，与青霉素具有共同抗原决定簇，存在交叉过敏反应，青霉素过敏者禁用，故不宜选用。四环素属四环素类，红霉素属大环内酯类，磺胺类干扰叶酸代谢，氯霉素属酰胺醇类，四者化学结构与青霉素完全不同，不存在交叉过敏，可按感染类型在青霉素过敏患者中替代使用。关键在于识别同属β-内酰胺类这一交叉过敏基础"},{"q":"某药物在口服和静注相同剂量后的时量曲线下面积相等，表明其","o":["口服吸收迅速","口服吸收完全","口服的生物利用度低","口服药物未经肝门脉吸收","属一室分布模型"],"a":1,"e":"口服与静脉注射等剂量时曲线下面积相等，说明口服药物几乎全部被吸收进入体循环，即吸收完全、生物利用度接近百分之百。吸收是否迅速取决于达峰时间与峰浓度，与曲线下面积大小无关，后者反映吸收总量。若生物利用度低，口服曲线下面积必小于静脉注射。是否经肝门脉吸收属吸收途径问题，一室或二室模型由分布特征决定，均与其相等无直接关系"},{"q":"贝特类对血脂的影响正确的是","o":["明显降低TC","轻度升高HDL-C","对VLDL影响小","明显降低LDL-C","对TG作用不定"],"a":1,"e":"贝特类通过激活过氧化物酶体增殖物激活受体α，增强脂蛋白脂酶活性，加速VLDL和甘油三酯分解，主要降低血清TG和VLDL，并可轻度升高HDL-C，故该表述正确。明显降低LDL-C和总胆固醇是他汀类的特点，源于抑制HMG-CoA还原酶。贝特类对VLDL影响显著而非影响小，对TG降低作用明确而非作用不定，三项均与其实际调脂谱不符"},{"q":"易燃易爆的吸入性全麻药是","o":["氧化亚氮","乙醚","氟烷","恩氟烷","异氟烷"],"a":1,"e":"乙醚为经典吸入性全麻药，麻醉范围宽、镇痛肌松良好，但蒸气易燃易爆，遇明火或电火花可燃烧爆炸，且有诱导期长、恶心呕吐多等缺点，已被含氟吸入麻醉药取代。氧化亚氮本身不燃烧但可助燃。氟烷、恩氟烷、异氟烷均为含氟醚类，化学性质稳定、不燃不爆，临床使用安全，均不符合易燃易爆这一特征"},{"q":"长期用异烟肼引起的周围神经炎可合用下列何种药物防治","o":["维生素B2","维生素B6","维生素K","维生素C","维生素B12"],"a":1,"e":"异烟肼结构与维生素B6相似，可竞争性抑制维生素B6依赖的酶并促进其排泄，导致周围神经炎，合用维生素B6可防治，但剂量不宜过大以免降低疗效。维生素B2参与能量代谢，缺乏致口角炎；维生素K参与凝血因子合成；维生素C缺乏致坏血病；维生素B12缺乏致巨幼细胞贫血，均与异烟肼周围神经炎的防治无关"},{"q":"氨基糖苷类抗生素对以下哪类细菌无效","o":["厌氧菌","铜绿假单胞菌","革兰氏阴性菌","革兰氏阳性菌","结核杆菌"],"a":0,"e":"氨基糖苷类抗菌谱以革兰阴性杆菌为主，对铜绿假单胞菌、结核杆菌亦有作用，对部分革兰阳性菌有效，但只对需氧菌有效——菌体摄取药物依赖氧依赖性主动转运，厌氧菌缺乏此系统，故对厌氧菌无效。这是该类药物抗菌谱的重要特点，庆大霉素、阿米卡星、链霉素均不用于厌氧菌感染，此类感染需选甲硝唑、克林霉素等"},{"q":"治疗军团菌感染首选的药物是","o":["红霉素","氯霉素","青霉素","麦白霉素","四环素"],"a":0,"e":"红霉素为大环内酯类抗生素，能穿透肺泡巨噬细胞并在细胞内浓集，对军团菌有良好抗菌活性，是治疗军团菌肺炎的经典首选药。青霉素对军团菌无效，该菌胞内寄生且产β-内酰胺酶。氯霉素、四环素虽有一定活性但疗效不如大环内酯类。麦白霉素同属大环内酯但抗菌效价较低，不作首选，须抓住军团菌与红霉素的对应关系"},{"q":"军团菌病的首选药是","o":["头孢曲松","阿莫西林","四环素","庆大霉素","红霉素"],"a":4,"e":"军团菌病由嗜肺军团菌引起，该菌为胞内寄生菌，红霉素等大环内酯类可进入巨噬细胞内抗菌，为首选药。头孢曲松为第三代头孢菌素，对军团菌无可靠抗菌活性；阿莫西林等青霉素类同样无效。四环素类、庆大霉素体外虽有一定作用，但临床疗效差、复发率高，不作军团菌病首选。两道军团菌题均指向红霉素，属同一知识点"},{"q":"阿司匹林与双香豆素合用可增加出血倾向的原因是","o":["降低双香豆素的代谢","降低双香豆素的排泄","竞争与血浆蛋白结合","增加双香豆素的吸收","抑制肝药酶"],"a":2,"e":"阿司匹林与双香豆素合用增加出血倾向，主要因两者均可与血浆白蛋白结合，阿司匹林竞争置换双香豆素，使游离型浓度升高、抗凝作用增强。降低其代谢或排泄、增加吸收均非两药相互作用的机制；阿司匹林对肝药酶无显著抑制，不通过抑制代谢途径增强双香豆素作用。此外阿司匹林抑制血小板聚集，也与抗凝药协同增加出血风险"},{"q":"利福平的抗菌机制","o":["抑制DNA螺旋霉","抑制二氢叶酸还原酶","抑制DNA依赖的RNA多聚酶","抑制细菌分枝菌酸合成","抑制细菌蛋白质合成"],"a":2,"e":"利福平特异性抑制细菌DNA依赖的RNA多聚酶，阻碍mRNA合成而发挥广谱杀菌作用，对结核分枝杆菌、麻风杆菌及多种革兰阳性、阴性菌有效。抑制DNA螺旋酶是喹诺酮类机制；抑制二氢叶酸还原酶为甲氨蝶呤、甲氧苄啶的作用；抑制分枝菌酸合成是异烟肼抗结核机制；抑制细菌蛋白质合成见于氨基糖苷类、四环素类，均非利福平机制"},{"q":"氟喹诺酮类作用机制是","o":["抑制细菌的转肽酶而影响细菌黏肽合成","抑制细菌二氢蝶酸合成酶","抑制细菌DNA回旋酶，阻碍DNA复制产生抗菌作用","抑制细菌蛋白合成","破坏细菌的细胞壁"],"a":2,"e":"氟喹诺酮类抑制细菌DNA回旋酶及拓扑异构酶Ⅳ，阻碍DNA复制与转录，产生快速杀菌作用，对革兰阴性菌尤强。抑制转肽酶、影响黏肽合成是β-内酰胺类机制；抑制二氢蝶酸合成酶为磺胺类，通过干扰叶酸合成起效；抑制细菌蛋白质合成见于氨基糖苷、大环内酯、四环素等；破坏细菌细胞壁亦属β-内酰胺类作用，均与氟喹诺酮无关"},{"q":"缩宫素兴奋子宫平滑肌的作用机制是","o":["直接兴奋","作用于缩宫素受体","激动M受体","激动H受体","阻断β受体"],"a":1,"e":"缩宫素与子宫平滑肌细胞膜上的特异性缩宫素受体结合，激活G蛋白-磷脂酶C途径，升高细胞内Ca²⁺而加强子宫收缩，作用有剂量依赖性及子宫部位差异。直接兴奋未指出受体本质，不是准确机制。激动M受体为乙酰胆碱、卡巴胆碱的作用，激动H受体为组胺效应，阻断β受体虽可取消β2介导的子宫松弛，但均非缩宫素本身的作用机制"},{"q":"维拉帕米对下列哪种心律失常的疗效最好","o":["房室传导阻滞","室性期前收缩","强心苷中毒所致心律失常","室性心动过速","房室结折返性心律失常"],"a":4,"e":"维拉帕米通过抑制Ca²⁺内流减慢房室结传导并延长有效不应期，对房室结折返性心律失常疗效最好，是阵发性室上性心动过速首选。房室传导阻滞时钙拮抗药进一步抑制传导，属禁忌。强心苷中毒所致心律失常以室性为主，首选苯妥英钠或利多卡因。室性心动过速、室性期前收缩宜用利多卡因、胺碘酮，钙拮抗药对室性心律失常效果差"},{"q":"胆碱M受体激动可导致","o":["瞳孔开大肌收缩，支气管平滑肌舒张","血管平滑肌收缩，胃肠道平滑肌舒张","瞳孔括约肌收缩，膀胱逼尿肌舒张","睫状肌收缩，膀胱括约肌舒张","骨骼肌收缩，子宫平滑肌舒张"],"a":3,"e":"M受体激动时睫状肌环形肌收缩使晶状体变凸、调节痉挛，同时膀胱逼尿肌收缩而膀胱括约肌舒张，促进排尿，该组合正确。瞳孔开大肌由α受体支配，支气管平滑肌舒张由β2受体介导；血管平滑肌上M受体激动引起舒张而非收缩，胃肠平滑肌则收缩。瞳孔括约肌虽收缩，但膀胱逼尿肌应收缩而非舒张；骨骼肌收缩由N_M受体介导，均非M受体激动效应"},{"q":"治疗急性肺水肿时宜选用的利尿药是","o":["氯酞酮","乙酰唑胺","呋塞米","氨苯蝶啶","阿米洛利"],"a":2,"e":"呋塞米为高效能袢利尿药，静脉给药起效快，既强效排钠排水减轻肺循环淤血，又能扩张静脉、降低左室充盈压，是急性肺水肿首选的利尿药。氯酞酮属噻嗪样利尿药，作用温和缓慢，不适于抢救。乙酰唑胺为碳酸酐酶抑制药，利尿弱、主要用于青光眼。氨苯蝶啶、阿米洛利为保钾利尿药，效能低，多与排钾利尿药合用，均不适于急性肺水肿紧急处理"},{"q":"氯丙嗪引起乳房肿胀、溢乳是由于阻滞","o":["脑干网状结构上行激活系统α受体","中脑边缘和中脑皮层通路的D2受体","结节-漏斗通路D2受体","黑质-纹状体通路D2受体","M胆碱受体"],"a":2,"e":"氯丙嗪阻断结节-漏斗通路D2受体，使下丘脑释放催乳素抑制因子减少，催乳素分泌增多，引起乳房肿胀、溢乳和月经紊乱。阻断中脑边缘及中脑皮层通路D2受体是其抗精神病作用基础；阻断黑质-纹状体通路D2受体导致锥体外系反应；阻断脑干网状结构上行激活系统α受体产生镇静淡漠；阻断M胆碱受体引起口干、视力模糊，均非溢乳机制"},{"q":"叶酸对抗剂甲氨蝶呤所致的巨幼细胞贫血首选","o":["维生素","亚叶酸钙","维生素B12","叶酸","氨苯甲酸"],"a":1,"e":"甲氨蝶呤抑制二氢叶酸还原酶，使叶酸不能还原为四氢叶酸，导致DNA合成障碍和巨幼细胞贫血。亚叶酸钙为甲酰四氢叶酸钙，无需经该酶还原即可直接补充活性四氢叶酸，是解救甲氨蝶呤毒性的首选。普通叶酸需经此酶活化，在酶被抑制时无效。维生素B12用于内因子缺乏的恶性贫血，氨苯甲酸为对氨基苯甲酸、可拮抗磺胺，均与本题解救无关"},{"q":"目前癫痫的治疗原则是","o":["减少或防止发作","对因治疗","症状消失后可立即停药","手术治疗为主","仅发作时给药"],"a":0,"e":"癫痫治疗以长期规律使用抗癫痫药减少和防止发作为主要原则，多数患者需长期甚至终身用药控制发作、提高生活质量。多数癫痫病因不明，难以对因治疗，故对因治疗不是普遍原则。症状控制后仍需维持治疗，突然停药可诱发发作甚至癫痫持续状态，不能立即停药。手术仅适于药物难治、病灶明确的少数患者；仅发作时给药无法维持有效血药浓度，不能预防复发"},{"q":"钾通道开放药通常作用于哪种钾通道","o":["IK","Ito","KCa","IK1","IK（ATP）"],"a":4,"e":"钾通道开放药主要作用于ATP敏感性钾通道，代表药有吡那地尔、米诺地尔、二氮嗪，开放后K⁺外流增加、细胞膜超极化，使血管平滑肌舒张而降压。IK为电压依赖的延迟整流钾通道，Ito为瞬时外向钾通道，IK1为内向整流钾通道，三者主要参与心肌动作电位复极；KCa为钙激活钾通道，均非该类药物主要作用靶点"},{"q":"治疗有机磷酸酯类急性中毒时，阿托品不能缓解的症状是","o":["瞳孔缩小","出汗","恶心、呕吐","呼吸困难","肌肉颤动"],"a":4,"e":"阿托品为M胆碱受体阻断药，能对抗有机磷中毒时乙酰胆碱蓄积所致的M样症状，如瞳孔缩小、大汗、恶心呕吐、支气管分泌增多和呼吸困难。肌肉颤动是乙酰胆碱激动骨骼肌N_M受体产生的N样症状，阿托品对N受体无阻断作用，不能缓解，须用碘解磷定等复活药恢复酶活性、减少乙酰胆碱蓄积才能消除，这是阿托品解毒的局限"},{"q":"丙米嗪的药理作用是","o":["抗抑郁作用","抗躁狂作用","抗精神分裂症作用","抗惊厥作用","抗癫痫作用"],"a":0,"e":"丙米嗪为三环类抗抑郁药，抑制突触前膜对去甲肾上腺素和5-羟色胺的再摄取，增加突触间隙单胺递质浓度而发挥抗抑郁作用，用于各型抑郁症。抗躁狂为碳酸锂所特有；抗精神分裂症靠氯丙嗪等多巴胺受体阻断药；抗惊厥、抗癫痫用地西泮、苯妥英钠、丙戊酸钠等，均非丙米嗪的药理作用，须区分各类精神药物归属"},{"q":"强心苷中毒所致的心脏毒性，不能用钾盐治疗的是","o":["室上性阵发性心动过速","室性心动过速","室性期前收缩","心房纤颤","房室传导阻滞"],"a":4,"e":"强心苷中毒出现房室传导阻滞时禁用钾盐，高浓度K⁺抑制房室结传导，可使阻滞加重甚至发展为完全性阻滞。室性期前收缩、室性心动过速、室上性阵发性心动过速及心房纤颤等快速性心律失常，多由心肌细胞缺钾、自律性增高引起，补钾可与强心苷竞争Na⁺-K⁺-ATP酶而减轻毒性、控制心律失常，故这些类型可用钾盐治疗"},{"q":"维拉帕米首选治疗的心律失常是","o":["房室传导阻滞","阵发性室上性心动过速","室性心动过速","室性期前收缩","强心苷中毒所致心律失常"],"a":1,"e":"维拉帕米为钙拮抗药，抑制房室结Ca²⁺内流、减慢传导并延长有效不应期，可终止房室结折返，是阵发性室上性心动过速首选。房室传导阻滞与室性心动过速用维拉帕米可加重传导抑制或血流动力学障碍，不宜选用。室性期前收缩多首选利多卡因或β受体阻断药。强心苷中毒所致心律失常宜用苯妥英钠或利多卡因并停药补钾，维拉帕米并非首选"},{"q":"以下药物中不具有抑制免疫系统效果的是","o":["泼尼松","环孢素","他克莫司","环磷酰胺","胸腺肽"],"a":4,"e":"胸腺肽为免疫增强剂，促进T淋巴细胞分化成熟、增强细胞免疫功能，用于免疫缺陷病和某些病毒感染，不具有免疫抑制作用。泼尼松为糖皮质激素，抑制淋巴细胞增殖和抗体生成；环孢素、他克莫司为钙调磷酸酶抑制剂，阻断T细胞活化；环磷酰胺为烷化剂，抑制淋巴细胞增殖，三者均属常用免疫抑制剂，关键在于区分免疫增强与免疫抑制两类"},{"q":"诱发甲状腺功能紊乱的药物是","o":["甲硫氧嘧啶","碘化物","三碘甲状腺原氨酸","卡比马唑","普萘洛尔"],"a":1,"e":"碘化物摄入过多可诱发甲状腺功能紊乱，既因过量碘导致甲状腺毒症，也可因长期过量抑制激素合成与释放引起甲状腺功能减退。甲硫氧嘧啶、卡比马唑为硫脲类抗甲状腺药，通过抑制过氧化物酶减少激素合成，用于治疗甲亢。三碘甲状腺原氨酸为激素替代药，普萘洛尔仅阻断β受体控制甲亢症状，均非诱发甲状腺功能紊乱的典型药物"},{"q":"皮肤癣菌临床感染常选用","o":["灰黄霉素","两性霉素B","制霉菌素","林可霉素","青霉素"],"a":0,"e":"灰黄霉素为抗浅部真菌药，抑制皮肤癣菌微管聚合、阻断其有丝分裂，口服后沉积于皮肤角质层，用于头癣、体癣、甲癣等皮肤癣菌感染。两性霉素B、制霉菌素为多烯类抗真菌药，主要用于深部真菌或局部念珠菌感染，对皮肤癣菌非首选。林可霉素、青霉素为抗菌药，对真菌无效，不在抗真菌考虑之列，故选灰黄霉素"},{"q":"有机磷酸酯类中毒，必须马上用胆碱酯酶复活药抢救，是因为","o":["胆碱酯酶不易复活","胆碱酯酶复活药起效慢","被抑制的胆碱酯酶很快“老化”","需要立即对抗乙酰胆碱作用","该药药效持续时间短，需迅速注射"],"a":2,"e":"有机磷酸酯类与胆碱酯酶共价结合形成磷酰化酶，若不及时复活，磷酰基会进一步脱落烷化基团，形成更稳定的老化酶，此时复活药无法恢复活性，故必须尽早给药。复活药起效并不慢，其价值在于抢在老化之前；立即对抗乙酰胆碱是阿托品的职责，并非复活药使用的根本原因；药效持续短也不是必须马上用的依据，老化才是关键时间窗"},{"q":"对脑水肿病人静注50%高渗葡萄糖的主要目的是","o":["补充能量","使脑组织脱水","增加血容量，防止休克","渗透性利尿","保护脑细胞，减慢脑死亡"],"a":1,"e":"50%高渗葡萄糖静注后提高血浆渗透压，使脑组织水分向血管内转移，从而减轻脑水肿、降低颅内压，这是主要目的。补充能量虽是葡萄糖作用之一，但在脑水肿抢救中并非首要。高渗溶液并不扩充血容量到抗休克程度，反因利尿可减少血容量。渗透性利尿是甘露醇等不易代谢脱水药的特点，葡萄糖易被代谢、利尿短暂，保护脑细胞、减慢脑损伤进展亦非直接目的"},{"q":"促进药物生物转化的主要酶系统是","o":["单胺氧化酶","细胞色素P450酶系统","辅酶Ⅱ","水解酶","葡萄糖醛酸转移酶"],"a":1,"e":"细胞色素P450酶系统是促进药物生物转化的主要酶系统，参与多数药物的氧化反应，其活性可被诱导或抑制，从而影响药物代谢和药效。单胺氧化酶主要代谢内源性单胺递质及少数药物；辅酶Ⅱ为羟化反应供氢、是P450的辅酶而非独立系统；水解酶仅水解酯类、酰胺类；葡萄糖醛酸转移酶催化结合反应，均不能替代P450在药物氧化中的核心地位"},{"q":"有关AT1受体拮抗剂氯沙坦不良反应，叙述错误的是","o":["避免与补钾药合用","对血液中脂质及葡萄糖含量无影响","不引起直立性低血压","刺激性干咳","禁用于肾动脉狭窄者"],"a":3,"e":"氯沙坦为AT1受体拮抗剂，不抑制缓激肽降解，很少引起刺激性干咳；干咳是血管紧张素转化酶抑制药因缓激肽蓄积的典型不良反应，故该项叙述错误。氯沙坦可致血钾升高，应避免与补钾药或保钾利尿药合用；对血脂、血糖无不良影响；不易引起直立性低血压；双侧肾动脉狭窄者用后肾小球滤过压下降，属禁忌，其余各项表述正确"},{"q":"阻滞钠通道而减少Na＋再吸收，同时减少K＋分泌的利尿药是","o":["乙酰唑胺","氢氯噻嗪","螺内酯","阿米洛利","呋塞米"],"a":3,"e":"阿米洛利直接阻滞远曲小管和集合管的上皮钠通道，减少Na⁺重吸收，使管腔负电位降低、K⁺分泌随之减少，产生保钾利尿作用。氢氯噻嗪抑制远曲小管近端Na⁺-Cl⁻共转运体，增加K⁺排出；呋塞米抑制髓袢升支粗段Na⁺-K⁺-2Cl⁻共转运体，也致排钾。螺内酯通过拮抗醛固酮间接保钾、不阻滞钠通道，乙酰唑胺抑制碳酸酐酶，均不符合阻滞钠通道的描述"},{"q":"阿托品不会引起的不良反应是","o":["恶心、呕吐","视力模糊","口干","排尿困难","心悸"],"a":0,"e":"阿托品阻断M胆碱受体，抑制腺体分泌与胃肠平滑肌蠕动，可引起口干、视力模糊、排尿困难及心悸，大剂量还可致中枢兴奋。恶心、呕吐并非其典型不良反应，相反，阿托品通过解痉作用可缓解胃肠绞痛所致的恶心呕吐，故该项不属于阿托品的不良反应，其余四项均为M受体阻断的常见表现"},{"q":"首次剂量加倍的原因是","o":["为了使血药浓度迅速达到Css","为了使血药浓度持续高水平","为了增强药理作用","为了延长半衰期","为了提高生物利用度"],"a":0,"e":"首剂加倍即给予负荷剂量，目的是使血药浓度迅速达到稳态浓度，从而在急症或需快速起效时尽早发挥药效。维持稳态浓度靠后续按半衰期给予维持剂量，而非单次加倍；加倍剂量并不增强药物固有的最大药理作用，也不能延长半衰期或提高生物利用度，半衰期与生物利用度是药物或制剂的固有特征，不因首剂加倍而改变"},{"q":"强心苷增强心肌收缩性的作用机制与下列哪种离子变化有关","o":["心肌细胞内K＋增加","心肌细胞内Na＋减少","心肌细胞内Ca2＋增加","心肌细胞内Mg2＋增加","心肌细胞内Cl－增加"],"a":2,"e":"强心苷抑制心肌细胞膜Na⁺-K⁺-ATP酶，使细胞内Na⁺升高，减弱Na⁺-Ca²⁺交换，导致细胞内Ca²⁺增加，从而增强心肌收缩力。细胞内K⁺不是增加而是因泵受抑而减少，细胞内Na⁺也是增加而非减少，两项方向说反。Mg²⁺、Cl⁻的变化与正性肌力机制无关，强心苷正是通过升高细胞内钙而非其他离子发挥强心作用"},{"q":"对脑血管有选择性扩张作用的钙拮抗药是","o":["硝苯地平","尼莫地平","尼群地平","维拉帕米","地尔硫䓬"],"a":1,"e":"尼莫地平为二氢吡啶类钙拮抗药，脂溶性高、易透过血脑屏障，对脑血管平滑肌有较高选择性，可增加脑血流量，用于防治蛛网膜下腔出血后的脑血管痉挛及缺血性脑血管病。硝苯地平、尼群地平主要扩张外周血管降压，脑血管选择性低。维拉帕米、地尔硫䓬属非二氢吡啶类，主要作用于心脏房室结和心肌，不以扩张脑血管为特点"},{"q":"下列关于胺碘酮的叙述，错误的是","o":["对α、β肾上腺素受体无阻断作用","降低窦房结和浦肯野纤维的自律性","阻滞心肌细胞钠、钙及钾通道","减慢浦肯野纤维和房室结的传导速度","延长心房肌、心室肌、浦肯野纤维的动作电位时程、有效不应期"],"a":0,"e":"胺碘酮为Ⅲ类抗心律失常药，兼有非竞争性阻断α、β肾上腺素受体的作用，故“对α、β受体无阻断作用”的叙述错误。它可阻滞钠、钙及钾通道，降低窦房结和浦肯野纤维自律性，减慢房室结与浦肯野纤维传导，显著延长心房肌、心室肌及浦肯野纤维的动作电位时程和有效不应期，这些均符合其广谱抗心律失常的电生理基础"},{"q":"下列可激动M和N胆碱受体的是","o":["毛果芸香碱、氯贝胆碱","毒蕈碱、筒箭毒碱","烟碱、乙酰胆碱","卡巴胆碱、醋甲胆碱","琥珀胆碱、毒扁豆碱"],"a":3,"e":"卡巴胆碱与醋甲胆碱均为人工合成的胆碱酯类，化学性质稳定、不被胆碱酯酶水解，可同时激动M和N胆碱受体，作用广泛。烟碱只选择性激动N受体，毒蕈碱只激动M受体，均无双重激动作用；毛果芸香碱、氯贝胆碱为M受体选择性激动药，琥珀胆碱激动N_M受体但属除极化肌松药，筒箭毒碱阻断N_M受体，毒扁豆碱通过抑制胆碱酯酶间接起效"},{"q":"对于应用甲氨蝶呤引起的巨幼红细胞性贫血，治疗时宜选用","o":["亚叶酸钙","叶酸＋维生素B12","红细胞生成素","叶酸","维生素B12"],"a":0,"e":"甲氨蝶呤抑制二氢叶酸还原酶，阻断叶酸向四氢叶酸转化，导致巨幼红细胞性贫血。亚叶酸钙是四氢叶酸的甲酰衍生物，不需经该酶还原即可直接提供活性叶酸，为首选。叶酸须经此酶活化才能生效，在酶被抑制时效果差；维生素B12用于恶性贫血；加用维生素B12或红细胞生成素均不能纠正叶酸缺乏，只有亚叶酸钙可绕过被抑制的环节"},{"q":"以下抗恶性肿瘤药为细胞周期非特异性药物的是","o":["羟基脲","阿糖胞苷","长春碱","烷化剂","甲氨蝶呤"],"a":3,"e":"烷化剂与DNA形成交叉联结，直接破坏DNA结构与功能，对增殖细胞各时相及非增殖细胞均有杀伤作用，属细胞周期非特异性药物。羟基脲抑制核苷酸还原酶、主要作用于S期；阿糖胞苷抑制DNA多聚酶、为S期特异药；甲氨蝶呤抑制二氢叶酸还原酶、主要作用于S期；长春碱抑制微管聚合、作用于M期，四者均为细胞周期特异性药物"},{"q":"丙磺舒延长青霉素药效的原因是","o":["也有杀菌作用","能减慢青霉素的代谢","能延缓耐药性的产生","能减慢青霉素的排泄","能减少青霉素的分布"],"a":3,"e":"丙磺舒竞争性抑制肾小管上皮细胞的有机酸转运体，减少青霉素经肾小管的主动分泌，使其排泄减慢、血药浓度维持时间延长，从而延长药效。丙磺舒本身无抗菌作用，不抑制肝药酶，也不减慢青霉素代谢；它不影响药物吸收，对耐药性产生无直接影响，更非通过减少分布来增效，该相互作用发生在肾脏排泄环节"},{"q":"对于人类免疫缺陷病毒感染，以下药物对其无治疗效果的是","o":["转移因子","齐多夫定","胸腺素","泼尼松","白细胞介素-2"],"a":3,"e":"泼尼松为糖皮质激素，具免疫抑制作用，不仅不能抑制人类免疫缺陷病毒复制，反而可因抑制机体防御而利于病毒扩散，对HIV感染无治疗价值。齐多夫定为核苷类逆转录酶抑制剂，是抗HIV基本药。转移因子、胸腺素、白细胞介素-2为免疫调节剂，可增强细胞免疫功能，作为辅助治疗，均有一定治疗或支持意义，唯泼尼松不属此类"},{"q":"唑类抗真菌药物的主要作用机制是","o":["抑制核酸合成","抑制二氢叶酸合成酶","抑制二氢叶酸还原酶","抑制蛋白质合成","抑制细胞膜麦角固醇的合成，使其通透性增加"],"a":4,"e":"唑类抗真菌药抑制真菌细胞色素P450依赖的14α-羊毛甾醇去甲基化酶，阻断麦角固醇合成，使细胞膜麦角固醇缺乏、通透性增加、胞内成分外漏而抑菌。抑制核酸合成是氟胞嘧啶的机制；抑制二氢叶酸合成酶为磺胺类；抑制二氢叶酸还原酶为甲氧苄啶等；抑制蛋白质合成见于氨基糖苷、四环素等抗菌药，均非唑类抗真菌机制"},{"q":"下列药物哪种是繁殖期杀菌药","o":["青霉素","庆大霉素","多黏菌素","四环素","阿米卡星"],"a":0,"e":"青霉素类抑制细菌细胞壁黏肽合成，使繁殖期细菌因细胞壁缺损、渗透压作用而裂解死亡，属繁殖期杀菌药。庆大霉素、阿米卡星为氨基糖苷类，主要作用于静止期，阻碍蛋白合成并破坏细胞膜，属静止期杀菌药。多黏菌素破坏革兰阴性菌细胞膜，对静止期亦有效；四环素抑制蛋白质合成、为快速抑菌药，均不属繁殖期杀菌药"},{"q":"呋塞米对尿中离子排泄的影响不正确的是","o":["Na＋排出增加","K＋排出增加","Mg2＋排出增加","Ca2＋排出增加","HCO3－排出减少"],"a":4,"e":"呋塞米抑制髓袢升支粗段Na⁺-K⁺-2Cl⁻共转运体，使Na⁺、K⁺、Cl⁻重吸收减少、排出增加；管腔正电位消失后Ca²⁺、Mg²⁺重吸收也减少，排出增加。该药还能使尿中HCO3⁻排出增加而非减少，长期使用可致低氯性碱血症，故“碳酸氢根排出减少”与呋塞米排离子特点不符，是本题要求选出的不正确项"},{"q":"解热镇痛药的主要镇痛机理","o":["激活阿片受体","抑制下丘脑的前列腺素合成","抑制外周组织前列腺素合成","抑制外周组织组胺合成","抑制外周组织缓激肽合成"],"a":2,"e":"解热镇痛药抑制外周组织环氧酶、减少前列腺素合成，降低痛觉敏感化而发挥镇痛作用，对炎症性钝痛好，且不激动阿片受体、无成瘾性。抑制下丘脑前列腺素合成是其解热机制，与镇痛部位不同。组胺、缓激肽虽参与炎症疼痛，但本类药物并不抑制其合成，而是减少前列腺素这一致痛敏介质，故外周前列腺素合成受抑才是镇痛主要机理"},{"q":"脑血管痉挛性疾病宜选用","o":["地尔硫䓬","普萘洛尔","维拉帕米","硝苯地平","尼莫地平"],"a":4,"e":"尼莫地平为二氢吡啶类钙拮抗药，脂溶性强、易进入中枢，选择性扩张脑血管、增加脑血流量，可防治蛛网膜下腔出血等所致脑血管痉挛，是脑血管痉挛性疾病的适宜选择。地尔硫䓬、维拉帕米主要作用于心脏、抑制房室传导与心肌收缩；普萘洛尔为β受体阻断药，可使脑血管收缩倾向；硝苯地平主要扩张外周血管，脑血管选择性远不如尼莫地平"},{"q":"不宜用于变异型心绞痛的药物","o":["硝酸甘油","硝苯地平","普萘洛尔","维拉帕尔","地尔硫䓬"],"a":2,"e":"变异型心绞痛由冠状动脉痉挛所致，普萘洛尔阻断β2受体后冠脉α受体介导的收缩占优势，可加重痉挛，故不宜使用。硝酸甘油直接扩张冠脉、缓解痉挛，是常用药。硝苯地平、维拉帕米、地尔硫䓬均为钙拮抗药，可抑制Ca²⁺内流、解除冠脉平滑肌痉挛，对变异型心绞痛疗效良好，其中硝苯地平尤为适用，只有普萘洛尔属禁忌"},{"q":"肝素的抗凝机制是","o":["拮抗维生素K","特异性抑制凝血酶活性","依赖抗凝血酶Ⅲ，抑制多种凝血因子、凝血酶","抗血小板聚集","络合钙离子"],"a":2,"e":"肝素依赖抗凝血酶Ⅲ发挥抗凝作用，与之结合后使其构象改变，灭活凝血酶及因子Ⅸa、Ⅹa、Ⅺa、Ⅻa等多种凝血因子，体内体外均迅速有效。拮抗维生素K是香豆素类的机制，通过抑制依赖维生素K的凝血因子合成起效、起效慢；特异性抑制凝血酶见于直接凝血酶抑制药；抗血小板聚集为阿司匹林等的作用；络合钙离子为枸橼酸钠体外抗凝机制，均非肝素机制"},{"q":"下列哪类药物常作为基础降压药应用","o":["肾上腺素受体阻断药","中枢交感神经抑制药","血管扩张药","血管紧张素转化酶抑制药","利尿降压药"],"a":4,"e":"利尿降压药尤其噻嗪类作用温和持久，能增强其他降压药效果并抵消其水钠潴留不良反应，常作为基础降压药用于轻中度高血压及联合方案。肾上腺素受体阻断药、中枢交感抑制药、血管紧张素转化酶抑制药均为常用降压药，但各有特定适应证和不良反应；血管扩张药因反射性心率加快、水钠潴留等缺点一般不作基础用药，故利尿药被称为基础降压药"},{"q":"肝功能障碍病人正常情况下，可以使用的抗菌药是","o":["红霉素","氯霉素","青霉素","利福平","林可霉素"],"a":2,"e":"青霉素类主要以原形经肾排泄、体内代谢极少，肝功能不良时消除基本不受影响，可按正常剂量使用，除非合并肾功能不全。红霉素、林可霉素主要经肝代谢并随胆汁排泄，氯霉素在肝内与葡萄糖醛酸结合灭活，利福平经肝代谢且有肝毒性，这四种药在肝功能损害时均易蓄积或加重肝损伤，应慎用或减量，只有青霉素对肝功能影响最小"},{"q":"排钠效能最高的利尿药是","o":["氢氯噻嗪","阿米洛利","呋塞米","环戊噻嗪","苄氟噻嗪"],"a":2,"e":"呋塞米属高效能袢利尿药，抑制髓袢升支粗段Na⁺-K⁺-2Cl⁻共转运体，该部位重吸收钠量最大，故排钠利尿效能居各类利尿药之首，可用于严重水肿和急性肺水肿。氢氯噻嗪、环戊噻嗪、苄氟噻嗪均为噻嗪类中效利尿药，作用于远曲小管近端。阿米洛利为保钾利尿药，阻滞远曲小管钠通道、利尿弱，排钠效能远低于呋塞米"},{"q":"pKa＜4的弱酸性药物如地西泮，在胃肠道pH范围内基本都是","o":["离子型，吸收快而完全","非离子型，吸收快而完全","离子型，吸收慢而不完全","非离子型，吸收慢而不完全","离子型和非离子型相等"],"a":1,"e":"弱酸性药物的解离取决于环境pH与pKa，当胃肠道pH高于其pKa时主要以非离子型存在，脂溶性大、易跨膜吸收，故pKa小于4者在该范围内基本为非离子型、吸收快而完全。离子型比例高时脂溶性低、吸收差，多见于pH远离pKa的极端环境，故离子型吸收快或离子与非离子相等均不对；非离子型吸收慢而不完全同样与该解离特点相悖"},{"q":"对伴有心律失常的心绞痛患者最好选用","o":["硝酸甘油","普萘洛尔","硝酸异山梨酯","氨氯地平","硝苯地平"],"a":1,"e":"普萘洛尔为β受体阻断药，既减慢心率、减弱心肌收缩力、降低心肌耗氧量而缓解心绞痛，又抑制窦房结和房室结、减慢传导，对伴快速性心律失常的心绞痛最适宜。硝酸甘油、硝酸异山梨酯主要扩张血管、降低前后负荷，无抗心律失常作用且可反射性加快心率。氨氯地平、硝苯地平主要扩张血管降压，对心律失常无明显治疗作用，部分还致反射性心动过速"},{"q":"利用玻璃微电极测定细胞膜对离子的通透性，可记录单个通道的电活动，并可应用于直径较小的细胞的技术是","o":["电压钳","电流钳","脑片钳","膜片钳","电位钳"],"a":3,"e":"膜片钳技术用玻璃微电极与细胞膜形成高阻封接，可记录单个离子通道的开放、关闭电流，灵敏度高、能用于直径较小的细胞，是研究通道电活动的重要方法。电压钳通过反馈控制膜电位、测量全细胞离子电流，不能分辨单通道；电流钳在恒定电流下记录膜电位变化；脑片钳是在脑切片上进行的膜片钳记录，均非题干所述通用技术名称"},{"q":"抑制5-羟色胺再摄取的口服抗抑郁药是","o":["阿米替林","氟西汀","丙咪嗪","地昔帕明","曲唑酮"],"a":1,"e":"氟西汀为选择性5-羟色胺再摄取抑制剂，抑制突触前膜对5-HT的再摄取、提高突触间隙浓度而抗抑郁，口服吸收好、不良反应较三环类少。阿米替林、丙咪嗪、地昔帕明均为三环类，主要抑制去甲肾上腺素再摄取且有较多抗胆碱和心脏毒性。曲唑酮虽影响5-HT系统，但以拮抗5-HT2受体并抑制其再摄取为主，与选择性抑制剂不同"},{"q":"糖皮质激素治疗过敏性支气管哮喘的主要作用机制是","o":["直接扩张支气管平滑肌","兴奋β2受体","稳定肥大细胞膜，抑制炎性介质释放","使细胞内cAMP增加","抑制补体参与免疫反应"],"a":2,"e":"糖皮质激素诱导脂皮素合成、抑制磷脂酶A2，减少白三烯与前列腺素生成，并稳定肥大细胞膜、抑制脱颗粒和炎性介质释放，从而减轻气道炎症和高反应性，是治疗过敏性哮喘的核心机制。直接扩张支气管为β2激动药和茶碱类作用；兴奋β2受体、升高cAMP是沙丁胺醇等机制；抑制补体参与免疫反应并非其平喘主要环节，均非本题正确表述"},{"q":"格列本脲降血糖的主要作用机制是","o":["拮抗胰高血糖素的作用","增强肌肉组织糖的无氧酵解","妨碍葡萄糖的肠道吸收","刺激胰岛β细胞释放胰岛素","升高血清糖原水平"],"a":3,"e":"格列本脲为磺酰脲类，阻断胰岛β细胞膜ATP敏感性钾通道，使膜去极化、Ca²⁺内流，触发胰岛素释放，故依赖尚有功能的β细胞，用于2型糖尿病。增强肌肉糖的无氧酵解是双胍类特点；妨碍葡萄糖肠道吸收为α-葡萄糖苷酶抑制药的机制；升高血清糖原水平、拮抗胰高血糖素均非其降糖途径，须区分不同口服降糖药机制"},{"q":"关于硝酸酯类，描述错误的是","o":["舌下含服避免首过消除","硝酸异山梨酯作用持久与代谢产物活性有关","其作用机制与释放NO有关","剂量过大时，血压降低可致反射性心率加快","增加心室内压，改善心内膜供血"],"a":4,"e":"硝酸酯类释放NO扩张血管，降低左室充盈压和室壁张力，使心内膜下血流灌注改善，而不是增加心室内压，故该项描述错误。舌下含服绕过肝首过消除、迅速起效；硝酸异山梨酯代谢生成的异山梨醇仍有扩血管活性，作用较持久；大剂量使血压明显下降时可反射性兴奋交感、心率加快，均为正确描述，只有增加心室内压与硝酸酯血流动力学效应相反"},{"q":"耳、肾毒性最小的氨基糖苷药物是","o":["链霉素","卡那霉素","庆大霉素","新霉素","奈替米星"],"a":4,"e":"奈替米星为半合成氨基糖苷类，对多种革兰阴性菌有效，其耳毒性、肾毒性在常用氨基糖苷类中最小，且对部分耐庆大霉素菌株有效。链霉素前庭功能损害明显，卡那霉素耳肾毒性均较大，庆大霉素肾毒性常见，新霉素毒性最大、仅供局部或口服肠道准备而不作全身给药。本题需比较同类药物毒性差异，奈替米星以毒性低为特点"},{"q":"流行性脑脊髓膜炎治疗应选用哪种药物","o":["甲氧苄啶","磺胺嘧啶","庆大霉素","万古霉素","多黏菌素"],"a":1,"e":"磺胺嘧啶较易透过血脑屏障，在脑脊液中浓度较高，是治疗流行性脑脊髓膜炎的常用药，尤其对敏感菌株。甲氧苄啶为叶酸通路增效剂，常与磺胺甲噁唑合用，不单独用于流脑。庆大霉素对脑膜炎球菌活性弱且不易入脑脊液。万古霉素主要针对革兰阳性菌，多黏菌素针对革兰阴性杆菌，均非流脑适宜选药，故选磺胺嘧啶"},{"q":"药物的副作用是指","o":["专指反应程度较高的过敏反应","因用量过大所致","治疗剂量下产生的与治疗目的无关作用","指剧毒药所产生的毒性","由于患者高度敏感所致"],"a":2,"e":"副作用指治疗剂量下出现的与治疗目的无关的药理作用，源于药物选择性低，通常较轻微、可预知、停药可恢复。过敏反应是免疫介导的异常反应、与剂量无关，并非反应程度较高即副作用；因用量过大所致为毒性反应；剧毒药引起的严重反应也属毒性反应；患者高度敏感所致多为变态或特异质反应，均不符合副作用治疗剂量、与目的无关的定义要点"},{"q":"舌下给药的特点是","o":["可避免胃肠刺激作用","可避免肝肠循环","可避免药物副作用","可避免不良反应","可避免首过消除"],"a":4,"e":"舌下给药时药物经舌下黏膜吸收，由舌下静脉汇入颈内静脉直接进入体循环，不经门静脉和肝脏，因而避免首过消除、生物利用度高、起效快。避免胃肠刺激虽是其特点之一，但最具特征性的是避免首过消除；肝肠循环指药物经胆汁排入肠道后被重吸收，舌下给药不能避免已进入体内的药物的肝肠循环。副作用与不良反应由药物性质决定，给药途径不能消除"},{"q":"药动学研究的内容是","o":["机体对药物的处置","药物剂量与药物效应强弱关系","药物化学结构的变化","药物对机体的作用","药物作用的两重性作用"],"a":0,"e":"药动学研究机体对药物的处置，即吸收、分布、代谢和排泄过程，常用血药浓度-时间曲线及动力学参数定量描述。剂量与效应强弱关系属药效学的量效关系；药物对机体的作用及其机制、作用两重性均属药效学范畴；药物化学结构的变化属药物化学内容，均非药动学主要研究对象，故选机体对药物的处置"},{"q":"氯丙嗪使下列哪种激素释放增加","o":["生长激素","促性腺激素","催乳素","甲状腺激素","促肾上腺皮质激素"],"a":2,"e":"氯丙嗪阻断结节-漏斗通路D2受体，使催乳素抑制因子释放减少，催乳素分泌增加，可引起溢乳、乳房肿大。该药对生长激素、促性腺激素、促肾上腺皮质激素的释放多为抑制或无明显促进，甲状腺激素分泌亦不受其促进，故这些激素释放增加的说法均不成立。本题与氯丙嗪内分泌不良反应为同一知识点，核心是催乳素升高"},{"q":"硝酸甘油与普萘洛尔联合应用治疗心绞痛，药理作用相同的因素是","o":["心率","心室容积","心肌耗氧量","射血时间","心肌收缩力"],"a":2,"e":"两药联用的共同点是均降低心肌耗氧量：硝酸甘油扩张静脉、降低前负荷和室壁张力，普萘洛尔减慢心率、减弱心肌收缩力。心率方面硝酸甘油反射性加快而普萘洛尔减慢；心室容积硝酸甘油缩小而普萘洛尔增大；射血时间硝酸甘油缩短而普萘洛尔延长；心肌收缩力硝酸甘油不减弱甚至反射增强而普萘洛尔减弱，这些指标正好互相抵消，唯独降低耗氧量一致"},{"q":"属于子宫平滑肌抑制药的是","o":["前列腺素","麦角胺","缩宫素","利托君","垂体后叶素"],"a":3,"e":"利托君为β2肾上腺素受体激动药，激动子宫平滑肌β2受体使cAMP升高、子宫松弛，可抑制宫缩、防治早产，属子宫平滑肌抑制药。前列腺素、缩宫素及含缩宫素的垂体后叶素均兴奋子宫平滑肌、促进宫缩，用于引产或产后止血；麦角胺亦收缩子宫、用于产后出血，均属子宫兴奋药，与利托君作用相反"},{"q":"下列关于钠通道阻滞药的说法，正确的是","o":["Ⅰa类适度阻滞钠通道，代表药物有利多卡因、苯妥英钠等","Ⅰa类轻度阻滞钠通道，轻度降低动作电位0期除极速率","Ⅰb类明显阻滞钠通道，显著降低动作电位0期除极速率和幅度","Ⅰb类代表药物有奎尼丁、普鲁卡因胺等","Ⅰc类代表药有普罗帕酮、氟卡尼等"],"a":4,"e":"Ⅰc类钠通道阻滞作用最强，显著减慢0期除极，代表药为普罗帕酮、氟卡尼，表述正确。Ⅰa类为适度阻滞、延长动作电位时程，代表奎尼丁、普鲁卡因胺；Ⅰb类为轻度阻滞、缩短动作电位时程，代表利多卡因、苯妥英钠。选项把利多卡因、苯妥英钠归为Ⅰa，把Ⅰa说成轻度阻滞，把Ⅰb说成明显阻滞，把奎尼丁、普鲁卡因胺归为Ⅰb，均张冠李戴"},{"q":"维拉帕米的抗心律失常作用机制是","o":["促进K＋外流","促进Na＋内流","促进Cl－内流","抑制Ca2＋内流","抑制K＋外流"],"a":3,"e":"维拉帕米为非二氢吡啶类钙拮抗药，抑制心肌及房室结L型钙通道、减少Ca²⁺内流，减慢房室结传导并延长有效不应期，可终止房室结折返。促进K⁺外流为利多卡因等Ⅰb类或腺苷的作用，抑制K⁺外流为Ⅲ类胺碘酮特点，均与钙拮抗无关；促进Na⁺内流会加快除极、提高自律性，不是抗心律失常机制；促进Cl⁻内流亦非维拉帕米作用"},{"q":"去氧肾上腺素的扩瞳作用机制是","o":["激动虹膜括约肌的M受体","阻断虹膜括约肌的M受体","激动虹膜开大肌的α受体","阻断虹膜开大肌的α受体","激动睫状肌的M受体"],"a":2,"e":"去氧肾上腺素为α1受体激动药，激动虹膜开大肌的α受体使开大肌收缩而散瞳，不引起调节麻痹、不明显升高眼压，可用于眼底检查。激动虹膜括约肌M受体为毛果芸香碱的作用、引起缩瞳；阻断虹膜括约肌M受体为阿托品的散瞳机制；激动睫状肌M受体致调节痉挛；阻断虹膜开大肌α受体则使瞳孔缩小，均与其扩瞳机制相反"},{"q":"下列疾病宜选用选择性M3受体阻断药治疗的是","o":["消化性溃疡","膀胱过度活动症","青光眼","妊娠呕吐","心律失常"],"a":1,"e":"选择性M3受体阻断药如托特罗定、索利那新，可抑制膀胱逼尿肌过度活动、降低膀胱敏感性，是膀胱过度活动症的主要治疗药。消化性溃疡主要用质子泵抑制剂，哌仑西平阻断M1抑酸而非选择性M3；青光眼需用M激动药毛果芸香碱缩瞳降眼压，M3阻断可升高眼压；妊娠呕吐与M3阻断无关；心律失常常用β阻断药或胺碘酮，均非其适应证"},{"q":"下列不属于作用于肾素-血管紧张素-醛固酮系统的药物是","o":["阿利吉仑","卡托普利","替米沙坦","氨氯地平","螺内酯"],"a":3,"e":"作用于肾素-血管紧张素-醛固酮系统的药物有直接肾素抑制药阿利吉仑、ACE抑制药卡托普利、AT1受体拮抗药替米沙坦及醛固酮受体拮抗药螺内酯，分别作用于该系统不同环节。氨氯地平为二氢吡啶类钙拮抗药，通过阻滞Ca²⁺内流扩张血管降压，不影响肾素、血管紧张素或醛固酮，故不属于作用于RAAS的药物"},{"q":"兼具抗肿瘤、抗病毒以及免疫调节功能的免疫增强剂是","o":["泼尼松","胸腺素","左旋咪唑","干扰素","环孢素"],"a":3,"e":"干扰素具广谱抗病毒、抑制细胞增殖和免疫调节三重作用，可增强NK细胞与巨噬细胞活性、上调MHC表达，用于病毒感染、某些肿瘤及免疫相关疾病，是符合三项功能的免疫增强剂。泼尼松、环孢素均为免疫抑制药，作用相反；胸腺素、左旋咪唑虽为免疫增强剂，主要调节T细胞功能，不具备明确的抗病毒与抗肿瘤三重作用，不能同时满足题干条件"},{"q":"耐青霉素酶的半合成青霉素是","o":["苯唑西林","氨苄西林","阿莫西林","羧苄西林","哌拉西林"],"a":0,"e":"苯唑西林为异噁唑类半合成青霉素，侧链空间位阻保护β-内酰胺环不被青霉素酶水解，对产酶金黄色葡萄球菌有效，属耐酶青霉素。氨苄西林、阿莫西林为广谱青霉素，对革兰阴性菌有效但不耐酶；羧苄西林、哌拉西林主要用于铜绿假单胞菌等感染，同样不耐酶、遇产酶菌株易失效，须区分耐酶、广谱与抗假单胞菌三类归属"},{"q":"下列哪一项不属于呋塞米的不良反应","o":["低钾血症","低镁血症","耳毒性","低氯性碱血症","灰婴综合征"],"a":4,"e":"灰婴综合征是氯霉素在新生儿、早产儿体内蓄积所致的严重不良反应，与呋塞米无关。呋塞米抑制髓袢升支粗段重吸收，使K⁺、Mg²⁺排出增多，引起低钾血症、低镁血症；Cl⁻排出增加可致低氯性碱血症；大剂量或与其他耳毒性药合用可致耳鸣、听力下降等耳毒性，均为其典型不良反应，只有灰婴综合征不属于"},{"q":"下列药物中属于吩噻嗪类抗精神分裂症药的是","o":["氯丙嗪","氟哌啶醇","氯氮平","舒必利","利培酮"],"a":0,"e":"氯丙嗪为吩噻嗪类抗精神病药代表，通过阻断中脑边缘及中脑皮层通路D2受体发挥抗精神分裂症作用。氟哌啶醇属丁酰苯类，氯氮平属二苯并二氮杂䓬类，舒必利属苯甲酰胺类，利培酮属苯并异噁唑类，均非吩噻嗪类结构。需按化学结构辨别各类抗精神病药，只有氯丙嗪具吩噻嗪母核"},{"q":"治疗甲氨蝶呤所致巨幼红细胞贫血，宜选用","o":["铁剂","维生素B12","叶酸","双香豆素","亚叶酸钙"],"a":4,"e":"甲氨蝶呤抑制二氢叶酸还原酶、阻断四氢叶酸生成，引起巨幼红细胞性贫血。亚叶酸钙为四氢叶酸的甲酰化衍生物，可绕过被抑制的酶直接提供活性叶酸，为解救首选。铁剂用于缺铁性贫血；维生素B12用于恶性贫血；普通叶酸需经该酶还原才生效，在甲氨蝶呤存在时疗效不佳；双香豆素为抗凝药，与本病无关，均非适宜选择"},{"q":"具有黏痰溶解作用的祛痰药是","o":["乙酰半胱氨酸","苯丙哌林","氯化铵","苯佐那酯","山梨醇"],"a":0,"e":"乙酰半胱氨酸含巯基，可断裂痰液黏蛋白的二硫键、降低痰液黏稠度，使痰液化易于咳出，属黏痰溶解药，适于痰液黏稠不易咳出者。氯化铵为刺激性祛痰药，刺激胃黏膜反射性增加呼吸道分泌使痰稀释，并非直接溶解黏痰。苯丙哌林、苯佐那酯为镇咳药、抑制咳嗽反射，山梨醇为渗透性脱水或缓泻用，均无黏痰溶解作用"},{"q":"酮替芬属于下述哪种药物","o":["茶碱类","β2肾上腺素受体激动药","糖皮质激素","抗过敏平喘药","M胆碱受体阻断药"],"a":3,"e":"酮替芬为口服抗过敏平喘药，可阻断H1受体并稳定肥大细胞膜、抑制炎性介质释放，用于预防支气管哮喘发作，尤适于过敏性哮喘及儿童。茶碱类以氨茶碱为代表，通过抑制磷酸二酯酶、拮抗腺苷受体平喘；β2激动药如沙丁胺醇为支气管舒张剂；糖皮质激素如布地奈德抗炎平喘；M受体阻断药如异丙托溴铵阻断M受体舒张支气管，均非酮替芬所属类别"},{"q":"高血压危象可选用下列哪种药物","o":["硝普钠","氯沙坦","卡托普利","氢氯噻嗪","普萘洛尔"],"a":0,"e":"硝普钠直接松弛血管平滑肌、同时扩张动脉和静脉，降低前后负荷，静脉给药起效迅速、作用强大且易调控，是高血压危象首选。氯沙坦、卡托普利为口服ARB/ACEI，起效较慢，不适于需立即降压的危象；氢氯噻嗪作用温和，用于轻中度高血压；普萘洛尔降压缓慢，单独使用不适于高血压危象的紧急处理，故选硝普钠"},{"q":"青霉素最适于治疗下列哪种细菌引起的感染","o":["溶血性链球菌","肺炎克雷伯菌","铜绿假单孢菌","变形杆菌","鼠疫杆菌"],"a":0,"e":"青霉素G对革兰阳性球菌作用强，溶血性链球菌高度敏感，所致咽炎、猩红热、蜂窝织炎为其最佳适应证。肺炎克雷伯菌、变形杆菌、铜绿假单胞菌均为革兰阴性杆菌，青霉素G基本无效，需选头孢菌素或氨基糖苷类。鼠疫杆菌为革兰阴性杆菌，治疗首选链霉素，青霉素G不适用，故只有溶血性链球菌感染最适合青霉素治疗"},{"q":"使用吗啡治疗能产生欣快与觅药行为，在脑内主要激活的神经通路是","o":["5-HT能神经通路","Ach能神经通路","NA能神经通路","Glu能神经通路","DA能神经通路"],"a":4,"e":"吗啡激动中脑边缘系统多巴胺能神经通路，即腹侧被盖区到伏核的DA通路，增加突触间隙多巴胺，产生欣快与觅药行为，是阿片类精神依赖的神经基础。5-羟色胺能通路主要调节情绪与睡眠；胆碱能、去甲肾上腺素能通路不直接介导奖赏效应；谷氨酸能通路参与学习记忆及兴奋传递，虽与成瘾可塑性有关，但即时欣快与觅药主要靠DA能通路"},{"q":"毛果芸香碱主要用于","o":["重症肌无力","感冒发汗","心动过速","青光眼","术后腹胀"],"a":3,"e":"毛果芸香碱为M胆碱受体激动药，滴眼后激动瞳孔括约肌M受体使瞳孔缩小，拉开房角、促进房水回流、降低眼压，主要用于闭角型青光眼。重症肌无力、术后腹胀尿潴留需用胆碱酯酶抑制药新斯的明，通过增加神经肌肉接头和胃肠乙酰胆碱起作用，毛果芸香碱对骨骼肌N_M受体无激动作用。心动过速常用β阻断药，感冒发汗亦非其适应证"},{"q":"去甲肾上腺素能神经兴奋可引起","o":["心收缩力减弱","血压下降","皮肤黏膜血管收缩","支气管平滑肌收缩","骨骼肌血管收缩"],"a":2,"e":"去甲肾上腺素能神经兴奋释放去甲肾上腺素，激动皮肤黏膜血管α1受体引起血管收缩，是典型效应。心肌β1受体激动后收缩力增强而非减弱；小动脉收缩使外周阻力升高、血压上升而非下降；支气管平滑肌β2受体激动后舒张而非收缩；骨骼肌血管以β2受体为主，激动时舒张。故其余选项方向均与该神经兴奋效应相反，只有皮肤黏膜血管收缩正确"},{"q":"有关哌替啶的用途，叙述错误的是","o":["镇痛","人工冬眠","麻醉前给药","心源性哮喘","止泻"],"a":4,"e":"哌替啶为阿片类镇痛药，可用于剧烈疼痛、麻醉前给药、人工冬眠（与氯丙嗪、异丙嗪配伍）及心源性哮喘，作用与吗啡相似而成瘾性较轻。止泻并非其用途，临床止泻多用洛哌丁胺、地芬诺酯或复方樟脑酊，通过作用于肠道阿片受体减少肠蠕动；哌替啶主要用于镇痛、不用于止泻，故该叙述错误，其余四项均为其适应证"},{"q":"儿童验光配镜检查宜选用","o":["东莨菪碱","溴丙胺太林","去氧肾上腺素","阿托品","吗噻洛尔"],"a":3,"e":"儿童验光配镜需充分麻痹睫状肌以排除调节因素干扰，阿托品阻断M受体，调节麻痹作用强而持久，是儿童验光首选。东莨菪碱虽有调节麻痹作用，但主要用于抗晕动和中枢镇静；去氧肾上腺素仅激动α受体散瞳、不麻痹睫状肌，无法满足验光要求；溴丙胺太林为季铵类解痉药，主要作用于胃肠；噻吗洛尔为β阻断药、用于降眼压，均不用于验光配镜"},{"q":"胆碱能神经兴奋不能介导的生理效应是","o":["缩瞳","心率减慢","促脂肪分解","汗腺分泌增加","子宫平滑肌收缩"],"a":2,"e":"胆碱能神经兴奋释放乙酰胆碱，激动M或N受体，可使瞳孔括约肌收缩而缩瞳、抑制窦房结使心率减慢、刺激汗腺分泌（交感节后胆碱能纤维支配汗腺）、促进子宫平滑肌收缩，均属胆碱能效应。促进脂肪分解主要由交感神经释放去甲肾上腺素激动β受体、激活激素敏感性脂肪酶实现，属肾上腺素能效应，不由胆碱能神经介导"},{"q":"药物的排泄途径不包括","o":["汗腺","肾脏","胆汁","肺","肝脏"],"a":4,"e":"药物排泄指原形药或代谢物排出体外，主要途径有肾脏（最主要）、胆汁、肺（挥发性药物随呼气）、汗腺、唾液和乳汁等。肝脏是药物代谢的主要器官，将脂溶性药物转化为水溶性代谢物，但其本身不是将药物排出体外的途径；经胆汁排泄虽与肝有关，仍归属胆汁这一途径。故肝脏不属于排泄途径，本题选此"},{"q":"对青霉素G不敏感的细菌是","o":["溶血性链球菌","脑膜炎球菌","肠球菌","炭疽杆菌","破伤风杆菌"],"a":2,"e":"青霉素G对多数革兰阳性菌作用强，溶血性链球菌、炭疽杆菌、破伤风杆菌高度敏感，脑膜炎球菌也对青霉素G敏感，是流脑治疗用药之一。肠球菌对青霉素G天然不敏感，其细胞壁与青霉素结合蛋白特性使药物难以杀菌，治疗需氨苄西林或万古霉素，必要时联合氨基糖苷类，故肠球菌为本题答案"},{"q":"几乎没有抗炎作用的药物是","o":["保泰松","布洛芬","阿司匹林","对乙酰氨基酚","吡罗昔康"],"a":3,"e":"对乙酰氨基酚抑制下丘脑前列腺素合成发挥解热作用，并抑制中枢痛觉传导产生镇痛，但对外周环氧酶抑制作用弱、几乎无抗炎抗风湿作用，不能用于类风湿关节炎等炎症性疾病。保泰松、布洛芬、阿司匹林、吡罗昔康均属非甾体抗炎药，抑制外周前列腺素合成、有明确抗炎镇痛作用，可治风湿性炎症，与对乙酰氨基酚形成对比"},{"q":"铁剂治疗缺铁性贫血，说法错误的是","o":["口服1周，血中网织红细胞即可上升","2～4周后，血红蛋白明显增加","血红蛋白达正常值约需4～8周","血红蛋白正常后，应继续服用2～3个月","肌内注射吸收率高于口服吸收率"],"a":4,"e":"铁剂治疗缺铁性贫血以口服为首选，铁主要在小肠上段吸收，口服吸收率并不低于肌注，且肌注吸收不稳定、局部刺激大、可致过敏，仅在不耐受口服或需快速补铁时用，故“肌注吸收率高于口服”错误。口服后1周左右网织红细胞上升，2～4周血红蛋白明显增加，约4～8周恢复正常，正常后仍需继续服2～3个月补足储存铁，这些表述均正确"},{"q":"既能降低LDL也能降低HDL的药物是","o":["辛伐他汀","苯扎贝齐","普罗布考","考来烯胺","烟酸"],"a":2,"e":"普罗布考抑制胆固醇合成与促进排泄，降低总胆固醇和LDL-C，同时也可使HDL-C降低，是少数既降LDL又降HDL的调脂药，其抗动脉粥样硬化作用与抗氧化有关。辛伐他汀降LDL-C并轻度升高HDL-C；苯扎贝特以降低TG为主并升高HDL-C；考来烯胺降LDL-C、对HDL无明显降低；烟酸则升高HDL-C，均不符合两者同时降低的特点"},{"q":"鲑降钙素的特点是","o":["可以口服治疗骨质疏松症","不可以皮下给药","主要靶器官是小肠","与破骨细胞结合抑制骨吸收","升高血浆钙离子浓度"],"a":3,"e":"鲑降钙素作用于破骨细胞特异性受体，抑制破骨细胞活性与骨吸收、减少骨钙释放，从而降低血钙，用于骨质疏松、高钙血症和Paget病。“可以口服”错误，其为多肽、口服被消化破坏，需注射或鼻喷；“不可皮下给药”错误，临床可皮下或肌注；主要靶器官是小肠也不对，其核心作用在骨；它降低而非升高血钙，其余选项均不成立"},{"q":"对肝素的正确描述是","o":["可抑制多种凝血因子的活化","可以口服给药","用于DIC的晚期治疗","仅在体内有抗凝作用","可抑制血小板聚集"],"a":0,"e":"肝素与抗凝血酶Ⅲ结合后增强其活性，可抑制凝血酶及因子Ⅸa、Ⅹa、Ⅺa、Ⅻa等多种凝血因子活化，抗凝强大且体内体外均有效。“可以口服”错误，肝素为多糖、口服被消化破坏，须注射；“用于DIC晚期”不对，肝素用于DIC早期高凝期，晚期出血明显时禁用；“仅在体内有抗凝作用”错误，体外亦有效；抑制血小板聚集主要归抗血小板药，肝素核心是抗凝血酶Ⅲ介导的因子抑制"},{"q":"下列哪个抗癫痫药物起效缓慢，使用时需逐渐加量","o":["苯妥英钠","苯巴比妥","地西泮","乙琥胺","丙戊酸钠"],"a":0,"e":"苯妥英钠口服吸收慢、个体差异大，体内按零级动力学代谢，血药浓度与剂量不成比例、易蓄积中毒，故需小剂量开始逐渐加量、起效缓慢，用于癫痫大发作维持治疗。苯巴比妥起效较快、有明显镇静作用；地西泮静注起效迅速，是癫痫持续状态首选；乙琥胺主用于失神发作，丙戊酸钠为广谱抗癫痫药，均不以起效慢、需缓慢加量为突出特点"},{"q":"病原体或肿瘤细胞对反复应用的化疗药物的敏感性降低，称为","o":["耐受性","耐药性","精神依赖性","生理依赖性","停药症状"],"a":1,"e":"耐药性指病原体或肿瘤细胞反复接触药物后敏感性降低，是化疗失败的重要原因，可由基因突变、外排泵增强、酶改变等机制产生，主体是病原体或肿瘤细胞。耐受性是机体连续多次用药后反应性降低、需加大剂量维持效应，主体是机体，二者主体不同不可混淆。精神依赖、生理依赖均为反复用药的强迫状态或戒断反应，停药症状为停药后的反应，均与敏感性降低无关"},{"q":"防治静脉血栓的口服药是","o":["链激酶","尿激酶","肝素","华法林","枸橼酸钠"],"a":3,"e":"华法林为香豆素类口服抗凝药，拮抗维生素K、抑制依赖维生素K的凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，起效慢但持久，可口服防治静脉血栓栓塞性疾病。链激酶、尿激酶为纤溶药，需静脉给药用于急性溶栓；肝素抗凝迅速但须注射、口服无效；枸橼酸钠络合钙离子体外抗凝，仅用于血液保存，均非口服防治静脉血栓药"},{"q":"药物的首过消除是指","o":["肾脏对体内药物的首次排泄","肠黏膜及肝脏对药物的转化","药物与血浆蛋白的牢固结合","胃酸对药物化学结构的破坏","皮肤给药后药物的吸收作用"],"a":1,"e":"首过消除指口服药物经胃肠道吸收后由门静脉首先入肝，部分在肠黏膜及肝脏被代谢灭活，使进入体循环的有效药量减少、生物利用度降低；舌下、直肠给药可部分避开。肾脏排泄属消除但非“首过”；药物与血浆蛋白结合是可逆暂存、不被灭活；胃酸破坏属吸收前的化学降解；皮肤给药经皮吸收不经门脉肝脏，均不符合首过消除定义"},{"q":"下列哪种药通过抑制蛋白质合成而起抗肿瘤作用","o":["喜树碱","L-门冬酰胺酶","博来霉素","羟基脲","氮芥"],"a":1,"e":"L-门冬酰胺酶水解血清中的门冬酰胺，使肿瘤细胞尤其急性淋巴细胞白血病细胞缺乏合成蛋白质必需的氨基酸，从而抑制其蛋白质合成而抗肿瘤。喜树碱抑制拓扑异构酶Ⅰ、干扰DNA复制；博来霉素与DNA结合引起链断裂；羟基脲抑制核苷酸还原酶、阻碍DNA合成；氮芥为烷化剂直接破坏DNA，均非通过抑制蛋白质合成起效"},{"q":"伴糖尿病肾病的高血压患者最好选用","o":["可乐定","卡托普利","哌唑嗪","氢氯噻嗪","硝普钠"],"a":1,"e":"卡托普利为ACE抑制药，扩张肾小球出球小动脉、降低肾小球内高压高滤过，减少蛋白尿、延缓肾功能恶化，并改善胰岛素敏感性，是伴糖尿病肾病高血压的首选。可乐定、哌唑嗪虽降压但无明确肾保护；氢氯噻嗪大剂量可影响糖代谢和电解质；硝普钠需静脉给药、用于高血压危象，不适于长期口服治疗，故选卡托普利"},{"q":"下列哪种药物只激动N受体","o":["乙酰胆碱","毛果芸香碱","毒蕈碱","卡巴胆碱","烟碱"],"a":4,"e":"烟碱即尼古丁，为N胆碱受体的选择性激动药，可激动神经节N1受体和骨骼肌终板N_M受体，小剂量兴奋、大剂量阻断，不激动M受体。乙酰胆碱同时激动M和N受体、无选择性；毛果芸香碱、毒蕈碱为M受体选择性激动药，对N几乎无作用；卡巴胆碱为完全拟胆碱药、兼有M与N激动作用，均不符合只激动N受体的要求"},{"q":"强心苷对下列何种原因所致的心衰不仅疗效差且易中毒","o":["高血压性心脏病","甲亢风湿性心脏病","房颤伴心功能不全贫血","肺源性心脏病","冠状动脉粥样硬化性心脏病"],"a":3,"e":"强心苷对肺源性心脏病心衰疗效差且易中毒，因常伴严重缺氧和二氧化碳潴留，心肌对强心苷敏感性显著增高，治疗量与中毒量接近，易致心律失常，且以右心衰为主、收缩功能改善受限。高血压性心脏病、风湿性心脏病心衰疗效较好；严重贫血、甲亢所致心衰因病因未去除疗效也差，但从易中毒角度肺源性心脏病最典型"},{"q":"强心苷疗效最好的适应证是","o":["肺源性心脏病引起的心衰","严重二尖瓣病引起的心衰","严重贫血引起的心衰","甲状腺功能亢进引起的心衰","高血压性心衰伴有房颤"],"a":4,"e":"强心苷疗效最好的适应证是高血压性或风湿性心脏病所致心衰伴心房颤动，正性肌力改善心衰，同时减慢房室传导、控制快速心室率，双重获益。肺源性心脏病伴缺氧者易中毒且疗效差；严重二尖瓣狭窄所致心衰因机械梗阻难以改善；严重贫血、甲亢所致心衰为高排量状态，病因未纠正前疗效不佳，均非最佳适应证"},{"q":"贝特类降低VLDL的机制是","o":["增加脂蛋白脂酶活性","抑制脂肪分解","抑制肝脏TG酯化","使肝脏合成Apo B增加","减少Apo A的基因表达"],"a":0,"e":"贝特类激活过氧化物酶体增殖物激活受体α，上调脂蛋白脂酶基因表达、增强其活性，加速VLDL中甘油三酯水解，使VLDL与TG下降并升高HDL-C。抑制脂肪分解是烟酸的作用，减少游离脂肪酸入肝间接降低VLDL生成。贝特类不使肝脏合成载脂蛋白B增加、反而促进降解；对载脂蛋白A是增加表达而非减少，后三项方向均不符"},{"q":"通过阻断H2受体减少胃酸分泌的药物是","o":["苯海拉明","哌仑西平","阿托品","雷尼替丁","阿司咪唑"],"a":3,"e":"雷尼替丁为H2受体阻断药，竞争性阻断胃壁细胞H2受体，抑制组胺刺激的胃酸分泌，也部分抑制胃泌素和乙酰胆碱引起的酸分泌，用于消化性溃疡。苯海拉明、阿司咪唑为H1受体阻断药、主要抗过敏；哌仑西平选择性阻断M1受体抑酸，作用于胆碱能通路；阿托品为非选择性M阻断药，抑酸同时致口干、视力模糊，均非经H2受体起作用"},{"q":"哌仑西平抑制胃酸分泌的主要作用是阻断或抑制","o":["M1受体","H2受体","胃泌素受体","H1受体","质子泵"],"a":0,"e":"哌仑西平为选择性M1胆碱受体阻断药，阻断胃壁细胞及胃窦G细胞M1受体，抑制乙酰胆碱介导的胃酸分泌并减少胃泌素释放，用于消化性溃疡，对唾液腺、瞳孔影响较小。H2受体阻断药以雷尼替丁、法莫替丁为代表；胃泌素受体拮抗药为丙谷胺；H1阻断药如苯海拉明、阿司咪唑主要抗过敏；奥美拉唑抑制H⁺-K⁺-ATP酶、抑酸最强，均非其靶点"},{"q":"抗铜绿假单胞菌作用最强的头孢菌素是","o":["头孢克洛","头孢他啶","头孢孟多","头孢噻吩","头孢氨苄"],"a":1,"e":"头孢他啶为第三代头孢菌素，对革兰阴性杆菌尤其铜绿假单胞菌抗菌活性强，是抗该菌作用最强的头孢菌素，常用于其所致严重感染。头孢噻吩、头孢氨苄为第一代，主要抗革兰阳性菌、对铜绿假单胞菌无效；头孢克洛、头孢孟多为第二代，谱较第一代扩大但对铜绿假单胞菌仍无可靠活性，故选头孢他啶"},{"q":"有机磷酸农药中毒后，碘解磷定解救无效的是","o":["内吸磷","马拉硫磷","对硫磷","敌百虫","乐果"],"a":4,"e":"碘解磷定为胆碱酯酶复活药，对对硫磷、内吸磷、马拉硫磷等形成的磷酰化酶复活效果较好，可恢复酶活性、消除肌颤。乐果中毒时磷酰化胆碱酯酶迅速老化，且其结构含甲氧基使复活药难以恢复酶活性，故碘解磷定对乐果解救无效，主要靠阿托品对症处理。敌百虫中毒复活效果亦较差，但明确无效者为乐果，是常考特例"},{"q":"阿司匹林的抗血小板作用机制是","o":["激活环氧酶","促进血小板中PGI2的合成","促进内皮细胞中PGI2的合成","抑制内皮细胞中TXA2的合成","抑制血小板中TXA2的合成"],"a":4,"e":"阿司匹林不可逆乙酰化血小板环氧酶-1，抑制血栓素A₂合成，TXA₂是强促聚集和缩血管介质，其减少使血小板聚集受抑、预防血栓。该药是抑制而非激活环氧酶；前列环素由血管内皮合成、为抗聚集扩血管介质，阿司匹林并不促进其合成；内皮细胞主要合成PGI₂而非TXA₂，故抑制内皮TXA₂合成也不符合实际，只有抑制血小板TXA₂合成正确"},{"q":"下列药物中对支原体肺炎首选药是","o":["红霉素","利福平","磺胺嘧啶","链霉素","青霉素"],"a":0,"e":"红霉素为大环内酯类，可穿透细胞膜并抑制蛋白质合成，对无细胞壁的支原体有良好活性，是支原体肺炎尤其儿童及青霉素过敏者的首选。青霉素抑制细胞壁黏肽合成，支原体缺乏细胞壁故完全无效。磺胺嘧啶干扰叶酸合成、对支原体作用差；链霉素疗效不确切；利福平主用于结核和麻风，均非支原体肺炎首选"},{"q":"可兼治脑血管病的抗高血压药是","o":["维拉帕米","尼莫地平","尼群地平","硝苯地平","地尔硫䓬"],"a":1,"e":"尼莫地平为二氢吡啶类钙拮抗药，脂溶性高、能透过血脑屏障，选择性扩张脑血管、增加脑血流量，兼具降压和改善脑循环作用，适用于高血压合并脑血管病或预防脑血管痉挛。维拉帕米、地尔硫䓬主要作用于心脏、抑制房室传导；尼群地平、硝苯地平以扩外周血管降压为主，脑血管选择性弱，不能兼顾脑血管病，故尼莫地平适宜"},{"q":"肾上腺素扩张支气管的机理是","o":["阻断α1受体","阻断β1受体","兴奋β1受体","兴奋β2受体","兴奋多巴胺受体"],"a":3,"e":"肾上腺素激动支气管平滑肌β2受体，激活腺苷酸环化酶、升高cAMP，使平滑肌松弛而解除支气管痉挛，是其平喘主要机制。肾上腺素本身激动α、β受体，阻断α1受体并非其作用；β1受体主要分布于心脏、激动后加快心率增强收缩力，不直接扩张支气管；多巴胺受体激动与支气管舒张无关，平滑肌舒张靠β2受体"},{"q":"糖皮质激素诱发和加重感染的主要原因是","o":["抑制炎症反应和免疫反应、降低机体的防御能力","用量不足，无法控制症状所致","患者对激素不敏感","促使许多病原微生物繁殖所致","抑制ACTH的释放"],"a":0,"e":"糖皮质激素抗炎、免疫抑制，可抑制白细胞吞噬、抗体生成及炎症介质释放，降低机体对病原体的防御，使潜在感染扩散或诱发新感染，这是其诱发加重感染的主要原因。用量不足与感染加重机制相反；患者不敏感不解释感染风险；病原体繁殖是防御下降的结果而非机制；抑制ACTH释放属轴负反馈，与感染易感性无直接关系"},{"q":"焦虑紧张引起的失眠宜用","o":["硫喷妥钠","苯妥英钠","水合氯醛","地西泮","氯丙嗪"],"a":3,"e":"地西泮为苯二氮䓬类，小剂量即有抗焦虑、镇静催眠作用，可缓解紧张焦虑并改善睡眠，是焦虑性失眠常用药，依赖潜力较低、安全范围大。硫喷妥钠为超短效巴比妥类、作静脉麻醉或诱导；苯妥英钠为抗癫痫药、无催眠作用；水合氯醛虽催眠但刺激性强、已少用；氯丙嗪为抗精神病药，不用于单纯失眠，故选地西泮"},{"q":"将卡巴多巴与左旋多巴按1∶10剂量合用，可使左旋多巴的使用剂量减少","o":["35%","45%","55%","65%","75%"],"a":4,"e":"卡比多巴为外周多巴脱羧酶抑制剂、不能透过血脑屏障，与左旋多巴按1∶10合用时抑制其外周脱羧，使更多原形药入脑发挥作用，从而将左旋多巴用量减少约75%，并减轻外周多巴胺增多所致恶心、呕吐和心血管反应。其余比例均低于实际减少幅度，未反映复方制剂使左旋多巴剂量大幅下降的显著效果，故选75%"},{"q":"易引起二重感染的药物是","o":["青霉素","链霉素","红霉素","四环素","异烟肼"],"a":3,"e":"四环素为广谱抗生素，口服抑制肠道正常菌群，使敏感菌减少、耐药菌或真菌大量繁殖，引起二重感染如鹅口疮、假膜性肠炎，长期大剂量时尤易发生。青霉素主抗革兰阳性菌、谱较窄；链霉素、异烟肼抗菌谱更局限；红霉素虽影响肠道菌群但二重感染率远低于四环素，答题抓住广谱致菌群失调这一链条即可"},{"q":"属于繁殖期杀菌药的是","o":["青霉素类、头孢菌素类","氯霉素类、四环素类","磺胺类、喹诺酮类","氨基糖苷类、多黏菌素类","四环素类、大环内酯类"],"a":0,"e":"青霉素类、头孢菌素类均属β-内酰胺类，抑制细菌细胞壁黏肽合成，使繁殖期细菌细胞壁缺损、膨胀破裂死亡，是典型繁殖期杀菌药。氯霉素类、四环素类、大环内酯类抑制蛋白质合成，为抑菌药；磺胺类干扰叶酸合成、喹诺酮类抑制DNA回旋酶；氨基糖苷类、多黏菌素对静止期细菌亦有杀灭作用，属静止期杀菌药，均不属繁殖期杀菌药"},{"q":"高血压伴支气管哮喘的患者宜选用","o":["地高辛","普萘洛尔","维拉帕米","硝苯地平","氟桂利嗪"],"a":3,"e":"硝苯地平为二氢吡啶类钙拮抗药，通过扩张外周血管降压，对支气管平滑肌无明显收缩作用、甚至轻度舒张，故高血压伴哮喘者选用较安全。普萘洛尔非选择性阻断β受体，阻断支气管β2可诱发加重痉挛、哮喘禁用。地高辛为强心苷不用于降压；维拉帕米、地尔硫䓬降压同时抑制传导，氟桂利嗪主作用于脑血管，均非本题适宜选择"},{"q":"唑吡坦对睡眠时相的影响是","o":["对正常睡眠时相干扰少","延长NERMS第2期","缩短REMS睡眠","“反跳性”延长REMS睡眠","引起非生理性睡眠"],"a":0,"e":"唑吡坦为非苯二氮䓬类催眠药，选择性激动GABA_A受体ω1亚型，主要缩短入睡时间、减少觉醒，对正常睡眠时相结构干扰少，不明显抑制快速眼动睡眠，停药反跳轻，故该表述正确。延长非快速眼动第2期、缩短快速眼动或反跳性延长快速眼动，多见于传统苯二氮䓬类或巴比妥类，它们明显改变睡眠结构；唑吡坦产生接近生理的睡眠，非生理性睡眠之说不符"},{"q":"苯二氮卓受体阻断剂是","o":["氟马西尼","阿托品","三唑仑","硫喷妥钠","甲丙氨酯"],"a":0,"e":"氟马西尼为苯二氮䓬受体拮抗药，竞争性阻断地西泮等与GABA_A受体复合物上苯二氮䓬位点结合，迅速逆转其镇静、催眠和呼吸抑制，用于苯二氮䓬中毒解救及麻醉后催醒。阿托品为M受体阻断药；三唑仑本身是苯二氮䓬受体激动药、有催眠作用；硫喷妥钠为巴比妥类、作用于不同位点；甲丙氨酯为氨基甲酸酯类镇静药，均非苯二氮䓬受体阻断剂"},{"q":"除极化型肌松药具备下列哪项特点","o":["药后无短暂肌颤","连续用药不产生快速耐受性","过量时不导致呼吸肌麻痹","治疗量有神经节阻断作用","其中毒症状不被新斯的明解除"],"a":4,"e":"除极化型肌松药以琥珀胆碱为代表，其中毒所致呼吸肌麻痹不能用新斯的明解救，因新斯的明抑制假性胆碱酯酶、减慢琥珀胆碱水解，反而加重延长肌松。给药后先有短暂肌束颤动、连续用药产生快速耐受性、过量同样致呼吸肌麻痹，三项均与其特点相反；治疗量下该类药不阻断神经节，选项说有神经节阻断也不符，只有新斯的明不能解除正确"},{"q":"氨基糖苷类药物的不良反应，不包括","o":["耳毒性","肾毒性","再生障碍性贫血","神经肌肉麻痹","过敏反应"],"a":2,"e":"氨基糖苷类典型不良反应有耳毒性（前庭与听神经损害）、肾毒性（近曲小管损伤）、神经肌肉麻痹（阻碍接头传递、与肌松药协同）及过敏反应，链霉素过敏可致休克。再生障碍性贫血是氯霉素等抑制骨髓造血的严重反应，不属氨基糖苷类不良反应谱，故选此，答题须区分各类抗菌药特征性毒性"},{"q":"下列是胆碱酯酶复活药的是","o":["新斯的明","碘解磷定","阿托品","地美溴铵","贝胆碱"],"a":1,"e":"碘解磷定为肟类胆碱酯酶复活药，可与磷酰化胆碱酯酶的磷酰基结合、使酶恢复活性，用于有机磷酸酯类中毒解救，须早期使用以防老化。新斯的明、地美溴铵为胆碱酯酶抑制药，作用相反；阿托品为M受体阻断药，仅对抗M样症状、不能恢复酶活性；贝胆碱为胆碱受体激动药，均非胆碱酯酶复活药，只有碘解磷定符合"},{"q":"药物是","o":["专指可以治疗疾病的化学物质","能干扰细胞代谢活动的化学物质","能影响机体生理功能的物质","用以防治及诊断疾病的物质","有滋补营养、保健作用的物质"],"a":3,"e":"药物指用以防治及诊断疾病的物质，包括治疗、预防及生育控制用药，这是其完整定义。“专指治疗疾病的化学物质”过窄、遗漏预防诊断；“干扰细胞代谢的化学物质”仅部分药物的作用方式；“影响机体生理功能的物质”过泛，可将毒品、食物纳入；“有滋补营养保健作用的物质”属营养保健品，均非药物的本质规定，故选用以防治及诊断疾病的物质"},{"q":"表示药物在体内分布程度的药物代谢动力学参数是","o":["表观分布容积","曲线下面积","生物利用度","血浆半衰期","清除率"],"a":0,"e":"表观分布容积为体内药物总量与血浆药物浓度之比，反映药物在体内分布广泛程度：数值大表示广泛分布于组织、血药浓度低，数值小表示主要局限于血浆。曲线下面积反映吸收进入体循环总量；生物利用度表示吸收的相对量和速度；血浆半衰期反映消除快慢；清除率是单位时间清除药物的血浆容积、反映消除能力，均不直接表示分布程度"},{"q":"具有耳毒性的利尿药是","o":["呋塞米","氢氯噻嗪","氨苯蝶啶","螺内酯","乙酰唑胺"],"a":0,"e":"呋塞米等高效能袢利尿药可致耳毒性，表现为耳鸣、听力下降甚至永久性耳聋，机制与干扰内耳淋巴液电解质平衡、损伤毛细胞有关，与氨基糖苷类合用风险显著增加。氢氯噻嗪为噻嗪类中效利尿药，氨苯蝶啶、螺内酯为保钾利尿药，乙酰唑胺为碳酸酐酶抑制药，均无耳毒性，故本题应选呋塞米，耳毒性是其区别于其他利尿药的重要不良反应"},{"q":"诺氟沙星属于哪类化合物","o":["磺胺类","硝基呋喃类","吡喹酮类","喹诺酮类","4-氨基喹啉类"],"a":3,"e":"诺氟沙星又名氟哌酸，为第三代喹诺酮类即氟喹诺酮类抗菌药，通过抑制细菌DNA回旋酶阻碍DNA复制而杀菌，主要用于肠道、泌尿道感染。磺胺类如磺胺甲噁唑干扰叶酸合成；硝基呋喃类如呋喃妥因、吡喹酮为抗寄生虫药、4-氨基喹啉类如氯喹为抗疟药，均属不同类别，与诺氟沙星结构不符，故选喹诺酮类"},{"q":"不属于应用胰岛素后出现的不良反应的是","o":["低血糖","过敏反应","胰岛素抵抗","脂肪萎缩","头痛"],"a":4,"e":"胰岛素常见不良反应有低血糖（剂量过大或未及时进食、最常见）、过敏反应（异性蛋白致荨麻疹等）、胰岛素抵抗（长期用药敏感性下降）及注射部位脂肪萎缩或增生。头痛并非其典型不良反应，也不是药理作用的延伸，故不属于胰岛素用药后出现的不良反应，其余四项均为教材明确列出的胰岛素不良反应"},{"q":"Ⅰ类抗心律失常药物为","o":["钙通道阻滞药","钠通道阻滞药","肾上腺素受体阻滞药","选择地延长复极过程的药","钾通道开放药"],"a":1,"e":"Ⅰ类抗心律失常药即钠通道阻滞药，阻滞快钠内流而降低自律性、减慢传导，代表有奎尼丁、利多卡因、普罗帕酮，按阻滞程度又分Ⅰa、Ⅰb、Ⅰc三个亚类。钙通道阻滞药属Ⅳ类，肾上腺素受体阻断药属Ⅱ类，选择性延长复极过程药为Ⅲ类，钾通道开放药不属Ⅰ类"},{"q":"属于浓度依赖性抗菌药物，可1日给药1次的是","o":["氨苄西林","莫西沙星","头孢他啶","红霉素","氯霉素"],"a":1,"e":"莫西沙星属氟喹诺酮类，为浓度依赖性抗菌药，峰值浓度越高杀菌越强，且有较长抗菌后效应，故可每日一次给药。氨苄西林、头孢他啶为β-内酰胺类，属时间依赖性，需分次给药维持血药浓度；红霉素、氯霉素亦为时间依赖性抑菌药，均不适合一日一次"},{"q":"对α和β受体均有阻断作用的药物是","o":["阿替洛尔","吲哚洛尔","拉贝洛尔","普萘洛尔","美托洛尔"],"a":2,"e":"拉贝洛尔兼有α1和β受体阻断作用，阻断β减弱心收缩力和心率，阻断α1扩张血管，降压时不反射性加快心率。阿替洛尔、美托洛尔为选择性β1阻断药，吲哚洛尔、普萘洛尔为非选择性β阻断药，均无α受体阻断作用，仅拉贝洛尔兼具二者"},{"q":"利多卡因最适于治疗的心律失常是","o":["房性期前收缩","心房扑动","心室纤颤","心房纤颤","室上性心动过速"],"a":2,"e":"利多卡因为Ⅰb类钠通道阻滞药，选择性作用于心室肌和浦氏纤维，抑制室性自律性和异位节律，对室性期前收缩、室性心动过速及室颤有效，是防治急性心肌梗死室性心律失常的首选。房性期前收缩、房扑、房颤及室上性心动过速属室上性心律失常，利多卡因对心房作用弱，疗效差"},{"q":"吗啡抑制呼吸的作用是由于","o":["中毒引起呼吸麻痹","阻滞神经肌肉接头","拮抗Ca2＋使运动神经释放递质减少","阻断N2受体","降低呼吸中枢对CO2张力敏感性"],"a":4,"e":"吗啡激动延髓呼吸中枢阿片受体，降低呼吸中枢对血液CO2张力的敏感性，并抑制脑桥呼吸调节中枢，使呼吸变慢变浅。中毒引起呼吸麻痹、阻滞神经肌肉接头、阻断N2受体均非其作用；拮抗Ca2＋减少递质释放亦不是，吗啡主要作用于中枢"},{"q":"强心苷引起心脏毒性的原理是","o":["抑制心肌细胞膜Na＋-K＋-ATP酶","兴奋心肌细胞膜Na＋-K＋-ATP酶","增加心肌细胞内K＋","增加心肌细胞内Ca2＋","增加心肌抑制因子的形成和释放"],"a":0,"e":"强心苷与心肌细胞膜Na＋-K＋-ATP酶结合并抑制其活性，使细胞内Na＋升高，经Na＋-Ca2＋交换使细胞内Ca2＋增多，增强收缩力；过度抑制则致细胞内失钾、最大舒张电位减小，自律性增高、传导减慢而诱发心律失常。兴奋该酶、增加细胞内K＋与毒性相反；增加Ca2＋是治疗基础，非毒性原理"},{"q":"硝酸酯类舒张血管的机制是","o":["直接松弛血管平滑肌","阻断α1受体","阻滞Ca2＋通道","在平滑肌细胞及血管内皮细胞中产生NO","阻断血管平滑肌β2受体"],"a":3,"e":"硝酸酯类在血管平滑肌细胞及内皮细胞内经酶或巯基作用释放一氧化氮，NO激活鸟苷酸环化酶，升高cGMP，降低胞内Ca2＋，从而松弛血管平滑肌。直接松弛血管平滑肌未指出NO这一关键环节；阻断α1受体、阻滞Ca2＋通道、阻断β2受体均非硝酸酯类机制，故不取"},{"q":"下列哪项不是氨基糖苷类抗生素的共同特点","o":["由氨基糖分子和非糖部分的苷元结合而成","水溶性好、性质稳定","对革兰氏阳性菌具有高度抗菌活性","对革兰氏阴性需氧菌具有高度抗菌活性","可结合核糖体30S亚基"],"a":2,"e":"氨基糖苷类由氨基糖与苷元结合而成，水溶性好、性质稳定，主要对革兰阴性需氧菌高度抗菌，通过结合核糖体30S亚基抑制蛋白质合成。其对革兰阳性菌作用弱，链球菌、厌氧菌多耐药，故对革兰阳性菌高度抗菌不是其共同特点，其余各项均为氨基糖苷类通性"},{"q":"大量或久用可损伤血管内皮细胞的药物是","o":["利托君","缩宫素","麦角胺","前列腺素","垂体后叶素"],"a":2,"e":"麦角胺直接收缩血管并损伤血管内皮细胞，大量或长期使用可致内皮损伤、血栓形成和坏疽，故用于偏头痛但需限量。缩宫素、垂体后叶素主要收缩子宫和升压，无内皮损伤之突出毒性；利托君为β2激动药松弛子宫；前列腺素扩血管，均不致此不良反应"},{"q":"为预防急性高山病，下列药物可在开始攀登前24小时口服的是","o":["呋塞米","甘露醇","氢氯噻嗪","乙酰唑胺","螺内酯"],"a":3,"e":"乙酰唑胺抑制碳酸酐酶，减少房水和脑脊液生成并促进碳酸氢盐排泄，可改善高原缺氧下的脑水肿和呼吸性碱中毒，故在登山前24小时口服预防急性高山病。呋塞米、氢氯噻嗪、螺内酯主要利尿，对高山病预防无效；甘露醇为脱水剂需静脉给药，不作口服预防"},{"q":"ACEI类的药理作用不包括","o":["抑制血管紧张素转化酶，减少AngⅡ的生成","减少醛固酮的生成，降低血压，逆转心血管重构","保存缓激肽活性","增敏胰岛素受体","兴奋AT2受体"],"a":4,"e":"ACEI抑制血管紧张素转化酶，减少AngⅡ生成，从而扩血管、降压、逆转心血管重构，并使醛固酮减少；同时保存缓激肽活性，促进NO和前列环素释放，还能增敏胰岛素受体。ACEI并不兴奋AT2受体，AngⅡ生成减少后AT1、AT2激动均减弱，此项不属于其药理作用"},{"q":"毛果芸香碱的不良反应不包括","o":["加重哮喘","恶心呕吐","呼吸困难","视物模糊","血压上升"],"a":4,"e":"毛果芸香碱为M胆碱受体激动药，全身吸收后激动腺体M受体使分泌增加，激动支气管平滑肌M受体致支气管收缩、呼吸困难并加重哮喘，激动眼M受体致瞳孔缩小、视物模糊；其扩血管作用使血压下降而非上升，故血压上升不属于其不良反应"},{"q":"子痫患者使用硫酸镁治疗后产生呼吸循环抑制，此时应给予何种药物对抗","o":["KCl","NaCl","CaCl2","MgCl2","AlCl3"],"a":2,"e":"硫酸镁过量时血镁升高，抑制呼吸中枢和心肌，钙离子与镁离子竞争结合位点，可迅速对抗镁引起的呼吸循环抑制，故用氯化钙静脉注射解救。KCl、NaCl、MgCl2不能拮抗镁毒性，反可加重；AlCl3无此用途，唯钙剂为特效对抗药"},{"q":"体液的pH影响药物的转运及分布，是由于它改变了药物的","o":["水溶性","脂溶性","pKa","解离度","溶解度"],"a":3,"e":"体液pH通过改变弱酸、弱碱性药物的解离度影响其转运和分布：解离型脂溶性低、不易跨膜，非解离型脂溶性高、易透膜。药物的pKa是固有常数，不随pH改变；水溶性、脂溶性和溶解度是解离度变化的结果而非pH直接改变的参数，故本题为解离度"},{"q":"异烟肼不具备的优点是","o":["疗效高","穿透力强","易透入细胞内，作用于被吞噬的结核杆菌","无肝毒性","口服吸收快而完全"],"a":3,"e":"异烟肼疗效高、穿透力强，口服吸收快而完全，易透入细胞内杀灭被吞噬的结核杆菌，是结核病首选药；但其代谢物乙酰肼可致肝损害，肝毒性明显，快代谢型者更易发生，故无肝毒性不是其优点。其余各项均为异烟肼确实具备的特点"},{"q":"下列关于阿司匹林加重出血倾向的描述，错误的是","o":["阿司匹林能不可逆地抑制环氧化酶","对血小板合成TXA2有强大而持久的抑制作用","对血管内皮合成PGI2有强大而持久的抑制作用","大剂量阿司匹林可抑制凝血酶原的形成","手术患者术前1周应停用阿司匹林"],"a":2,"e":"阿司匹林不可逆抑制血小板环氧化酶，持久抑制TXA2合成而抗血小板聚集，大剂量还抑制凝血酶原形成，术前一周需停药。但它对血管内皮PGI2合成的抑制是可逆且短暂的，因内皮细胞可重新合成环氧酶，故强大而持久抑制PGI2的表述错误，为本题答案"},{"q":"铁剂用于治疗","o":["溶血性贫血","再生障碍性贫血","小细胞低色素性贫血","巨幼细胞贫血","恶性贫血"],"a":2,"e":"铁是合成血红蛋白的原料，缺铁导致小细胞低色素性贫血，补铁可纠正，故铁剂专用于此。溶血性贫血、再生障碍性贫血并非缺铁；巨幼细胞贫血和恶性贫血由叶酸或维生素B12缺乏引起，属大细胞性贫血，需补叶酸或B12，用铁剂无效"},{"q":"具有对抗醛固酮而引起利尿作用的药物是","o":["呋塞米","氢氯噻嗪","螺内酯","氢苯蝶啶","乙酰唑胺"],"a":2,"e":"螺内酯结构与醛固酮相似，竞争性拮抗醛固酮受体，抑制远曲小管和集合管的Na＋-K＋交换，产生保钾利尿作用，故为对抗醛固酮的利尿药。呋塞米抑制髓袢升支粗段Na＋-K＋-2Cl－转运；氢氯噻嗪抑制远曲小管Na＋-Cl－转运，均不拮抗醛固酮"},{"q":"利福平、异烟肼、吡嗪酰胺均可引起哪种不良反应","o":["胃肠道刺激症状","激活肝药酶","视神经炎","肝损害","周围神经炎"],"a":3,"e":"利福平、异烟肼、吡嗪酰胺均为一线抗结核药，三者都有不同程度肝毒性，联用时肝损害叠加，需监测肝功能。利福平是肝药酶诱导剂，异烟肼、吡嗪酰胺无此作用；视神经炎主要见于乙胺丁醇，周围神经炎见于异烟肼，胃肠刺激并非三者共有的突出不良反应"},{"q":"下列离子通道中，其激活与突触神经递质的释放有关的是","o":["电压依赖性Na+通道","电压依赖性Ca2+通道","配体门控性Ca2+通道","Ca2+依赖性K+通道","配体门控性Cl-通道"],"a":1,"e":"突触前膜去极化使电压依赖性Ca2＋通道开放，Ca2＋内流触发突触小泡与膜融合并释放神经递质，是递质释放的关键。电压依赖性Na＋通道参与动作电位去极化而非直接触发释放；配体门控Ca2＋通道、Ca2＋依赖性K＋通道及配体门控Cl－通道均不介导此过程"},{"q":"奥美拉唑是","o":["H2受体阻断剂","H＋-K＋-ATP酶抑制剂","M受体阻断剂","胃泌素受体阻断剂","Na＋-K＋-ATP酶抑制剂"],"a":1,"e":"奥美拉唑在胃壁细胞酸性环境中活化，不可逆抑制H＋-K＋-ATP酶，阻断胃酸分泌的最后环节，抑酸强而持久。H2受体阻断剂是西咪替丁等；M受体阻断剂为阿托品类；胃泌素受体阻断剂非奥美拉唑；Na＋-K＋-ATP酶抑制剂为强心苷，均与其机制不符"},{"q":"糖皮质激素类药物对血液和造血系统的作用是","o":["血小板减少","使红细胞与血红蛋白减少","使中性粒细胞减少","刺激骨髓造血机能","淋巴细胞增加"],"a":3,"e":"糖皮质激素刺激骨髓造血，使红细胞、血红蛋白、血小板及中性粒细胞增多，淋巴细胞、嗜酸性粒细胞减少。故使红细胞与血红蛋白减少、使中性粒细胞减少、淋巴细胞增加均与事实相反；血小板不减少，本题唯一正确的是刺激骨髓造血机能"},{"q":"下列药物中口服生物利用度最低的是","o":["头孢拉定","头孢氨苄","氨苄西林","阿莫西林","青霉素G"],"a":4,"e":"青霉素G在胃酸中极不稳定，口服易被破坏，生物利用度最低，故一般注射给药。头孢拉定、头孢氨苄为耐酸头孢菌素，口服吸收良好；氨苄西林、阿莫西林耐酸且口服吸收好，其中阿莫西林吸收优于氨苄西林，均远高于青霉素G"},{"q":"下列药物中易通过血脑屏障的是","o":["异丙托溴铵","东莨菪碱","山莨菪碱","溴甲东莨菪碱","索利那新"],"a":1,"e":"东莨菪碱脂溶性高，易透过血脑屏障，中枢镇静作用强，可用于晕动病和帕金森病。异丙托溴铵、溴甲东莨菪碱为季铵盐，极性大不易入脑；山莨菪碱中枢作用弱；索利那新为M3阻断药，主要用于膀胱，透过血脑屏障能力均不及东莨菪碱"},{"q":"下列哪种药物不是镇静催眠药","o":["卡马西平","奥沙西泮","水合氯醛","甲丙氨酯","三唑仑"],"a":0,"e":"卡马西平为抗癫痫药，主要阻滞钠通道用于癫痫和三叉神经痛，不属镇静催眠药。奥沙西泮、三唑仑为苯二氮䓬类，水合氯醛为醛类，甲丙氨酯为氨基甲酸酯类，均无抗癫痫定位而用于镇静催眠，故本题答案为卡马西平"},{"q":"增加左旋多巴抗帕金森病疗效，减少不良反应的药物是","o":["卡比多巴","维生素B6","利舍平","苯乙肼","丙胺太林"],"a":0,"e":"卡比多巴为外周多巴胺脱羧酶抑制剂，不能透过血脑屏障，与左旋多巴合用可抑制其在外周转变为多巴胺，使更多左旋多巴进入中枢，增效并减少外周不良反应。维生素B6是该脱羧酶辅基，会加速外周脱羧而降低疗效；利舍平耗竭多巴胺，苯乙肼、丙胺太林无此配伍价值"},{"q":"青霉素G过敏的患者，G＋菌感染时可选用","o":["链霉素","头孢菌素","红霉素","氨苄西林","多黏菌素"],"a":2,"e":"青霉素G过敏者禁用青霉素类及头孢菌素（有交叉过敏），G＋菌感染可改用红霉素等大环内酯类。头孢菌素与青霉素有部分交叉过敏，不宜选用；氨苄西林属青霉素类禁用；链霉素、多黏菌素主要针对G－菌，对G＋菌感染疗效差，故红霉素最合适"},{"q":"影响胆固醇吸收的药物是","o":["普罗布考","考来烯胺","洛伐他汀","烟酸","苯扎贝特"],"a":1,"e":"考来烯胺为胆汁酸螯合剂，在肠道与胆汁酸结合阻断其重吸收，促使肝脏用胆固醇合成胆汁酸，从而降低血胆固醇，故属影响胆固醇吸收药。洛伐他汀抑制HMG-CoA还原酶减少合成；烟酸、苯扎贝特主要降甘油三酯；普罗布考以抗氧化降脂为主，均非影响吸收"},{"q":"干扰皮质醇及皮质酮生物合成的皮质激素抑制剂是","o":["美替拉酮","ACTH","氢化可的松","去氧皮质酮","曲安西龙"],"a":0,"e":"美替拉酮抑制11β-羟化酶，阻断皮质醇和皮质酮的生物合成，可用于库欣综合征及肾上腺皮质功能检查。ACTH促进皮质合成，氢化可的松、曲安西龙本身是糖皮质激素，去氧皮质酮为盐皮质激素，均不抑制合成，故只有美替拉酮符合"},{"q":"能补充纹状体中多巴胺的药物是","o":["多巴胺","卡比多巴","左旋多巴","苯海索","金刚烷胺"],"a":2,"e":"左旋多巴是多巴胺前体，可透过血脑屏障进入脑内，经多巴脱羧酶转变为多巴胺，补充纹状体多巴胺而抗帕金森病。多巴胺本身不能透过血脑屏障；卡比多巴为外周脱羧酶抑制剂，单用无效；苯海索为抗胆碱药；金刚烷胺促多巴胺释放，均非直接补充"},{"q":"糖皮质激素抗炎作用机制不包括","o":["对抗细胞因子介导的炎症","直接收缩血管，减少渗出","抑制炎性介质介导的炎症","抑制NO介导的炎症","诱导脂皮素-1的生成"],"a":1,"e":"糖皮质激素抗炎通过诱导脂皮素-1抑制磷脂酶A2，减少白三烯等炎性介质，并抑制细胞因子、NO介导的炎症反应。其降低血管通透性是炎症介质受抑的继发结果，并非直接收缩血管，故该项不属于其机制；其余各项均为明确机制"},{"q":"胃肠反应较轻的解热镇痛抗炎药是","o":["阿司匹林","保泰松","吲哚美辛","布洛芬","甲芬那酸"],"a":3,"e":"布洛芬对COX的抑制相对均衡，胃肠道不良反应较阿司匹林轻，患者耐受性好。阿司匹林直接刺激胃黏膜并抑制胃黏膜PG保护；吲哚美辛、保泰松胃肠反应重，保泰松还可致水钠潴留和骨髓抑制；甲芬那酸亦有明显胃肠刺激，故布洛芬胃肠反应较轻"},{"q":"解磷定对有机磷中毒症状作用最明显的是","o":["大小便失禁","视物不清","骨骼肌震颤及麻痹","血压下降","中枢神经兴奋"],"a":2,"e":"解磷定为胆碱酯酶复活剂，能恢复被有机磷抑制的胆碱酯酶活性，对烟碱样（N样）症状如骨骼肌震颤、肌无力麻痹效果最明显。大小便失禁、视物不清、血压下降属毒蕈碱样（M样）症状，主要靠阿托品对抗；中枢神经兴奋需中枢性解救，解磷定对之较弱"},{"q":"关于甘露醇的描述不正确的是","o":["不良反应以水、电解质紊乱最常见","体内不被代谢","不易通过毛细血管","提高血浆渗透压","易被肾小管重吸收"],"a":4,"e":"甘露醇为多元醇，体内不被代谢，不易通过毛细血管进入组织，静脉给药后提高血浆渗透压而脱水，且不易被肾小管重吸收，得以在肾小管形成高渗而利尿。易被肾小管重吸收与甘露醇特性相反；水、电解质紊乱确为其常见不良反应，其余描述均正确"},{"q":"哪项不是苯妥英钠的不良反应","o":["胃肠反应","齿龈增生","过敏反应","共济失调","肾脏严重损害"],"a":4,"e":"苯妥英钠常见胃肠反应，长期用致齿龈增生，可见过敏反应，剂量过大出现共济失调、眼球震颤等小脑毒性；它主要经肝代谢，不引起严重肾损害。故肾脏严重损害不是其不良反应，其余均为苯妥英钠已知的不良反应"},{"q":"不直接引起药效的药物是","o":["经肝脏代谢的药物","与血浆蛋白结合的药物","在血循环的药物","达到膀胱的药物","不被肾小管重吸收的药物"],"a":1,"e":"药物与血浆蛋白结合后形成结合型，分子变大不能跨膜转运，也暂时失去药理活性，只有游离型才能分布到组织发挥药效。经肝脏代谢、在血循环、到达膀胱或不被肾小管重吸收的药物，均可有游离形式存在或最终产生效应，故结合型药物不直接引起药效"},{"q":"口服后药物在皮肤、毛发及指（趾）甲等处含量较高的抗真菌药有","o":["两性霉素B","制霉菌素","水杨酸","灰黄霉素","特比萘芬"],"a":3,"e":"灰黄霉素口服后沉积于皮肤、毛发和指（趾）甲的角蛋白中，抑制浅表真菌，用于头癣、体癣、甲癣。两性霉素B、制霉菌素为多烯类，主要抗深部真菌且口服吸收差；水杨酸为外用角质溶解剂；特比萘芬虽也用于甲癣，但以角蛋白结合蓄积为特点的是灰黄霉素"},{"q":"强心苷中毒所致的室性期前收缩最宜采用的药物是","o":["利多卡因","阿托品","普鲁帕酮","奎尼丁","胺碘酮"],"a":0,"e":"强心苷中毒引起的室性心律失常如室性期前收缩、室性心动过速，首选利多卡因，亦可改用苯妥英钠。阿托品用于中毒所致缓慢性心律失常和房室传导阻滞，不用于室性快速心律失常；普罗帕酮、奎尼丁、胺碘酮均可加重传导抑制，不宜选用"},{"q":"以下哪个药物属于国内自主研发的抗阿尔茨海默病的药物","o":["左旋多巴","加兰他敏","多奈哌齐","石杉碱甲","利斯的明"],"a":3,"e":"石杉碱甲是从我国石杉科植物中提取的高效可逆性胆碱酯酶抑制剂，能改善阿尔茨海默病患者认知功能，为我国自主研发。多奈哌齐、加兰他敏、利斯的明虽也用于AD，但均为国外研制；左旋多巴为抗帕金森病药，与AD治疗无关"},{"q":"小剂量阿托品即可引起的药理作用是","o":["血管扩张","平滑肌松弛","扩瞳","腺体分泌减少","心率加快"],"a":3,"e":"阿托品阻断M受体，各组织敏感性不同，腺体（唾液腺、汗腺）最敏感，小剂量即抑制分泌；瞳孔扩大、平滑肌松弛、心率加快需较大剂量，血管扩张更需大剂量且机制与阻断M受体无关。故小剂量最先出现的是腺体分泌减少"},{"q":"组胺H1受体阻断药不能治疗的疾病是","o":["晕动病","变态反应性疾病","过敏性休克","失眠","过敏性鼻炎"],"a":2,"e":"过敏性休克以血压骤降和喉头水肿为特征，须立即用肾上腺素收缩血管、升高血压并缓解支气管痉挛，H1受体阻断药仅能拮抗组胺引起的皮肤黏膜症状，不能挽救休克，故不能治疗。晕动病、变态反应性疾病、失眠、过敏性鼻炎均为H1阻断药适用范围"},{"q":"关于α受体阻断药体内过程的描述正确的是","o":["酚妥拉明生物利用度高","酚妥拉明肌内注射作用维持时间长达数小时","酚苄明脂溶性高，作用持久","酚苄明常作肌内注射或皮下注射","妥拉唑林以口服给药为主"],"a":2,"e":"酚苄明脂溶性高，与α受体共价结合，作用强而持久，一次给药可维持数日。酚妥拉明生物利用度低且肌注维持时间短；酚苄明刺激性强，不作肌注或皮下注射，主要口服或静脉；妥拉唑林以口服或局部给药为主，并非以口服为唯一主要途径。故酚苄明描述正确"},{"q":"下列哪种不是华法林的禁忌证","o":["心房颤动患者","消化性溃疡活动期","严重高血压","对华法林过敏患者","血友病患者"],"a":0,"e":"华法林为维生素K拮抗剂，用于防治血栓栓塞，心房颤动患者需抗凝预防脑栓塞，正是其适应证而非禁忌。消化性溃疡活动期、严重高血压有出血风险，血友病为凝血障碍，对华法林过敏者均属禁忌，不宜使用"},{"q":"通过利尿发挥降压作用的药物是","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":4,"e":"氢氯噻嗪为噻嗪类利尿药，早期通过排钠利尿减少血容量降压，长期则降低血管平滑肌对缩血管物质的反应性，是常用基础降压药。可乐定、美卡拉明为中枢性或神经节阻断降压药，利舍平耗竭递质，卡托普利抑制ACE，均非以利尿为主要机制"},{"q":"氨甲苯酸的作用机制为","o":["抗血小板聚集","激活纤溶酶原","激活凝血酶","竞争性对抗纤溶酶原激活因子","灭活凝血酶"],"a":3,"e":"氨甲苯酸为抗纤溶药，竞争性抑制纤溶酶原激活因子，使纤溶酶原不能转为纤溶酶，从而抑制纤维蛋白溶解而止血，用于纤溶亢进所致出血。抗血小板聚集是阿司匹林作用；激活纤溶酶原、激活凝血酶、灭活凝血酶分别为溶栓药、凝血药和抗凝药机制，均不符"},{"q":"能竞争性阻断NM受体的药物是","o":["筒箭毒碱","阿托品","乙酰胆碱","琥珀胆碱","酚妥拉明"],"a":0,"e":"筒箭毒碱为非去极化型肌松药，竞争性阻断骨骼肌终板膜NM受体，拮抗乙酰胆碱的除极化作用而致肌松，可被新斯的明解救。阿托品阻断M受体；乙酰胆碱激动NM受体；琥珀胆碱为去极化型肌松药，激动受体持续去极化；酚妥拉明阻断α受体，均不竞争NM受体"},{"q":"关于硝酸甘油的药理作用正确的是","o":["收缩静脉","降低回心血量","减慢心率","增加室壁肌张力","增加前负荷"],"a":1,"e":"硝酸甘油扩张静脉，使血液滞留于外周静脉，回心血量减少，降低左室前负荷和室壁张力，从而降低心肌耗氧量。它并不收缩静脉而是扩张；反射性心率加快而非减慢；降低室壁肌张力而非增加；前负荷是降低而非增加，故仅降低回心血量正确"},{"q":"强心苷治疗房颤的机制主要是","o":["减慢房室传导","缩短心房有效不应期","抑制窦房结","降低浦氏纤维自律性","降低心室率"],"a":0,"e":"强心苷兴奋迷走神经并直接抑制房室结，减慢房室传导，使心房颤动时过多冲动不能下传心室，从而减慢心室率、改善循环。它并不转复房颤心律；缩短心房不应期、抑制窦房结、降低浦氏纤维自律性均非其主要机制；降低心室率是结果，机制在于减慢传导"},{"q":"低温麻醉需要配合进行降温的药物是","o":["氯丙嗪","左旋多巴","琥珀胆碱","芬太尼","氟哌利多"],"a":0,"e":"氯丙嗪抑制下丘脑体温调节中枢，使体温调节失灵，体温随环境温度下降，配合物理降温用于低温麻醉和人工冬眠。左旋多巴抗帕金森病；琥珀胆碱为肌松药；芬太尼为镇痛药；氟哌利多为抗精神病药，均无降低体温调节的作用"},{"q":"氨苯喋啶的利尿作用机制是","o":["抑制K＋-Na＋-2Cl－共同转运系统","抑制Na＋-K＋转运系统","拮抗醛固酮","抑制碳酸酐酶","抑制远曲小管及集合管对NaCl的重吸收"],"a":1,"e":"氨苯蝶啶直接抑制远曲小管和集合管上皮的Na＋通道，减少Na＋重吸收并抑制Na＋-K＋交换，产生保钾利尿，故属抑制Na＋-K＋转运系统。抑制Na＋-K＋-2Cl－共同转运是呋塞米；拮抗醛固酮是螺内酯；抑制碳酸酐酶是乙酰唑胺；抑制NaCl重吸收表述笼统，本题选抑制Na＋-K＋转运系统"},{"q":"与阿托品阻断M受体无关的药理作用是","o":["扩大瞳孔","松弛内脏平滑肌","加快心率","扩张血管","抑制腺体分泌"],"a":3,"e":"阿托品扩张血管主要是大剂量时直接松弛血管平滑肌，与阻断M受体无关，因血管平滑肌虽有M受体但无胆碱能神经支配。扩大瞳孔、松弛内脏平滑肌、加快心率、抑制腺体分泌均是其阻断M受体的直接结果，故扩血管为无关作用"},{"q":"可引起金鸡纳反应的抗心律失常药是","o":["奎宁","胺碘酮","奎尼丁","利多卡因","多非利特"],"a":2,"e":"奎尼丁为Ⅰa类钠通道阻滞药，过量或久用可引起金鸡纳反应，表现为耳鸣、听力减退、视力模糊、神志不清等，因其为奎宁的异构体而得名。胺碘酮主要致肺纤维化和甲状腺功能异常；利多卡因、多非利特无此反应；奎宁虽也可致金鸡纳反应但主要作抗疟药，本题抗心律失常药为奎尼丁"},{"q":"以下容易造成二重感染的广谱抗菌药物是","o":["氯霉素","红霉素","克拉维酸","甲氧苄啶","链霉素"],"a":0,"e":"氯霉素为广谱抑菌药，可抑制肠道正常菌群，使耐药菌或真菌大量繁殖引起二重感染。红霉素、克拉维酸、甲氧苄啶、链霉素抗菌谱较窄或主要作用于特定菌群，二重感染风险远低于氯霉素；四环素类亦易致二重感染，但本题选项中氯霉素最典型"},{"q":"硝酸甘油抗心绞痛的主要作用原理是","o":["收缩冠状动脉，降低心肌自身负荷","减慢心率，降低心肌耗氧量","减少NO对心肌的损伤","扩张外周血管，降低心脏负荷和心肌耗氧量","降低血压，反射性兴奋交感神经改善心肌供血"],"a":3,"e":"硝酸甘油扩张外周静脉和小动脉，减少回心血量、降低前负荷，并降低外周阻力减轻后负荷，使心室壁张力和心肌耗氧量下降，从而缓解心绞痛；同时扩张冠状动脉增加缺血区供血。它不是收缩冠脉，也不直接减慢心率；NO是其作用介质而非被减少；反射性交感兴奋是扩血管后的副作用，非治疗原理"},{"q":"全身麻醉前给予阿托品的目的是","o":["镇静","增强麻醉药的作用","减少患者对术中的不良刺激的记忆","减少呼吸道腺体分泌","松弛骨骼肌"],"a":3,"e":"全身麻醉药和气管插管可刺激呼吸道腺体分泌，阿托品阻断M受体抑制唾液和支气管腺体分泌，保持呼吸道通畅、防止误吸和吸入性肺炎。阿托品无镇静作用，不增强麻醉药效能，也不能减少术中记忆；松弛骨骼肌需肌松药，均非其给药目的"},{"q":"腺垂体分泌的FSH、LH，可使下丘脑的GnRH释放减少，这一过程被称为","o":["长反馈","短反馈","超短反馈","正反馈","允许作用"],"a":1,"e":"腺垂体分泌的FSH、LH经血流反馈作用于下丘脑，抑制GnRH释放，因反馈信息来自腺垂体这一较近环节，故称短反馈。长反馈是性腺激素对下丘脑和垂体的反馈；超短反馈为下丘脑激素对自身的反馈；正反馈如雌激素诱发LH峰；允许作用指激素间的协同，均不符"},{"q":"灰黄霉素对哪种真菌病无效","o":["甲癣","牛皮癣","头癣","体癣","深部真菌病"],"a":4,"e":"灰黄霉素口服沉积于角蛋白，仅对皮肤癣菌引起的浅表真菌感染有效，对头癣、体癣、甲癣有效，但深部真菌病由念珠菌、隐球菌等引起，灰黄霉素对其无效，须用两性霉素B等。牛皮癣并非真菌感染，但灰黄霉素对真菌性的浅表感染有效，本题问真菌病无效者，深部真菌病为答案"},{"q":"阿司匹林解热作用机制是","o":["抑制环氧酶，减少PG合成","抑制下丘脑体温调节中枢","抑制致炎因子的合成","杀菌作用","中和内毒素"],"a":0,"e":"阿司匹林抑制环氧酶，减少前列腺素合成，使下丘脑体温调节中枢的PG水平下降，调定点回降，通过散热增加而解热。它不直接抑制体温调节中枢，也不抑制致炎因子合成；无杀菌作用，亦不能中和内毒素，仅针对PG合成环节发挥解热效应"},{"q":"羟甲唑啉用于鼻充血时应采用的剂型是","o":["口服制剂","注射制剂","气雾剂","滴鼻剂","缓释剂"],"a":3,"e":"羟甲唑啉为α受体激动药，局部收缩鼻黏膜血管减轻充血，须制成滴鼻剂直接作用于鼻黏膜起效快、全身不良反应少。口服制剂经胃肠吸收无法在鼻部达到有效浓度且全身副作用大；注射制剂、气雾剂、缓释剂均非鼻充血局部给药的常规剂型"},{"q":"甲巯咪唑最严重的不良反应是","o":["药疹","关节痛","粒细胞缺乏","血管神经性水肿","腹痛、腹泻"],"a":2,"e":"甲巯咪唑为硫脲类抗甲状腺药，最严重的不良反应是粒细胞缺乏症，可致严重感染甚至危及生命，用药期间须监测血象。药疹、关节痛、血管神经性水肿、腹痛腹泻多为较轻或较常见反应，虽可发生但严重性远不及粒细胞缺乏"},{"q":"巴比妥类药物随剂量由小到大依次表现为","o":["镇静、催眠、抗惊厥、麻醉","催眠、镇静、麻醉、抗惊厥","镇静、催眠、麻醉、抗惊厥","镇静、抗惊厥、麻醉、催眠","镇静、麻醉、抗惊厥、催眠"],"a":0,"e":"巴比妥类随剂量增加依次出现镇静、催眠、抗惊厥和麻醉作用，过量则致呼吸和循环抑制。其机制是增强GABA能神经抑制，剂量越大中枢抑制越深。催眠出现在镇静之后，抗惊厥在催眠之后，麻醉最深，其余选项的排列顺序均与这一剂量依赖关系不符"},{"q":"青霉素G不是治疗下列哪种病原体所致感染的主要药物","o":["溶血性链球菌","螺旋体","白喉杆菌","淋病奈瑟菌","军团菌"],"a":4,"e":"青霉素G主要作用于革兰阳性菌和部分革兰阴性球菌、螺旋体，对溶血性链球菌、白喉杆菌、淋病奈瑟菌及螺旋体有效。军团菌为细胞内寄生的革兰阴性杆菌，青霉素G对其无效且不能进入细胞内，治疗首选大环内酯类或氟喹诺酮类，故军团菌为例外"},{"q":"可取消迟后除极所引起的触发活动的药物是","o":["地高辛","维拉帕米","阿托品","异丙肾上腺素","肾上腺素"],"a":1,"e":"迟后除极由细胞内Ca2＋超载诱发，维拉帕米阻滞L型钙通道，减少Ca2＋内流，可取消迟后除极所致的触发活动，用于室上性心律失常。地高辛增加细胞内Ca2＋反可诱发迟后除极；阿托品、异丙肾上腺素、肾上腺素加快心率或增强自律性，均不能消除触发活动"},{"q":"主要合成和分泌盐皮质激素的部位是","o":["垂体前叶","下丘脑","球状带","束状带","网状带"],"a":2,"e":"肾上腺皮质球状带分泌盐皮质激素，以醛固酮为主，调节水盐代谢。束状带分泌糖皮质激素如皮质醇；网状带分泌性激素；垂体前叶分泌ACTH等促激素；下丘脑分泌CRH等释放激素，均不直接合成盐皮质激素"},{"q":"毛果芸香碱不适用于治疗","o":["开角型青光眼","闭角型青光眼","阿托品中毒","虹膜睫状体炎","重症肌无力"],"a":4,"e":"毛果芸香碱为M受体激动药，可缩瞳、降眼压、调节痉挛，用于青光眼和虹膜睫状体炎，亦可用其M样作用对抗阿托品中毒。重症肌无力是神经肌肉接头N2受体受损，须用胆碱酯酶抑制剂新斯的明增加乙酰胆碱，毛果芸香碱对N2受体无效，故不适用"},{"q":"肥胖或超重的2型糖尿病患者推荐的一线治疗药物是","o":["阿卡波糖","胰高血糖素","二甲双胍","格列苯脲","罗格列酮"],"a":2,"e":"二甲双胍减少肝糖输出、改善外周胰岛素抵抗并轻度减重，不增加胰岛素分泌，低血糖风险小，是肥胖或超重2型糖尿病的一线首选。阿卡波糖主要降低餐后血糖；格列苯脲促胰岛素分泌易致低血糖和增重；罗格列酮可致水钠潴留和增重；胰高血糖素升高血糖，均不首选"},{"q":"可待因是","o":["兼有镇痛作用的镇咳药","兼有中枢和外周作用的镇咳药","非成瘾性镇咳药","外周性镇咳药","镇咳效果较吗啡好的镇咳药"],"a":0,"e":"可待因为阿片类生物碱，激动阿片受体，具有中枢性镇咳作用并兼有中等强度镇痛作用，用于剧烈干咳和中等疼痛。它有一定成瘾性，属成瘾性镇咳药；其作用以中枢为主而非外周；镇咳强度弱于吗啡，故兼有镇痛作用的镇咳药表述准确"},{"q":"初发轻症高血压患者可首选使用的降压药物是","o":["中枢性降压药","血管平滑肌扩张药","利尿药","钾通道开放药","中枢降压药"],"a":2,"e":"利尿药通过排钠利尿降低血容量和血管反应性，降压平稳、价廉，是初发轻症高血压的首选，尤其适合老年高血压。中枢性降压药如可乐定、血管平滑肌扩张药、钾通道开放药多用于二三线或特殊情况；血管扩张药不良反应较多，均不作轻症一线"},{"q":"对革兰氏阴性及革兰氏阳性厌氧菌均具有较强的抗菌作用是","o":["多黏菌素B","青霉素G","阿米卡星","万古霉素","林可霉素"],"a":4,"e":"林可霉素对革兰阳性菌和革兰阴性厌氧菌均有较强抗菌作用，尤其对厌氧菌效果好，可透过骨组织，常用于骨髓炎。多黏菌素B仅抗革兰阴性杆菌；青霉素G对厌氧菌作用有限；阿米卡星为氨基糖苷类，抗需氧G－菌；万古霉素主要针对耐药G＋菌，均不兼具抗厌氧菌"},{"q":"高血压合并支气管哮喘的患者不宜用","o":["β受体阻断药","α受体阻断药","利尿药","扩血管药","钙通道阻断药"],"a":0,"e":"β受体阻断药阻断支气管平滑肌β2受体，可引起支气管收缩，诱发或加重哮喘，故高血压合并哮喘者禁用或慎用。α受体阻断药、利尿药、扩血管药、钙通道阻断药均不收缩支气管，对哮喘无此不良影响，其中钙通道阻断药还可降压，更为合适"},{"q":"筒箭毒碱过量致死的主要原因是","o":["直接抑制心脏","肋间肌和膈肌麻痹","严重损害肝肾功能","过敏性休克","显著抑制呼吸中枢"],"a":1,"e":"筒箭毒碱为非去极化型肌松药，阻断神经肌肉接头NM受体，过量时全部骨骼肌松弛，肋间肌和膈肌麻痹导致呼吸停止而死亡。它不直接抑制心脏，也无严重肝肾损害；过敏性休克非其主要致死原因；其不抑制呼吸中枢，呼吸停止源于呼吸肌麻痹"},{"q":"毛果芸香碱引起调节痉挛的原因是","o":["兴奋瞳孔括约肌上的M受体","兴奋瞳孔开大肌上的α受体","兴奋睫状肌上的M受体","兴奋睫状肌上的α受体","兴奋睫状肌上的N受体"],"a":2,"e":"毛果芸香碱激动睫状肌环形肌上的M受体，使睫状肌收缩、悬韧带松弛，晶状体变凸、屈光度增加，视远物模糊而视近物清楚，即调节痉挛。瞳孔括约肌M受体兴奋致缩瞳，与调节痉挛不同；睫状肌上无α、N受体主导此效应，瞳孔开大肌α受体兴奋致扩瞳，均非原因"},{"q":"下列哪种药物与呋塞米合用可增强耳毒性","o":["四环素","红霉素","链霉素","青霉素","氯霉素"],"a":2,"e":"链霉素属氨基糖苷类，本身有耳毒性，与呋塞米等袢利尿药合用时二者耳毒性叠加，可致不可逆听力损害，故禁止配伍。四环素、红霉素、青霉素、氯霉素虽有各自不良反应，但无明显耳毒性，与呋塞米合用不突出增强耳毒性"},{"q":"强心苷减慢房颤时的心室率主要是由于","o":["减少房室结中的隐匿性传导","降低心房自律性","增加房室结中的隐匿性传导","降低心室自律性","降低窦房结自律性"],"a":2,"e":"强心苷兴奋迷走神经，增加房室结中的隐匿性传导，使更多心房冲动在房室结内受阻不能下传，从而显著减慢心室率。它不是减少而是增加隐匿性传导；降低心房或心室、窦房结自律性均非主要机制，减慢心室率的关键在于房室传导的抑制"},{"q":"由于情绪激动引起的窦性心动过速最好选用","o":["苯妥英钠","奎尼丁","普萘洛尔","氟卡尼","利多卡因"],"a":2,"e":"情绪激动时交感神经兴奋、儿茶酚胺释放增多致窦性心动过速，普萘洛尔阻断β受体，减慢心率、抑制交感兴奋，针对病因疗效最好。苯妥英钠、奎尼丁、氟卡尼、利多卡因均为钠通道阻滞药，主要治疗室性或异位心律失常，对单纯窦性心动过速并非首选"},{"q":"治疗精神分裂症的药物是","o":["地西泮","氟奋乃静","碳酸锂","哌唑嗪","阿米替林"],"a":1,"e":"氟奋乃静为吩噻嗪类抗精神病药，阻断中脑边缘系统多巴胺D2受体，对精神分裂症幻觉妄想等阳性症状疗效好。地西泮为抗焦虑镇静催眠药；碳酸锂治躁狂症；哌唑嗪为α受体阻断降压药；阿米替林为三环类抗抑郁药，均非抗精神病药"},{"q":"下列抗高血压药物中，对心脏有明显的抑制作用的是","o":["维拉帕米","卡托普利","尼莫地平","硝苯地平","氯沙坦"],"a":0,"e":"维拉帕米为非二氢吡啶类钙通道阻滞药，阻滞心肌L型钙通道，抑制窦房结和房室结，减慢心率、减弱收缩力，对心脏抑制明显。卡托普利、氯沙坦作用于肾素-血管紧张素系统；硝苯地平、尼莫地平为二氢吡啶类，主要扩血管，对心脏抑制弱，甚至反射性加快心率"},{"q":"糖皮质激素引起的负氮平衡可选用的治疗药物是","o":["雌激素","雄激素","甲状腺素","胰岛素","ACTH"],"a":1,"e":"糖皮质激素促进蛋白质分解、抑制合成，长期应用致负氮平衡；雄激素（蛋白同化激素）可促进蛋白质合成、减少分解，纠正负氮平衡。雌激素无此蛋白同化作用；甲状腺素促进代谢反而加重消耗；胰岛素虽促合成但主要用于降糖；ACTH促皮质醇分泌会加重负氮平衡"},{"q":"行胸部手术全麻，需要辅助使用除极化型肌松药，下列属于该类的药物是","o":["筒箭毒碱","琥珀胆碱","阿曲库铵","多库铵","米库铵"],"a":1,"e":"琥珀胆碱为除极化型肌松药，激动NM受体使肌纤维持续去极化，先有短暂肌束颤动后转为松弛，起效快、维持短，用于气管插管和内镜检查。筒箭毒碱、阿曲库铵、多库铵、米库铵均为非去极化型肌松药，竞争性阻断NM受体，作用性质与琥珀胆碱相反"},{"q":"奥美拉唑属于","o":["H2受体阻断药","H＋-K＋-ATP酶抑制剂","M受体阻断药","胃泌素受体阻断药","抗幽门螺旋菌药"],"a":1,"e":"奥美拉唑在胃壁细胞酸性环境中转化为活性形式，不可逆抑制H＋-K＋-ATP酶，阻断胃酸分泌终末环节，抑酸作用强而持久。H2受体阻断药为西咪替丁、雷尼替丁；M受体阻断药为阿托品类；胃泌素受体阻断药丙谷胺；抗幽门螺杆菌药为抗生素和铋剂，均非奥美拉唑所属类别"},{"q":"具有抗氧化作用的抗动脉粥样硬化药物是","o":["辛伐他汀","环丙贝特","普罗布考","考来烯胺","烟酸"],"a":2,"e":"普罗布考为抗氧化剂，抑制LDL氧化修饰，减少泡沫细胞形成，兼具降胆固醇作用，用于抗动脉粥样硬化。辛伐他汀通过抑制HMG-CoA还原酶降脂；环丙贝特、烟酸主要降甘油三酯；考来烯胺为胆汁酸螯合剂，均不以抗氧化为主要机制"},{"q":"心房纤颤转律可使用的药物是","o":["奎尼丁","维拉帕米","腺苷","胺碘酮","普萘洛尔"],"a":0,"e":"奎尼丁为Ⅰa类钠通道阻滞药，延长心房肌有效不应期、减慢传导，可转复心房颤动并维持窦性心律，是经典的复律药。维拉帕米、普萘洛尔主要减慢心室率而非转律；腺苷用于终止室上速；胺碘酮虽也可复律，但本题传统答案为奎尼丁"},{"q":"预防过敏性哮喘最好选用","o":["麻黄碱","氨茶碱","色甘酸钠","沙丁胺醇","肾上腺素"],"a":2,"e":"色甘酸钠稳定肥大细胞膜，阻止过敏原激发后组胺等介质释放，用于预防过敏性哮喘发作，须提前用药，对已发作无效。麻黄碱、沙丁胺醇为支气管扩张药，用于缓解症状；氨茶碱为磷酸二酯酶抑制剂，平喘；肾上腺素用于急性发作，均非预防用药"},{"q":"下列不属于胰岛素常见不良反应的是","o":["过敏反应","胃肠道反应","低血糖症","胰岛素耐受性","注射部位脂肪萎缩"],"a":1,"e":"胰岛素常见低血糖症、过敏反应、胰岛素耐受性及注射部位脂肪萎缩或增生，均与其使用相关。胃肠道反应不是胰岛素的典型不良反应，因胰岛素为注射给药且本身不直接刺激胃肠道，该反应多见于口服降糖药如二甲双胍、阿卡波糖"},{"q":"下列药物可首选治疗急性肺水肿的是","o":["氢氯噻嗪","乙酰唑胺","呋塞米","氨苯喋啶","螺内酯"],"a":2,"e":"呋塞米为强效袢利尿药，静脉给药迅速扩张静脉、降低前负荷，并强力利尿减少血容量，快速减轻肺水肿，是急性肺水肿首选。氢氯噻嗪、氨苯蝶啶、螺内酯利尿作用温和，起效慢；乙酰唑胺利尿弱且易耐受，均不适合急性肺水肿抢救"},{"q":"胺碘酮在分类上属于","o":["钠通道阻滞药","促钾外流药","延长动作电位时程药","β受体阻断药","钙通道阻滞药"],"a":2,"e":"胺碘酮为Ⅲ类抗心律失常药，阻滞钾通道延长动作电位时程和有效不应期，兼有钠通道阻滞、β受体阻断和钙通道阻滞作用，是广谱抗心律失常药。钠通道阻滞药为Ⅰ类；促钾外流会缩短动作电位；β受体阻断药为Ⅱ类；钙通道阻滞药为Ⅳ类，均非胺碘酮主类"},{"q":"长期大量应用糖皮质激素的不良反应是","o":["枯草热","骨质疏松","过敏性紫癜","血小板减少症","粒细胞减少症"],"a":1,"e":"长期大量用糖皮质激素抑制成骨细胞、促进骨吸收并减少钙吸收，导致骨质疏松甚至骨折，是其严重不良反应。枯草热、过敏性紫癜为过敏性疾病，非激素引起；血小板减少症、粒细胞减少症亦非其典型反应，激素反而使血小板和中性粒细胞增多"},{"q":"下列何为脑内最重要的抑制性递质","o":["5-HT","GABA","ACh","DA","NA"],"a":1,"e":"γ-氨基丁酸（GABA）是脑内最重要的抑制性神经递质，作用于GABA_A受体开放氯离子通道，使突触后膜超极化产生抑制效应，与镇静催眠、抗癫痫密切相关。5-HT、ACh、DA、NA在脑内主要发挥兴奋或调制作用，虽也有抑制性通路，但重要性不及GABA"},{"q":"下列哪点是镇静催眠药的共同不良反应","o":["明显缩短快动眼睡眠时间","视力模糊","明显诱导肝药酶","久用产生依赖性和成瘾","肝功能损害"],"a":3,"e":"镇静催眠药（苯二氮䓬类、巴比妥类等）久用均可产生耐受性、依赖性和成瘾，停药出现戒断症状，是其共性。明显缩短快动眼睡眠以巴比妥类突出，苯二氮䓬类影响较小；并非都明显诱导肝药酶；视力模糊、肝功能损害亦非各类共同反应"},{"q":"子痫所致的惊厥可用下列哪种药物","o":["氯丙嗪","硝西泮","硫酸镁","地西泮","苯巴比妥"],"a":2,"e":"硫酸镁可抑制中枢神经和神经肌肉接头，松弛平滑肌、解除血管痉挛，是治疗和预防子痫惊厥的首选药。氯丙嗪、硝西泮、地西泮、苯巴比妥虽有镇静抗惊厥作用，但均非子痫惊厥的专门首选，硫酸镁针对子痫病理机制疗效确切"},{"q":"相对生物利用度等于","o":["（AUC试药/AUC标准药）×100%","（AUC标准药/AUC试药）×100%","（AUC口服等量药后/AUC静脉注射等量药后）×100%","（AUC静脉注射等量药后/AUC口服等量药后）×100%","（AUC口服标准药后/AUC静脉注射等量药后）×100%"],"a":0,"e":"相对生物利用度是同一剂量下试验制剂与标准参比制剂曲线下面积之比，即（AUC试药/AUC标准药）×100%，用于评价制剂吸收程度。绝对生物利用度才是（AUC口服/AUC静脉注射）×100%；其余将分子分母颠倒或混入静脉注射的选项均不符合相对生物利用度定义"},{"q":"钙拮抗药可用于治疗","o":["低血压","心绞痛","心力衰竭","肥厚性心肌病","心动过缓"],"a":1,"e":"钙拮抗药阻滞钙通道，扩张冠状动脉和外周血管，降低心肌氧耗并增加供血，对心绞痛尤其是变异型心绞痛疗效显著。它会降压而非治低血压；肥厚性心肌病慎用；严重心力衰竭和心动过缓并非其适应证，部分钙拮抗药反而抑制心功能或减慢心率"},{"q":"药理学效应可包括","o":["治疗作用与预防作用","选择作用","兴奋作用与抑制作用","特异性作用","治疗作用与毒性反应"],"a":2,"e":"药理效应按作用性质分为兴奋和抑制，使机体原有功能增强为兴奋，减弱为抑制，是基本效应类型。治疗作用与预防作用、治疗作用与毒性反应是按治疗目的和效果分类；选择作用、特异性作用描述作用范围，均非按效应性质划分的基本类型"},{"q":"以下哪一项是胰岛素治疗的目标","o":["减少胰岛素的降解","增加胰岛素释放","抑制机体的生长","增加肌肉细胞对葡萄糖的摄取","促进胰岛素的合成"],"a":3,"e":"胰岛素与肌肉、脂肪细胞受体结合，促进葡萄糖转运入细胞并氧化利用，从而降低血糖，增加肌肉细胞摄取葡萄糖是其核心治疗目标。减少降解、增加释放、促进合成均非胰岛素治疗目标而是机体自身调节；抑制生长与胰岛素促合成代谢的作用相反"},{"q":"抗菌药物是","o":["对病原菌有杀灭作用的药物","对病原菌有抑制作用的药物","对病原菌有杀灭或抑制作用的药物","能用于预防细菌性感染的药物","能治疗细菌性感染的药物"],"a":2,"e":"抗菌药物是指对病原微生物具有杀灭或抑制作用的药物，涵盖杀菌药和抑菌药两方面，此定义最完整。仅说杀灭或仅说抑制都片面；能预防或能治疗细菌感染是用途描述，不能作为定义，且预防用药本身也基于其杀灭或抑制作用，故第三项最准确"},{"q":"治疗阿尔茨海默病的药物不包括","o":["左旋多巴","他克林","多奈哌齐","石杉碱甲","占诺美林"],"a":0,"e":"他克林、多奈哌齐、石杉碱甲为胆碱酯酶抑制剂，占诺美林为M1受体激动药，均用于改善阿尔茨海默病认知功能。左旋多巴是多巴胺前体，通过补充脑内多巴胺治疗帕金森病，与阿尔茨海默病的胆碱能缺陷机制无关，故不属于AD治疗药"},{"q":"下列哪一个利尿药不引起失钾","o":["阿米洛利","氯酞酮","呋塞米","布美他尼","氯噻嗪"],"a":0,"e":"阿米洛利阻断远曲小管和集合管钠通道，抑制Na＋重吸收和K＋分泌，为保钾利尿药，不引起失钾。氯酞酮、氯噻嗪为噻嗪类，呋塞米、布美他尼为袢利尿药，均增加钾排泄，长期用可致低血钾，故只有阿米洛利不引起失钾"},{"q":"抑制Na+-K+-2Cl-同向转运子的利尿药是","o":["氢氯噻嗪","呋塞米","氨苯蝶啶","螺内酯","甘露醇"],"a":1,"e":"呋塞米作用于髓袢升支粗段，抑制Na＋-K＋-2Cl－同向转运子，减少NaCl重吸收并破坏髓质渗透梯度，产生强大利尿作用。氢氯噻嗪抑制远曲小管Na＋-Cl－转运；氨苯蝶啶阻断钠通道；螺内酯拮抗醛固酮；甘露醇为渗透性利尿药，机制均不同"},{"q":"甲氨蝶呤抗代谢作用机制是","o":["阻止嘧啶核苷酸合成","抑制DA多聚酶","抑制二氢叶酸还原酶","抑制核苷酸还原酶","抑制拓扑异构酶"],"a":2,"e":"甲氨蝶呤为叶酸类似物，竞争性抑制二氢叶酸还原酶，阻断二氢叶酸还原为四氢叶酸，使一碳单位代谢障碍、嘌呤和胸苷酸合成受阻，抑制肿瘤细胞DNA合成。阻止嘧啶合成、抑制核苷酸还原酶、抑制拓扑异构酶、抑制DNA多聚酶分别为其他抗代谢药或抗肿瘤药机制"},{"q":"糖皮质激素可通过增加下列哪种物质抑制合成白三烯","o":["脂皮素","磷脂酶A2","前列腺素","白细胞介素","血小板活化因子"],"a":0,"e":"糖皮质激素诱导脂皮素-1合成，脂皮素抑制磷脂酶A2，使膜磷脂不能释放花生四烯酸，从而减少白三烯和前列腺素生成而抗炎。磷脂酶A2是被抑制的对象而非增加的物质；前列腺素、白细胞介素、血小板活化因子均为炎症介质，不是激素增加以抑制白三烯的物质"},{"q":"治疗麻风病的首选药物是","o":["利福平","氨苯砜","乙胺丁醇","巯苯咪唑","氯法齐明"],"a":1,"e":"氨苯砜为砜类药物，抑制麻风分枝杆菌叶酸合成，对麻风病疗效确切、价廉，是治疗各型麻风的首选药。利福平、氯法齐明用于麻风但多作联合用药；乙胺丁醇、巯苯咪唑抗结核或抗真菌，非麻风首选，故氨苯砜为首选"},{"q":"可耗竭肾上腺素能神经末梢递质的药物","o":["可乐定","美卡拉明","利舍平","卡托普利","氢氯噻嗪"],"a":2,"e":"利舍平与去甲肾上腺素能神经末梢的囊泡膜结合，抑制递质再摄取，使囊泡内去甲肾上腺素逐渐耗竭，从而降低交感神经功能而降压。可乐定为中枢α2激动药；美卡拉明为神经节阻断药；卡托普利抑制ACE；氢氯噻嗪为利尿药，均不耗竭末梢递质"},{"q":"肾功能不全的病人患铜绿假单胞菌感染，治疗可选用","o":["多黏菌素E","氨苄西林","庆大霉素","羧苄西林","林可霉素"],"a":3,"e":"羧苄西林为抗铜绿假单胞菌青霉素，对铜绿假单胞菌有效且肾毒性低，适用于肾功能不全者。庆大霉素、多黏菌素E虽抗铜绿假单胞菌但肾毒性强，肾功能不全者不宜；氨苄西林对铜绿假单胞菌无效；林可霉素主要抗G＋菌和厌氧菌，故羧苄西林最合适"},{"q":"可用于治疗伤寒和副伤寒的药物是","o":["氯霉素","金霉素","四环素","红霉素","米诺环素"],"a":0,"e":"氯霉素对伤寒、副伤寒沙门菌高度敏感，组织穿透力强，是治疗伤寒、副伤寒的经典有效药物。金霉素、四环素、米诺环素为四环素类，对伤寒疗效差；红霉素为大环内酯类，主要抗G＋菌，均非伤寒首选"},{"q":"可用于预防高原反应的利尿药是","o":["阿米洛利","螺内酯","美托拉宗","乙酰唑胺","呋塞米"],"a":3,"e":"乙酰唑胺抑制碳酸酐酶，减少脑脊液生成、改善脑水肿并纠正高原低氧所致的呼吸性碱中毒，可预防和减轻高原反应。呋塞米、美托拉宗、阿米洛利、螺内酯虽为利尿药，但均无此预防高原反应的独特机制与疗效"},{"q":"以下药物无法对疟原虫提供有效预防效果的药物是","o":["氯喹","乙胺嘧啶","磺胺多辛","氨苯砜","甲硝唑"],"a":0,"e":"官方答案为【氯喹】，但依据教材，正确答案为【甲硝唑】。氯喹对红细胞内期疟原虫有强大杀灭作用，可用于疟疾的症状性预防；乙胺嘧啶、磺胺多辛、氨苯砜通过抑制叶酸代谢等机制用于病因性预防。甲硝唑主要抗厌氧菌、阿米巴和滴虫，对疟原虫无杀灭作用，不能提供任何预防效果，氯喹亦有预防作用，原答案站不住"},{"q":"下列哪种强心苷口服后吸收最完全","o":["洋地黄毒苷","地高辛","黄夹苷","毛花苷C","毒毛花苷K"],"a":0,"e":"洋地黄毒苷脂溶性高、口服吸收近完全，作用持久，主要经肝代谢。地高辛口服吸收较完全但不及洋地黄毒苷；黄夹苷、毛花苷C、毒毛花苷K脂溶性低，口服吸收差或不规则，其中毒毛花苷K、毛花苷C多作静脉注射，故洋地黄毒苷吸收最完全"},{"q":"有关异烟肼的错误叙述是","o":["对结核杆菌有高度的选择性","肝毒性以快代谢型者较多见","口服易吸收","单用时结核杆菌不易产生耐药性","适用于治疗各种类型结核病的首选药"],"a":3,"e":"异烟肼对结核杆菌有高度选择性，口服易吸收，是各种类型结核病的首选药，肝毒性以快代谢型者较多见。但异烟肼单用时结核杆菌极易产生耐药性，故临床需联合用药，单用时不易产生耐药性的说法错误，为本题答案"},{"q":"静脉注射除极化型肌松药用于食道镜检查，该药具备的特点是","o":["产生肌松作用前无短暂的肌束颤动","连续用药不产生快速耐受性","过量不导致呼吸肌麻痹","新斯的明无法解救其中毒反应","治疗量有神经节阻断作用"],"a":3,"e":"琥珀胆碱为除极化型肌松药，与NM受体结合产生持久去极化，因不被乙酰胆碱酯酶水解，新斯的明不仅不能解救反可加重其肌松，故中毒时新斯的明无法解救。它起效前有短暂肌束颤动，连续用可产生快速耐受性，过量致呼吸肌麻痹，治疗量无明显神经节阻断，其余描述均错误"},{"q":"药物进入细胞最常见的方式是","o":["特殊载体摄入","脂溶性跨膜扩散","胞饮现象","水溶扩散","氨基酸载体转运"],"a":1,"e":"大多数药物为弱酸或弱碱，以非解离的脂溶性形式顺浓度差通过细胞膜脂质双层，即简单扩散（脂溶性跨膜扩散），是最常见的转运方式，不耗能、不需载体。特殊载体摄入、氨基酸载体转运属主动转运或易化扩散，仅少数药物采用；胞饮和水溶扩散适用范围有限"},{"q":"氨基糖苷类抗生素的体内过程，下列哪点不正确","o":["部分从肾脏排泄，部分在肝脏代谢","口服不易吸收","主要分布在细胞外液","脑脊液中浓度较低","内耳淋巴液浓度高"],"a":0,"e":"氨基糖苷类水溶性强，口服不易吸收，主要分布在细胞外液，内耳淋巴液和肾皮质浓度高，脑脊液浓度低，主要以原形经肾小球滤过排泄，几乎不在肝脏代谢。部分在肝脏代谢的说法错误；其余关于吸收、分布和排泄的描述均正确"},{"q":"糖皮质激素用于炎症后期应用的目的在于","o":["具有强大抗炎作用，促进炎症消散","抑制肉芽组织生长，防止粘连和疤痕形成","促进炎症区血管收缩，降低通透性","稳定溶酶体膜，减少蛋白水解酶释放","抑制花生四烯酸释放，使PG合成减少"],"a":1,"e":"糖皮质激素在炎症后期抑制毛细血管和成纤维细胞增生，抑制肉芽组织生长，从而防止粘连和瘢痕形成，减轻后遗症。强大抗炎、促进消散是炎症早期作用；收缩血管降低通透性、稳定溶酶体膜、抑制花生四烯酸释放均为抗炎机制，而非炎症后期应用的主要目的"},{"q":"哌仑西平有下述哪项药理作用","o":["阻断H2受体，抑制胃酸分泌","阻断胃泌素受体，减少胃酸分泌","促进胃黏液分泌，保护胃黏膜","抗幽门螺杆菌","阻断M胆碱受体，抑制胃酸分泌"],"a":4,"e":"哌仑西平为选择性M1胆碱受体阻断药，阻断壁细胞M受体，抑制胃酸分泌，用于消化性溃疡。阻断H2受体是西咪替丁等；阻断胃泌素受体是丙谷胺；促进胃黏液分泌是黏膜保护剂；抗幽门螺杆菌靠抗生素和铋剂，均非哌仑西平作用"},{"q":"碳酸锂主要用于治疗","o":["躁狂症","抑郁症","焦虑症","精神分裂症","神经官能症"],"a":0,"e":"碳酸锂抑制去甲肾上腺素和多巴胺释放、增强其再摄取，稳定神经突触传递，是治疗躁狂症和双相情感障碍躁狂发作的首选药，亦用于预防复发。抑郁症用抗抑郁药；焦虑症用抗焦虑药；精神分裂症用抗精神病药；神经官能症非其适应证"},{"q":"下列药物中既能降低TG和VLDL，又能降低Lp(a)的是","o":["考来烯胺","普伐他汀","硫酸软骨素","二十二碳六烯酸","烟酸"],"a":4,"e":"烟酸抑制脂肪组织脂解、减少肝脏合成TG和VLDL，并能显著降低脂蛋白(a)，是少数可降低Lp(a)的降脂药，还可升高HDL。考来烯胺、普伐他汀主要降LDL；硫酸软骨素作用弱；二十二碳六烯酸主要降TG，均不能显著降低Lp(a)"},{"q":"不属于哌替啶适应证的是","o":["术后镇痛","人工冬眠","心源性哮喘","麻醉前给药","支气管哮喘"],"a":4,"e":"哌替啶为阿片类镇痛药，可用于术后镇痛、心源性哮喘、麻醉前给药及人工冬眠。但它收缩支气管平滑肌并抑制呼吸，支气管哮喘患者禁用；心源性哮喘可用是其扩张血管、减轻心脏负荷之故，与支气管哮喘不同，故支气管哮喘不属于适应证"},{"q":"不具有内在拟交感活性的选择性β受体阻断药是","o":["美托洛尔","普萘洛尔","醋丁洛尔","纳多洛尔","普拉洛尔"],"a":0,"e":"美托洛尔为选择性β1受体阻断药，无内在拟交感活性，对心脏抑制明确。普萘洛尔、纳多洛尔为非选择性β阻断药；醋丁洛尔、普拉洛尔虽有选择性但具内在拟交感活性，部分激动受体，故兼具选择性和无内在拟交感活性的是美托洛尔"},{"q":"普萘洛尔不能治疗","o":["室上性心动过速","心绞痛","高血压","心房颤动","房窒传导阻滞"],"a":4,"e":"普萘洛尔阻断β受体，减慢心率、抑制房室传导，房室传导阻滞者使用会加重阻滞，属禁忌，故不能治疗。它对室上性心动过速、心绞痛、高血压、心房颤动伴快速心室率均有疗效，通过减慢心率和传导发挥作用，唯房室传导阻滞例外"},{"q":"卡托普利的主要降压机制是","o":["利尿降压","血管扩张","阻滞钙通道","抑制血管紧张素转化酶","α受体阻断"],"a":3,"e":"卡托普利含巯基，与血管紧张素转化酶的锌离子结合，抑制该酶活性，减少AngⅡ生成，降低血管阻力和醛固酮水平而降压。它不抑制肾素活性，也不抑制血管紧张素Ⅰ的生成（反而使其蓄积），不抑制β-羟化酶，亦非阻断血管紧张素受体，故为抑制ACE活性"},{"q":"下列属于特异质反应的是","o":["高血压患者突然停用普萘洛尔出现血压升高","患者服用伯氨喹发生急性溶血性贫血","患者接受青霉素注射发生休克","患者使用阿托品后出现口干、视力模糊","患者使用巴比妥类药物次晨仍嗜睡、困倦"],"a":1,"e":"特异质反应是遗传缺陷导致的异常药物反应，伯氨喹在G6PD缺乏者中可引起急性溶血性贫血，属典型特异质反应。停普萘洛尔血压反跳为停药反应；青霉素休克为过敏反应；阿托品口干视物模糊为副作用；巴比妥次晨嗜睡为后遗效应，均非特异质反应"},{"q":"可以用双膦酸盐类治疗的疾病不包括","o":["原发性骨质疏松","糖皮质激素继发的骨质疏松","绝经后骨质疏松","骨质疏松性骨折","低钙血症"],"a":4,"e":"双膦酸盐抑制破骨细胞、减少骨吸收，用于原发性及绝经后骨质疏松、糖皮质激素继发骨质疏松和骨质疏松性骨折。它可能降低血钙，绝不用于低钙血症，后者需补钙和维生素D，故低钙血症是其治疗禁忌而非适应证"},{"q":"糖皮质激素治疗哮喘的主要药理学作用是","o":["兴奋呼吸中枢","直接松弛支气管平滑肌","增强气道纤毛摆动","抗炎作用","增强哮喘患者的免疫功能"],"a":3,"e":"支气管哮喘本质为气道慢性炎症，糖皮质激素通过强大抗炎作用抑制炎症细胞、介质和气道高反应性，是控制哮喘最有效的药物。它不兴奋呼吸中枢，也不直接松弛支气管平滑肌；增强纤毛摆动和增强免疫均非其治疗机制，抗炎才是核心"},{"q":"耐药性是指","o":["连续用药后药物在体内的蓄积现象","连续用药后机体对药物产生敏感现象","连续用药后细菌对药物的敏感性降低甚至消失","反复用药患者对药物产生生理依赖性","反复用药患者对药物产生精神依赖性"],"a":2,"e":"耐药性又称抗药性，指连续或反复用药后细菌对药物的敏感性降低甚至消失，使疗效下降，是病原体对药物的适应。药物在体内蓄积为蓄积中毒；机体敏感性增高非耐药；生理依赖和精神依赖属药物依赖性，主体是机体而非细菌，均与耐药性不同"},{"q":"下列药物中属于选择性α2受体阻断药的是","o":["哌唑嗪","育亨宾","坦洛新","酚妥拉明","酚苄明"],"a":1,"e":"育亨宾选择性阻断α2受体，促进去甲肾上腺素释放，主要用于研究工具药。哌唑嗪、坦洛新为选择性α1受体阻断药；酚妥拉明为非选择性α受体阻断药，对α1、α2均有阻断；酚苄明亦为非选择性α阻断药且作用持久，故只有育亨宾选择性阻断α2"},{"q":"复方新诺明是以下哪两种药物的复方制剂","o":["新斯的明 + 诺氟沙星","甲氧苄啶 + 磺胺甲噁唑","新斯的明 + 甲氧苄啶","磺胺嘧啶 + 诺氟沙星","呋喃妥因 + 甲氧苄啶"],"a":1,"e":"复方新诺明由磺胺甲噁唑与甲氧苄啶按一定比例组成，前者抑制二氢蝶酸合酶、后者抑制二氢叶酸还原酶，双重阻断叶酸代谢，抗菌作用增强。新斯的明为胆碱酯酶抑制剂，诺氟沙星为喹诺酮类，磺胺嘧啶、呋喃妥因均非该复方成分，故正确组合为甲氧苄啶加磺胺甲噁唑"},{"q":"青霉素的抗菌作用机制主要是","o":["影响细菌叶酸代谢","抑制细菌细胞壁的合成","抑制细菌蛋白质的合成","抑制细菌DNA的合成","抑制细菌RNA的合成"],"a":1,"e":"青霉素与细菌细胞壁合成中的青霉素结合蛋白结合，抑制转肽酶，阻碍肽聚糖交联，使细胞壁缺损，菌体因渗透压膨胀破裂而死亡，对繁殖期细菌作用强。影响叶酸代谢是磺胺类；抑制蛋白质合成是氨基糖苷类、大环内酯类；抑制DNA、RNA合成是喹诺酮类和利福平"},{"q":"常用于抗心律失常的局麻药是","o":["普罗帕酮","罗哌卡因","利多卡因","丁卡因","丁哌卡因"],"a":2,"e":"利多卡因既是局麻药又是Ⅰb类抗心律失常药，阻滞心室肌和浦氏纤维钠通道，用于室性心律失常，是唯一常作抗心律失常用的局麻药。普罗帕酮为抗心律失常药但非局麻药；罗哌卡因、丁卡因、丁哌卡因均为局麻药，基本不用于心律失常"},{"q":"卡托普利的抗高血压作用的机制是","o":["抑制肾素活性","抑制血管紧张素转化酶活性","抑制血管紧张素Ⅰ的生成","抑制β-羟化酶的活性","阻滞血管紧张素受体"],"a":1,"e":"卡托普利含巯基，与血管紧张素转化酶结合并抑制其活性，减少AngⅡ生成，降低血管阻力和醛固酮水平而降压，并逆转心血管重构。它不直接利尿，不是单纯血管扩张药，不阻滞钙通道，也不阻断α受体，这些均非其主要机制"},{"q":"长期使用血管紧张素转化酶抑制药最常见的不良反应是","o":["首剂低血压","咳嗽","高血钾","低血糖","肾功能损伤"],"a":1,"e":"ACEI抑制缓激肽降解，使缓激肽和P物质蓄积，刺激呼吸道引起干咳，是长期应用最常见的不良反应，常致停药。首剂低血压多见于开始时，高血钾、肾功能损伤虽可发生但不如咳嗽常见；低血糖并非ACEI典型不良反应"},{"q":"下列药物具有降糖和抗利尿作用的是","o":["甲苯磺丁脲","格列吡嗪","苯乙双胍","二甲双胍","氯磺丙脲"],"a":4,"e":"氯磺丙脲为第一代磺酰脲类降糖药，还能促进抗利尿激素分泌、增强其对集合管的作用，减少尿量，可用于尿崩症，兼具降糖和抗利尿作用。甲苯磺丁脲、格列吡嗪仅有降糖作用；苯乙双胍、二甲双胍为双胍类，降糖但不抗利尿"},{"q":"青霉素对下列何种疾病基本无效","o":["梅毒","非典型性肺炎","破伤风","猩红热","大叶性肺炎"],"a":1,"e":"青霉素抑制细菌细胞壁合成，对有细胞壁的细菌有效。非典型性肺炎多由支原体、衣原体或病毒引起，支原体无细胞壁，病毒无细胞结构，青霉素对其基本无效，治疗用大环内酯类或四环素类。梅毒螺旋体、破伤风杆菌、溶血性链球菌、肺炎球菌所致感染青霉素均有效"},{"q":"强心苷中毒最常见的早期症状是","o":["心动过缓","室性早搏","视物模糊","头痛、失眠","厌食、恶心、呕吐"],"a":4,"e":"强心苷中毒最常见的早期表现是胃肠道反应，如厌食、恶心、呕吐，与其刺激延髓催吐化学感受区有关。心动过缓、室性早搏为心脏毒性表现，多在稍后的严重阶段出现；视物模糊等视觉异常及头痛失眠为中枢症状，出现较晚，故胃肠道症状最常见最早"},{"q":"具有抗动脉粥样硬化作用的脂蛋白是","o":["LDL","HDL","IDL","Apo B","VLDL"],"a":1,"e":"高密度脂蛋白（HDL）介导胆固醇逆向转运，将外周组织胆固醇运回肝脏代谢排泄，并有抗氧化、抗炎作用，是抗动脉粥样硬化的保护性脂蛋白。LDL、VLDL、IDL及含Apo B的脂蛋白均促进胆固醇沉积、致动脉粥样硬化，作用相反"},{"q":"能与强心苷竞争Na＋-K＋-ATP酶的抗心律失常药是","o":["利多卡因","苯妥英钠","普萘洛尔","普罗帕酮","胺碘酮"],"a":1,"e":"苯妥英钠可与强心苷竞争Na＋-K＋-ATP酶，恢复该酶活性，并抑制强心苷中毒所致的室性心律失常，是治疗强心苷中毒心律失常的常用药。利多卡因、普萘洛尔、普罗帕酮、胺碘酮虽可抗心律失常，但不通过竞争Na＋-K＋-ATP酶发挥解毒作用"},{"q":"双嘧达莫是","o":["纤溶药","抗纤维蛋白溶解药","抗血小板药","促凝血药","抗贫血药"],"a":2,"e":"双嘧达莫抑制磷酸二酯酶、升高血小板cAMP，并抑制腺苷再摄取，从而抑制血小板聚集，属抗血小板药，常与阿司匹林合用预防血栓。纤溶药如链激酶用于溶栓；抗纤溶药如氨甲苯酸止血；促凝血药和抗贫血药作用各异，均非双嘧达莫所属类别"},{"q":"抑制胆固醇在肝脏合成的药物是","o":["考来烯胺","烟酸","非诺贝特","阿托伐他汀","阿昔莫司"],"a":3,"e":"阿托伐他汀为他汀类药物，竞争性抑制HMG-CoA还原酶，阻断肝脏胆固醇合成，反馈性增加LDL受体而降低血脂。考来烯胺在肠道结合胆汁酸减少重吸收；烟酸、阿昔莫司抑制脂解；非诺贝特激活PPARα主要降甘油三酯，均非抑制肝脏胆固醇合成"},{"q":"乙酰胆碱可引起","o":["心率增加","血管舒张","胃肠平滑肌舒张","瞳孔扩大","腺体分泌减少"],"a":1,"e":"乙酰胆碱激动血管内皮M3受体，促使内皮释放NO，NO扩散至平滑肌激活鸟苷酸环化酶，使血管舒张。它使心率减慢而非增加；促进胃肠平滑肌收缩而非舒张；使瞳孔缩小而非扩大；促进腺体分泌而非减少，故血管舒张为其正确效应"},{"q":"非甾体类抗炎药对以下哪种疼痛类型无效","o":["牙痛","痛经","一过性刺痛","癌症骨转移痛","产后疼痛"],"a":2,"e":"非甾体抗炎药通过抑制环氧酶减少前列腺素合成，对慢性钝痛如牙痛、痛经、癌症骨转移痛、产后疼痛疗效好。一过性刺痛持续时间极短、机制不同于前列腺素介导的炎症痛，NSAIDs无能为力，需用其他镇痛方式，故一过性刺痛为无效类型"},{"q":"合并重度感染的糖尿病患者应选用的药物是","o":["甲苯磺丁脲","格列苯脲","苯乙双胍","正规胰岛素","精蛋白锌胰岛素"],"a":3,"e":"正规胰岛素为短效胰岛素，起效快、作用时间短，可静脉给药精确控制，适用于合并重度感染、酮症酸中毒等应激状态的糖尿病，便于随时调整剂量。甲苯磺丁脲、格列苯脲为口服降糖药，应激时疗效不足；苯乙双胍易致乳酸酸中毒；精蛋白锌胰岛素起效慢，不适合急救"},{"q":"下列哪个药物因肝毒性较大目前已撤出治疗阿尔茨海默症的市场","o":["石杉碱甲","加兰他敏","多奈哌齐","利斯的明","他克林"],"a":4,"e":"他克林为第一代中枢胆碱酯酶抑制剂，因肝毒性较大已撤出阿尔茨海默病治疗市场。石杉碱甲、加兰他敏、多奈哌齐、利斯的明均为较新的胆碱酯酶抑制剂，肝毒性相对较小，仍在临床使用，其中我国自主研发的石杉碱甲安全性良好"},{"q":"强心苷的临床应用有","o":["窦性心动过缓","心房扑动","传导阻滞","室性心动过速","室颤"],"a":1,"e":"强心苷减慢房室传导、减慢心室率，用于心房颤动和心房扑动，通过控制心室率改善症状，也可治疗慢性心功能不全。窦性心动过缓、传导阻滞使用强心苷会加重抑制；室性心动过速、室颤为强心苷中毒表现，属禁忌，故房扑为其应用之一"},{"q":"氨基糖苷类抗生素的不良反应不包括","o":["耳毒性","肾毒性","肝毒性","过敏反应","神经肌肉阻断作用"],"a":2,"e":"氨基糖苷类主要不良反应有耳毒性、肾毒性、神经肌肉阻断作用和过敏反应，前二者较为突出。肝毒性并非其典型不良反应，该类药物主要经肾排泄、少见肝损害，故不属于其不良反应；其余四项均为氨基糖苷类已知毒性"},{"q":"主要毒性是视神经炎的药物","o":["乙胺丁醇","异烟肼","利福平","链霉素","吡嗪酰胺"],"a":0,"e":"乙胺丁醇主要不良反应为视神经炎，表现为视力下降、视野缩小和红绿色盲，剂量过大或疗程长时易发生，停药多可恢复。异烟肼主要致周围神经炎和肝毒性；利福平肝毒性和橘红色分泌物；链霉素耳肾毒性；吡嗪酰胺致高尿酸血症，均不以视神经炎为主"},{"q":"治疗月经痛可选用药","o":["对乙酰氨基酚","吗啡","哌替啶","阿托品","可待因"],"a":0,"e":"痛经与子宫内膜前列腺素含量增高有关，对乙酰氨基酚抑制中枢环氧酶、减少前列腺素合成，可有效缓解痛经且胃肠刺激较小。吗啡、哌替啶、可待因为阿片类，成瘾性强，不用于痛经；阿托品解痉但非首选；故对乙酰氨基酚最合适"},{"q":"高血压患者口服普萘洛尔吸收良好，但经过肝脏后仅有30%的药量达体循环，以致血药浓度较低，原因是","o":["化疗指数低","效价强度高","药物效能低","首过消除多","药物排泄快"],"a":3,"e":"普萘洛尔口服吸收良好，但经门静脉进入肝脏时被大量代谢灭活，仅约30%药量进入体循环，此为首过消除（首过效应）强所致，故口服生物利用度低、血药浓度低。化疗指数、效价强度、药物效能是药效学参数，排泄快属消除，均非口服后药量锐减的原因"},{"q":"磺胺类药物的作用机制是","o":["与PABA竞争二氢蝶酸合酶，阻止细菌二氢叶酸合成","抑制二氢叶酸还原酶","与PBP结合，抑制细菌细胞壁合成","抑制细菌蛋白质合成","抑制细菌DNA回旋酶"],"a":0,"e":"磺胺类与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合酶，阻断细菌二氢叶酸合成，进而影响核酸合成而抑菌。抑制二氢叶酸还原酶是甲氧苄啶、甲氨蝶呤；与PBP结合抑制细胞壁合成是青霉素类；抑制蛋白质合成是氨基糖苷类；抑制DNA回旋酶是喹诺酮类"},{"q":"华法林过量出血时可用的拮抗药是","o":["维生素C","维生素K","鱼精蛋白","氨甲苯酸","氨甲环酸"],"a":1,"e":"华法林为维生素K环氧化物还原酶抑制剂，阻断维生素K依赖凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成而抗凝，过量出血时补充维生素K可恢复凝血因子合成而拮抗。维生素C无此作用；鱼精蛋白拮抗肝素；氨甲苯酸、氨甲环酸为抗纤溶药，不针对华法林机制"},{"q":"酚妥拉明兴奋心脏的主要机理是","o":["直接兴奋心肌","反射性兴奋交感神经","直接激动心脏β1受体","阻断心脏M受体","直接兴奋交感神经中枢"],"a":1,"e":"酚妥拉明阻断α受体、扩张血管、降低血压，通过压力感受器反射性兴奋交感神经，使心率加快、心收缩力增强，即反射性兴奋交感神经。它不直接兴奋心肌，也不直接激动β1受体；心脏以β受体为主，无M受体阻断兴奋之说；亦非直接兴奋中枢，故反射机制为主要原因"},{"q":"属于二氢吡啶类钙通道阻滞药的是","o":["维拉帕米","地尔硫䓬","硝苯地平","氟桂利嗪","普尼拉明"],"a":2,"e":"硝苯地平为典型二氢吡啶类钙通道阻滞药，主要阻滞血管平滑肌L型钙通道，扩张血管降压，对心脏抑制弱。维拉帕米为苯烷胺类，地尔硫䓬为苯硫䓬类，均属非二氢吡啶类且抑制心脏；氟桂利嗪、普尼拉明非二氢吡啶类，故硝苯地平为答案"},{"q":"丙硫氧嘧啶最严重的不良反应是","o":["药疹、药热","关节痛、淋巴结肿大","腹痛、腹泻、恶心、呕吐","血管神经性水肿，喉头水肿","粒细胞缺乏症"],"a":4,"e":"丙硫氧嘧啶为硫脲类抗甲状腺药，抑制甲状腺激素合成，最严重不良反应是粒细胞缺乏症，可致严重感染，用药须监测血象。药疹药热、关节痛、腹痛腹泻、血管神经性水肿均较常见但程度较轻，远不及粒细胞缺乏凶险，故粒细胞缺乏症为最严重者"},{"q":"属于n-6型多烯脂肪酸的药物是","o":["亚油酸","α-亚麻油酸","二十碳五烯酸","二十二碳六烯酸","烟酸"],"a":0,"e":"亚油酸为十八碳二烯酸，双键位于第九、十二位，属n-6系必需脂肪酸，体内可转变为花生四烯酸。α-亚麻油酸为n-3系；二十碳五烯酸、二十二碳六烯酸均属n-3系多烯脂肪酸；烟酸为维生素B3类调脂药，不属多烯脂肪酸"},{"q":"叶酸在体内的活性形式是","o":["四氢叶酸","5-甲基四氢叶酸","叶酸","二氢叶酸","5，10-甲烯四氢叶酸"],"a":0,"e":"叶酸本身无活性，须经二氢叶酸还原酶还原为四氢叶酸，后者作为一碳单位载体参与嘌呤及胸苷酸合成，是其在体内的活性形式。二氢叶酸为还原中间产物；5-甲基四氢叶酸、5,10-甲烯四氢叶酸是四氢叶酸携带一碳单位的具体形式，均归属于四氢叶酸，并非独立于其外的活性形式"},{"q":"对支气管平滑肌选择性较高的药物是","o":["异丙托溴铵","溴丙胺太林","溴甲东莨菪碱","溴甲后马托品","溴化甲哌佐酯"],"a":0,"e":"异丙托溴铵为季铵化阿托品衍生物，吸入给药不易吸收，可直接阻断支气管平滑肌M3受体而舒张气道，对支气管选择性高。溴丙胺太林、溴甲东莨菪碱、溴化甲哌佐酯主要作用于胃肠平滑肌，用于解痉止痛；溴甲后马托品主要用于眼科散瞳，均无支气管高选择性"},{"q":"强心苷中毒所致室性心律失常可选用","o":["利多卡因","美西律","普萘洛尔","地尔硫䓬","普鲁卡因胺"],"a":0,"e":"强心苷中毒抑制Na⁺-K⁺-ATP酶，细胞内钙超载触发室性心律失常；利多卡因阻断心室肌钠通道、缩短动作电位时程，静脉给药起效快，为优选。美西律作用类似但多用于慢性维持；普萘洛尔、地尔硫䓬抑制传导，可加重阻滞；普鲁卡因胺延长QT，均非适宜"},{"q":"可诱发或加重支气管哮喘的药物是","o":["普萘洛尔","沙丁胺醇","阿托品","哌唑嗪","酚妥拉明"],"a":0,"e":"普萘洛尔为非选择性β受体阻断药，阻断支气管平滑肌β2受体，使气道收缩、阻力增加，可诱发或加重哮喘，哮喘者禁用。沙丁胺醇为β2受体激动药，舒张支气管、用于平喘；阿托品阻断M受体亦能松弛气道；哌唑嗪、酚妥拉明阻断α受体，对气道无明显收缩作用"},{"q":"下述何种药物中毒引起血压下降时，禁用肾上腺素","o":["苯巴比妥","地西泮","氯丙嗪","水合氯醛","吗啡"],"a":2,"e":"氯丙嗪阻断α受体，使肾上腺素激动α的缩血管作用被取消，而β2舒血管作用占优势，反致血压更低，故其中毒低血压时禁用肾上腺素。苯巴比妥、地西泮、水合氯醛中毒以中枢抑制为主，吗啡中毒低血压主要因血管扩张，均不出现此翻转现象"},{"q":"吗啡的镇痛作用原理","o":["激动阿片受体，模拟内阿片肽","阻断疼痛冲动向大脑皮质传导","阻断阿片受体，拮抗内阿片肽","抑制体内致痛介质的合成和释放","降低痛觉感受器对疼痛刺激的敏感性"],"a":0,"e":"吗啡为阿片受体激动药，激动中枢及外周感觉神经末梢的μ等阿片受体，模拟内源性阿片肽，抑制痛觉传导并改变情绪反应而镇痛。阻断阿片受体是纳洛酮的作用，可拮抗吗啡；阻断感觉传导、抑制致痛介质合成分别为局麻药和解热镇痛药机制，降低感受器敏感性非其镇痛原理"},{"q":"下列属于选择性β1受体阻断药的是","o":["普萘洛尔","纳多洛尔","拉贝洛尔","卡维地洛","美托洛尔"],"a":4,"e":"美托洛尔为选择性β1受体阻断药，主要阻断心脏β1，减慢心率、降低心肌收缩力，对β2影响小，对支气管影响较轻。普萘洛尔、纳多洛尔为非选择性β阻断药，兼阻β2；拉贝洛尔兼有α、β阻断作用；卡维地洛兼阻α1，均不属选择性β1阻断药"},{"q":"可乐定的降压机制是","o":["激动中枢的I1咪唑啉受体","阻断中枢的α2受体","激动中枢的α1受体","激动中枢的M受体","激动中枢的多巴胺受体"],"a":0,"e":"可乐定激动延髓I1咪唑啉受体，并激动突触前α2受体减少去甲肾上腺素释放，抑制交感传出而降压，I1受体为其主要机制。阻断中枢α2受体会增强交感、升高血压，方向相反；激动中枢α1、M或多巴胺受体均无降压作用"},{"q":"既可用于治疗青光眼，又可用于脑水肿的药物是","o":["氢氯噻嗪","呋塞米","螺内酯","甘露醇","阿米洛利"],"a":3,"e":"甘露醇静脉给药后提高血浆渗透压，使组织水分进入血管，降低颅内压和眼压，故既治脑水肿又治青光眼。氢氯噻嗪、螺内酯、阿米洛利为利尿药，主要排钠利尿，降颅压、眼压作用弱；呋塞米虽强效利尿并可用于脑水肿，但对青光眼非首选，两者兼顾者首推甘露醇"},{"q":"介导阿托品对膀胱收缩抑制作用最重要的M受体亚型是","o":["M1受体","M2受体","M3受体","M4受体","M5受体"],"a":2,"e":"膀胱逼尿肌平滑肌以M3受体为主，阿托品阻断M3受体，抑制逼尿肌收缩、降低膀胱内压，用于缓解尿频尿急。M2受体主要分布于心肌，介导心率减慢；M1多在神经节和胃壁细胞；M4、M5主要在中枢，均非抑制膀胱收缩的主要亚型"},{"q":"治疗糖尿病昏迷应选用","o":["甲苯磺丁脲","格列齐特","地特胰岛素","正规胰岛素","精蛋白锌胰岛素"],"a":3,"e":"糖尿病昏迷需迅速降糖，正规胰岛素为短效普通胰岛素，可静脉给药、起效快，为抢救首选。地特胰岛素为长效基础胰岛素，精蛋白锌胰岛素亦长效，起效慢不适于急救；甲苯磺丁脲、格列齐特为口服磺酰脲类，依赖残存β细胞功能且起效慢，均不用于昏迷抢救"},{"q":"可治疗心房纤颤的药物是","o":["利多卡因","美西律","苯妥英钠","胺碘酮","普鲁卡因胺"],"a":3,"e":"胺碘酮为Ⅲ类广谱抗心律失常药，延长心房肌动作电位时程和有效不应期，可转复并维持窦性心律，用于心房纤颤。利多卡因、美西律、苯妥英钠偏作用于心室肌，对房性心律失常疗效差；普鲁卡因胺虽属Ⅰa类，但维持窦律和安全性不及胺碘酮，故本题以胺碘酮为宜"},{"q":"苯巴比妥长期应用产生耐受性的主要原因是","o":["重分布，贮存于脂肪组织内","被血浆中假性胆碱酯酶迅速水解破坏","以原型从肾脏排泄加快","诱导肝药酶加快自身代谢","GABA受体下调"],"a":3,"e":"苯巴比妥为肝药酶诱导剂，长期应用诱导肝细胞色素P450合成，加速自身代谢清除，产生耐受性，需增量维持疗效。重分布为硫喷妥钠作用短暂的原因；假性胆碱酯酶水解与琥珀胆碱相关；以原型肾排加快、GABA受体下调均非苯巴比妥耐受的主要机制"},{"q":"氯丙嗪过量引起血压下降时，应选用的药物是","o":["肾上腺素","去甲肾上腺素","阿托品","多巴胺","异丙肾上腺素"],"a":1,"e":"氯丙嗪阻断α受体致血管扩张、血压下降，须用α受体激动药去甲肾上腺素收缩血管升压。肾上腺素因α受体被阻断，β2扩血管占优势会翻转降压，故禁用；多巴胺在α受体阻断时升压效果差；阿托品、异丙肾上腺素不能有效纠正低血压，反可加快心率"},{"q":"下列哪个药物是单纯疱疹病毒感染的首选药物","o":["齐多夫定","拉米夫定","糖皮质激素","阿昔洛韦","阿糖腺苷"],"a":3,"e":"阿昔洛韦为抗疱疹病毒药，在感染细胞内经病毒胸苷激酶磷酸化后抑制病毒DNA聚合酶，对单纯疱疹病毒疗效好、毒性低，为首选。齐多夫定、拉米夫定为抗逆转录病毒药；阿糖腺苷毒性较大、已少用；糖皮质激素抑制免疫，可加重病毒感染，均非首选"},{"q":"给予普萘洛尔后，异丙肾上腺素的降压作用将会","o":["进一步加强","减弱","转为升压","先升压再降压","先降压再升压"],"a":1,"e":"异丙肾上腺素激动β2受体，舒张骨骼肌血管、降低外周阻力而降压；普萘洛尔阻断β受体后，其β2扩血管效应被拮抗，降压作用减弱。该药以β效应为主，无显著α缩血管作用，故不会转为升压或出现先升后降的双相变化，进一步加强亦不成立"},{"q":"阿托品禁用于","o":["流涎症","前列腺肥大","心动过缓","胃痉挛","虹膜睫状体炎"],"a":1,"e":"阿托品阻断M受体，松弛膀胱逼尿肌、收缩尿道括约肌，可加重排尿困难，故前列腺肥大者禁用，以免诱发尿潴留。流涎症用其抑制腺体分泌，心动过缓用其加快心率，胃痉挛用其解痉，虹膜睫状体炎用其散瞳消炎，均为适应证"},{"q":"heparin的中文名是","o":["双香豆素","肝素","华法林","噻氯匹啶","阿司匹林"],"a":1,"e":"heparin即肝素，为含硫酸基的黏多糖，通过激活抗凝血酶Ⅲ发挥抗凝作用，属抗凝血药。双香豆素、华法林为香豆素类口服抗凝药；噻氯匹啶为抗血小板药；阿司匹林为环氧酶抑制剂，均非heparin的中文名"},{"q":"噻嗪类利尿药的利尿作用机制是","o":["增加肾小球滤过率","抑制近曲小管碳酸酐酶，减少H＋-Na＋交换","抑制髓袢升支粗段髓质部Na＋-K＋-Cl－共转运子","抑制远曲小管近端Na＋-Cl－共转运子","抑制远曲小管K＋-Na＋交换"],"a":3,"e":"噻嗪类利尿药抑制远曲小管近端Na⁺-Cl⁻共转运子，减少钠氯重吸收，产生中等强度利尿，同时促进钾排出。抑制髓袢升支粗段Na⁺-K⁺-Cl⁻共转运子是呋塞米等袢利尿药机制；抑制近曲小管碳酸酐酶为乙酰唑胺作用；抑制K⁺-Na⁺交换属保钾利尿药；噻嗪类不增加肾小球滤过率"},{"q":"临床最常用的抗躁狂症药是","o":["碳酸锂","氯丙嗪","舒必利","氯普噻吨","氟西汀"],"a":0,"e":"碳酸锂为治疗躁狂症及双相障碍的首选和常用药，抑制肌醇磷酸酶、干扰神经递质信号，稳定情绪。氯丙嗪、舒必利、氯普噻吨为抗精神病药，主要控制精神分裂症阳性症状；氟西汀为SSRI类抗抑郁药，均非抗躁狂常用药"},{"q":"具有一定肾毒性的β-内酰胺类抗生素是","o":["青霉素G","耐酶青霉素类","半合成广谱青霉素类","第一代头孢菌素类","第三代头孢菌素类"],"a":3,"e":"第一代头孢菌素（如头孢唑林）有一定肾毒性，大剂量或与氨基糖苷类合用时可致肾小管损伤。青霉素G、耐酶青霉素及半合成广谱青霉素基本无肾毒性；第三代头孢菌素肾毒性显著降低，故肾毒性主要见于第一代头孢菌素类"},{"q":"下列关于离子通道的选择性，说法错误的是","o":["钠通道是选择性允许Na+跨膜通过的离子通道，维持细胞膜的行为及其传导","膜上存在两大类钙离子通道：电压门控型和配体门控型","钾通道按照电生理特性可分为电压依赖性、钙依赖性、内向整流钾通道","氯离子通道可参与兴奋性细胞稳定膜电位，抑制动作电位的产生等","其他阳性离子也有部分可以通过钠、钾、钙通道进行跨膜转运"],"a":4,"e":"离子通道对离子具有高度选择性，钠、钾、钙通道分别主要通透相应离子，其他阳离子一般不能通过，故其他阳性离子也可部分通过的表述错误。钠通道选择性通透Na⁺；钙通道分电压门控和配体门控型；钾通道分电压依赖、钙依赖及内向整流型；氯通道参与稳定膜电位、抑制动作电位产生，均表述正确"},{"q":"作用机制为抑制DNA合成的药物是","o":["磺胺类","万古霉素","异烟肼","红霉素","喹诺酮类"],"a":4,"e":"喹诺酮类抑制细菌DNA回旋酶（拓扑异构酶Ⅱ）和拓扑异构酶Ⅳ，阻碍DNA复制而抗菌，作用机制为抑制DNA合成。磺胺类抑制二氢蝶酸合酶、干扰叶酸合成；万古霉素抑制细胞壁合成；异烟肼抑制分枝菌酸合成；红霉素抑制蛋白质合成，均不以抑制DNA合成为机制"},{"q":"抗心绞痛药共有的药理作用是","o":["降低儿茶酚胺的生成","扩张冠状动脉","降低心肌的耗氧量","降低外周血管阻力","减慢心率"],"a":2,"e":"各类抗心绞痛药通过降低心肌耗氧量或增加冠脉供血缓解心绞痛，降低心肌耗氧量是硝酸酯、β阻断药、钙拮抗剂的共同作用。扩张冠脉并非全都具备，β阻断药反而收缩冠脉；降低儿茶酚胺、减慢心率主要为β阻断药作用；降低外周阻力主要为硝酸酯和钙拮抗剂，均非全部共有"},{"q":"酚妥拉明扩张血管主要是因为","o":["阻断NA能神经末梢突触前膜α2受体","兴奋血管平滑肌β2受体","阻断血管平滑肌M受体","阻断血管平滑肌α1受体","兴奋血管平滑肌M受体"],"a":3,"e":"酚妥拉明为α受体阻断药，阻断血管平滑肌α1受体，取消内源性去甲肾上腺素的缩血管作用，使血管扩张、外周阻力下降。阻断突触前α2受体会增加去甲肾上腺素释放，并非主要扩血管原因；血管平滑肌的β2扩血管作用与本品无关；M受体阻断或兴奋亦非其机制"},{"q":"急性肾衰竭时，与利尿剂配伍增加尿量的药物是","o":["多巴胺","麻黄碱","去甲肾上腺素","异丙肾上腺素","肾上腺素"],"a":0,"e":"多巴胺小剂量激动肾血管D1受体，扩张肾血管、增加肾血流量和肾小球滤过率，与呋塞米等利尿剂合用可增加尿量，用于急性肾衰竭。麻黄碱、去甲肾上腺素、肾上腺素收缩肾血管、减少肾血流；异丙肾上腺素主要兴奋心脏，均不增加尿量"},{"q":"四环素类主要不良反应是","o":["二重感染","灰婴综合征","对第八对脑神经损害","骨髓抑制","神经肌肉接头阻断"],"a":0,"e":"四环素为广谱抗生素，长期或大剂量应用抑制肠道正常菌群，使耐药菌或真菌大量繁殖，引起二重感染，为其主要不良反应。灰婴综合征为氯霉素特有；第八对脑神经损害、神经肌肉接头阻断为氨基糖苷类；骨髓抑制多见于氯霉素和抗肿瘤药"},{"q":"阿利吉仑发挥降压作用主要是通过","o":["结合肾素作用于肾素-血管紧张素系统","直接抑制血管紧张素Ⅰ","直接抑制血管紧张素Ⅱ","直接抑制血管紧张素受体亚型1","利尿作用"],"a":0,"e":"阿利吉仑为直接肾素抑制剂，与肾素活性部位结合，阻断肾素将血管紧张素原转化为血管紧张素Ⅰ，从源头抑制肾素-血管紧张素-醛固酮系统而降压。其不直接抑制血管紧张素Ⅰ、Ⅱ，也不阻断AT1受体，更无利尿作用，这些分别为ACEI下游、ARB及利尿药的机制"},{"q":"糖皮质激素类药物隔日疗法的给药方式是","o":["隔日一次，下午4时给药","隔日一次，中午12时给药","隔日一次，晨8时给药","隔日一次，晚8时给药","隔日一次，午夜12时给药"],"a":2,"e":"糖皮质激素分泌具有昼夜节律，清晨8时分泌达高峰，此时下丘脑-垂体-肾上腺轴对负反馈抑制最不敏感。隔日晨8时一次给药可减轻对肾上腺皮质功能的抑制，同时维持疗效。下午、中午、晚间或午夜给药均偏离生理高峰，达不到减轻轴抑制的目的"},{"q":"下列关于塞来昔布的不良反应，正确的是","o":["磺胺类过敏的患者可以使用","胃肠道不良反应较轻","出血风险较高","几乎不会发生肾损伤","心血管系统不良反应较轻"],"a":1,"e":"塞来昔布为选择性COX-2抑制剂，较少抑制胃黏膜COX-1，故胃肠道不良反应较轻。其含磺酰胺结构，磺胺过敏者禁用；不抑制血小板COX-1，出血风险不高且心血管风险并未减轻；肾血流依赖前列腺素调节，肾功能不全者仍可致肾损伤，并非几乎不发生"},{"q":"普萘洛尔的临床应用不包括","o":["室上性心动过速","心绞痛","高血压","心房纤颤","重度房室传导阻滞"],"a":4,"e":"普萘洛尔阻断β受体，减慢心率、抑制房室传导，可用于室上性心动过速、心房纤颤、心绞痛和高血压。重度房室传导阻滞者使用会进一步抑制传导、加重病情，属禁忌，故不属于其临床应用；其余均为β阻断药的适应证"},{"q":"胆道平滑肌痉挛引起的胆绞痛应选用","o":["哌替啶＋美沙酮","阿托品＋纳洛酮","吗啡＋纳洛酮","吗啡＋哌替啶","阿托品＋哌替啶"],"a":4,"e":"胆道平滑肌痉挛致胆绞痛，单用阿托品解痉镇痛效果有限，单用吗啡等阿片药又可引起Oddi括约肌痉挛加重绞痛，故采用阿托品解痉联合哌替啶镇痛，两者协同。纳洛酮为阿片受体拮抗剂，可对抗镇痛；美沙酮、哌替啶单用或两两配伍均非胆绞痛的规范方案"},{"q":"选择性低的药物，在治疗量下表现为","o":["毒性较大","副作用较多","过敏反应剧烈","容易成瘾","容易耐药"],"a":1,"e":"药物选择性低意味着可作用于多个受体或组织，治疗剂量下除治疗作用外还累及其他靶器官，表现为副作用较多。毒性较大与剂量过大相关；过敏反应与免疫反应性有关，与选择性无关；成瘾、耐药属依赖性或耐受，均非选择性低的直接表现"},{"q":"在长期用药过程中，突然停药易引起严重高血压，这种药是","o":["普萘洛尔","肼屈嗪","哌唑嗪","氨氯地平","吲达帕胺"],"a":0,"e":"长期应用普萘洛尔等β受体阻断药，突然停药可出现反跳现象，因β受体上调、对内源性儿茶酚胺敏感性增高，致心率加快、血压骤升，故应逐步减量。肼屈嗪、哌唑嗪、氨氯地平、吲达帕胺停药后一般无如此明显的反跳性高血压"},{"q":"下列哪项不是抗菌药物联合用药的目的","o":["提高疗效","降低毒性","减少耐药性的发生","延长作用时间","扩大抗菌范围"],"a":3,"e":"抗菌药联合用药目的在于提高疗效、扩大抗菌范围、降低毒性及减少或延缓耐药性产生。延长作用时间需通过制剂工艺或给药途径实现，不属于联合用药目的，故该项为答案"},{"q":"主要用于治疗伴有醛固酮增高的顽固性水肿的药物是","o":["甘露醇","螺内酯","呋塞米","氨苯蝶啶","氢氯噻嗪"],"a":1,"e":"螺内酯为醛固酮受体拮抗剂，竞争性阻断醛固酮对远曲小管和集合管的作用，抑制钠水重吸收、留钾排钠，对醛固酮增高所致顽固性水肿针对性强。甘露醇为脱水药；呋塞米、氢氯噻嗪为排钾利尿药；氨苯蝶啶虽保钾但不拮抗醛固酮，均非针对醛固酮增高者"},{"q":"甲亢术前准备的正确给药方式是","o":["只给硫脲类","只给碘化物","给予放射性碘","先给硫脲类，术前两周再给碘化物","先给碘化物，术前两周再给硫脲类药物"],"a":3,"e":"甲亢术前先用硫脲类抑制甲状腺激素合成，使症状控制；术前两周加用碘化物，使腺体缩小变硬、减少充血，利于手术并减少出血。只给硫脲类腺体仍充血脆弱；单用碘化物久用可致脱逸复发；放射性碘不用于术前准备；先碘后硫脲的顺序颠倒，不符合要求"},{"q":"格列齐特的主要作用机制是","o":["促进葡萄糖降解","拮抗胰高血糖素作用","刺激胰岛素","刺激胰岛β细胞释放胰岛素","减少胰外组织对胰岛素的敏感性和糖的利用"],"a":3,"e":"格列齐特为磺酰脲类降糖药，阻断胰岛β细胞ATP敏感钾通道，使膜去极化、钙内流，触发胰岛素释放，故主作用于β细胞促泌。促进葡萄糖降解、拮抗胰高血糖素非其主要机制；减少组织对胰岛素敏感性和糖利用会升高血糖，方向相反；笼统地说刺激胰岛素不如促β细胞释放准确"},{"q":"去甲肾上腺素减慢心率是由于","o":["降低外周阻力","抑制心脏传导","直接的负性频率作用","抑制心血管中枢的调节","血压升高引起的继发性效应"],"a":4,"e":"去甲肾上腺素激动α受体使外周血管收缩、血压显著升高，通过压力感受器反射性兴奋迷走神经，使心率减慢，属血压升高后的继发性效应。其无直接负性频率作用，也不抑制心脏传导或心血管中枢；降低外周阻力与其缩血管升压作用相反"},{"q":"下列哪个是口服长效（1周1次）的抗精神分裂症药","o":["五氟利多","氯氮平","利培酮","氯丙嗪","舒必利"],"a":0,"e":"五氟利多为长效口服抗精神病药，每周服用一次即可维持疗效，适用于精神分裂症维持治疗。氯氮平、利培酮、氯丙嗪、舒必利均需每日给药，不属每周一次的长效口服制剂，故不作为答案"},{"q":"苯二氮䓬类药物不能单独用于下列何种情况","o":["入睡困难","焦虑症","抗惊厥","全身麻醉","癫痫持续状态"],"a":3,"e":"苯二氮䓬类具有抗焦虑、镇静催眠、抗惊厥、抗癫痫及中枢性肌松作用，可用于入睡困难、焦虑、惊厥及癫痫持续状态。但其镇痛和肌松不足以达到外科手术要求，不能单独用于全身麻醉，仅可作麻醉前给药或辅助用药"},{"q":"药物经一级动力学消除的特点是","o":["恒比消除，半衰期恒定","恒量消除，半衰期恒定","恒比消除，半衰期不恒定","恒量消除，半衰期不恒定","消除速率与给药剂量无关"],"a":0,"e":"一级动力学消除指单位时间内消除恒定比例的药量，消除速率与血药浓度成正比，半衰期恒定，与剂量无关。恒量消除为零级动力学特点；半衰期不恒定与一级动力学矛盾；消除速率与给药剂量无关的说法错误，一级动力学下剂量越大单位时间消除量越多"},{"q":"兼具抗心律失常、抗高血压和抗心绞痛作用的药物是","o":["阿托品","普萘洛尔","异丙肾上腺素","硝酸甘油","可乐定"],"a":1,"e":"普萘洛尔为非选择性β受体阻断药，通过阻断心脏β1降低心率与收缩力，兼具抗心律失常、抗高血压和抗心绞痛作用。阿托品、异丙肾上腺素加快心率；硝酸甘油主要扩血管抗心绞痛，无抗心律失常作用；可乐定仅中枢性降压，均不兼具三效"},{"q":"在药动学模型中，一室模型是指","o":["药物在全身各组织部位的转运速率是相同或者相似的，此时把整个机体视为一个房室","房室代表有腔室解剖部位，把整个机体视为一个房室","药物按两种速率消除，整体视为一个房室","将机体划分为药物分布均匀程度不同的两个独立系统，将整体视为一个房室","药物主要分布到较大的管腔器官，属于一个房室"],"a":0,"e":"一室模型将机体视为一个房室，假定药物在全身各组织间转运速率相同或相似，进入体内后迅速在血浆和组织间达动态平衡，分布均匀。房室是药动学抽象概念，非解剖腔室；按两种速率消除、划分两个独立系统属二室模型；大管腔器官分布或先进入血流量大器官均非一室模型定义"},{"q":"局麻药的作用机制主要是","o":["阻断钙离子通道","阻断钠离子通道","阻断钾离子通道","阻断镁离子通道","阻断氯离子通道"],"a":1,"e":"局麻药与神经细胞膜钠通道结合，阻滞钠内流，抑制动作电位的产生和传导，使感觉尤其痛觉丧失而发挥局麻作用。钙、钾、镁、氯通道阻断分别为钙拮抗剂等的作用，均非局麻药主要机制"},{"q":"可制成喷雾制剂用于耳鼻咽喉科术前使用的药物是","o":["普鲁卡因","布比卡因","丁卡因","可卡因","罗哌卡因"],"a":2,"e":"丁卡因穿透力强、麻醉作用强而持久，常用于黏膜表面麻醉，可制成喷雾剂用于耳鼻咽喉科术前表面麻醉。普鲁卡因穿透力弱，多用于浸润麻醉；布比卡因、罗哌卡因主要用于传导和硬膜外麻醉；可卡因因成瘾性和毒性现已少用"},{"q":"下列关于酚妥拉明药理作用的叙述，正确的是","o":["可阻断M胆碱受体","可激动5-HT受体","可翻转肾上腺素升压效应","可抑制心脏活动，降低心排量","对小静脉无舒张作用"],"a":2,"e":"酚妥拉明阻断α受体，若先给本品再给肾上腺素，肾上腺素的α缩血管作用被阻断，仅剩β2扩血管作用，血压由升转降，即翻转肾上腺素升压效应。本品不阻断M受体、不激动5-HT受体；其阻断α2、反射性兴奋心脏可致心率加快、心输出量增加，且对静脉亦有舒张作用，故其余叙述均错"},{"q":"如果某药在体内的转运与分布符合一房室模型，则该药","o":["仅存在于细胞外液中","高度解离，在体内被迅速消除","仅存在于血液中","转运快，在体内分布迅速达平衡","药物先进入血流量大的器官"],"a":3,"e":"符合一房室模型的药物转运迅速，进入体内后很快在血浆与组织间达到动态平衡，可将机体视为单一房室，以血药浓度推算全身药量。仅存于细胞外液或血液不符合其全身分布；高度解离、迅速消除属药物性质，与房室模型无关；先分布到血流量大器官是分布初期现象，非达平衡特征"},{"q":"患者，老年男性，冠心病10余年，遵医嘱用小剂量阿司匹林防止冠脉血栓形成，其原理是","o":["抑制前列环素合成","抑制血栓素合成","抑制前列环素和血栓素合成","抑制花生四烯酸的合成","抑制磷酸二酯酶"],"a":1,"e":"小剂量阿司匹林不可逆抑制血小板环氧酶，减少血栓素A2生成，抑制血小板聚集，从而预防冠脉血栓形成。前列环素由血管内皮生成、抑制聚集，低剂量阿司匹林对其影响小；同时抑制前列环素和血栓素、抑制花生四烯酸合成、抑制磷酸二酯酶均非小剂量阿司匹林的机制"},{"q":"抗嘌呤代谢的抗癌药是","o":["顺铂","紫杉醇","阿糖胞苷","6-MP","5-FU"],"a":3,"e":"6-巯基嘌呤（6-MP）为嘌呤类似物，干扰嘌呤核苷酸的从头合成与相互转化，属抗嘌呤代谢类抗癌药。顺铂与DNA交联；紫杉醇促进微管聚合并抑制解聚；阿糖胞苷抑制DNA聚合酶；5-FU为嘧啶类似物，均不属抗嘌呤代谢药"},{"q":"某药的t1/2是6小时，如果按0.5g一次，每天3次给药，达到血浆坪值的时间是","o":["5～10小时","10～16小时","17～23小时","24～30小时","31～36小时"],"a":3,"e":"一级动力学给药约经4至5个半衰期达稳态血药浓度（坪值）。t1/2为6小时，4至5个半衰期即24至30小时，故选24～30小时。5～10小时、10～16小时、17～23小时均不足4个半衰期；31～36小时虽已达到但不是达到坪值的最早时间，故以24～30小时为宜"},{"q":"有关哌替啶的叙述，错误的是","o":["镇咳作用与可待因相似","镇痛作用比吗啡弱","成瘾性较吗啡轻","无止泻作用","治疗剂量能引起体位性低血压"],"a":0,"e":"哌替啶无镇咳作用或镇咳作用极弱，不像可待因具有明显镇咳作用，故该项叙述错误。其镇痛作用较吗啡弱、成瘾性较吗啡轻且发生较慢、无止泻作用（不引起便秘），治疗剂量可扩张血管引起体位性低血压，这些均符合哌替啶特点"},{"q":"四环素口服吸收后，分布于哪个部位的药物浓度比血液内的药物浓度高","o":["脑脊液","胆汁","前列腺","唾液腺","细胞外液"],"a":1,"e":"四环素口服吸收后分布广泛，可浓集于胆汁，胆汁中浓度显著高于血药浓度，有利于治疗胆道感染。脑脊液、前列腺、唾液腺中药物浓度均低于血药浓度，且不易透过血脑屏障；细胞外液浓度亦低于血液，故只有胆汁中浓度高于血液"},{"q":"肝细胞的微粒体混合功能氧化酶中，最重要的酶是","o":["单胺氧化酶","细胞色素P450","葡萄糖醛酸转移酶","乙醛脱氢酶","胆碱酯酶"],"a":1,"e":"肝细胞微粒体混合功能氧化酶系以细胞色素P450为核心，参与多数药物的氧化代谢，是药物代谢最重要的酶。单胺氧化酶、乙醛脱氢酶、胆碱酯酶属非微粒体酶；葡萄糖醛酸转移酶催化结合反应，均非最重要的混合功能氧化酶"},{"q":"引起病人对巴比妥类药物产生依赖性的主要原因是","o":["使病人产生欣快感","抑制肝药酶","能诱导肝药酶","停药后快动眼睡眠时间反跳性延长，引起睡眠障碍","受体下调"],"a":3,"e":"巴比妥类缩短快动眼睡眠时相，长期应用停药后出现反跳性快动眼睡眠延长，导致睡眠障碍，迫使患者继续用药，产生依赖。欣快感可促成滥用但非主要依赖机制；巴比妥类诱导而非抑制肝药酶；受体下调并非对本题所指的主要依赖原因"},{"q":"下列具有内在拟交感活性的非选择性β受体阻断药是","o":["吲哚洛尔","噻吗洛尔","醋丁洛尔","普萘洛尔","纳多洛尔"],"a":0,"e":"吲哚洛尔为非选择性β受体阻断药，兼有较强内在拟交感活性，阻断β受体的同时部分激动β受体。噻吗洛尔、纳多洛尔、普萘洛尔为非选择性β阻断药但无内在拟交感活性；醋丁洛尔虽有内在拟交感活性，但为选择性β1阻断药，故非答案"},{"q":"降压时伴有心率加快、心输出量增加和肾素活性增高的药物是","o":["依那普利","可乐定","哌唑嗪","硝苯地平","普萘洛尔"],"a":3,"e":"硝苯地平为二氢吡啶类钙通道阻滞药，扩张外周血管降压，可反射性兴奋交感神经，引起心率加快、心输出量增加和肾素活性升高。依那普利抑制ACE、可乐定抑制中枢交感，均不引起此反射；普萘洛尔减慢心率、抑制肾素释放；哌唑嗪主要引起首剂低血压，无此典型反应"},{"q":"关于糖皮质激素治疗哮喘的叙述，错误的是","o":["发挥局部抗炎作用","可吸入给药","抑制磷脂酶A2","减少白三烯的生成","通过抑制磷酸二酯酶"],"a":4,"e":"糖皮质激素治疗哮喘通过诱导脂皮素、抑制磷脂酶A2，减少白三烯等炎症介质生成，发挥局部抗炎作用，可吸入给药。抑制磷酸二酯酶、升高cAMP是茶碱类药物的作用机制，与糖皮质激素无关，故该项叙述错误"},{"q":"糖尿病患者合并重度感染时宜选用","o":["罗格列酮","磺酰脲类","双胍类","胰岛素","α-葡萄糖苷酶抑制药"],"a":3,"e":"糖尿病患者合并重度感染时处于应激状态，血糖升高明显，需迅速有效控制血糖，胰岛素降糖作用强、起效快，为首选。罗格列酮、双胍类、α-葡萄糖苷酶抑制药起效慢、降糖强度有限；磺酰脲类依赖残存β细胞功能，均不适合重症感染的血糖控制"},{"q":"下列药物可通过血脑屏障的是","o":["乙酰胆碱","毛果芸香碱","卡巴胆碱","醋甲胆碱","氯贝胆碱"],"a":1,"e":"毛果芸香碱为叔胺类生物碱，脂溶性较大，可透过血脑屏障及角膜，故可全身或局部给药。乙酰胆碱、卡巴胆碱、醋甲胆碱、氯贝胆碱为季铵盐，极性大、脂溶性低，不易透过血脑屏障和角膜，主要作用于外周或局部"},{"q":"属三环类抗抑郁药的是","o":["丙米嗪","氯丙嗪","碳酸锂","氟哌啶醇","舒必利"],"a":0,"e":"丙米嗪为典型三环类抗抑郁药，抑制突触前膜对去甲肾上腺素和5-羟色胺的再摄取，提高突触间隙递质浓度而抗抑郁。氯丙嗪、氟哌啶醇、舒必利为抗精神病药；碳酸锂为抗躁狂药，均不属三环类抗抑郁药"},{"q":"下列不属于抗心律失常药物作用方式的是","o":["阻滞钠通道","拮抗心脏的交感效应","阻滞钾通道","阻滞钙通道","阻滞水通道"],"a":4,"e":"抗心律失常药主要通过阻滞钠通道、钾通道、钙通道或拮抗心脏交感效应来纠正心律失常。水通道（水孔蛋白）与心肌电活动无关，阻滞水通道不属于抗心律失常药的作用方式，故答案为该项"},{"q":"下列关于半最大效应浓度的描述中，正确的是","o":["常用于表示药物的亲和力","指能引起50%最大效应的药物浓度","常见的表述形式为ED5和ED50","常见的表述形式为LD50和LD95","常见的表述形式为TD50"],"a":1,"e":"半最大效应浓度（EC50）指能引起50%最大效应的药物浓度，是评价药物效应强度的指标。表示亲和力常用Kd或pD2；ED5、ED50、LD50、TD50分别涉及剂量效应和安全性评价，均非半最大效应浓度的含义，故只有该项描述正确"},{"q":"某药t1/2为12小时，单次静脉给药后，最少几天后血药浓度小于高峰浓度的2%","o":["1天","2天","3天","4天","6天"],"a":2,"e":"药物约经6个半衰期后体内剩余量低于峰浓度的2%。t1/2为12小时，6个半衰期恰为72小时即3天，故最少3天后血药浓度低于峰浓度的2%。1天、2天不足6个半衰期，4天、6天虽满足但非最少时间，故答案为3天"},{"q":"抑制T4转化为T3的抗甲状腺药物是","o":["放射性碘","卡比马唑","甲苯磺丁脲","碘制剂","丙硫氧嘧啶"],"a":4,"e":"丙硫氧嘧啶除抑制甲状腺激素合成外，还能抑制外周组织5-脱碘酶，阻断T4向T3转化，较快降低血中活性激素水平，适用于甲状腺危象。卡比马唑需转化为甲巯咪唑起作用，主要抑制合成；碘制剂抑制释放；放射性碘破坏腺体；甲苯磺丁脲为降糖药，均无此作用"},{"q":"可引起血钾增高的药物是","o":["氢氯噻嗪","呋塞米","依他尼酸","吲哒帕胺","氨苯蝶啶"],"a":4,"e":"氨苯蝶啶为保钾利尿药，阻断远曲小管和集合管钠通道，减少钠重吸收并抑制钾分泌，可使血钾升高。氢氯噻嗪、呋塞米、依他尼酸、吲哒帕胺均为排钾利尿药，促进钾排出，可引起低血钾，而非高血钾"},{"q":"有机磷农药中毒的机制是","o":["直接兴奋M受体","直接兴奋N受体","抑制胆碱酯酶活性","抑制细胞色素氧化酶","抑制转肽酶"],"a":2,"e":"有机磷农药与胆碱酯酶共价结合，形成难以水解的磷酰化胆碱酯酶，抑制胆碱酯酶活性，使乙酰胆碱大量蓄积，产生毒蕈碱样、烟碱样及中枢症状。其不直接兴奋M或N受体；抑制细胞色素氧化酶为氰化物中毒机制；抑制转肽酶为某些抗菌药机制，均非有机磷中毒原理"},{"q":"为下列感染选择有效的联合用药方案抗药性金葡菌感染","o":["青霉素G＋链霉素","羧苄西林＋庆大霉素","青霉素G＋四环素","苯唑西林＋庆大霉素","异烟肼＋链霉素"],"a":3,"e":"耐β-内酰胺酶金葡菌感染宜用耐酶青霉素，苯唑西林不易被酶水解，对耐药金葡菌有效；与庆大霉素联合可增强杀菌、扩大抗菌范围。青霉素G、羧苄西林易被β-内酰胺酶破坏；四环素为抑菌药；异烟肼抗结核，均不适用于耐药金葡菌感染"},{"q":"肾功能不全应避免或慎用的药物是","o":["氯霉素","利福平","氨基糖苷类","氨苄西林","甘露醇"],"a":2,"e":"氨基糖苷类主要以原型经肾小球滤过排泄，肾功能不全时排泄减慢、药物蓄积，可加重耳毒性和肾毒性，故应避免或慎用。氯霉素、利福平、氨苄西林主要经肝代谢或肝胆排泄，肾功能不全时相对安全；甘露醇为渗透性利尿药，非本题所指需慎用的肾毒性药物"},{"q":"属于广谱抗心律失常药的是","o":["氟卡尼","奎尼丁","维拉帕米","苯妥英钠","多非利特"],"a":1,"e":"奎尼丁为Ⅰa类抗心律失常药，适度阻滞钠通道并兼阻滞钾通道，对心房和心室的多种心律失常均有效，属广谱抗心律失常药。氟卡尼、多非利特主要作用于心室；维拉帕米为钙拮抗剂，主用于室上性心律失常；苯妥英钠主用于强心苷中毒所致室性心律失常，适用范围较窄"},{"q":"弱酸性药物在酸性环境中","o":["容易吸收","解离多","排泄不变","不容易吸收","排泄较快"],"a":0,"e":"弱酸性药物在酸性环境中解离少、分子型比例高，脂溶性大，易跨膜转运，故容易吸收。解离多会使离子型增多、不易吸收；酸性环境促进其重吸收、减少排泄，而非排泄加快或不变，故其余选项均不符合弱酸性药物的解离与转运特点"},{"q":"可使皮肤、黏膜血管收缩，骨骼肌血管扩张的药物是","o":["去甲肾上腺素","普萘洛尔","肾上腺素","异丙肾上腺素","间羟胺"],"a":2,"e":"肾上腺素激动α受体使皮肤、黏膜血管收缩，激动β2受体使骨骼肌血管和冠脉扩张，并兴奋心脏，故呈现该双向血管效应。去甲肾上腺素、间羟胺以α效应为主，使血管普遍收缩；异丙肾上腺素主要激动β受体，无α缩血管作用；普萘洛尔阻断β受体，不产生扩血管效应"},{"q":"以下药物中不具有增强免疫系统效果的是","o":["左旋咪唑","干扰素","卡介苗","泼尼松","胸腺肽"],"a":3,"e":"泼尼松为糖皮质激素，具有抗炎、抗过敏和免疫抑制作用，可抑制免疫功能，而非增强免疫。左旋咪唑为免疫调节剂，可增强免疫功能；干扰素、卡介苗、胸腺肽均能增强或调节机体免疫，故只有泼尼松不具有增强免疫的效果"},{"q":"在碱性尿液中弱碱性药物","o":["解离多，重吸收少，排泄快","解离少，重吸收多，排泄快","解离多，重吸收多，排泄快","解离少，重吸收多，排泄慢","解离多，重吸收少，排泄慢"],"a":3,"e":"弱碱性药物在碱性尿液中解离少、分子型多，脂溶性高，易被肾小管重吸收，排泄减慢。按离子障原理，解离型不易跨膜，解离多则重吸收少、排泄快，故解离多、重吸收少、排泄快的组合均不符合弱碱性药物在碱性尿中的特点"},{"q":"可引起高血钾的药物是","o":["氨苯蝶啶","氢氯噻嗪","布美他尼","依他尼酸","乙酰唑胺"],"a":0,"e":"氨苯蝶啶为保钾利尿药，阻断远曲小管、集合管的上皮钠通道，减少钠重吸收与钾排出，可致血钾升高。氢氯噻嗪、布美他尼、依他尼酸、乙酰唑胺均增加尿钾排泄，易引起低血钾，不会导致高血钾"},{"q":"麻醉时用于控制血压，减少手术区出血的神经节阻断药是","o":["美卡拉明","利多卡因","普鲁卡因","筒箭毒碱","地西泮"],"a":0,"e":"美卡拉明为神经节阻断药，阻断交感和副交感神经节，扩张血管、降低血压，并可减少手术野出血，曾用于控制性降压。利多卡因为局麻药和抗心律失常药；普鲁卡因为局麻药；筒箭毒碱为阻断N2受体的肌松药；地西泮为镇静催眠药，均非神经节阻断药"},{"q":"大多数抗癌药常见的严重不良反应是","o":["肝脏损害","脱发","心肌损害","骨髓抑制","过敏反应"],"a":3,"e":"多数抗癌药抑制细胞增殖，对增殖旺盛的骨髓造血干细胞损伤明显，常见而严重的毒性为骨髓抑制，表现为白细胞、血小板减少。肝损害、脱发、心肌损害、过敏反应可由部分药物引起，但并非大多数抗癌药共有且严重的反应，故以骨髓抑制为答案"},{"q":"青霉素最常见和应警惕的不良反应是","o":["变态反应","腹泻、恶心、呕吐","听力减退","二重感染","肝、肾损害"],"a":0,"e":"青霉素最常见且应警惕的是变态反应，其中过敏性休克最严重，用药前须皮试、备肾上腺素。腹泻、恶心、呕吐为轻度胃肠道反应；听力减退和肾损害为氨基糖苷类不良反应；二重感染多见于广谱抗生素，均非青霉素最主要和应警惕的反应"},{"q":"因某种全麻辅助用药导致的中毒反应，可选用新斯的明进行解救，该药引起中毒反应的原因是","o":["与抗胆碱酯酶药有加强作用","肌松作用最短，并有骨骼肌的始期纤颤","升高血钾","非除极化型肌松药","主要被假性胆碱酯酶水解"],"a":3,"e":"新斯的明抑制胆碱酯酶、增加接头间隙乙酰胆碱，可拮抗非除极化型（竞争性）肌松药的肌松作用，故此类药物过量中毒可用其解救。与抗胆碱酯酶药有加强作用并非原因；除极化型肌松药作用短、先有肌束纤颤、升高血钾，主要被假性胆碱酯酶水解，新斯的明不能解救反可延长其作用，故均非答案"},{"q":"下列不属于心律失常主要发生机制的是","o":["折返","自律性升高","早后除极","迟后除极","体外循环"],"a":4,"e":"心律失常的主要发生机制包括折返、自律性升高、早后除极和迟后除极等心肌电生理异常。体外循环为心脏手术中的一种支持技术，不是心律失常的发生机制，故不属于"},{"q":"对变异型心绞痛疗效最好的药物是","o":["硝酸甘油","普萘洛尔","硝苯地平","单硝酸异山梨酯","维拉帕米"],"a":2,"e":"变异型心绞痛由冠脉痉挛所致，硝苯地平为二氢吡啶类钙通道阻滞药，强力扩张冠脉、解除痉挛，疗效最好。硝酸甘油、单硝酸异山梨酯主要扩张静脉、降低前负荷；普萘洛尔阻断β2可致冠脉收缩，不宜用于变异型；维拉帕米虽扩冠但疗效不及硝苯地平"},{"q":"对磺酰脲类过敏的糖尿病患者仍可使用的药物是","o":["格列苯脲","格列吡嗪","甲苯磺丁脲","氯磺丙脲","瑞格列奈"],"a":4,"e":"瑞格列奈为苯甲酸衍生物，属非磺酰脲类促泌剂，与磺酰脲类化学结构不同，通过关闭β细胞钾通道促进胰岛素分泌，可用于磺酰脲类过敏者。格列苯脲、格列吡嗪、甲苯磺丁脲、氯磺丙脲均为磺酰脲类，存在交叉过敏，不宜使用"},{"q":"能很有效性治疗癫痫大发作而又无催眠作用的药物是","o":["地西泮","苯巴比妥钠","乙琥胺","苯妥英钠","扑米酮"],"a":3,"e":"苯妥英钠为治疗癫痫大发作和单纯局限性发作的首选药，抗癫痫作用强且无催眠镇静作用。地西泮、苯巴比妥钠有明显镇静催眠作用；乙琥胺仅对小发作有效；扑米酮代谢为苯巴比妥，有催眠作用，均不符合无催眠的要求"},{"q":"应用利福平容易出现的不良反应是","o":["可引起肝损害，并能激活肝药酶","视神经炎","外周神经炎","使中枢抑制性神经递质GABA生成减少","耳、肾毒性"],"a":0,"e":"利福平常见肝损害，并可诱导肝药酶，加速多种药物代谢，使合用药疗效降低，还可使尿液、泪液等呈橘红色。视神经炎、外周神经炎多见于乙胺丁醇、异烟肼等；利福平不减少GABA生成；耳、肾毒性为氨基糖苷类不良反应，均非利福平特点"},{"q":"关于青霉素过敏性休克，下列哪种说法不正确","o":["头孢菌素类与青霉素类之间可能有交叉过敏","对青霉素G过敏者可以改用阿莫西林口服","用药前必须皮试","每次用药后应观察半小时","在抢救时必须使用肾上腺素"],"a":1,"e":"青霉素G与阿莫西林同属β-内酰胺类，存在交叉过敏，对青霉素G过敏者改用阿莫西林仍可发生过敏反应，故该说法不正确。头孢菌素与青霉素可能有交叉过敏；用药前必须皮试、用药后观察半小时；抢救首选肾上腺素，这些均为正确处理"},{"q":"细菌对氨基糖苷类抗生素耐药的主要原因是","o":["细菌产生大量PABA","细菌产生大量二氢蝶酸合成酶","细菌产生水解酶","细菌产生钝化酶","细菌细胞膜通透性降低"],"a":3,"e":"细菌对氨基糖苷类耐药的主要机制是产生钝化酶，如乙酰化酶、磷酸化酶、腺苷化酶，使药物失活。产生大量PABA和二氢蝶酸合成酶与磺胺类耐药相关；产生水解酶即β-内酰胺酶与β-内酰胺类耐药相关；膜通透性降低虽可参与，但非氨基糖苷类耐药的主要原因"},{"q":"硫糖铝治疗消化性溃疡的机制是","o":["中和胃酸","抑制胃酸分泌","保护胃肠黏膜","抗幽门螺杆菌","促进胃肠动力"],"a":2,"e":"硫糖铝在酸性环境中解离为硫酸蔗糖复合物，与溃疡面带正电的蛋白质结合形成保护膜，覆盖溃疡面、隔绝胃酸和胃蛋白酶，保护胃肠黏膜促进愈合。中和胃酸为抗酸药作用；抑制胃酸分泌为H2受体阻断药和PPI作用；抗幽门螺杆菌需抗菌药；促进胃肠动力为促动力药作用，均非硫糖铝机制"},{"q":"胺碘酮少见的不良反应是","o":["窦性心动过缓","眼角膜微粒沉淀","房室传导阻滞","肺纤维化","低血压"],"a":3,"e":"胺碘酮常见不良反应包括窦性心动过缓、房室传导阻滞、低血压及眼角膜微粒沉淀；肺纤维化虽最严重但发生率较低，属少见不良反应，故答案为肺纤维化，其余各项均为较常见的不良反应"},{"q":"支气管哮喘的患者应慎用或禁用","o":["沙丁胺醇","异丙肾上腺素","普萘洛尔","糖皮质激素","氨茶碱"],"a":2,"e":"普萘洛尔为非选择性β受体阻断药，阻断β2受体可致支气管平滑肌收缩、诱发或加重哮喘，故哮喘患者慎用或禁用。沙丁胺醇、异丙肾上腺素为β2激动药，可舒张支气管；糖皮质激素抗炎、氨茶碱平喘，均可用于哮喘治疗而非禁用"},{"q":"强心苷最适宜治疗的心衰是","o":["心包缩窄引起的心衰","肺源性心脏病引起的心衰","高血压性心衰伴有房颤","甲状腺功能亢进的心衰","严重贫血引起的心衰"],"a":2,"e":"强心苷增强心肌收缩力并减慢房室传导，对伴有快速心房颤动的心衰疗效最好，高血压性心脏病所致心衰伴房颤即属此类。心包缩窄、严重贫血、甲亢、肺源性心脏病所致心衰，病因未去除或心肌损害为主，强心苷疗效差或易中毒，故非最适宜"},{"q":"尼可地尔的作用是","o":["激活KATP钾通道，促进K＋外流","激活KACh钾通道，促进K＋外流","阻滞钙通道，减少钙内流","阻滞钠通道，抑制细胞膜除极","促进血管平滑肌细胞膜上的Na＋-Ca2＋交换，增加细胞内钙"],"a":0,"e":"尼可地尔为钾通道开放药，激活血管平滑肌ATP敏感钾通道，促进K⁺外流使膜超极化，血管扩张，用于抗心绞痛。KACh为乙酰胆碱激活的钾通道，主要存在于心房；阻滞钙通道、钠通道及促进Na⁺-Ca²⁺交换分别为钙拮抗剂、钠通道阻滞剂等机制，均非尼可地尔作用"},{"q":"对心率和血压无明显影响的选择性α1受体阻断药是","o":["酚苄明","哌唑嗪","坦洛新","酚妥拉明","育亨宾"],"a":2,"e":"坦洛新为选择性α1A/D受体阻断药，主要作用于前列腺和膀胱颈平滑肌，用于良性前列腺增生，对血管α1B受体作用弱，故对心率和血压影响小。酚苄明、酚妥拉明阻断α1和α2，扩血管明显、可致反射性心率加快；哌唑嗪降压显著；育亨宾为选择性α2阻断药，均不符合"},{"q":"抗肿瘤药共有的毒性反应主要是","o":["肝脏毒性","肾脏毒性","骨髓抑制","神经毒性","过敏反应"],"a":2,"e":"抗肿瘤药多抑制细胞增殖，对骨髓造血细胞增殖活跃的特点使其普遍受损，共有毒性为骨髓抑制，表现为白细胞、血小板减少。肝毒性、肾毒性、神经毒性、过敏反应仅见于部分药物或特定品种，并非抗肿瘤药普遍共有的毒性反应"},{"q":"双胍类降糖药最常见的不良反应是","o":["乳酸性酸中毒","肝功能异常","低血糖","过敏性皮疹","胃肠道反应"],"a":4,"e":"双胍类最常见不良反应为胃肠道反应，如恶心、呕吐、腹泻、腹部不适。乳酸性酸中毒虽严重但少见；双胍类不刺激胰岛素分泌，单用很少引起低血糖；肝功能异常、过敏性皮疹均非最常见反应"},{"q":"HMG-CoA还原酶抑制剂最严重的不良反应是","o":["甲状腺功能异常","中枢神经系统反应","肝损伤","横纹肌溶解症","肺纤维化"],"a":3,"e":"他汀类最严重的不良反应为横纹肌溶解症，可致肌痛、肌无力及急性肾衰竭。肝损伤较常见但多可逆；甲状腺功能异常、中枢神经系统反应少见；肺纤维化并非他汀类不良反应，故横纹肌溶解症为最严重者"},{"q":"链霉素不良反应不包括","o":["过敏性休克","肾损害","第八对脑神经损害","神经肌肉阻滞","灰婴综合征"],"a":4,"e":"链霉素为氨基糖苷类，不良反应包括过敏性休克、肾损害、第八对脑神经即前庭和听神经损害及神经肌肉阻滞。灰婴综合征为氯霉素特有的严重不良反应，与链霉素无关，故不属于其不良反应"},{"q":"地西泮不具有下列哪项作用","o":["镇静、催眠作用","中枢性肌松作用","抗癫痫作用","抗焦虑","抗躁狂症"],"a":4,"e":"地西泮为苯二氮䓬类，具有镇静催眠、抗焦虑、中枢性肌松、抗惊厥和抗癫痫作用，可用于癫痫持续状态。其无抗躁狂症作用，躁狂症治疗常用碳酸锂等心境稳定剂，故抗躁狂症为地西泮不具有的作用"},{"q":"以下选项中可以通过抑制虫体微管聚集、葡萄糖摄取、减少ATP生成从而达到广谱驱虫效果的药物是","o":["阿苯达唑","左旋咪唑","哌嗪","吡喹酮","恩波吡维铵"],"a":0,"e":"阿苯达唑为苯并咪唑类广谱驱虫药，与虫体微管蛋白结合、抑制微管聚集，阻碍葡萄糖摄取，减少ATP生成，使虫体麻痹死亡。左旋咪唑为免疫调节兼驱虫；哌嗪改变虫体肌膜电位致麻痹；吡喹酮增加虫体膜通透性；恩波吡维铵干扰虫体能量代谢但机制不同，均非通过抑制微管聚集发挥广谱驱虫"},{"q":"全身应用毒性大，仅限于局部应用的药物是","o":["利巴韦林","干扰素","齐多夫定","碘苷","阿糖腺苷"],"a":3,"e":"碘苷为嘧啶类抗病毒药，全身应用毒性大，仅局部用于单纯疱疹病毒性角膜炎等。利巴韦林、干扰素、齐多夫定、阿糖腺苷均可全身给药治疗相应病毒感染，不属仅限局部应用者"},{"q":"治疗全身性深部真菌感染的首选药是","o":["灰黄霉素","制霉菌素","两性霉素B","克霉唑","咪康唑"],"a":2,"e":"两性霉素B与真菌细胞膜麦角固醇结合、形成孔道，导致胞内物质外漏，抗菌谱广、疗效强，是治疗全身性深部真菌感染的首选药。灰黄霉素仅用于浅表真菌感染；制霉菌素毒性大、多局部用；克霉唑、咪康唑主要用于浅表或局部感染，均非深部感染首选"},{"q":"强心苷正性肌力作用的表现不包括","o":["提高心肌收缩时最高张力","提高心肌收缩速率","心脏容积扩张","每搏输出量增加","不增加心肌耗氧量"],"a":2,"e":"强心苷正性肌力作用表现为提高心肌收缩速率和最高张力、增加每搏输出量，并使心脏容积缩小、心室排空充分，且不增加甚至降低心肌耗氧量。心脏容积扩张与强心苷使心脏缩小、排空增加的作用相反，故不属于其表现"},{"q":"香豆素类抗凝药最常见的给药途径是","o":["肌内注射","皮下注射","口服","舌下含服","静脉注射"],"a":2,"e":"香豆素类（如华法林）口服吸收良好、生物利用度高，临床常规口服给药抗凝。肌内注射、皮下注射、静脉注射、舌下含服均非香豆素类的常规给药途径；其中华法林也可静脉给药但非最常见，故答案为口服"},{"q":"不能引起调节麻痹作用的药物是","o":["阿托品","后马托品","尤卡托品","托吡卡胺","环喷托酯"],"a":2,"e":"尤卡托品为短效散瞳药，只散瞳而不引起调节麻痹，作用时间短。阿托品、后马托品、托吡卡胺、环喷托酯均阻断睫状肌M受体，引起调节麻痹即视近物模糊，其中阿托品作用最强最久，故只有尤卡托品不引起调节麻痹"},{"q":"属于皮质激素类药物共有的基本结构是","o":["C4-5之间为一双键","C1-2之间为一双键","C17上有α羟基","C11上无氧","C9上有氟（F）"],"a":0,"e":"糖皮质激素等皮质激素类药物具有甾体母核，其共有基本结构为C4-C5间双键与C3位酮基共轭。C1-C2间双键仅见于部分合成品如泼尼松；C17α羟基、C9氟取代并非全部共有；C11无氧则不符，可的松类C11为酮基、氢化可的松为羟基，故以C4-5双键为共有结构"},{"q":"必须与胃壁细胞分泌的糖蛋白即“内因子”结合才能吸收的抗贫血药是","o":["枸橼酸铁铵","叶酸","硫酸亚铁","维生素B12","右旋糖酐铁"],"a":3,"e":"维生素B12须与胃壁细胞分泌的内因子结合形成复合物，才能在回肠末端被吸收，缺乏内因子可致B12吸收障碍。叶酸在十二指肠和空肠上段吸收，不需内因子；枸橼酸铁铵、硫酸亚铁、右旋糖酐铁均为铁剂，其吸收与内因子无关"},{"q":"胰岛素对糖代谢的影响是","o":["抑制葡萄糖向组织细胞内转移","抑制葡萄糖的氧化和酵解","促进糖原的分解和异生","抑制糖原的合成和储存","降低血糖"],"a":4,"e":"胰岛素促进葡萄糖向组织细胞转运、加速葡萄糖氧化和糖原合成，抑制糖原分解和糖异生，总体效应是降低血糖。抑制葡萄糖转运、抑制氧化酵解、促进糖原分解异生、抑制糖原合成均为升高血糖的方向，与胰岛素作用相反"},{"q":"下列哪项是吗啡的作用","o":["兴奋呼吸","止吐","止泻","升高血压","散瞳"],"a":2,"e":"吗啡激动肠道阿片受体，减慢肠蠕动、提高括约肌张力、减少分泌，可用于止泻。吗啡抑制呼吸而非兴奋；常见恶心呕吐而非止吐；可扩张血管、降低血压而非升压；兴奋动眼神经缩瞳核引起针尖样瞳孔而非散瞳，故其余均非吗啡作用"},{"q":"有首过消除的给药途径是","o":["直肠给药","舌下给药","静脉给药","喷雾给药","口服给药"],"a":4,"e":"口服给药经胃肠道吸收后须先通过门静脉进入肝脏，部分药物被肝脏代谢灭活，使进入体循环的药量减少，即首过消除。舌下给药、直肠给药可部分避开首过效应；静脉给药直接进入体循环，无吸收过程；喷雾给药经黏膜吸收，均无显著首过消除"},{"q":"不具有溶栓作用的药物是","o":["肝素","链激酶","尿素酶","组织纤溶酶原激活剂","阿尼普酶"],"a":0,"e":"肝素为抗凝血药，通过激活抗凝血酶Ⅲ抑制凝血因子，防止血栓形成和扩大，但无溶解已形成血栓的作用。链激酶、尿素酶即尿激酶、组织纤溶酶原激活剂、阿尼普酶均激活纤溶系统、溶解纤维蛋白，属溶栓药，故肝素不具有溶栓作用"},{"q":"抗高血压药中，不属于交感神经抑制药的是","o":["莫索尼定","美卡拉明","利血平","普萘洛尔","米诺地尔"],"a":4,"e":"米诺地尔为钾通道开放药，直接舒张血管平滑肌降压，不属交感神经抑制药。莫索尼定激动中枢I1咪唑啉受体、美卡拉明阻断神经节、利血平耗竭去甲肾上腺素、普萘洛尔阻断β受体，均通过抑制交感神经发挥降压作用"},{"q":"下列药物中属于M受体阻断药的是","o":["东莨菪碱","筒箭毒碱","琥珀胆碱","毒扁豆碱","乙酰胆碱"],"a":0,"e":"东莨菪碱为M胆碱受体阻断药，作用类似阿托品而中枢作用较强。筒箭毒碱为非去极化型肌松药，阻断N2受体；琥珀胆碱为去极化型肌松药；毒扁豆碱为胆碱酯酶抑制剂；乙酰胆碱为胆碱受体激动药，均非M受体阻断药"},{"q":"通过抑制细菌的细胞壁的合成发挥杀菌作用，但杀菌速度较慢的抗菌药物是","o":["青霉素","阿奇霉素","阿莫西林","多黏菌素B","万古霉素"],"a":4,"e":"万古霉素抑制细菌细胞壁合成而杀菌，属繁殖期杀菌药但杀菌速度较青霉素类慢。青霉素、阿莫西林亦抑制细胞壁合成但杀菌迅速；阿奇霉素抑制蛋白质合成；多黏菌素B影响细胞膜通透性，均不符合抑制细胞壁合成且杀菌较慢的特点"},{"q":"以下哪种药物对阿米巴包囊最有效","o":["甲硝唑","氯喹","二氯尼特","巴龙霉素","吡喹酮"],"a":2,"e":"二氯尼特为抗阿米巴药，主要杀灭肠腔内阿米巴包囊，是治疗无症状带包囊者的首选，对包囊最有效。甲硝唑主要杀灭滋养体；氯喹作用于组织内滋养体；巴龙霉素为肠腔抗阿米巴药但主要针对滋养体；吡喹酮主要抗血吸虫和绦虫，均非针对包囊最有效"},{"q":"氨基糖苷类抗生素的消除途径是","o":["原型经肾小球滤过排出","原型经肾小管分泌排出","被单胺氧化酶代谢","被肝药酶P450代谢","与葡糖醛酸结合后排出"],"a":0,"e":"氨基糖苷类在体内不被代谢，主要以原型经肾小球滤过排出，肾功能减退时排泄减少、易蓄积中毒。原型经肾小管分泌排出不是其主要方式；单胺氧化酶、肝药酶P450代谢及葡糖醛酸结合均非氨基糖苷类的消除途径，因其几乎不经肝脏代谢"},{"q":"下列哪项不是四环素类产生耐药性的机制","o":["产生灭活酶","产生核糖体保护蛋白","缺乏自溶酶","减少药物进入菌体","促进药物主动外排"],"a":2,"e":"四环素类耐药机制包括产生灭活酶、产生核糖体保护蛋白、减少药物进入菌体及促进药物主动外排。缺乏自溶酶与β-内酰胺类耐药相关，不属于四环素的耐药机制，故为答案"},{"q":"部分激动剂的特点是","o":["与受体无亲和力，但有部分内在活性","与受体亲和力弱，内在活性强","与受体亲和力强，但内在活性弱","与受体亲和力强，内在活性亦强","与受体亲和力强，但无内在活性"],"a":2,"e":"部分激动剂与受体亲和力强，但内在活性弱，介于零和一之间，单独应用产生较弱激动效应，与完全激动剂合用时可竞争性拮抗其部分效应。无亲和力、无内在活性、内在活性强等表述均不符合定义，其中亲和力强而无内在活性为拮抗药特点"},{"q":"用硫喷妥钠或氧化亚氮作诱导麻醉是因为","o":["可增加镇痛作用","肌肉松弛效果好","能迅速进入外科麻醉期","减少支气管分泌物的产生","减少麻醉药用量"],"a":2,"e":"硫喷妥钠脂溶性高、静脉给药后迅速透过血脑屏障，氧化亚氮吸入后起效快，二者均能使病人迅速进入外科麻醉期，故常用于诱导麻醉。增加镇痛、肌松好、减少分泌物、减少麻醉药用量均非诱导麻醉选用它们的主要原因"},{"q":"易燃易爆，有特殊臭味的麻醉药是","o":["乙醚","氟烷","恩氟烷","异氟烷","氧化亚氮"],"a":0,"e":"乙醚为经典吸入麻醉药，麻醉效能强、安全范围大，但易燃易爆，且具有特殊刺激性臭味，诱导期长、苏醒慢，现已被氟烷等取代。氟烷、恩氟烷、异氟烷不易燃、无明显臭味；氧化亚氮不燃、无味，故只有乙醚符合"},{"q":"以下治疗方式不属于肿瘤免疫治疗药物的是","o":["肿瘤疫苗","细胞毒T淋巴细胞抗原-4（CTLA-4）单克隆抗体","程序性死亡受体1（PD-1）单克隆抗体","表皮生长因子受体（EGFR）单克隆抗体","与DNA交联的烷化剂"],"a":3,"e":"肿瘤免疫治疗通过激活或调节机体免疫系统抗肿瘤，包括肿瘤疫苗、CTLA-4单抗、PD-1单抗等免疫检查点抑制剂，均属免疫治疗。EGFR单抗阻断肿瘤细胞生长信号，属分子靶向治疗而非免疫治疗，故答案为EGFR单抗"},{"q":"轻度抑制心肌细胞Na＋通道，主要作用于心室肌的抗心律失常药是","o":["奎尼丁","利多卡因","普鲁卡因胺","胺碘酮","维拉帕米"],"a":1,"e":"利多卡因为Ⅰb类抗心律失常药，轻度阻滞心室肌钠通道，缩短动作电位时程，主要作用于心室肌，用于室性心律失常。奎尼丁、普鲁卡因胺为Ⅰa类，作用较广；胺碘酮为Ⅲ类延长动作电位；维拉帕米为Ⅳ类钙拮抗剂，主作用于房室结，均非主要作用于心室的Ⅰb类药物"},{"q":"西咪替丁治疗消化性溃疡的机制是","o":["中和胃酸","吸附胃酸","阻断H1受体，抑制胃酸分泌","阻断H2受体，抑制胃酸分泌","阻断M1受体，抑制胃酸分泌"],"a":3,"e":"西咪替丁为H2受体阻断药，竞争性阻断胃壁细胞H2受体，抑制基础及刺激后的胃酸分泌，用于消化性溃疡。中和胃酸为抗酸药作用；吸附胃酸非其主要机制；阻断H1受体为抗组胺药即抗过敏作用；阻断M1受体为抗胆碱药作用，均非西咪替丁机制"},{"q":"对尿量已减少的中毒性休克，最好选用","o":["阿托品","多巴胺","麻黄碱","异丙肾上腺素","酚妥拉明"],"a":1,"e":"多巴胺激动β1受体增强心肌收缩力，并激动多巴胺受体扩张肾血管、增加肾血流，在尿量已减少的中毒性休克中可升压并改善肾灌注、增加尿量。阿托品、麻黄碱、异丙肾上腺素、酚妥拉明或升压作用弱、或扩血管降压，均不适合尿量减少的休克"},{"q":"苯妥英钠对下列哪种癫痫无效","o":["癫痫持续状态","大发作","单纯局限性发作","小发作","精神运动性发作"],"a":3,"e":"苯妥英钠对癫痫大发作、单纯局限性发作、精神运动性发作及癫痫持续状态有效，但对小发作即失神发作无效，甚至可加重，故小发作为答案。乙琥胺、丙戊酸钠才是治疗小发作的有效药物，其余类型均为苯妥英钠的适应证"},{"q":"中枢神经受到抑制的表现为","o":["欣快","失眠","幻觉","抑郁","躁狂"],"a":3,"e":"抑郁表现为精神活动减退、情绪低落，属中枢神经系统抑制状态。欣快、失眠、幻觉、躁狂均为中枢兴奋或功能亢进的表现，与抑制相反，故只有抑郁符合中枢抑制的表现"},{"q":"糖皮质激素可增强儿茶酚胺的血管收缩作用，称为","o":["允许作用","协同作用","拮抗作用","依赖作用","叠加作用"],"a":0,"e":"允许作用指某些激素本身对某器官无直接作用，但它的存在是其他激素发挥效应的前提或使其效应增强。糖皮质激素本身对血管平滑肌无明显收缩作用，但可增强儿茶酚胺的缩血管效应，即为允许作用。协同作用指两药效应相加或增强且均有直接作用；拮抗作用为相反效应；依赖、叠加均非此概念"},{"q":"治疗癫痫小发作的首选药物是","o":["乙琥胺","丙戊酸钠","苯妥英钠","扑米酮","卡马西平"],"a":0,"e":"乙琥胺为治疗癫痫小发作即失神发作的首选药，可抑制丘脑神经元T型钙通道。丙戊酸钠为广谱抗癫痫药，可用于各型但非小发作首选；苯妥英钠对小发作无效；扑米酮、卡马西平主要用于大发作和局限性发作，均非小发作首选"},{"q":"糖皮质激素用于严重的感染的目的","o":["提高机体防御能力","抗细菌感染","提高抗菌药物的活性","防止病灶扩散","使病人度过危险期"],"a":4,"e":"严重感染时短期使用糖皮质激素，利用其抗炎、抗毒、抗休克作用减轻炎症反应和中毒症状，帮助病人度过危险期，同时须配伍足量有效抗菌药。糖皮质激素抑制而非提高机体防御；无抗细菌感染作用；不能提高抗菌药活性；防止病灶扩散亦非其主要目的"},{"q":"洛伐他汀的降脂机制为","o":["抑制磷酸二酯酶","抑制HMG-CoA还原酶","抑制血管紧张素转换酶","激活乙酰胆碱酯酶","激活一氧化氮合酶"],"a":1,"e":"洛伐他汀为他汀类调脂药，竞争性抑制肝脏HMG-CoA还原酶，减少胆固醇合成，上调LDL受体、加速LDL清除，降低血胆固醇。抑制磷酸二酯酶、抑制ACE、激活乙酰胆碱酯酶、激活一氧化氮合酶分别为其他类药物机制，与他汀类调脂无关"},{"q":"最易引起心律失常的药物是","o":["去甲肾上腺素","间羟胺","肾上腺素","麻黄碱","多巴胺"],"a":2,"e":"肾上腺素激动α、β受体，强烈兴奋心脏，提高自律性、加快传导，易诱发心律失常，尤其在心肌缺血或合用某些药物时更明显。去甲肾上腺素、间羟胺以α作用为主；麻黄碱作用温和；多巴胺心脏兴奋作用相对较弱，均不及肾上腺素易致心律失常"},{"q":"决定药物每天用药次数的最主要因素是","o":["吸收快慢","作用强弱","体内分布速度","体内转化速度","体内消除速度"],"a":4,"e":"给药次数主要取决于药物在体内的消除速度即半衰期，消除快、半衰期短者需增加每日给药次数以维持有效血药浓度。吸收快慢、作用强弱、分布速度、转化速度虽影响药效，但决定给药间隔的最主要因素是药物消除速度"},{"q":"治疗前列腺癌宜选用的药物是","o":["苯丙酸诺龙","炔雌醇","丙酸睾丸素","氯米芬","双醋炔诺醇"],"a":1,"e":"炔雌醇为雌激素，通过负反馈抑制下丘脑-垂体-性腺轴、减少雄激素分泌，并直接对抗雄激素作用，可用于前列腺癌治疗。苯丙酸诺龙、丙酸睾丸素为雄激素，可促进前列腺癌发展；氯米芬为促排卵药；双醋炔诺醇为孕激素，均不适用于前列腺癌"},{"q":"格列美脲的主要作用机制是","o":["促进葡萄糖降解","拮抗胰高血糖素的作用","刺激胰岛β细胞释放胰岛素","促进葡萄糖的合成","刺激胰岛素"],"a":2,"e":"格列美脲为磺酰脲类降糖药，与胰岛β细胞膜磺酰脲受体结合，关闭ATP敏感钾通道、使膜去极化、钙内流，触发胰岛素释放。促进葡萄糖降解、拮抗胰高血糖素非其主要机制；促进葡萄糖合成会升高血糖，方向相反；笼统地说刺激胰岛素不如促β细胞释放准确"},{"q":"氯丙嗪中毒引起血压下降时，禁用哪种措施","o":["注射多巴胺","补充血容量","注射去甲肾上腺素","中枢兴奋药","吸氧"],"a":0,"e":"氯丙嗪阻断α受体使血管扩张、血压下降，此时注射多巴胺，因其α缩血管效应被阻断且可激动β2扩血管，反致血压更低或升压无效，故属禁用。补充血容量、注射去甲肾上腺素、应用中枢兴奋药、吸氧均为纠正低血压的合理措施，其中去甲肾上腺素为升压首选"},{"q":"因电击导致的心脏骤停，在采用心肺复苏措施的同时还应给予的急救药物是","o":["去甲肾上腺素","肾上腺素","多巴胺","多巴酚丁胺","糖皮质激素"],"a":1,"e":"肾上腺素激动α、β受体，兴奋心脏、增加心输出量，并提高室颤阈值、利于复苏，是心脏骤停包括电击所致者心肺复苏的首选急救药。去甲肾上腺素、多巴胺、多巴酚丁胺主要用于低血压或心衰，糖皮质激素无复苏作用，均非心脏骤停首选"},{"q":"伴有胃溃疡的风湿性关节炎患者最好选用","o":["吲哚美辛","布洛芬","阿司匹林","保泰松","对乙酰氨基酚"],"a":1,"e":"布洛芬为非选择性NSAID，抗炎镇痛作用较强，胃肠道不良反应相对较轻，适合伴有胃溃疡的风湿性关节炎患者，必要时合用胃黏膜保护剂。吲哚美辛、阿司匹林、保泰松胃肠道刺激大、可致溃疡出血；对乙酰氨基酚抗炎作用弱，不适合风湿性关节炎的抗炎治疗"},{"q":"能引起金鸡纳反应的药物是","o":["普萘洛尔","普鲁卡因胺","胺碘酮","奎尼丁","普罗帕酮"],"a":3,"e":"奎尼丁为Ⅰa类抗心律失常药，是奎宁的金鸡纳生物碱，可引起金鸡纳反应，表现为耳鸣、听力减退、视力模糊、神志不清等。普萘洛尔、普鲁卡因胺、胺碘酮、普罗帕酮均无此特有的不良反应，故金鸡纳反应为奎尼丁所特有"},{"q":"下列药物属于α、β受体阻断药的是","o":["普萘洛尔","吲哚洛尔","酚苄明","拉贝洛尔","阿替洛尔"],"a":3,"e":"拉贝洛尔兼有α1和β受体阻断作用，阻断α1扩血管、阻断β抑制心脏，降压时不明显反射性加快心率，属α、β受体阻断药。普萘洛尔、吲哚洛尔、阿替洛尔为β受体阻断药；酚苄明为α受体阻断药，均不兼有α、β阻断作用"},{"q":"钙通道阻滞药的药理作用不包括","o":["血管平滑肌松弛，血压下降","冠脉血管扩张","抗动脉粥样硬化","加快房室传导","明显增加肾血流"],"a":3,"e":"钙通道阻滞药阻滞钙内流，松弛血管平滑肌、降低血压，扩张冠脉、增加肾血流，并有抗动脉粥样硬化作用；维拉帕米、地尔硫䓬还减慢房室传导。加快房室传导与钙拮抗剂延缓传导的作用相反，故不属于其作用"},{"q":"下列地西泮的药理学作用中，小剂量即可明显改善症状的是","o":["镇静催眠","抗惊厥、抗癫痫","中枢性肌肉松弛","抗焦虑","暂时性记忆缺失"],"a":3,"e":"地西泮小剂量即可明显改善焦虑症状，抗焦虑作用选择性强、起效快。镇静催眠需较大剂量；抗惊厥、抗癫痫、中枢性肌松及暂时性记忆缺失均需相对较大剂量或为其他作用，小剂量下最敏感、改善最明显的是抗焦虑"},{"q":"强心苷心脏毒性的发生机制是","o":["兴奋心肌细胞膜上Na＋-K＋-ATP酶","使心肌细胞内K＋增多","促进心肌抑制因子的释放","抑制心肌细胞膜上Na＋-K＋-ATP酶","激活磷酸二酯酶"],"a":3,"e":"强心苷心脏毒性源于过度抑制心肌细胞膜Na⁺-K⁺-ATP酶，使细胞内Na⁺升高、K⁺减少，钠钙交换增加、细胞内钙超载，诱发迟后除极和心律失常。兴奋该酶与强心苷作用相反；细胞内K⁺增多不符合；促进心肌抑制因子释放、激活磷酸二酯酶均非其毒性机制"},{"q":"长期应用糖皮质激素后停药不会引起","o":["原病复发或恶化","肾上腺皮质功能不全","肾上腺皮质功能亢进","糖皮质激素抵抗","肾上腺危象"],"a":2,"e":"长期应用糖皮质激素停药后可因下丘脑-垂体-肾上腺轴受抑制出现肾上腺皮质功能不全，甚至肾上腺危象，并可致原病复发或恶化、激素抵抗。肾上腺皮质功能亢进是长期大量用药期间的表现，而非停药后引起，故为答案"},{"q":"小剂量的多巴胺即能增加肾血流量的主要原因是","o":["兴奋β1受体","兴奋β2受体","兴奋多巴胺受体","阻断α受体","直接松弛肾血管平滑肌"],"a":2,"e":"小剂量多巴胺选择性激动肾血管平滑肌的D1多巴胺受体，扩张肾血管、增加肾血流量和肾小球滤过率。兴奋β1、β2受体需较大剂量；阻断α受体、直接松弛肾血管平滑肌均非小剂量多巴胺的作用机制，其扩肾血管主要由多巴胺受体介导"},{"q":"呋塞米的利尿效能高的原因是","o":["增强肾脏的稀释功能","抑制肾脏的浓缩功能","抑制肾脏的稀释和浓缩功能","抗醛固酮的作用","阻滞Na＋重吸收"],"a":2,"e":"呋塞米抑制髓袢升支粗段Na⁺-K⁺-2Cl⁻共转运子，既影响肾脏对尿液的稀释功能，又破坏髓质渗透梯度、干扰浓缩功能，故利尿效能强大。增强稀释功能与利尿无关；仅抑制浓缩功能或抗醛固酮、单纯阻滞Na⁺重吸收均不能解释其高效能，故以抑制稀释和浓缩功能为答案"},{"q":"下列药物中，中枢镇静作用最强的是","o":["阿司咪唑","氯苯那敏","布克力嗪","苯海拉明","美克洛嗪"],"a":3,"e":"苯海拉明为第一代H1受体阻断药，脂溶性高、易透过血脑屏障，中枢镇静作用最强，可引起嗜睡，常用于失眠或晕动。阿司咪唑不易入脑、无镇静作用；氯苯那敏、布克力嗪、美克洛嗪虽有一定中枢作用，但镇静强度均不及苯海拉明"},{"q":"可用于解救低分子量肝素应用过量所致出血的药物是","o":["维生素K","鱼精蛋白","垂体后叶素","氨甲苯酸","氯化钙"],"a":1,"e":"鱼精蛋白为强碱性蛋白质，可与酸性的肝素包括低分子量肝素结合形成稳定复合物，使肝素失活，用于解救其过量所致出血。维生素K拮抗香豆素类；垂体后叶素、氨甲苯酸、氯化钙分别通过收缩血管、抑制纤溶、补充钙离子止血，均非肝素的特效解毒剂"},{"q":"属于n-3型多烯脂肪酸的药物是","o":["二十碳五烯酸","亚油酸","γ-亚麻酸","硫酸类肝素","烟酸"],"a":0,"e":"二十碳五烯酸即EPA，为双键从第三位碳开始的多烯脂肪酸，属n-3型，常与DHA同用于调脂。亚油酸、γ-亚麻酸属n-6型；硫酸类肝素为黏多糖类抗凝物质；烟酸为维生素类调脂药，均不属于n-3型多烯脂肪酸"},{"q":"有关叶酸的说法，错误的是","o":["主要在十二指肠和空肠上段吸收","促进氨基酸的互变","妊娠妇女需要量增加","吸收需要内因子的协助","参与嘌呤的从头合成"],"a":3,"e":"叶酸在十二指肠和空肠上段吸收，不需内因子协助；需要内因子才能吸收的是维生素B12。叶酸参与嘌呤从头合成和氨基酸互变，妊娠期需要量增加，故其余说法均正确，只有吸收需要内因子协助错误"},{"q":"巨幼红细胞性贫血患者合并神经症状时需应用","o":["亚叶酸钙","维生素B12","红细胞生成素","硫酸亚铁","叶酸"],"a":1,"e":"维生素B12参与神经髓鞘脂类合成，缺乏时除巨幼红细胞性贫血外还有神经症状，故合并神经症状时须应用维生素B12。叶酸仅纠正贫血、不能改善神经症状；亚叶酸钙为叶酸活性形式；红细胞生成素用于肾性贫血；硫酸亚铁用于缺铁性贫血，均不适合"},{"q":"喹诺酮类药物对革兰阴性菌的抗菌作用机制为","o":["抑制β-内酰胺酶","抑制DNA回旋酶","抑制二氢蝶酸合酶","抑制细菌细胞壁的合成","增加细菌胞浆膜的通透性"],"a":1,"e":"喹诺酮类对革兰阴性菌主要通过抑制DNA回旋酶即拓扑异构酶Ⅱ，阻碍DNA复制而发挥抗菌作用。抑制β-内酰胺酶为β-内酰胺酶抑制剂作用；抑制二氢蝶酸合酶为磺胺类机制；抑制细胞壁合成为β-内酰胺类；增加胞浆膜通透性为多黏菌素类机制，均非喹诺酮类对革兰阴性菌的作用靶点"},{"q":"易通过血脑屏障的抗真菌药物是","o":["咪康唑","克霉唑","氟康唑","酮康唑","阿司咪唑"],"a":2,"e":"氟康唑属三唑类，分子小、蛋白结合率低，能透过血脑屏障，可用于隐球菌性脑膜炎等深部真菌感染。咪康唑、克霉唑、酮康唑主要为局部或浅表用药，难以进入脑脊液。阿司咪唑是抗组胺药，无抗真菌作用"},{"q":"可用于处理去甲肾上腺素静脉滴注外漏引起局部缺血的药物是","o":["酚妥拉明","阿托品","去氧肾上腺素","多巴胺","普萘洛尔"],"a":0,"e":"酚妥拉明为非选择性α受体阻断药，可扩张血管、改善局部缺血，用于去甲肾上腺素外漏的对抗。去氧肾上腺素本身是α受体激动药，会加重缺血。阿托品解除平滑肌痉挛，对血管α受体无阻断作用；普萘洛尔阻断β受体，亦不能对抗α受体介导的血管收缩"},{"q":"为了保证药物的疗效，多次给药应该","o":["后续给药剂量加倍","每天3次或3次以上给药","根据药物半衰期确定给药间隔","每2小时用药1次","不间断用药"],"a":2,"e":"按一级动力学消除的药物半衰期恒定，等于0.693/Ke，多次给药时依据半衰期设定给药间隔，约经5个半衰期达稳态血药浓度。加倍剂量或每日3次以上并非通用原则，易致蓄积中毒。每2小时用药或不停药只是机械做法，未按药物消除速率个体化设计"},{"q":"下列农药中毒，碘解磷定抢救无效的是","o":["对硫磷","内吸磷","马拉硫磷","乐果","敌百虫"],"a":3,"e":"碘解磷定为胆碱酯酶复活药，对对硫磷、内吸磷、马拉硫磷中毒能有效恢复酶活性。乐果中毒形成的磷酰化胆碱酯酶稳定，复活药难以奏效，故抢救无效。敌百虫中毒疗效虽较差，仍以阿托品配合复能药综合处理，并非完全无效"},{"q":"立克次体感染，治疗首选","o":["四环素类","氯霉素类","青霉素类","头孢菌素类","万古霉素类"],"a":0,"e":"立克次体为专性细胞内寄生菌，四环素类能进入细胞抑制其蛋白质合成，是斑疹伤寒、恙虫病等立克次体感染的首选。氯霉素类可作替代但不良反应较重。青霉素类与头孢菌素类作用于细胞壁，对立克次体无效；万古霉素仅针对革兰阳性菌"},{"q":"甲氧苄啶长期大量服用会引起人体叶酸缺乏症，原因是人体的哪种酶被抑制","o":["二氢叶酸还原酶","四氢叶酸还原酶","二氢蝶酸合酶","一碳单位转移酶","葡萄糖-6-磷酸脱氢酶"],"a":0,"e":"甲氧苄啶抑制二氢叶酸还原酶，阻断二氢叶酸还原为四氢叶酸，使核酸合成受阻；人体该酶被抑制时即出现叶酸缺乏。二氢蝶酸合酶是磺胺类作用的靶点，并非甲氧苄啶所抑制。一碳单位转移酶、葡萄糖-6-磷酸脱氢酶与此无关"},{"q":"应用硫脲类药物前一般避免服用碘剂的原因是","o":["可明显延缓硫脲类药物的疗效","可产生交叉过敏反应","易诱发甲状腺功能低下和甲状腺肿","可与硫脲类药物竞争靶细胞","可加速肝脏对硫脲类药物的代谢灭活"],"a":0,"e":"碘剂可抑制甲状腺激素的释放并使腺体缩小变硬，先用碘会使甲状腺内碘储量增加，从而延缓硫脲类药物发挥疗效，故用药前一般避免给碘。甲状腺功能低下与甲状腺肿是长期过量碘或硫脲类自身的不良反应，并非用药前避免碘的原因；两药也不存在交叉过敏或竞争靶细胞"},{"q":"由于心脏手术或洋地黄中毒引起的室性期前收缩，宜选用的治疗药物是","o":["利多卡因","奎尼丁","普鲁卡因胺","普萘洛尔","氟卡尼"],"a":0,"e":"利多卡因为Ⅰb类抗心律失常药，抑制心室肌钠内流、缩短动作电位时程，对室性期前收缩和室性心动过速疗效好，尤其适用于心脏手术或洋地黄中毒所致者。奎尼丁、普鲁卡因胺属Ⅰa类，易致QT延长与低血压；氟卡尼属Ⅰc类，心脏抑制明显，不宜用于器质性心脏病"},{"q":"金刚烷胺能特异性地抑制下列哪项病毒感染","o":["A型流感病毒","乙型流感病毒","麻疹病毒","腮腺炎病毒","单纯疱疹病毒"],"a":0,"e":"金刚烷胺特异抑制A型流感病毒，通过阻断病毒穿入宿主细胞并抑制脱壳而发挥抗病毒作用，临床用于甲型流感。乙型流感病毒对其天然不敏感；麻疹病毒、腮腺炎病毒及单纯疱疹病毒也不受抑制，各需选用相应药物"},{"q":"卡托普利的降压作用机制是","o":["抑制血管紧张素转化酶","拮抗AT1受体","拮抗α1受体","兴奋α2受体","阻滞钙通道"],"a":0,"e":"卡托普利含巯基，抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成并抑制缓激肽降解，从而扩张血管、降低外周阻力而降压。拮抗AT1受体是氯沙坦等沙坦类的机制；拮抗α1受体为哌唑嗪类，兴奋α2受体为可乐定，阻滞钙通道为硝苯地平"},{"q":"可引起幼儿牙釉质发育不良并黄染的药物是","o":["红霉素","四环素","青霉素","林可霉素","多黏霉素E"],"a":1,"e":"四环素可与牙齿、骨骼中的钙结合，沉积于牙釉质，导致幼儿牙釉质发育不良并呈黄色，故儿童及孕妇禁用。红霉素、青霉素、林可霉素无此钙螯合作用；多黏菌素E主要损害肾与神经，亦不引起牙着色"},{"q":"下列药物对血压产生双相反应的是","o":["去甲肾上腺素","肾上腺素","异丙肾上腺素","多巴酚丁胺","间羟胺"],"a":1,"e":"肾上腺素兼具α与β受体激动作用，小剂量时β2效应占优使血管扩张、血压下降，较大剂量时α效应占优使血压上升，故呈先降后升的双相反应。去甲肾上腺素主要激动α受体，几乎只升不降；异丙肾上腺素仅激动β受体，表现为单纯降压；间羟胺以α效应为主"},{"q":"下列属于七氟烷的特点的是","o":["刺激性大","血/气分配系数大","脑/血分配系数大","易燃易爆","对心肺功能影响小"],"a":4,"e":"七氟烷血/气分配系数低，诱导和苏醒迅速，对心肺功能影响小，且无明显刺激性、不易燃，临床常用。刺激性大是乙醚等特点；血/气分配系数大者为乙醚、甲氧氟烷，苏醒慢；脑/血分配系数大并非七氟烷特征；易燃易爆为乙醚的缺点"},{"q":"用于治疗心力衰竭和高血压病的药物是","o":["洋地黄毒苷","氨力农","米力农","毛花苷C","卡托普利"],"a":4,"e":"卡托普利通过抑制ACE减少血管紧张素Ⅱ生成、降低外周阻力，既能降压又能改善心衰重构，适用于心力衰竭和高血压。洋地黄毒苷、毛花苷C为强心苷，仅用于心衰；氨力农、米力农为磷酸二酯酶抑制药，静脉用于急性心衰，均无降压适应证"},{"q":"乙胺丁醇与利福平合用抗结核可以","o":["减少利福平的不良反应","延长利福平的作用时间","延缓利福平的排泄","增加利福平的血药浓度","延缓结核菌产生耐药性"],"a":4,"e":"乙胺丁醇与利福平合用可延缓结核菌产生耐药性，两者抗菌机制不同，联合应用是抗结核的基本原则。利福平的不良反应如肝损害、橘红色分泌物并不因此减少；两药也不延长作用时间、减慢排泄或升高血药浓度"},{"q":"下列药物哪一个是肝药酶抑制药","o":["卡马西平","苯巴比妥","西咪替丁","苯妥英钠","利福平"],"a":2,"e":"西咪替丁为H2受体阻断药，是典型的肝药酶抑制药，可抑制细胞色素P450，使苯妥英钠、茶碱等药物代谢减慢、血药浓度升高。卡马西平、苯巴比妥、苯妥英钠和利福平均为肝药酶诱导药，会加速其他药物代谢，方向相反"},{"q":"下列β受体阻断药中半衰期最长的是","o":["普萘洛尔","纳多洛尔","卡维地洛","阿替洛尔","噻吗洛尔"],"a":1,"e":"纳多洛尔脂溶性低、肾排泄慢，消除半衰期在β受体阻断药中最长，约10～24小时，作用持久。普萘洛尔半衰期仅2～5小时；阿替洛尔、噻吗洛尔半衰期约6～9小时；卡维地洛兼有α阻断作用，半衰期更短"},{"q":"右美托咪定的作用是","o":["激动中枢α1受体","激动中枢α2受体","阻断中枢α1受体","阻断中枢α2受体","激动外周α受体"],"a":1,"e":"右美托咪定是高选择性α2受体激动药，激动中枢α2受体，抑制去甲肾上腺素释放，产生镇静、镇痛和抗焦虑，且呼吸抑制轻微。激动中枢α1受体会升高血压、产生兴奋；阻断α1或α2受体均非其作用；外周α受体激动则以升压为主"},{"q":"可抑制婴幼儿骨骼发育的药物是","o":["青霉素","庆大霉素","四环素","头孢曲松","阿奇霉素"],"a":2,"e":"四环素能与骨组织中钙结合，沉积于骨骼，抑制婴幼儿骨骼发育，并致牙齿黄染、牙釉质发育不全，故儿童及孕妇禁用。青霉素、头孢曲松、阿奇霉素无此钙螯合作用，不影响骨骼与牙齿。庆大霉素主要损害肾和听神经，亦不引起牙着色与骨发育障碍"},{"q":"抑制血管紧张素转化酶的抗高血压药是","o":["卡托普利","可乐定","普萘洛尔","拉贝洛尔","肼屈嗪"],"a":0,"e":"卡托普利通过抑制血管紧张素转化酶，阻断血管紧张素Ⅰ转化为血管紧张素Ⅱ，降低外周血管阻力而降压。可乐定激动中枢α2受体，普萘洛尔阻断β受体，拉贝洛尔兼阻α、β受体，肼屈嗪直接扩张血管，均不抑制ACE"},{"q":"治疗心肌梗死所致室性期前收缩的首选药物是","o":["普萘洛尔","胺碘酮","维拉帕米","利多卡因","苯妥英钠"],"a":3,"e":"利多卡因是Ⅰb类药，选择性作用于心室肌，抑制钠内流并缩短动作电位时程，为心肌梗死所致室性期前收缩的首选。胺碘酮虽可用于室性心律失常但非首选且含碘；维拉帕米主要用于室上性心律失常；普萘洛尔、苯妥英钠亦非心梗后室性早搏首选"},{"q":"关于雌激素替代治疗的描述以下哪一项是不正确的","o":["可以有效抑制绝经期后骨吸收","调整每个重建周期的骨吸收和形成的平衡","是治疗骨质疏松的一线方案","绝经早期用药获益大","治疗方案个体化，使用最低有效剂量"],"a":2,"e":"雌激素替代治疗能抑制绝经后骨吸收、调节骨重建平衡，绝经早期使用获益较大，需个体化并采用最低有效剂量。但因其增加乳腺癌、血栓等风险，已不作为骨质疏松的一线方案，双膦酸盐等才是首选，故该项描述不正确"},{"q":"药物代谢动力学研究","o":["药物进入血液循环与血浆蛋白结合及解离的规律","药物吸收后在机体细胞分布变化的规律","药物经肝脏代谢为无活性产物的过程","药物从给药部位进入血液循环的过程","药物在机体的影响下发生的变化及其规律"],"a":4,"e":"药物代谢动力学研究机体对药物的处置，即药物在体内吸收、分布、代谢、排泄的过程及其规律，常用半衰期、清除率等参数描述。吸收、分布、代谢各自只是其中单一环节；血浆蛋白结合属分布范畴；药物对机体的作用及机制属药效学，均不能概括药动学全部内容"},{"q":"克林霉素（氯林可霉素）可引起下列哪种不良反应","o":["胆汁阻塞性肝炎","听力下降","伪膜性肠炎","肝功能严重损害","肾功能严重损害"],"a":2,"e":"克林霉素抑制肠道正常菌群，使艰难梭菌大量繁殖并产生毒素，引起伪膜性肠炎，是其典型不良反应。胆汁阻塞性肝炎多见于红霉素酯化物；听力下降为氨基糖苷类耳毒性；严重肝、肾损害并非克林霉素的主要表现"},{"q":"阿托品可用于治疗","o":["心房扑动","心房纤颤","窦性心动过缓","室上性心动过速","室性心动过速"],"a":2,"e":"阿托品阻断M受体，解除迷走神经对心脏的抑制，使心率加快、传导改善，可用于窦性心动过缓。心房扑动、心房纤颤及室上性、室性心动过速均以快速心律为特征，阿托品加快心率会加重病情，属禁忌，应改用胺碘酮、维拉帕米等减慢心率的药物"},{"q":"阿托品中毒治疗可选用的药物是","o":["乙酰胆碱","毒扁豆碱","肾上腺素","酚妥拉明","哌仑西平"],"a":1,"e":"毒扁豆碱为胆碱酯酶抑制药，能透过血脑屏障，增加中枢乙酰胆碱，对抗阿托品的中枢与外周中毒症状。乙酰胆碱自身不易透过血脑屏障且作用短暂；肾上腺素、酚妥拉明作用于肾上腺素受体；哌仑西平本身即M1受体阻断药，会加重中毒"},{"q":"按一级动力学消除的药物，其血浆半衰期等于","o":["0.693/Ke","Ke/0.693","2.303/Ke","Ke/2.303","0.301/Ke"],"a":0,"e":"按一级动力学消除时，血药浓度按恒定比例衰减，半衰期与初始浓度无关，等于0.693/Ke。Ke/0.693为其倒数；2.303/Ke用于求取药物消除99.9%所需时间等相关计算，0.301/Ke亦非半衰期公式"},{"q":"下列药物中抑制胃酸作用最强的是","o":["法莫替丁","硫糖铝","兰索拉唑","铝碳酸镁","米索前列醇"],"a":2,"e":"兰索拉唑为质子泵抑制药，不可逆抑制H+/K+-ATP酶，阻断胃酸分泌的最后环节，抑酸作用最强。法莫替丁阻断H2受体，抑酸弱于PPI；硫糖铝、铝碳酸镁为黏膜保护剂和抗酸药；米索前列醇为前列腺素衍生物，抑酸作用有限"},{"q":"药物在肝脏内代谢转化后都会","o":["毒性减小或消失","经胆汁排泄","极性增高","脂/水分布系数增大","分子量减小"],"a":2,"e":"药物在肝内经氧化、还原、水解或结合反应代谢，多数使分子极性增高、水溶性增大，利于排泄。结合反应可使分子量增大而非减小；毒性可能降低也可能增加，如前体药活化；经胆汁排泄只适用于部分药物，并非都会发生"},{"q":"泰能为临床上治疗G+和G-需氧菌和厌氧菌所致各种严重感染的药物，是西司他汀与下列哪个药物组成的复方制剂","o":["硫霉素","亚胺培南","头孢西丁","拉氧头孢","氨曲南"],"a":1,"e":"泰能为亚胺培南与西司他汀组成的复方制剂，亚胺培南属碳青霉烯类，抗菌谱广，对革兰阳性、阴性需氧菌和厌氧菌均有效；西司他汀抑制肾脱氢肽酶，保护亚胺培南不被破坏。硫霉素抗菌活性低且不稳定；头孢西丁、拉氧头孢、氨曲南均非其组分"},{"q":"维司力农治疗心衰的作用机制是","o":["兴奋心脏β1受体","抑制钠钾ATP酶","通过抑制PDE-Ⅲ提高细胞内cAMP含量","促进血管内皮细胞合成NO","阻滞钙通道"],"a":2,"e":"维司力农属磷酸二酯酶Ⅲ抑制药，抑制cAMP降解，提高细胞内cAMP含量，增加心肌收缩力并扩张血管，用于心衰。兴奋β1受体是多巴酚丁胺等的作用；抑制钠钾ATP酶是强心苷机制；促进NO合成与阻滞钙通道与此无关"},{"q":"在远曲小管通过与醛固酮竞争性拮抗而产生利尿作用的药物是","o":["呋塞米","布美他尼","螺内酯","阿米洛利","氨苯蝶啶"],"a":2,"e":"螺内酯结构与醛固酮相似，在远曲小管与醛固酮竞争性结合受体，抑制钠重吸收和钾排泄，属保钾利尿药。呋塞米、布美他尼为袢利尿药，抑制髓袢升支粗段；阿米洛利、氨苯蝶啶虽也保钾，但直接阻滞钠通道，不拮抗醛固酮"},{"q":"硝酸甘油扩血管是通过哪项发挥作用的","o":["增加NO的生成","抑制交感神经","兴奋迷走神经","抑制血管紧张素生成","利尿作用"],"a":0,"e":"硝酸甘油在血管平滑肌内经代谢释放一氧化氮，激活鸟苷酸环化酶，升高cGMP，使血管平滑肌松弛，扩张静脉和冠脉。其机制不涉及抑制交感或兴奋迷走神经；抑制血管紧张素生成是ACE抑制药的作用；利尿作用属利尿药"},{"q":"下列不宜用于支气管哮喘患者的静脉麻醉药是","o":["依托咪酯","氯胺酮","丙泊酚","硫喷妥钠","咪达唑仑"],"a":3,"e":"硫喷妥钠为巴比妥类静脉麻醉药，可释放组胺、兴奋交感并使喉痉挛和支气管痉挛风险增加，支气管哮喘患者不宜使用。氯胺酮反而可扩张支气管、适用于哮喘；依托咪酯、丙泊酚、咪达唑仑无明显致支气管痉挛作用"},{"q":"青霉素治疗效果最好的是","o":["铜绿假单胞菌感染","肺炎杆菌感染","破伤风杆菌感染","结核杆菌感染","变形杆菌感染"],"a":2,"e":"青霉素对破伤风杆菌等革兰阳性厌氧芽胞杆菌抗菌作用强，是破伤风治疗的重要药物，需配合抗毒素中和毒素。铜绿假单胞菌、肺炎杆菌、变形杆菌为革兰阴性菌，多对青霉素天然耐药；结核杆菌细胞壁含分枝菌酸，须用异烟肼、利福平等抗结核药，青霉素无效"},{"q":"下列用于治疗阿尔茨海默病的药物中，不属于胆碱酯酶抑制剂的是","o":["多奈哌齐","美金刚","石杉碱甲","加兰他敏","利斯的明"],"a":1,"e":"美金刚为NMDA受体拮抗药，通过调节谷氨酸能神经传递治疗阿尔茨海默病，不属于胆碱酯酶抑制剂。多奈哌齐、石杉碱甲、加兰他敏、利斯的明均通过抑制胆碱酯酶、提高脑内乙酰胆碱水平发挥作用"},{"q":"麦角新碱治疗产后出血的作用机制是","o":["收缩子宫平滑肌","收缩血管","促进血管修复","促进凝血过程","促进血小板聚集"],"a":0,"e":"麦角新碱直接兴奋子宫平滑肌，使子宫强直性收缩，压迫子宫肌层血管而止血，用于产后出血。其并非通过收缩外周血管、促进血管修复或增强凝血、血小板聚集发挥止血作用，那些环节与产后出血的止血机制不符"},{"q":"别嘌醇属于","o":["镇痛药","抗癫痫药","解热镇痛抗炎药","抗痛风药","中枢兴奋药"],"a":3,"e":"别嘌醇抑制黄嘌呤氧化酶，使次黄嘌呤、黄嘌呤不能转化为尿酸，减少尿酸生成，用于原发性和继发性高尿酸血症及痛风，属抗痛风药。它不是镇痛药，也非解热镇痛抗炎药，不能用于急性痛风止痛；中枢兴奋药如咖啡因、抗癫痫药如苯妥英钠均与其作用无关"},{"q":"下列哪类抗菌药物属于静止期杀菌药","o":["青霉素类","磺胺类","大环内酯类","氨基苷类","四环素类"],"a":3,"e":"氨基苷类在细菌静止期仍能抑制蛋白质合成并破坏细胞膜，属静止期杀菌药，对革兰阴性杆菌作用强。青霉素类为繁殖期杀菌药；磺胺类、四环素类、大环内酯类均为抑菌药，仅在细菌繁殖期抑制其生长"},{"q":"组胺H2受体阻滞药在临床适用于治疗的疾病是","o":["荨麻疹","呕吐","晕动病","消化道溃疡","支气管哮喘"],"a":3,"e":"H2受体阻滞药阻断胃壁细胞H2受体，抑制基础胃酸及刺激引起的胃酸分泌，临床用于胃、十二指肠溃疡。荨麻疹、晕动病、呕吐多用H1受体阻断药或止吐药；支气管哮喘与H2受体无关，H1阻断药亦非其主治"},{"q":"糖皮质激素抗毒作用机理是","o":["对抗细菌外毒素","中和细菌内毒素","提高机体对细菌内毒素的耐受力","加速细菌内毒素的排泄","加速机体对细菌外毒素的代谢"],"a":2,"e":"糖皮质激素能稳定溶酶体膜、降低血管通透性，提高机体对细菌内毒素的耐受力，减轻毒血症症状，此即抗毒作用。它不能直接对抗或中和外毒素、内毒素，也不加速其排泄或代谢，故感染时须合用足量抗菌药"},{"q":"抗消化性溃疡米索前列醇禁用于妊娠妇女是由于","o":["子宫收缩","女性胎儿男性化","致畸胎作用","盆腔充血","胃肠道反应"],"a":0,"e":"米索前列醇为前列腺素E1衍生物，能兴奋子宫平滑肌、引起子宫收缩，妊娠妇女使用可致流产或早产，故禁用。其消化道反应和腹泻常见但不构成妊娠禁忌；致畸、盆腔充血、女性胎儿男性化并非其禁用的主要原因"},{"q":"具有扩瞳作用的药物是","o":["溴甲东莨菪碱","普鲁本辛","哌仑西平","后马托品","双环维林"],"a":3,"e":"后马托品为阿托品合成代用品，阻断虹膜括约肌M受体，使瞳孔散大，用于眼科散瞳。溴甲东莨菪碱、普鲁本辛、双环维林主要解除胃肠道平滑肌痉挛；哌仑西平选择性阻断M1受体抑制胃酸，均无散瞳用途"},{"q":"妥拉唑林的药物分类属于","o":["选择性α1受体阻断药","非选择性α受体阻断药","选择性β1受体阻断药","非选择性β受体阻断药","选择性α2受体阻断药"],"a":1,"e":"妥拉唑林阻断α1和α2受体，属非选择性α受体阻断药，可扩张血管、降低外周阻力。酚苄明亦属此类；选择性α1阻断药为哌唑嗪，选择性α2阻断药为育亨宾；β1或β受体阻断药如阿替洛尔、普萘洛尔作用于β受体，与本类无关"},{"q":"下列无抗幽门螺杆菌作用的药物是","o":["阿莫西林","奥美拉唑","四环素","普鲁苯辛","枸橼酸铋钾"],"a":3,"e":"阿莫西林、四环素可直接抑制幽门螺杆菌，奥美拉唑抑制胃酸为其创造不利于生存的环境，枸橼酸铋钾覆盖黏膜并杀菌，均参与根除方案。普鲁苯辛为M受体阻断药，仅能解除平滑肌痉挛并减少胃酸分泌，对幽门螺杆菌无杀灭作用，单用还会掩盖症状"},{"q":"吗啡的中枢药理作用有","o":["镇痛、镇静、致咳","镇痛、镇咳、兴奋呼吸","镇痛、欣快、散瞳","镇痛、镇静、抑制呼吸、镇咳","镇痛、镇静、兴奋呼吸"],"a":3,"e":"吗啡激动中枢阿片受体，产生强镇痛、镇静及欣快，同时抑制呼吸中枢并直接抑制咳嗽中枢，故有镇咳作用，并扩张外周血管引起体位性低血压。它使瞳孔缩小而非散瞳；治疗量即抑制呼吸而非兴奋；镇咳虽强，却因释放组胺、抑制呼吸而不用于支气管哮喘"},{"q":"不能用于治疗甲状腺危象的药物是","o":["大剂量碘剂","丙硫氧嘧啶","普萘洛尔","甲苯磺丁脲","卡比马唑"],"a":3,"e":"甲状腺危象需抑制甲状腺激素合成与释放、阻断β受体并降温，常用丙硫氧嘧啶、大剂量碘剂、普萘洛尔和卡比马唑综合处理。甲苯磺丁脲为第一代磺酰脲类降糖药，通过阻滞钾通道促胰岛素释放，与甲状腺激素合成释放无关，不能用于甲状腺危象"},{"q":"下列药物属于α-葡萄糖苷酶抑制药是","o":["氯磺丙脲","甲苯磺丁脲","格列齐特","吡格列酮","阿卡波糖"],"a":4,"e":"阿卡波糖在肠道竞争性抑制α-葡萄糖苷酶，延缓碳水化合物分解为葡萄糖，降低餐后血糖，属α-葡萄糖苷酶抑制药。氯磺丙脲、甲苯磺丁脲、格列齐特为磺酰脲类，吡格列酮为噻唑烷二酮类，机制各不相同"},{"q":"有关维生素K的叙述，错误的是","o":["对于应用链激酶所致出血有特效","较大剂量维生素K3可出现新生儿溶血","参与凝血因子的合成","天然维生素K为脂溶性","维生素K1注射过快可出现呼吸困难"],"a":0,"e":"维生素K参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，用于维生素K缺乏所致出血，天然品为脂溶性，注射过快可致呼吸困难，大剂量K3可致新生儿溶血。链激酶所致出血系纤溶亢进，维生素K无效，应用氨甲苯酸等抗纤溶药，故该项叙述错误"},{"q":"按一级动力学消除的药物，其血浆半衰期的计算公式是","o":["Ke/1、44","1.44/Ke","0.693/Ke","Ke/0.693","2D/Ke"],"a":2,"e":"一级消除动力学中半衰期恒定，等于0.693/Ke，与给药剂量和初始血药浓度无关。1.44/Ke用于估算药物基本消除所需时间；Ke/0.693和2D/Ke均非半衰期表达式，量与时间维度不符"},{"q":"关于吗啡作用的叙述，哪项是错误的","o":["镇痛","抑制呼吸","瞳孔缩小","治疗支气管哮喘","引起体位性低血压"],"a":3,"e":"吗啡有强镇痛、抑制呼吸、缩瞳及扩张外周血管引起体位性低血压等作用，还能镇静、镇咳。它释放组胺并抑制呼吸中枢，可诱发或加重支气管哮喘，属禁忌而非治疗；支气管哮喘应选β2激动药或糖皮质激素，故该项叙述错误"},{"q":"吗啡连续应用易成瘾，一般仅应用于","o":["慢性钝痛","慢性失眠","慢性充血性心力衰竭","精神焦虑症","急性剧痛"],"a":4,"e":"吗啡易产生耐受和成瘾，一般仅短期用于其他镇痛药无效的急性剧痛，如严重创伤、烧伤和晚期癌症剧痛。慢性钝痛宜用解热镇痛药，慢性失眠与精神焦虑应用镇静催眠药，成瘾风险大；慢性充血性心力衰竭并非其常规适应证，仅急性左心衰肺水肿时可慎用"},{"q":"磺酰脲类降糖作用主要机制是","o":["抑制胰高血糖素分泌","提高靶细胞对胰岛素的敏感性","增加靶细胞膜上胰岛素受体数目","阻滞ATP敏感钾通道，触发胰岛素释放","降低食物吸收和糖原异生"],"a":3,"e":"磺酰脲类阻断胰岛β细胞ATP敏感钾通道，使细胞膜去极化、钙内流，触发胰岛素释放，发挥降糖作用，前提是胰岛尚有功能。提高靶细胞胰岛素敏感性是双胍类、噻唑烷二酮类的作用；抑制胰高血糖素、减少糖原异生均非其主要机制"},{"q":"氨基糖苷类抗生素对下列哪类细菌作用差","o":["铜绿假单胞菌","厌氧菌属","结核分枝杆菌","克雷伯菌属","肠杆菌"],"a":1,"e":"氨基糖苷类需氧依赖转运进入菌体，对铜绿假单胞菌、克雷伯菌属、肠杆菌及结核分枝杆菌均有较好作用。厌氧菌缺乏相应转运系统，天然耐药，故本类对厌氧菌作用差，治疗厌氧菌感染须选甲硝唑或克林霉素"},{"q":"去甲肾上腺素扩张冠脉的原因是","o":["激动α2受体","阻断α1受体","激动β2受体","兴奋心脏，使心肌代谢产物增加","激动M受体"],"a":3,"e":"去甲肾上腺素激动心脏β1受体，使心肌收缩力增强、代谢产物如腺苷等增加，继发扩张冠状动脉，增加冠脉血流，故冠脉扩张属间接效应。其本身激动α受体使血管收缩；β2受体激动和M受体激动均非其扩张冠脉的机制，阻断α1更会消除升压"},{"q":"受体拮抗剂的特点是","o":["对受体有亲和力，有内在活性","对受体无亲和力，有内在活性","对受体无亲和力，无内在活性","对受体有亲和力，无内在活性","抑制体内自主神经末梢释放递质"],"a":3,"e":"受体拮抗剂能与受体结合，具备亲和力，但不产生激动效应，内在活性为零，通过占据受体阻断激动药作用。有亲和力且有内在活性是激动药；无亲和力则不能结合受体；抑制递质释放是某些药物的间接作用，非拮抗剂的本质特征"},{"q":"某碱性药物的pKa为9.8，如果增高尿液的pH，则此药在尿中","o":["解离度增高，重吸收减少，排泄加快","解离度增高，重吸收增多，排泄减慢","解离度降低，重吸收减少，排泄加快","解离度降低，重吸收增多，排泄减慢","排泄速度并不改变"],"a":3,"e":"该药为碱性，pKa为9.8，升高尿液pH使环境更偏碱，碱性药物非解离型比例增加，解离度降低。非解离型脂溶性高，易被肾小管重吸收，故排泄减慢、作用延长；解离度增高、重吸收减少则加快排泄，适用于酸性药物碱化尿液的情况"},{"q":"哪项不是氯丙嗪的不良反应","o":["体位性低血压","嗜睡、无力、鼻塞、心动过速","帕金森综合征","迟发性运动障碍","牙龈增生"],"a":4,"e":"氯丙嗪阻断α受体可致体位性低血压，阻断M受体引起嗜睡、无力、鼻塞、心动过速，阻滞纹状体多巴胺受体可致帕金森综合征，长期用药还可出现迟发性运动障碍。牙龈增生是苯妥英钠的典型不良反应，与氯丙嗪无关"},{"q":"下列不属于自体活性物质的是","o":["前列腺素","内皮素","血管紧张素","肾上腺素","血清素"],"a":3,"e":"自体活性物质是局部产生、局部作用的活性物质，包括前列腺素、内皮素、血管紧张素、血清素及组胺、缓激肽等。肾上腺素由肾上腺髓质分泌，作为循环激素和神经递质经血液远距离发挥作用，不属于自体活性物质"},{"q":"X、Y两药的S型量-效曲线位于同一坐标上，其中，Y药在X药的右侧且高出后者20%，下列描述正确的是","o":["X药的效价强度和效能均较大","X药的效价强度和效能均较小","X药的效价强度较小而效能较大","X药的效价强度较大而效能较小","两药的效价强度和效能均相等"],"a":3,"e":"量效曲线中横坐标反映效价强度，越靠左所需剂量越小、效价强度越大；纵坐标高度反映效能。Y药位于X药右侧，说明X药效价强度较大；Y药又高出20%，说明Y效能较大、X效能较小，故X药效价强度较大而效能较小"},{"q":"小剂量多巴胺舒张血管主要是通过激动","o":["α1受体","β1受体","D1受体","β2受体","α2受体"],"a":2,"e":"小剂量多巴胺主要激动肾、肠系膜血管的D1受体，激活腺苷酸环化酶使血管舒张，增加肾血流量。β1受体激动增强心肌收缩力需较大剂量；α1受体激动致血管收缩见于大剂量；β2、α2受体与小剂量多巴胺舒张血管无关"},{"q":"肝素过量时特效的解毒剂是","o":["鱼精蛋白","维生素K","氨甲苯酸","硫酸亚铁","阿司匹林"],"a":0,"e":"鱼精蛋白为强碱性蛋白，与强酸性的肝素结合形成稳定复合物，使肝素失去抗凝活性，是肝素过量的特效解毒剂。维生素K用于香豆素类过量；氨甲苯酸为抗纤溶药；硫酸亚铁补铁；阿司匹林抑制血小板，均不能对抗肝素"},{"q":"氯丙嗪翻转肾上腺素升压效应是因为它","o":["阻断DA受体","阻断M受体","阻断α受体","阻断β受体","阻断N受体"],"a":2,"e":"氯丙嗪阻断α受体，使肾上腺素激动α受体所致的血管收缩作用消失，而β2受体激动的舒血管作用保留，原先的升压效应翻转为降压。阻断DA受体与其抗精神病作用相关；阻断M、β、N受体并非翻转升压效应的原因"},{"q":"可引起出血性膀胱炎的抗肿瘤药是","o":["阿糖胞苷","环磷酰胺","长春碱","阿奇霉素","长春新碱"],"a":1,"e":"环磷酰胺在体内代谢生成丙烯醛，经尿液排泄时刺激膀胱黏膜，可引起出血性膀胱炎，多饮水或用美司钠可预防。阿糖胞苷主要致骨髓抑制；长春碱、长春新碱主要为神经毒性；阿奇霉素是抗生素，非抗肿瘤药"},{"q":"TMP的抗菌作用机制是抑制","o":["二氢叶酸还原酶","过氧化物酶","二氢蝶酸合酶","DNA回旋酶","β-内酰胺酶"],"a":0,"e":"TMP即甲氧苄啶，抑制二氢叶酸还原酶，阻断二氢叶酸还原为四氢叶酸，与磺胺类抑制二氢蝶酸合酶形成双重阻断，抗菌作用增强。DNA回旋酶是喹诺酮类靶点；过氧化物酶参与甲状腺激素合成；β-内酰胺酶水解青霉素类，均与TMP抗菌机制无关"},{"q":"丙磺舒与青霉素合用，增强后者疗效的原因是","o":["与青霉素竞争血浆结合蛋白","与青霉素在杀菌作用上有协同效应","抑制青霉素在肝内的代谢","与青霉素竞争肾小管分泌","延缓青霉素耐药性的产生"],"a":3,"e":"丙磺舒与青霉素均经肾小管主动分泌排泄，两者竞争同一转运载体，使青霉素排泄减慢、血药浓度升高、作用增强。丙磺舒不与血浆蛋白结合竞争，也不抑制肝代谢或延缓耐药性，更无直接杀菌协同作用"},{"q":"麦角胺治疗偏头痛的作用机制是","o":["阻断血管平滑肌α受体","具有镇痛作用","扩张脑血管，改善脑组织供氧","抑制前列腺素合成","收缩脑血管"],"a":4,"e":"麦角胺直接收缩脑血管，减轻偏头痛发作时脑动脉扩张和搏动，从而缓解头痛。它并不阻断α受体，也不是通过中枢镇痛、扩张脑血管改善供氧或抑制前列腺素合成起效；麦角新碱则主要收缩子宫，扩张血管反而会加重偏头痛"},{"q":"小剂量碘的用途是","o":["黏液性水肿","甲亢","单纯性甲状腺肿","呆小病","甲状腺危象"],"a":2,"e":"小剂量碘可补充合成甲状腺激素所需的碘原料，用于防治因缺碘引起的单纯性甲状腺肿。甲亢和甲状腺危象需用大剂量碘抑制激素释放；黏液性水肿、呆小病属甲状腺功能减退，须用甲状腺激素替代治疗"},{"q":"药物作用的两重性是指药物同时具有","o":["兴奋作用和抑制作用","副作用和毒性反应","治疗作用和不良反应","药物作用和药理效应","选择性和专一性"],"a":2,"e":"药物作用的两重性指同一药物既有防治疾病的治疗作用，也伴随与治疗目的无关、甚至有害的不良反应，两者并存。兴奋与抑制是作用的基本表现形式；副作用与毒性反应只是不良反应的一部分，不能概括两重性"},{"q":"有机磷酸酯类中毒时产生M样症状的原因是","o":["胆碱能神经递质释放减少","胆碱能神经递质释放增加","胆碱能神经递质破坏减慢","药物排泄减慢","M受体的敏感性增加"],"a":2,"e":"有机磷酸酯类抑制胆碱酯酶，使乙酰胆碱不能被及时水解破坏，大量蓄积于突触间隙，持续激动M受体，产生瞳孔缩小、流涎、腹痛腹泻、支气管分泌增多等M样症状。递质释放并未增加，也不是M受体敏感性升高所致"},{"q":"甲氨蝶呤引起的贫血宜选用的治疗药物是","o":["硫酸亚铁","叶酸","亚叶酸钙","维生素B12","二氢叶酸"],"a":2,"e":"甲氨蝶呤抑制二氢叶酸还原酶，造成四氢叶酸缺乏而致巨幼红细胞性贫血。亚叶酸钙即甲酰四氢叶酸钙，无需还原即可直接补充四氢叶酸，为特效解救药。普通叶酸需经该酶还原，故无效；铁剂、维生素B12、二氢叶酸亦不能纠正"},{"q":"能抑制胃酸分泌最后环节的药物是","o":["哌仑西平","奥美拉唑","雷尼替丁","丙谷胺","米索前列醇"],"a":1,"e":"奥美拉唑抑制胃壁细胞H+/K+-ATP酶，即质子泵，阻断胃酸分泌的最终共同通路，抑酸最强。哌仑西平阻断M1受体、雷尼替丁阻断H2受体、丙谷胺阻断胃泌素受体，均只阻断单一环节；米索前列醇为黏膜保护剂"},{"q":"某弱酸性药物，口服可由胃吸收，pKa=5.4，当达平衡时血浆（pH=7.4）药物浓度约是胃中（pH=1.4）药物浓度的","o":["1倍","10倍","100倍","1000倍","10000倍"],"a":2,"e":"弱酸性药物按Henderson-Hasselbalch方程分布，血浆pH7.4高于pKa5.4两个单位，解离型约为非解离型的100倍；胃液pH1.4时几乎全部非解离。非解离型可自由跨膜，平衡时两侧非解离浓度相等，故血浆总浓度约为胃中的100倍"},{"q":"治疗强心苷中毒引起的房室传导阻滞或窦性心动过缓最好选用","o":["异丙肾上腺素","阿托品","苯妥英钠","氨茶碱","麻黄碱"],"a":1,"e":"强心苷中毒抑制房室传导并兴奋迷走神经，可引起房室传导阻滞和窦性心动过缓，阿托品阻断M受体、解除迷走抑制，是首选。苯妥英钠用于强心苷中毒所致室性心律失常；异丙肾上腺素、麻黄碱、氨茶碱虽可加快心率，但非该情况首选"},{"q":"抗菌药物的抗菌范围称为","o":["抗菌谱","抗菌活性","化疗指数","抗生素后效应","首次接触效应"],"a":0,"e":"抗菌谱指抗菌药物抑制或杀灭病原微生物的范围，分窄谱与广谱。抗菌活性是药物抑制或杀灭微生物的能力，常用MIC、MBC表示；化疗指数为LD50与ED50之比，反映安全性；抗生素后效应、首次接触效应均属药效学其他概念"},{"q":"下列哪种药物首次服用时，可能引起较严重的体位性低血压","o":["哌唑嗪","可乐定","普萘洛尔","硝苯地平","卡托普利"],"a":0,"e":"哌唑嗪选择性阻断α1受体，首次给药可因小动脉和静脉突然扩张、回心血量骤减，出现严重体位性低血压甚至晕厥，称首剂现象。可乐定、普萘洛尔、硝苯地平、卡托普利虽可降压，但无典型首剂体位性低血压"},{"q":"哌替啶中毒时发生的呼吸抑制、昏迷等症状，可注射以下哪种药物解救","o":["美沙酮","纳洛酮","氟马西尼","丁丙诺啡","曲马多"],"a":1,"e":"哌替啶为阿片类镇痛药，过量可致呼吸抑制、昏迷和瞳孔缩小。纳洛酮为阿片受体拮抗药，能迅速置换吗啡样物质、逆转呼吸抑制与昏迷，是首选解救药。美沙酮、丁丙诺啡本身为阿片类；氟马西尼解救苯二氮䓬类；曲马多亦为镇痛药"},{"q":"药物代谢动力学参数不包括","o":["消除速率常数","表观分布容积","半衰期","半数致死量","血浆清除率"],"a":3,"e":"药动学参数描述药物在体内的处置过程，包括消除速率常数、表观分布容积、半衰期和血浆清除率，用于设计给药方案。半数致死量反映药物毒性大小，是评价安全性的毒理学指标，属药效学范畴，不属于药动学参数，两者研究内容不同"},{"q":"下列不属于吗啡禁忌证的是","o":["哺乳期妇女止痛","肺源性心脏病","支气管哮喘","颅内压增高","血压正常的心肌梗死患者"],"a":4,"e":"吗啡禁用于支气管哮喘、肺源性心脏病、颅内压增高及哺乳期妇女，因其抑制呼吸、释放组胺或经乳汁分泌。血压正常的心肌梗死患者并非禁忌，吗啡可镇痛、减轻焦虑并扩张血管，反可用于急性心肌梗死"},{"q":"糖皮质激素隔日疗法的给药时间是","o":["隔日早上","隔日中午","隔日下午","隔日晚上","隔日午夜"],"a":0,"e":"糖皮质激素分泌具有昼夜节律，清晨血中浓度最高。隔日疗法将两日总量于隔日清晨一次给予，可减轻对下丘脑-垂体-肾上腺轴的抑制，故给药时间为隔日早上。中午、下午、晚上或午夜给药均违背生理节律，不良反应增加"},{"q":"不具有抗铜绿假单胞菌的抗生素是","o":["头孢呋辛","羧苄西林","头孢哌酮","庆大霉素","头孢他啶"],"a":0,"e":"头孢呋辛为二代头孢菌素，对革兰阳性菌作用较强，对铜绿假单胞菌无效。羧苄西林为抗假单胞菌青霉素；头孢哌酮、头孢他啶为三代头孢，头孢他啶抗铜绿假单胞菌作用尤强；庆大霉素属氨基苷类，亦对该菌有效，可用于铜绿假单胞菌感染"},{"q":"抗着床的避孕药是","o":["复方氯地孕酮","大剂量雌激素","炔雌醇","大剂量甲地孕酮","炔雌醚"],"a":3,"e":"大剂量孕激素如甲地孕酮可抑制下丘脑-垂体-卵巢轴，使子宫内膜提前分泌转化，不利于受精卵着床，从而发挥抗着床避孕作用。复方氯地孕酮、炔雌醇、炔雌醚主要通过抑制排卵避孕，并非抗着床机制"},{"q":"一个效能和效价强度均高的激动剂应该是","o":["亲和力高，内在活性低","亲和力低，内在活性较弱","亲和力低，内在活性低","亲和力低，内在活性高","亲和力高，内在活性高"],"a":4,"e":"效价强度取决于药物与受体的亲和力，亲和力越高、所需剂量越小；效能取决于内在活性，内在活性越高、最大效应越强。因此效能和效价强度均高的激动剂应兼具高亲和力和高内在活性，其余组合均存在某一方面不足"},{"q":"香豆素类药物抗凝作用的机制是","o":["妨碍肝脏合成凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ","耗竭体内凝血因子","激活血浆中抗凝血酶Ⅲ","抑制纤溶酶原变为纤溶酶","抑制凝血酶原转变为凝血酶"],"a":0,"e":"香豆素类为维生素K拮抗药，抑制维生素K在肝内参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成，使这些因子缺乏而抗凝。它不耗竭已有凝血因子，也不激活抗凝血酶Ⅲ；抑制纤溶酶原激活是抗纤溶药作用，抑制凝血酶原转变亦非其机制"},{"q":"卡托普利的降压作用主要通过下列哪项产生","o":["利尿降压","血管扩张","钙拮抗","ACE抑制","α受体阻断"],"a":3,"e":"卡托普利含巯基，抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成并减少缓激肽降解，从而扩张血管降压。利尿降压是氢氯噻嗪机制；钙拮抗为硝苯地平；α受体阻断为哌唑嗪；血管扩张为肼屈嗪的直接作用"},{"q":"地高辛不良反应的叙述，下列哪项是错误的","o":["胃肠道反应","外周神经炎","黄视、绿视","各种心律失常","中枢神经系统"],"a":1,"e":"地高辛不良反应包括胃肠道反应如恶心呕吐，视觉异常如黄视、绿视，以及各类心律失常，也可有头痛、失眠等中枢神经系统症状，与中毒量相关。外周神经炎不是地高辛的典型不良反应，多见于长春新碱等抗肿瘤药或异烟肼，系其神经毒性表现"},{"q":"红霉素、克林霉素合用可","o":["扩大抗菌谱","由于竞争结合部位产生拮抗作用","增强抗菌活性","降低毒性","增加毒性"],"a":1,"e":"红霉素与克林霉素均作用于细菌核糖体50S亚基，竞争相同结合部位，合用可相互拮抗，不宜联用。两药抗菌谱相近，合用并不能扩大抗菌谱或增强活性；合用也非降低毒性之法，反而增加不良反应与耐药风险"},{"q":"某哮喘患者，遵医嘱使用糖皮质激素类药治疗哮喘的药理作用的是","o":["降低支气管平滑肌对儿茶酚胺的敏感性","抗炎作用","直接松弛支气管平滑肌","增强气道纤毛的清除功能","呼吸兴奋作用"],"a":1,"e":"糖皮质激素治疗哮喘主要依靠强大抗炎作用，抑制气道炎症细胞浸润和炎症介质释放，降低气道高反应性。它并不直接松弛支气管平滑肌；降低平滑肌对儿茶酚胺敏感性会削弱β2激动药效果；增强纤毛清除、呼吸兴奋均非其抗喘机制"},{"q":"阻止病毒穿入宿主细胞、抑制其脱壳而抗病毒的药物是","o":["金刚烷胺","阿昔洛韦","利巴韦林","碘苷","吗啉胍"],"a":0,"e":"金刚烷胺可阻止流感病毒穿入宿主细胞并抑制脱壳，从而抑制病毒复制，用于甲型流感。阿昔洛韦抑制病毒DNA聚合酶，碘苷抑制DNA合成，利巴韦林、吗啉胍为广谱抗病毒药，机制均非阻断穿入与脱壳，对甲型流感无此特异作用"},{"q":"丙磺舒可在肾小管主动分泌，其主动转运跨膜时的特点是","o":["需要载体，耗能，有饱和性和竞争性","不需要载体，不耗能，无饱和性和竞争性","需要载体，耗能，无饱和性和竞争性","不需要载体，不耗能，有饱和性和竞争性","需要载体，不耗能，无饱和性和竞争性"],"a":0,"e":"丙磺舒在肾小管的主动分泌属主动转运，需载体蛋白参与、消耗能量，因载体数量有限而具饱和性，结构相似药物间可发生竞争性抑制。不需载体、不耗能的被动扩散无饱和性与竞争性，与该转运特点不符"},{"q":"伴窦性心动过缓的高血压不宜用","o":["普萘洛尔","硝普钠","氢氯噻嗪","肼屈嗪","硝酸甘油"],"a":0,"e":"普萘洛尔为非选择性β受体阻断药，抑制心脏β1受体，使心率减慢、传导减慢，伴窦性心动过缓的高血压患者使用会加重心动过缓，故不宜用。硝普钠、硝酸甘油扩张血管，氢氯噻嗪利尿，肼屈嗪扩血管，均可反射性加快心率，不加重心动过缓"},{"q":"强心苷中毒引起的传导阻滞可选用的治疗药物是","o":["氯化钾","肾上腺素","阿托品","氨茶碱","苯妥英钠"],"a":2,"e":"强心苷中毒抑制窦房结和房室传导，出现传导阻滞时，阿托品阻断M受体、解除迷走神经抑制，可改善传导。氯化钾用于纠正低钾所致心律失常，但传导阻滞时补钾慎用；苯妥英钠主治室性心律失常；肾上腺素、氨茶碱非首选"},{"q":"有关氧化亚氮的理化性质，正确的是","o":["有色无味液态气体","对呼吸道有刺激","易燃烧，且与可燃性全麻药混合时有助燃性","脂溶性低，血/气分配系数为0.47","性质不稳定"],"a":3,"e":"氧化亚氮为无色无味、性质稳定的气体，对呼吸道无刺激，不燃不爆，脂溶性低，血/气分配系数约0.47，故诱导快、苏醒快但麻醉效能弱。有色液态、刺激呼吸道、易燃易爆及性质不稳定均与其理化性质不符"},{"q":"链激酶引起的出血宜选用哪种药物进行治疗","o":["维生素K","氨甲苯酸","去甲肾上腺素","维生素C","维生素B12"],"a":1,"e":"链激酶激活纤溶酶原，使纤溶系统活性增强而致出血，氨甲苯酸抑制纤溶酶原激活因子，阻断纤溶过程，为特效治疗。维生素K用于凝血因子缺乏出血；维生素C、B12无止血特效；去甲肾上腺素仅局部收缩血管，不能纠正纤溶亢进"},{"q":"毒蕈碱的中毒症状不包括","o":["恶心呕吐","头痛、眼痛、视物模糊","腹痛、腹泻","心率过快、血压上升","流涎、呼吸困难"],"a":3,"e":"毒蕈碱激动M受体，出现恶心呕吐、腹痛腹泻、流涎、呼吸困难、头痛眼痛及视物模糊等毒蕈碱样症状，并致心率减慢、血压下降、瞳孔缩小。心率过快、血压上升属N样受体激动或交感兴奋表现，恰与M样作用相反，不属毒蕈碱中毒症状"},{"q":"强心苷主要用于治疗","o":["充血性心力衰竭","心肌炎","心室纤颤","甲亢性心脏病","室性心律失常"],"a":0,"e":"强心苷抑制心肌细胞膜Na+/K+-ATP酶，使胞内钙增加，增强心肌收缩力，主要用于充血性心力衰竭，尤其伴快速房颤者。心肌炎、甲亢性心脏病属其相对禁忌或疗效差；心室纤颤、室性心律失常为强心苷中毒表现，不能用其治疗"},{"q":"呋塞米的不良反应不包括","o":["胃肠道反应","电解质紊乱（低钾等）","恶心、呕吐","耳毒性","坏死性胰腺炎"],"a":4,"e":"呋塞米为强效袢利尿药，不良反应包括胃肠道反应、恶心呕吐、电解质紊乱如低钾低钠，以及耳毒性，静脉推注过快还可致耳鸣耳聋。坏死性胰腺炎不是其不良反应，多与胆道疾病、酗酒或高甘油三酯相关，与袢利尿剂作用机制无关"},{"q":"双膦酸盐类治疗骨质疏松的机制是","o":["只能被破骨细胞摄取","抑制破骨细胞的凋亡","促进法尼基焦磷酸合酶的活性","抑制破骨细胞的活性","促进小分子GTP酶的异戊烯化"],"a":3,"e":"双膦酸盐与骨中羟基磷灰石结合，被破骨细胞摄取后抑制其活性并诱导凋亡，从而抑制骨吸收，用于骨质疏松。它不仅能被破骨细胞摄取，还抑制法尼基焦磷酸合酶、阻碍小分子GTP酶异戊烯化，故促进该酶活性或促进破骨细胞凋亡的说法均错误"},{"q":"具有M1受体阻断作用的抗消化性溃疡药是","o":["奥美拉唑","苯海拉明","阿托品","哌仑西平","雷尼替丁"],"a":3,"e":"哌仑西平选择性阻断胃壁细胞M1受体，抑制乙酰胆碱促胃酸分泌作用，用于消化性溃疡。奥美拉唑抑制质子泵，雷尼替丁阻断H2受体，均非M1阻断；苯海拉明、阿托品为广义抗组胺或非选择性M阻断药，不属M1选择性抗溃疡药"},{"q":"强心苷治疗心衰的直接作用是","o":["缩小已扩大的心室容积","减慢心率","增强心肌收缩力","降低心室壁张力","增加冠脉血供"],"a":2,"e":"强心苷抑制Na+/K+-ATP酶，增加胞内钙离子，产生正性肌力作用，这是治疗心衰的直接作用。缩小心室容积、降低室壁张力、减慢心率及增加冠脉血供多为心功能改善后的继发效应，并非其直接作用"},{"q":"下列药物属于钾通道开放药的是","o":["硝苯地平","维拉帕米","普罗帕酮","米诺地尔","苯妥英钠"],"a":3,"e":"米诺地尔开放血管平滑肌钾通道，使细胞膜超极化、钙内流减少，血管扩张而降压，属钾通道开放药。硝苯地平、维拉帕米为钙通道阻滞药；普罗帕酮为钠通道阻滞的Ⅰc类抗心律失常药；苯妥英钠为Ⅰb类药，均非钾通道开放药"},{"q":"静脉注射2g磺胺药，其血药浓度为10mg/L，经计算其表观分布容积为","o":["0.05L","2L","5L","20L","200L"],"a":4,"e":"表观分布容积等于体内药量除以血药浓度，Vd=A/C=2000mg/(10mg/L)=200L。该值远大于体液总量，提示药物大量分布于组织并与组织成分结合；其余数值均与按公式计算的结果不符"},{"q":"下列药物哪种是中枢多巴胺受体拮抗药","o":["阿托品","安定","尼可刹米","氯丙嗪","哌替啶"],"a":3,"e":"氯丙嗪阻断中枢多巴胺受体，尤其是中脑-边缘和中脑-皮层通路的D2受体，发挥抗精神病作用，并引起锥体外系反应。阿托品阻断M受体，安定即地西泮作用于苯二氮䓬受体，尼可刹米为中枢兴奋药，哌替啶激动阿片受体，均非多巴胺拮抗药"},{"q":"药物的化疗指数是指","o":["ED95/LD5","LD95/ED5","LD50/ED50","LD50＝ED50","ED5＝LD95"],"a":2,"e":"化疗指数是半数致死量与半数有效量之比，即LD50/ED50，用于评价化疗药物的安全性，指数越大越安全。ED95/LD5等为可靠安全系数；LD95/ED5并非标准定义；LD50＝ED50表示几乎无安全范围，不是化疗指数"},{"q":"对H2受体具有阻断作用的药物","o":["哌仑西平","雷尼替丁","丙谷胺","甲硝唑","苯海拉明"],"a":1,"e":"雷尼替丁为H2受体阻断药，阻断胃壁细胞H2受体，抑制胃酸分泌，用于消化性溃疡。哌仑西平阻断M1受体，丙谷胺阻断胃泌素受体，甲硝唑抗厌氧菌和幽门螺杆菌，苯海拉明为H1受体阻断药，均不阻断H2受体"}];
